WEB_MANIFEST = {
    # The PWA's own chrome. background/theme colour are filled from the HOST's theme at
    # send time (see _web_manifest): a home-screen icon that opens into a blue-grey frame
    # is the page telling the operator their brand does not apply here.
    "name": "tinycmdr",
    "short_name": "tinycmdr",
    "start_url": "/",
    "display": "standalone",
    "icons": [{"src": "/icon.png?v={{VERSION}}", "sizes": "512x512", "type": "image/png"}],
}


def _web_theme_vars():
    """The page's CSS variables, from the SAME theme the terminal uses (theme_palette()).

    theme.toml is host-owned and update never overwrites it, so one file decides both the
    TUI and the page and the two cannot drift. A missing file (or a typo) already fell
    back inside theme_palette(); here a non-hex value falls back again, because a page
    that cannot paint is worse than a page in the wrong colour.
    """
    true = (theme_palette().get("truecolor") or {})
    # theme role -> the page's CSS variable. The derived names the page also paints with
    # (--panel translucent, --line, --gold-bright, --error-bg, --fg/--dim aliases) are
    # computed in the stylesheet FROM these, so a host's theme.toml stays the one source.
    roles = (("background", "--bg", "#0d0f12"), ("panel", "--panel-solid", "#17191d"),
             ("text", "--ivory", "#e9e2d6"), ("muted", "--muted", "#a79b88"),
             ("gold", "--gold", "#d7a94a"), ("ember", "--ember", "#d9782d"),
             ("bronze", "--bronze", "#75654d"), ("crimson", "--crimson", "#c43a32"),
             ("error", "--error", "#e05245"), ("laurel", "--laurel", "#8fae6b"),
             ("selection_bg", "--sel", "#3a2524"))
    out = {}
    for role, var, fallback in roles:
        v = str(true.get(role) or "").strip()
        out[var] = v if re.match(r"^#[0-9a-fA-F]{6}$", v) else fallback
    return out


def _release_page_url():
    """The release notes for THIS build - what the page's version stamp links to.

    Derived from update_url (the one place the repo's URL lives), so a fork or a mirror
    keeps its own links: .../releases/latest/download -> .../releases/tag/v<version>.
    """
    base = str(CONFIG["agent"].get("update_url")
               or os.environ.get("TINYCMDR_UPDATE_URL")
               or DEFAULT_UPDATE_URL)
    root = base.split("/releases/")[0].rstrip("/")
    return "%s/releases/tag/v%s" % (root, VERSION)


def _web_page_html():
    """The page, with the host's palette and art baked in and nothing left to fetch."""
    # The art URLs carry the app version: /page.css and the HTML revalidate, but the
    # art routes cache for a day, so an update used to show a new stylesheet beside the
    # OLD mascot until a hard reload (operator, 2026-10-04: "new background but old
    # chibi"). Versioned URLs make a release invalidate exactly the art it changed.
    figure = ("/chibi.png?v=%s" % VERSION if _web_chibi_bytes() is not None
              else "/mark.png?v=%s" % VERSION)
    return (WEB_PAGE.replace("{{VERSION}}", VERSION)
                    .replace("{{RELEASE_URL}}", _release_page_url())
                    .replace("{{THEME_COLOR}}", _web_theme_vars()["--bg"])
                    .replace("{{EMPTY_ART}}", figure)
                    .replace("{{BACKDROP}}", _web_backdrop_html()))


def _web_manifest():
    """The manifest JSON, with the theme's background/theme colour."""
    bg = _web_theme_vars()["--bg"]
    return json.dumps(dict(WEB_MANIFEST, background_color=bg, theme_color=bg))


def _web_chibi_bytes():
    """The page's CHIBI - the character - or None when the host ships none."""
    path = BASE_DIR / "assets" / "page-chibi.png"
    try:
        data = path.read_bytes()
        if data.startswith(b"\x89PNG\r\n\x1a\n"):
            return data
        log.warning("assets/page-chibi.png is not a PNG - serving no chibi")
    except OSError:
        pass
    return None


def _web_icon_bytes():
    """The page's icon: the host's own assets/page-icon.png, else the built-in one.

    The shipped file is derived from the same badge master the terminal's rail art comes
    from (maintenance/make-brand-art.py --page-icon), so the tab, the home-screen icon
    and the rail all show one emblem - and a host that wants different art drops its own
    PNG at that path, no code and no restart of anything but the page's cache.
    """
    path = BASE_DIR / "assets" / "page-icon.png"
    try:
        data = path.read_bytes()
        if data.startswith(b"\x89PNG\r\n\x1a\n"):
            return data
        log.warning("assets/page-icon.png is not a PNG - serving the built-in icon")
    except OSError:
        pass
    return base64.b64decode(WEB_ICON_PNG_B64)


def _web_mark_bytes():
    """The page's MARK: the same emblem with a transparent plate.

    Two files because they answer two different questions: an apple-touch icon is
    composited by the OS (white or black under transparency), while the header and the
    empty state sit ON the page's own background and want no square edge. Absent art
    falls back to the built-in icon, which is opaque - a mark with a plate still beats a
    broken image.
    """
    path = BASE_DIR / "assets" / "page-mark.png"
    try:
        data = path.read_bytes()
        if data.startswith(b"\x89PNG\r\n\x1a\n"):
            return data
        log.warning("assets/page-mark.png is not a PNG - serving the built-in icon")
    except OSError:
        pass
    return base64.b64decode(WEB_ICON_PNG_B64)


def _web_command(text, key="web"):
    """Slash commands for the web UI / gateway. Returns ('reply', msg) when
    handled locally, or ('task', text) to hand to the agent."""
    text = cmdr_strip(text)          # `/tinycmdr <cmd>`: the commands, namespaced
    low = text.strip().lower()
    if low in ("/new", "/reset"):
        AGENT.reset(key)
        return ("reply", "🔄 Session cleared. Fresh context.")
    if low == "/model" or low.startswith("/model "):
        parts = text.strip().split(maxsplit=1)
        return ("reply", model_command(key, parts[1] if len(parts) > 1 else ""))
    if low == "/restart" or low.startswith("/restart "):
        # no channel to announce into, so a web restart is logged only
        threading.Thread(target=perform_restart, args=(None, None, "web-ui"),
                         daemon=True).start()
        return ("reply", "♻️ Restarting — the bot replaces itself in a few "
                         "seconds; reload this page after that.")
    if low == "/version":
        return ("reply", f"tinycmdr v{VERSION}")
    if low == "/status":
        return ("reply", status_text(key))
    if low == "/undo" or low.startswith("/undo "):
        parts = low.split()
        try:
            n = int(parts[1]) if len(parts) > 1 else 1
        except ValueError:
            n = 1
        removed = AGENT.undo(key, max(1, min(n, 50)))
        return ("reply", f"↩️ Removed {removed} exchange(s)." if removed
                else "Nothing to undo.")
    if low == "/retry":
        last = AGENT.pop_last_user(key)
        if last is None:
            return ("reply", "Nothing to retry.")
        if not isinstance(last, str):
            last = "\n".join(p.get("text", "") for p in last
                             if isinstance(p, dict))
        return ("task", last)
    if low == "/stop":
        # The page's Stop button only works while that tab still knows its run
        # id; after a reload (or from a second tab) there was no way to stop a
        # live run at all. /stop cancels whatever is running in this session.
        run = _web_active_run(key)
        if run is None:
            return ("reply", "Nothing is running.")
        run.cancel.set()
        run.add("system", "stop requested")
        return ("reply", "🛑 Stop requested — the current step finishes first.")
    if low == "/help":
        return ("reply",
                "Commands:\n"
                + "\n".join(f"{c} — {h}" for c, h in WEB_COMMANDS)
                + "\nEverything else is a task for the agent.")
    if cmdr_legacy_prefix(text):
        return ("reply", CMDR_MOVED)
    if low.startswith("/"):
        return ("reply", "Unknown command — try %s help." % CMDR)
    return ("task", text)

# This box's own names: loopback/hostname/web.host immediately, the resolver's answers
# (getfqdn hits DNS) merged in from a background thread - never on a request's path.
_WEB_HOSTS_CACHE = None
_WEB_HOSTS_WARM = None


def _web_local_hosts():
    """Every name THIS box answers to: loopback, its own host name, its own addresses.

    The page's Host check exists so a hostile site cannot POST into a loopback page
    It allowed loopback names plus `web.host` when that was a specific
    name - and NOTHING when it was `0.0.0.0`, which is exactly what all three installers
    write for "Should the page be reachable from other machines on your network?" (yes).
    So the installer promised a page you could reach, and the server refused every request
    to it: `forbidden: cross-origin or unexpected Host` on the box's own LAN address, found by
    the operator on 2026-09-28, ~11 releases after both halves were written a day apart.

    A Host that names this box is not a threat - the Origin rule below is what carries CSRF
    protection - it is the door being used the way the installer said it could be.

    The RESOLVER is not on the request path any more. `getfqdn`/`gethostbyname_ex` can
    take seconds (measured: >5s on a macOS CI runner, which made the first request to a
    freshly started server time out), and this function is called per request. The cheap
    names - loopback, the hostname, `web.host` when it is one - are always available; the
    resolved set is merged in from a background thread, and `_web_hosts_settled()` waits
    for it only when a request carries a Host that is not already known.
    """
    global _WEB_HOSTS_CACHE, _WEB_HOSTS_WARM
    if _WEB_HOSTS_CACHE is None:
        names = {"127.0.0.1", "localhost", "::1"}
        try:
            names.add(socket.gethostname().strip().lower())
        except Exception:                                    # noqa: BLE001
            pass
        _WEB_HOSTS_CACHE = names
    if _WEB_HOSTS_WARM is None:
        _WEB_HOSTS_WARM = threading.Thread(target=_web_hosts_resolve, daemon=True,
                                           name="web-hosts")
        _WEB_HOSTS_WARM.start()
        _WEB_HOSTS_CACHE.update(_web_hosts_configured())
    return set(_WEB_HOSTS_CACHE)


def _web_hosts_configured():
    """`web.host`, when it names ONE host - the name the operator bound to."""
    configured = str((CONFIG.get("web") or {}).get("host") or "").strip().lower()
    if configured and configured not in ("0.0.0.0", "::"):
        return {configured.rsplit(":", 1)[0].strip("[]")}
    return set()


def _web_authority(authority):
    """(host, port) for a Host header or an Origin authority.

    A missing port stays "" on both sides, so what is compared is exactly what the
    client addressed. IPv6 literals may or may not carry their brackets. A trailing
    dot is the FQDN spelling of the same host (`127.0.0.1.` is `127.0.0.1`), so it is
    dropped before the compare - a bookmark or link that gained the dot is not a
    different name (A-217).
    """
    a = (authority or "").strip().lower()
    if a.startswith("["):
        host, _, rest = a.partition("]")
        return host[1:].rstrip("."), rest.lstrip(":")
    host, sep, port = a.rpartition(":")
    if not sep or ":" in host:              # no colon, or a bare (bracketless) IPv6
        return a.rstrip("."), ""
    return host.rstrip("."), port


def _web_hosts_resolve():
    """The names that need the resolver, merged into the cache when they land."""
    extra = set()
    try:
        host = socket.gethostname()
        fq = socket.getfqdn(host)
        if fq:
            extra.add(fq.strip().lower())
        for ip in socket.gethostbyname_ex(host)[2]:
            extra.add(str(ip).strip().lower())
    except Exception:                                        # noqa: BLE001
        pass
    if _WEB_HOSTS_CACHE is not None:
        _WEB_HOSTS_CACHE.update(extra)


def _web_hosts_settled(timeout=3.0):
    """Wait for the resolver, ONCE, for a Host the fast set does not know.

    A LAN visitor's first request can arrive before the background resolve has
    finished; refusing it would be a wrong answer, not a safe one. Waiting here costs
    nothing on the common path (loopback is in the fast set, so this is never called),
    and it is capped short: an unknown Host - a hostile one, or a scanner - must not tie
    a handler thread for long (measured: a 5s cap made a foreign-Host check on a slow
    resolver take exactly that long).
    """
    if _WEB_HOSTS_WARM is not None:
        _WEB_HOSTS_WARM.join(timeout)
    return set(_WEB_HOSTS_CACHE or ()) | _web_hosts_configured()

def health_payload():
    """What a monitor should read, answering "can it hear me?" rather than "is the HTTP
    server up".

    HTTP stays 200 even when `ok` is false, on purpose: the installers and the macOS restart
    door probe this endpoint with `curl -sf`, and turning a dead chat lane into a failing HTTP
    probe would break the very commands that bring a box back. The door with an exit code is
    `tinycmdr health`.
    """
    lanes = lanes_snapshot()
    return {
        "ok": all(v["state"] != "failed" for v in lanes.values()),
        "version": VERSION,
        "pid": os.getpid(),
        "lanes": lanes,
        # Not folded into `ok`: a pending restart is not a dead lane, but a reader deciding
        # whether to believe this page needs it.
        "config_changed": config_drift(),
    }


def run_webui():
    """Start the local web UI (chat + live run view + /api/health) on a
    daemon thread.  No-op if disabled.  Returns the server so a caller that
    owns the process (--web) can hold it open, and so tests can read the
    bound port."""
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

    class QuietServer(ThreadingHTTPServer):
        """ThreadingHTTPServer that does not scream when a client hangs up.

        A browser tab closed mid-poll, or a caller that stops reading because it
        already has what it wanted, makes the handler's write fail with
        ConnectionAbortedError.  The stock server prints a full traceback for
        that, which reads like a crash in the agent's own log.  Clients leaving
        is normal; log it as one line and keep serving."""

        daemon_threads = True
        # SO_REUSEADDR means two DIFFERENT things: on POSIX it only relaxes the TIME_WAIT
        # rebind a restart needs, while on Windows it lets a SECOND process bind a port
        # that is already served - measured 2026-09-22, `tinycmdr web` shared 8787 with the
        # running bot's page, so the operator saw a banner for a page that was already up
        # and two servers shared one port. On where it only helps, off where it bit, and
        # the retry loop below still covers the second or two after a restart.
        allow_reuse_address = os.name != "nt"

        # One thread per connection with no ceiling means a LAN peer can stack
        # threads up to the box's limit (2026-09-23). Count the
        # live handlers and refuse past a modest cap; a refused connection never
        # spawns a thread, and the counter drops when a handler thread ends.
        MAX_CONN = 32
        # A SECOND, larger cap for the exempt peers above (A-212/A-213). Exempting
        # loopback removed the ceiling entirely: any local process - including one the
        # agent itself starts - could hold as many 60-second handler threads as it could
        # open sockets (measured 2026-10-06: 48 simultaneous local connections were all
        # served and _conn_live reached 48). This keeps `curl -sf` from a busy box working
        # while still bounding the thread count; a refusal past it is the same 503.
        MAX_CONN_EXEMPT = 256
        _conn_lock = threading.Lock()
        _conn_live = 0

        def process_request(self, request, client_address):
            # Loopback callers are exempt from the LAN cap: they are already ON the box
            # (the same trust boundary as this process), and they are the ones that probe
            # /api/health - the installers, the restart doors, curl from a terminal.
            # Counting them made a busy server read as a DEAD one to `curl -sf`, which is
            # the answer the restart path must never get wrong (measured 2026-10-05: 40
            # idle sockets aborted the health probe mid-connection). They are not exempt
            # from ALL limits: past MAX_CONN_EXEMPT they hear the same 503, so the thread
            # count stays bounded even locally (A-213). A LAN peer stays capped at
            # MAX_CONN - that is the 2026-09-23 thread-stacking incident - and hears BUSY
            # in HTTP instead of a bare close, so a monitor can tell it apart from a dead
            # box.
            peer = str((client_address or ("",))[0])
            exempt = peer in ("127.0.0.1", "::1", "::ffff:127.0.0.1")
            cap = self.MAX_CONN_EXEMPT if exempt else self.MAX_CONN
            with self._conn_lock:
                if self._conn_live >= cap:
                    log.info("web: refused a connection, %d already open",
                             self._conn_live)
                    try:
                        request.sendall(b"HTTP/1.1 503 Service Unavailable\r\n"
                                        b"Retry-After: 1\r\n"
                                        b"Content-Length: 0\r\n"
                                        b"Connection: close\r\n\r\n")
                    except OSError:
                        pass
                    request.close()
                    return
                self._conn_live += 1
            try:
                super().process_request(request, client_address)
            except Exception:
                with self._conn_lock:
                    self._conn_live -= 1
                raise

        def process_request_thread(self, request, client_address):
            try:
                super().process_request_thread(request, client_address)
            finally:
                with self._conn_lock:
                    self._conn_live -= 1

        def handle_error(self, request, client_address):
            err = sys.exc_info()[1]
            if isinstance(err, (ConnectionError, BrokenPipeError,
                                ConnectionResetError, ConnectionAbortedError,
                                TimeoutError)):
                log.info("web client hung up before the reply finished (%s)",
                         type(err).__name__)
                return
            log.error("web request failed: %s", err, exc_info=True)

    web = CONFIG.get("web") or {}
    if not web.get("enabled", True):
        return None
    # The token is MANDATORY. The removed lane treated "no token" as "loopback, open
    # to any page on this machine" - which is CSRF against shell access
    # - and one flag path left the port serving with no token at all. No token,
    # no server: the installer mints one and `tinycmdr token set TINYCMDR_WEB_TOKEN`
    # rotates it.
    token = str(web.get("token") or os.environ.get("TINYCMDR_WEB_TOKEN") or "").strip()
    if not token:
        log.error("web UI not started: no token. Mint one with `tinycmdr token set "
                  "TINYCMDR_WEB_TOKEN` (or set web.enabled: false).")
        lane_down("web", "no token configured")
        return None

    class Handler(BaseHTTPRequestHandler):
        # HTTP/1.1, so the page's poll reuses ONE connection instead of paying a
        # fresh TCP handshake and thread for every /api/events request: this class
        # defaulted to HTTP/1.0, which closes after each reply (A-202, measured
        # 2026-10-06: a pipelined second GET got no answer at all). Keep-alive is
        # only safe because every response path sends an exact Content-Length and
        # every request body is either fully read or the connection is closed -
        # an undrained body would be parsed as the NEXT request line.
        protocol_version = "HTTP/1.1"
        # a peer that sends a request line and never finishes the headers or the
        # body is cut off by the socket timeout, so one silent client cannot
        # hold a handler thread (2026-09-23)
        timeout = 60
        _body_taken = False     # this request's body has been read or closed off
        _head_only = False      # do_HEAD runs the GET routing with the body dropped
        _body_got = "no body"   # what _body() found, for the 400 that names the shape
        _body_code = 400        # the status a refused body deserves (400/408/411/413)
        _cookie_given = False   # this request carried a tinycmdr_token cookie
        _refuse_why = "host"    # which _origin_ok rule refused this request
        _refuse_origin = ""     # the Origin that did not match, for the 403

        def handle_one_request(self):
            """Reset the per-REQUEST state the last request on this connection left.

            One Handler instance serves EVERY request on a kept-alive connection
            (protocol_version above), and every flag here is set on `self`: a flag the
            previous request set was read as this one's. Measured 2026-10-07: the first
            GET /api/health drains (and so sets `_body_taken`), the next POST /api/run
            was refused 401 without reading its body - `_drain` returned at once,
            believing the body was already accounted for - and the leftover bytes were
            parsed as the NEXT request line: the third request on that connection got
            Python's stock 501 and the socket closed, while both earlier ones were
            healthy."""
            self._body_taken = False
            self._head_only = False
            self._body_got = "no body"
            self._body_code = 400
            self._cookie_given = False
            self._refuse_why = "host"
            self._refuse_origin = ""
            super().handle_one_request()

        def log_message(self, *a):
            pass

        def _write(self, data):
            """The response body, dropped for HEAD.

            A HEAD answer is exactly the GET headers - status, Content-Type and
            Content-Length included - with no body (A-203)."""
            if not self._head_only:
                self.wfile.write(data)

        def _asset(self, ctype, path, getter, max_age, fallback=""):
            """One static asset: an ETag, a conditional request and a guarded read.

            Five routes re-read their file on every request with no validator, and the
            font route read it OUTSIDE any try, so a file that vanished between the
            exists() check and the read raised out of the handler and the client got
            zero bytes (A-252/A-253). Here the ETag comes from the file's mtime and
            size - a stat, not a read - so a warm tab's revalidation is answered 304
            without touching the bytes, and `getter` runs inside the try that turns a
            vanished file into a 404 instead of a dropped connection. `fallback` names
            the ETag for byte-but-no-file assets (the built-in art, the versioned CSS).
            """
            etag = None
            if path is not None:
                try:
                    st = path.stat()
                    etag = '"%x-%x"' % (st.st_mtime_ns, st.st_size)
                except OSError:
                    etag = None
            if etag is None:
                etag = '"%s"' % (fallback or "builtin")
            # max-age=0 with must-revalidate: the asset IS stored, but is stale at
            # once, so every use revalidates. The page and its stylesheet must not be
            # served from a stale cache (a fixed server beside yesterday's client reads
            # as "still broken"), and with the ETag that revalidation is a 304 - not a
            # re-read and a re-template (A-254).
            cache = ("max-age=0, must-revalidate" if max_age <= 0
                     else "max-age=%d" % max_age)
            if (self.headers.get("If-None-Match") or "").strip() == etag:
                self.send_response(304)
                self.send_header("ETag", etag)
                self.send_header("Cache-Control", cache)
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            try:
                data = getter()
            except OSError:
                data = None
            if data is None:
                self._send("not found", 404, "text/plain")
                return
            if isinstance(data, str):          # the stylesheet is text; art is bytes
                data = data.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", cache)
            self.send_header("ETag", etag)
            self.end_headers()
            self._write(data)

        def _send(self, body, code=200, ctype="text/html; charset=utf-8", extra=None):
            data = body.encode()
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            # The page IS the application: a cached copy means the browser keeps
            # running yesterday's client after the server was fixed, which is
            # how a real fix gets reported as "still broken". Poll responses too.
            self.send_header("Cache-Control", "no-store, must-revalidate")
            self.send_header("Content-Length", str(len(data)))
            if self.close_connection:
                # A reply that will be followed by a close must SAY so: on keep-alive
                # (A-202) a client that cannot see the close would reuse a socket the
                # server is about to drop. Set by _drain/_body for a refused or
                # unreadable body, where leftover bytes make reuse unsafe (A-207).
                self.send_header("Connection", "close")
            for name, value in (extra or ()):
                self.send_header(name, value)
            self.end_headers()
            self._write(data)

        def _json(self, obj, code=200, extra=None):
            if code == 401 and self._cookie_given:
                # A cookie was presented and did not authenticate - usually a token
                # rotated with `tinycmdr token set` while this browser still held the
                # old one. Nothing used to clear it, so the browser kept sending a
                # stale value and 401'd until the page's own boot dance ran (A-221);
                # Max-Age=0 drops it, and the page then asks for the new token.
                extra = list(extra or ()) + [
                    ("Set-Cookie", "tinycmdr_token=; Path=/; HttpOnly; "
                                   "SameSite=Strict; Max-Age=0")]
            # ensure_ascii=False: JSON is UTF-8 by definition, and escaping every emoji
            # and every CJK character to \uXXXX cost six bytes each on the routes the
            # page polls several times a second (A-261, measured 2026-10-06: a /new
            # reply was "\\ud83d\\udd04 Session cleared...").
            self._send(json.dumps(obj, ensure_ascii=False), code, "application/json",
                       extra=extra)

        def _file(self, path):
            """Stream an OFFERED file to the token holder, as an attachment.

            Only a file the agent attached (a line of kind 'file' in a live or kept
            run) can reach here: there is no path browser, and anything else is 404.
            A `Range: bytes=a-b` is honoured, so a download that drops at 99% resumes
            where it stopped instead of starting from zero (A-250, measured
            2026-10-06: the header was ignored and the whole body re-sent)."""
            try:
                size = path.stat().st_size
            except OSError:
                self._json({"error": "the file is gone"}, 404)
                return
            if size > SEND_FILE_MAX:
                self._json({"error": "file too large to serve"}, 413)
                return
            start, end, code = 0, size - 1, 200
            m = re.match(r"bytes=(\d*)-(\d*)\s*$",
                         (self.headers.get("Range") or "").strip())
            if m and (m.group(1) or m.group(2)):
                if m.group(1):
                    start = int(m.group(1))
                    end = int(m.group(2)) if m.group(2) else size - 1
                else:
                    # a suffix range: the LAST N bytes
                    start = max(0, size - int(m.group(2)))
                    end = size - 1
                end = min(end, size - 1)
                if start > end or start >= size:
                    self._json({"error": "range not satisfiable", "size": size}, 416,
                               extra=[("Content-Range", "bytes */%d" % size)])
                    return
                code = 206
            # Open it BEFORE the headers go out: a path that stat()s and then cannot be
            # read - a directory line in a run log that predates attach() refusing them,
            # a file that vanishes or loses its mode in the gap - used to be given a
            # Content-Length with no body, which leaves the operator's fetch hanging and
            # parks this handler thread on the socket until its 60s timeout. Same shape
            # A-252/253 fixed in _asset: a failure is ANSWERED, never promised.
            try:
                fh = open(path, "rb")
            except OSError as e:
                self._json({"error": "the file cannot be read", "got": str(e)}, 404)
                return
            try:
                fh.seek(start)
                self.send_response(code)
                self.send_header("Content-Type", "application/octet-stream")
                self.send_header("Content-Length", str(end - start + 1))
                self.send_header("Accept-Ranges", "bytes")
                if code == 206:
                    self.send_header("Content-Range",
                                     "bytes %d-%d/%d" % (start, end, size))
                self.send_header("Content-Disposition",
                                 _web_filename_header(path.name))
                self.end_headers()
                if self._head_only:
                    return              # HEAD: the headers are the whole answer
                left = end - start + 1
                while left > 0:
                    chunk = fh.read(min(65536, left))
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    left -= len(chunk)
            except (BrokenPipeError, ConnectionError, OSError):
                pass
            finally:
                fh.close()

        def _auth_ok(self):
            # compare_digest, not ==: this token is shell and code execution on
            # this box, and a plain compare leaks its prefix through response
            # timing (2026-09-23). Bytes on both sides so a
            # header carrying non-ASCII can never raise here.
            # The header is what every non-browser caller uses (the probes, curl, the
            # installer). A BROWSER gets an HttpOnly cookie from /api/login instead, so
            # the token stops living in its URL and its localStorage - see the page's
            # boot: it hands the fragment over once and forgets it.
            given = self.headers.get("X-Tinycmdr-Token") or ""
            if not given:
                authz = self.headers.get("Authorization") or ""
                if authz.lower().startswith("bearer "):
                    # A2A peers authenticate the standard way (web.a2a); it is the
                    # SAME page token, and the published card says so.
                    given = authz[7:].strip()
            if not given:
                for part in (self.headers.get("Cookie") or "").split(";"):
                    name, _, value = part.strip().partition("=")
                    if name == "tinycmdr_token":
                        given = value
                        self._cookie_given = True      # so a 401 can clear a stale one
                        break
            return hmac.compare_digest(
                given.encode("utf-8", "replace"), token.encode("utf-8"))

        def _origin_ok(self):
            """Same-origin/Host check for EVERY route.

            The token is mandatory; this rule is defence in depth on top of it. Host must
            be a loopback name (or the configured bind host), and an Origin header, when
            the browser sends one, must match that host AND its port (cookies are
            host-scoped, so the port is part of the check). curl, the installer's probe
            and the supervisor send no Origin and keep working; an opaque "null" origin
            (a file:// page, a sandboxed iframe) is refused.
            """
            host_hdr = (self.headers.get("Host") or "").strip().lower()
            # _web_authority, not rsplit: a bare IPv6 Host ("[::1]", no port - what a
            # proxy or an HTTP/1.0 client sends) was parsed to "" and refused, and a
            # trailing dot ("127.0.0.1.", the FQDN form a bookmark or link can gain)
            # came back different from the name this box answers to (A-216/A-217,
            # measured 2026-10-06: both were 403).
            name = _web_authority(host_hdr)[0]
            # This box's own names answer the question "did you address me?"; `web.host`,
            # when it names one host, is an extra name the operator chose.
            allowed = _web_local_hosts()
            if name not in allowed:
                # A name the fast set does not know may be the box's own LAN address,
                # still being resolved in the background: settle it once before refusing.
                allowed = _web_hosts_settled()
            configured = str((CONFIG.get("web") or {}).get("host") or "").strip().lower()
            if configured and configured not in ("0.0.0.0", "::"):
                allowed.add(configured.rsplit(":", 1)[0].strip("[]"))
            if name not in allowed:
                log.warning("web: refused a request with Host %r (not a loopback/"
                            "configured name)", host_hdr)
                self._refuse_why = "host"
                return False
            origin = (self.headers.get("Origin") or "").strip()
            if not origin:
                return True                     # curl, the installer, the supervisor
            # The FULL authority, port included. Cookies are bound to the host, not the
            # port, so a page served from another port of this same name still carries
            # the session cookie - and the host-only compare let it drive the API
            # (measured 2026-10-05 with a real browser: a page on 127.0.0.1:8799 created
            # a conversation through /api/sessions with the operator's HttpOnly cookie;
            # the same request to /api/chat is shell access).
            oauth = origin.split("://", 1)[-1].split("/", 1)[0].lower()
            if _web_authority(oauth) == _web_authority(host_hdr):
                return True
            log.warning("web: refused a cross-origin request (Origin %r, Host %r)",
                        origin, host_hdr)
            self._refuse_why = "origin"
            self._refuse_origin = origin
            return False

        def _forbidden(self):
            self._drain()
            # Say what WOULD work. The old body was four words of jargon, and the operator
            # who hit it (2026-09-28, browsing to a live install by IP) had no way to learn
            # that the page accepts only particular names - or which.
            # `accepts` stays (an operator diagnostic, A-38). The live PORT and the
            # copy-pasteable tunnel recipe that used to ride along do NOT: this body is
            # built before auth, so one unauthenticated request mapped the box and handed
            # out the port to tunnel to (A-215, measured 2026-10-06). `tinycmdr web`
            # prints the tunnel command locally, where the operator already is.
            payload = {
                "error": "forbidden: unexpected Host, or a cross-origin request",
                "host": (self.headers.get("Host") or ""),
                "accepts": ", ".join(sorted(_web_local_hosts())),
            }
            if self._refuse_why == "origin":
                # A reverse proxy on port 80 presents an Origin without the page's port
                # while Host carries it, and the old body only suggested `web.host`, which
                # never clears this (A-219, measured 2026-10-06). Name the disagreement.
                origin = self._refuse_origin or (self.headers.get("Origin") or "")
                payload["reason"] = ("the Origin (%s) and the Host (%s) disagree; a "
                                     "reverse proxy must forward both unchanged, port "
                                     "included" % (origin,
                                                   self.headers.get("Host") or ""))
                payload["fix"] = ("load the page by the address in `accepts` (its Origin "
                                  "and Host then agree), or have the proxy pass an Origin "
                                  "that matches the Host it sends - same name AND port.")
            else:
                payload["reason"] = ("the Host (%s) is not a name this box answers to"
                                     % (self.headers.get("Host") or ""))
                payload["fix"] = ("browse this box by one of `accepts`, or make the name "
                                  "you use one of them: `tinycmdr config set web.host "
                                  "<name-or-ip>` then restart.")
            self._json(payload, 403)

        # -- routing ------------------------------------------------------

        def _query(self):
            """?a=b&c=d as a dict, with each key and value percent-decoded.

            The page builds every URL with encodeURIComponent, so a search term or a
            filename with an accent or a space arrives percent-encoded. The old
            "%20-only" replace matched it against its own encoding (A-223, measured
            2026-10-06: ?q=caf%C3%A9 echoed caf%C3%A9, ?q=hello+world kept the +). A
            duplicated key keeps its FIRST value - what a proxy or a log line shows -
            instead of the last (A-224).
            """
            from urllib.parse import unquote_plus
            if "?" not in self.path:
                return {}
            out = {}
            for pair in self.path.split("?", 1)[1].split("&"):
                if "=" in pair:
                    k, v = pair.split("=", 1)
                    k, v = unquote_plus(k), unquote_plus(v)
                elif pair:
                    k, v = unquote_plus(pair), ""
                else:
                    continue
                if k not in out:
                    out[k] = v
            return out

        def _target_ok(self):
            """The request-target bound (A-226), checked before any routing branch.

            The chain below runs startswith() over self.path for every branch, so a huge
            target is unbounded work a token-less peer can ask for (measured 2026-10-06:
            a 9,000-character path walked the whole chain before the 404). 414 names it.
            """
            if len(self.path) <= WEB_TARGET_MAX:
                return True
            self._drain()
            self._json({"error": "request target too long", "max": WEB_TARGET_MAX}, 414)
            return False

        def do_GET(self):
            if not self._target_ok():
                return
            # A GET carries no body, but if one is announced it must still be read
            # or the connection closed: on HTTP/1.1 keep-alive (A-202) those bytes
            # would be parsed as the next request line. `_drain` is idempotent and a
            # no-op for the ordinary body-less GET.
            self._drain()
            if not self._origin_ok():
                self._forbidden()
                return
            if self.path.startswith("/api/health"):
                self._json(health_payload())
            elif self.path.startswith("/.well-known/agent-card.json"):
                # The A2A card (web.a2a): public metadata and no token - it names no
                # secret, and a peer has to read it before it can authenticate. Every
                # other route on this server stays token-gated, /a2a included.
                if not (CONFIG.get("web") or {}).get("a2a"):
                    self._json({"error": "not found"}, 404)
                    return
                self._json(a2a_card())
            elif self.path.startswith("/api/events"):
                if not self._auth_ok():
                    self._drain()
                    self._json({"error": "unauthorized"}, 401)
                    return
                q = self._query()
                run = WEB_RUNS.get(q.get("run_id", ""))
                if run is None:
                    self._json({"error": "no such run"}, 404)
                    return
                try:
                    since = int(q.get("since", "0"))
                except ValueError:
                    since = 0
                try:
                    rev = int(q.get("rev", "0"))
                except ValueError:
                    rev = 0
                self._json(run.view(since, rev))
            elif self.path.startswith("/api/search"):
                # The page's SEARCH: inside conversations, not just their titles
                # (operator, 2026-10-04). Same corpus and rules as the model's
                # search_sessions tool (session_search_hits), with the rail's own titles
                # attached so a result reads like a conversation. Two characters is the
                # floor: a 1-char query matches everything and costs a full scan.
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                _q = self._query().get("q") or ""
                q = (_q[0] if isinstance(_q, list) else _q) or ""
                if len(str(q).strip()) < 2:
                    self._json({"query": q, "matches": []})
                    return
                titles = {s.get("key"): (s.get("title") or "")
                          for s in web_sessions(_web_client(self.headers), True)}
                self._json({"query": q, "matches": [
                    {"key": key, "role": role,
                     # a snippet is a QUOTE, but emphasis markers read as noise in a
                     # narrow rail; the model's tool output keeps them
                     "snippet": re.sub(r"\*\*|`", "", snippet),
                     "title": titles.get(key) or key}
                    for key, role, snippet, _rank in session_search_hits(q, 20)]})
            elif self.path.startswith("/api/sessions"):
                # The rail: what conversations this browser has, newest first.
                # ?all=1 is the token holder's view of EVERY conversation on this
                # host, which is what the operator uses on their own box - and it
                # is an EXPOSURE the shared view is accepted for: any holder of the
                # page token sees every conversation's key, title and last-active
                # (A-236). Mutation stays scoped to the owning client (A-235); the
                # page's toggle title says exactly what this view is.
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                q = self._query()
                client = _web_client(self.headers)
                self._json({"sessions": web_sessions(client, q.get("all") == "1"),
                            "open": web_resolve_session(client, q.get("session")),
                            "client": client, "budget": AGENT._context_budget(),
                            "host": socket.gethostname(), "version": VERSION})
            elif self.path.startswith("/api/session?"):
                # One conversation as ordered line lists per run - what a reload
                # paints, so a browser that lost its localStorage still sees the
                # conversation and can go on with it instead of a blank page.
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                q = self._query()
                client = _web_client(self.headers)
                key = web_resolve_session(client, q.get("key") or q.get("session"))
                out = web_transcript(key)
                out["key"] = key
                self._json(out)
            elif self.path.startswith("/api/live"):
                # A page that just loaded (reload, second tab, phone waking up)
                # has no run id and used to guess: it posted a message, which
                # the server turned into a steer of the run already going, and
                # the operator saw their message twice in the transcript. Ask
                # instead, then re-attach to that run and keep polling it.
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                q = self._query()
                live = _web_active_run(
                    web_resolve_session(_web_client(self.headers),
                                        q.get("session")))
                self._json({"run_id": live.id if live else None})
            elif self.path.startswith("/api/commands"):
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                client = _web_client(self.headers)
                q = self._query()
                self._json({"commands": web_commands(q.get("prefix")),
                            "session": web_resolve_session(client, q.get("session"))})
            elif self.path.startswith("/api/tasks"):
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                self._json(web_tasks_view())
            elif self.path.startswith("/api/jobs"):
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                self._json(web_jobs_view())
            elif self.path.startswith("/api/login"):
                # The page's probe (GET): 200 when this browser already authenticates
                # (the HttpOnly cookie the handover set), 401 when it must be asked.
                # POST does the handover itself, in the POST chain - and this branch
                # must sit ABOVE /api/log, whose prefix would otherwise swallow
                # /api/login (tests/test_contracts.py grades the whole ordering class).
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                self._json({"ok": True})
            elif self.path.startswith("/api/log"):
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                self._json(web_log_tail(self._query().get("lines")))
            elif self.path.startswith("/api/inventory"):
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                self._json(web_inventory())
            elif self.path.startswith("/api/download"):
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                q = self._query()
                # _query() has already percent-decoded both values, so no second
                # unquote here (a name holding a literal "%2F" must not become "/").
                run = WEB_RUNS.get(str(q.get("run") or ""))
                uid = str(q.get("uid") or "")
                line = None
                if run is not None:
                    with run.lock:
                        line = next((l for l in run.lines if l.get("uid") == uid), None)
                if line is None or line.get("kind") != "file":
                    self._json({"error": "no such file"}, 404)
                    return
                self._file(Path(str(line.get("text") or "")))
            elif self.path.startswith("/manifest.webmanifest"):
                self._send(_web_manifest(), 200, "application/manifest+json")
            elif self.path.startswith("/icon.png"):
                self._asset("image/png", BASE_DIR / "assets" / "page-icon.png",
                            _web_icon_bytes, 86400, fallback="icon-" + VERSION)
            elif self.path.startswith("/mark.png"):
                self._asset("image/png", BASE_DIR / "assets" / "page-mark.png",
                            _web_mark_bytes, 86400, fallback="mark-" + VERSION)
            elif self.path.startswith("/chibi.png"):
                self._asset("image/png", BASE_DIR / "assets" / "page-chibi.png",
                            _web_chibi_bytes, 86400, fallback="chibi-" + VERSION)
            elif self.path.startswith("/fonts/"):
                name = self.path.split("/fonts/", 1)[1].split("?", 1)[0]
                path = _web_font_path(name)
                if path is None:
                    self._send("not found", 404, "text/plain")
                else:
                    # the fonts are ours and immutable: a week is safe, they never change
                    # under a running page (a release writes new bytes, new generation)
                    self._asset("font/woff2", path, path.read_bytes, 604800,
                                fallback="font-" + name)
            elif self.path.startswith("/page.css"):
                # max-age 0: kept, but revalidated before EVERY use. A stale stylesheet
                # (or page) reads as "still broken" after a fix, so it must not be
                # served from cache - and with the ETag the revalidation is a 304, not
                # a re-read and a re-template (A-254).
                self._asset("text/css; charset=utf-8",
                            BASE_DIR / "assets" / "webui.css", _web_page_css, 0,
                            fallback="css-" + VERSION)
            elif self.path.startswith("/temple.jpg"):
                self._asset("image/jpeg",
                            BASE_DIR / "assets" / "roman-temple-spring.jpg",
                            _web_temple_bytes, 86400, fallback="temple-" + VERSION)
            elif self.path == "/" or self.path.startswith("/?"):
                self._send(_web_page_html())
            else:
                self._send("not found", 404, "text/plain")

        def do_HEAD(self):
            """HEAD runs the SAME routing as GET and throws the body away.

            `curl -I` (what most uptime checkers and the restart probes use) hit
            Python's stock 501 for an unknown method, so a healthy bot read as dead
            (A-203). The status line, Content-Type and Content-Length are the GET
            ones - `_write` drops only the body - so a checker sees exactly what a
            GET would answer."""
            self._head_only = True
            try:
                self.do_GET()
            finally:
                self._head_only = False

        def _refuse_method(self, method):
            """A method this server does not serve, refused in the API's own shape.

            Python's stock 501 is an HTML error page, which a JSON client cannot
            read (A-204/A-205)."""
            self._drain()
            self._json({"error": "method not allowed",
                        "method": method,
                        "allows": "GET, HEAD, POST, OPTIONS"}, 405,
                       extra=[("Allow", "GET, HEAD, POST, OPTIONS")])

        def do_OPTIONS(self):
            self._refuse_method("OPTIONS")

        def do_PUT(self):
            self._refuse_method("PUT")

        def do_DELETE(self):
            self._refuse_method("DELETE")

        def do_PATCH(self):
            self._refuse_method("PATCH")

        def _body(self):
            """The request body as a JSON OBJECT, or None.

            None means "refuse" (see _need_body), never "silently drop the request".
            `_body_got` names what arrived and `_body_code` is the status the refusal
            deserves, so a caller can tell the answers apart:
              * 411 - a Transfer-Encoding body (chunked is not decoded here, A-207), or
                a Content-Length that is not a count (A-211);
              * 413 - a body over the cap, which says "send less" rather than "your JSON
                is broken" (A-208);
              * 408 - a body that announced bytes and then stalled, which is not a syntax
                error (A-210);
              * 400 - everything else, including a JSON value that is not an object
                (A-206) and malformed JSON.
            """
            self._body_taken = True
            self._body_code = 400
            if (self.headers.get("Transfer-Encoding") or "").strip():
                # Chunked was neither decoded nor refused: the body read as the integer
                # 0, the caller got "empty message", and the chunk bytes stayed in the
                # socket for the next keep-alive request (A-207, measured 2026-10-06).
                # A length is required here; say so, and close so nothing is mis-parsed.
                self.close_connection = True
                self._body_got = "a Transfer-Encoding body (chunked is not supported)"
                self._body_code = 411
                return None
            try:
                length = int(self.headers.get("Content-Length", 0))
            except (TypeError, ValueError):
                self.close_connection = True
                self._body_got = ("a Content-Length that is not a count (%r)"
                                  % (self.headers.get("Content-Length"),))
                self._body_code = 411
                return None
            if length < 0:
                self.close_connection = True
                self._body_got = "a negative Content-Length (%d)" % length
                self._body_code = 411
                return None
            if length > WEB_BODY_MAX:
                # the claimed length is attacker-controlled and both paths
                # ran before the 401 (2026-09-23): a huge
                # claim allocates or blocks, and read(-n) runs to EOF.
                # Read (and drop) what we can, bounded by the cap and under the
                # deadline, so the caller HEARS the refusal instead of a reset.
                try:
                    self.connection.settimeout(WEB_BODY_DEADLINE)
                    self.rfile.read(min(length, WEB_BODY_MAX))
                except Exception:
                    pass
                self.close_connection = True
                self._body_got = "a body over the %d-byte cap" % WEB_BODY_MAX
                self._body_code = 413
                return None
            try:
                # An absolute deadline for THIS read: a client that announces a length and
                # trickles bytes must not hold a worker for the whole socket timeout.
                self.connection.settimeout(WEB_BODY_DEADLINE)
                raw = self.rfile.read(length) or b"{}"
                self._body_got = "body"
                parsed = json.loads(raw)
            except (socket.timeout, TimeoutError):
                self.close_connection = True
                self._body_got = ("a body that stalled (no bytes within %ds)"
                                  % WEB_BODY_DEADLINE)
                self._body_code = 408
                return None
            except Exception as e:
                self._body_got = "an unreadable body (%s)" % type(e).__name__
                return None
            if not isinstance(parsed, dict):
                self._body_got = "a JSON %s" % _json_type_name(parsed)
                return None
            return parsed

        def _need_body(self):
            """The JSON object body, or None after answering with `_body_code`.

            ONE refusal for every JSON route, so a body like `[]` can never reach
            `body.get(...)` and kill the connection (A-206) and the caller is told
            what to send instead - with the status that names the condition (413 too
            big, 408 stalled, 411 no usable length, else 400)."""
            body = self._body()
            if body is None:
                code = self._body_code
                if code == 413:
                    err = {"error": "request body too large", "got": self._body_got,
                           "max": WEB_BODY_MAX, "content_type": "application/json"}
                elif code == 411:
                    err = {"error": "a request body needs a Content-Length",
                           "got": self._body_got, "content_type": "application/json"}
                elif code == 408:
                    err = {"error": "the request body stalled", "got": self._body_got,
                           "content_type": "application/json"}
                else:
                    err = {"error": "expected a JSON object body", "got": self._body_got,
                           "content_type": "application/json"}
                self._json(err, code)
            return body

        def _raw(self, max_bytes):
            """A raw (non-JSON) request body - uploads - with _body's discipline: the
            claimed length is capped BEFORE reading and the read runs under an absolute
            deadline, so a trickling client cannot hold a worker."""
            self._body_taken = True
            try:
                length = int(self.headers.get("Content-Length", 0))
                if not 0 < length <= max_bytes:
                    self.close_connection = True
                    return None
                self.connection.settimeout(WEB_BODY_DEADLINE)
                data = self.rfile.read(length)
                return data if len(data) == length else None
            except Exception:
                return None

        def _drain(self):
            """Read and drop a request body before answering early.

            Answering an unauthorized POST while the caller is still sending the
            body makes Windows abort the connection under the caller (WinError
            10053) instead of delivering the 401, which looks like the server
            crashed rather than refused. Same for a 404 on a POST.

            Idempotent: with HTTP/1.1 keep-alive (A-202) a second read of the same
            Content-Length would block until the socket timeout, waiting for bytes
            that are already gone."""
            if self._body_taken:
                return
            self._body_taken = True
            try:
                if (self.headers.get("Transfer-Encoding") or "").strip():
                    # No Content-Length bounds the read, and the chunk bytes would be
                    # parsed as the next keep-alive request: answer, then close (A-207).
                    self.close_connection = True
                    return
                length = int(self.headers.get("Content-Length", 0) or 0)
                if length < 0:
                    self.close_connection = True
                    return
                if length > 0:
                    self.connection.settimeout(WEB_BODY_DEADLINE)
                    got = self.rfile.read(min(length, WEB_BODY_MAX))
                    # A short read means EOF (or a stall): bytes we did not account for
                    # may remain, so this connection cannot be reused.
                    if len(got) < min(length, WEB_BODY_MAX):
                        self.close_connection = True
                if length > WEB_BODY_MAX:
                    self.close_connection = True
            except Exception:
                # A body we could not read to its end leaves unknown bytes behind; the
                # safe answer is to stop reusing the connection.
                self.close_connection = True

        def _start_run(self, text, key="web", client=""):
            """Kick off a browser run on its own thread; the page polls for
            lines.  One run per CONVERSATION at a time - two conversations may
            both be working, which is what makes parking one and opening another
            possible instead of queueing behind it."""
            web_touch(key)
            run, busy = _web_claim_run(key, client)
            if busy is not None:
                _busy_owner = web_run_owner(busy)
                if _busy_owner and _busy_owner != client:
                    # A reloaded tab of ANOTHER browser is not a second tab of
                    # yours: its text must not be queued into someone else's run.
                    self._json({"error": "that run belongs to another browser on "
                                         "this host - start your own conversation "
                                         "to send it a message"}, 403)
                    return
                # A tab that reloaded (or a second tab) does not know a run is
                # live, and its message used to be dropped on the floor. Queue
                # it into the running run as a steer - what the page does when
                # it does know - and echo it into that run's buffer so it shows.
                with busy.lock:
                    busy.steer.append(text)
                busy.add("you", text + "   (mid-run)")
                log.info("web run %s: message from a second client queued as steer",
                         busy.id)
                self._json({"run_id": busy.id, "busy": True, "steered": True})
                return
            run.add("you", text)
            threading.Thread(target=_web_drive, args=(run, text),
                             daemon=True, name=f"webrun-{run.id}").start()
            log.info("web run %s started from the browser in %s", run.id, key)
            self._json({"run_id": run.id, "busy": False})

        def do_POST(self):
            if not self._target_ok():
                return
            if not self._origin_ok():
                self._forbidden()
                return
            if self.path.startswith("/a2a"):
                # The A2A JSON-RPC endpoint (web.a2a): SendMessage runs one message
                # through this box and returns a Task. The card route is public; this
                # one takes the page token as a Bearer.
                if not (CONFIG.get("web") or {}).get("a2a"):
                    self._drain()
                    self._json({"error": "not found"}, 404)
                    return
                body = self._body() or {}
                status, payload = a2a_http(self.path, body, self._auth_ok(),
                                           self.headers.get("A2A-Version"))
                self._json(payload, status)
                return
            if self.path.startswith("/api/login"):
                # The browser's one handover: the page reads the token from the URL
                # fragment, POSTs it here with the header, and gets an HttpOnly cookie
                # back. After this the token is in no URL, no history entry and no
                # localStorage, and the page authenticates by cookie alone.
                self._drain()
                if not self._auth_ok():
                    self._json({"error": "unauthorized"}, 401)
                    return
                self._json({"ok": True}, 200, extra=[
                    ("Set-Cookie", "tinycmdr_token=%s; Path=/; HttpOnly; SameSite=Strict; "
                                   "Max-Age=31536000" % token)])
                return
            if self.path.startswith("/api/run"):
                if not self._auth_ok():
                    self._drain()
                    self._json({"error": "unauthorized"}, 401)
                    return
                body = self._need_body()
                if body is None:
                    return
                text = (body.get("message") or "").strip()
                if not text:
                    self._json({"error": "empty message"}, 400)
                    return
                client = _web_client(self.headers)
                key = web_resolve_session(client, body.get("session"))
                # Starting a run in another browser's conversation writes into it
                # as surely as a rename would (A-235): the owning browser's run
                # must not be steered, and its transcript must not be extended,
                # by a different browser. The SHARED conversation (owner "") is
                # still open to everyone.
                if web_owned_by_other(key, client):
                    self._json({"error": "that conversation belongs to another "
                                         "browser on this host - you may read it in "
                                         "the shared view, not run in it"}, 403)
                    return
                kind, payload = _web_command(text, key)
                if kind != "task":
                    # fast-path commands answer immediately, like /api/chat
                    self._json({"reply": payload, "immediate": True, "session": key})
                    return
                web_set_open(client, key)
                self._start_run(payload, key, client)
                return
            if self.path.startswith("/api/upload"):
                if not self._auth_ok():
                    self._drain()
                    self._json({"error": "unauthorized"}, 401)
                    return
                data = self._raw(WEB_UPLOAD_MAX)
                if data is None:
                    self._json({"error": "upload refused: empty, over %d bytes, or "
                                         "stalled" % WEB_UPLOAD_MAX}, 413)
                    return
                # _query() already percent-decoded the name once; decoding again would
                # turn a literal "%2e%2e" in a filename into ".." before _web_safe_name
                # sees it (A-223).
                raw = (self._query().get("name") or "").strip()
                UPLOADS_DIR.mkdir(exist_ok=True)
                safe = _web_safe_name(raw) if raw else "upload.bin"
                dest = UPLOADS_DIR / ("%d_%s" % (int(time.time()), safe))
                try:
                    dest.write_bytes(data)
                except OSError as e:
                    # A name this filesystem will not take (a reserved character, or a
                    # name that is already a directory) used to raise OUT of the handler
                    # and close the socket with zero bytes - the browser showed a
                    # spinner and the operator never learned why (A-231).
                    log.warning("web upload: cannot write %s: %s", dest.name, e)
                    self._json({"error": "that upload name cannot be stored on this "
                                         "host", "name": dest.name, "got": str(e)}, 400)
                    return
                rel = str(dest.relative_to(BASE_DIR))
                log.info("web upload: %d bytes -> %s", len(data), rel)
                reply = {"path": rel, "name": dest.name, "bytes": len(data),
                         "note": "[attachment saved to %s - use read_file to "
                                 "inspect it]" % rel}
                # The stored base is not always the requested one: separators, controls
                # and the platform-reserved characters are replaced, and the base is cut
                # at 120. Say so, so a caller that asked for a 300-character name learns
                # which file it got instead of finding out by listing uploads/ (A-232).
                want = os.path.basename(str(raw).replace("\\", "/")).strip(" .")
                if want and want != safe:
                    reply["name_note"] = ("stored as %s: the requested name was "
                                          "rewritten (separators, controls and the "
                                          "platform-reserved characters are replaced, "
                                          "and the base name is cut at 120)"
                                          % safe)
                self._json(reply)
                return
            if self.path.startswith("/api/sessions"):
                if not self._auth_ok():
                    self._drain()
                    self._json({"error": "unauthorized"}, 401)
                    return
                body = self._need_body()
                if body is None:
                    return
                op = (body.get("op") or "").strip()
                key = (body.get("key") or "").strip()
                client = _web_client(self.headers)
                if op == "new":
                    made = web_new_session(client, (body.get("title") or "").strip()[:80])
                    log.info("web conversation %s created", made)
                    self._json({"key": made, "sessions": web_sessions(client)})
                    return
                if op in ("rename", "delete", "open"):
                    if not _web_key_ok(key) or web_entry(key) is None:
                        self._json({"error": "no such conversation"}, 404)
                        return
                    # Only the browser that owns a conversation may change it.
                    # Reading stays open: the rail's shared view shows every
                    # conversation on this host (A-235 - a second browser could
                    # rename, open and DELETE a first browser's conversation, and
                    # a delete removes its runlog for good).
                    if web_owned_by_other(key, client):
                        self._json({"error": "that conversation belongs to another "
                                             "browser on this host - you may read it "
                                             "in the shared view, but not %s it" % op},
                                   403)
                        return
                    if op == "rename":
                        title = (body.get("title") or "").strip()
                        if not title:
                            # A blank title used to be stored as "" and the rail fell
                            # back to the key: a rename that means nothing DESTROYED the
                            # label, because "no title" and "an empty one" were the same
                            # state (A-240, measured 2026-10-06: title "  " stored "").
                            # Refuse it, so the old title stays.
                            self._json({"error": "a rename needs a title"}, 400)
                            return
                        web_rename_session(key, title)
                        self._json({"ok": True, "sessions": web_sessions(client)})
                        return
                    if op == "delete":
                        verdict = web_delete_session(key)
                        if verdict == "busy":
                            self._json({"error": "a run is still going in that "
                                                 "conversation - stop it first"}, 409)
                            return
                        if verdict == "scheduled":
                            self._json({"error": "a scheduled job reports into "
                                                 "that conversation - remove the "
                                                 "job first"}, 409)
                            return
                        if verdict != "deleted":
                            self._json({"error": "no such conversation"}, 404)
                            return
                        self._json({"deleted": key, "sessions": web_sessions(client)})
                        return
                    web_set_open(client, key)
                    self._json({"open": key})
                    return
                self._json({"error": "unknown op"}, 400)
                return
            if self.path.startswith("/api/steer"):
                if not self._auth_ok():
                    self._drain()
                    self._json({"error": "unauthorized"}, 401)
                    return
                body = self._need_body()
                if body is None:
                    return
                run = WEB_RUNS.get(body.get("run_id", ""))
                text = (body.get("message") or "").strip()
                if run is None:
                    self._json({"error": "no such run"}, 404)
                    return
                # Bind the message to the run's OWN browser. This route answers a
                # parked question and approves a confirm-tier command, so a run id
                # seen in the shared rail was enough for any token holder to
                # answer another browser's question or approve its command
                # (A-244, measured 2026-10-06: a second client answered a first
                # client's parked question). The owning tab still works; a run in
                # the shared conversation has no owner and stays open to all.
                owner = web_run_owner(run)
                if owner and owner != _web_client(self.headers):
                    self._json({"error": "that run belongs to another browser on "
                                         "this host - only that browser can answer "
                                         "its questions"}, 403)
                    return
                if not text:
                    self._json({"error": "empty message"}, 400)
                    return
                if run.done:
                    self._json({"error": "run finished"}, 409)
                    return
                # A question is open on this run: this POST is its ANSWER, not a steering
                # line. It is read here and handed to the parked run through the row,
                # because only the run's own thread can unblock itself.
                with run.lock:
                    _row = getattr(run, "asked", None)
                if _row is not None:
                    _row["answer"] = text
                    _row["ev"].set()
                    run.add("you", text + "   (answer)")
                    log.info("web run %s: question answered", run.id)
                    self._json({"answered": True})
                    return
                with run.lock:
                    run.steer.append(text)
                run.add("you", text + "   (mid-run)")
                log.info("web run %s: steering message queued", run.id)
                self._json({"queued": True})
                return
            if self.path.startswith("/api/stop"):
                if not self._auth_ok():
                    self._drain()
                    self._json({"error": "unauthorized"}, 401)
                    return
                body = self._need_body()
                if body is None:
                    return
                run = WEB_RUNS.get(body.get("run_id", ""))
                if run is None:
                    self._json({"error": "no such run"}, 404)
                    return
                run.cancel.set()
                run.add("system", "stop requested")
                log.info("web run %s: stop requested", run.id)
                self._json({"stopping": True})
                return
            if not self.path.startswith("/api/chat"):
                self._drain()
                self._send("not found", 404, "text/plain")
                return
            if not self._auth_ok():
                self._drain()
                self._json({"reply": "unauthorized — wrong token"}, 401)
                return
            req = self._body()
            if req is None:
                # /api/chat's own shape is {"reply": ...}, so the shape complaint
                # rides there instead of a bare "bad request" (A-206).
                self._json({"reply": "expected a JSON object body (e.g. "
                                     '{"message": "..."}); got %s' % self._body_got,
                            "error": "expected a JSON object body"}, 400)
                return
            text = (req.get("message") or "").strip()
            if not text:
                self._json({"reply": "(empty message)"})
                return
            # The conversation this call means: what it asked for, else what this
            # client had open, else the shared one. It used to be hardcoded "web",
            # so a gateway caller that believed it was scoping by `session` was not
            # (A-229, measured 2026-10-06), and the conversation was never touched in
            # the registry, so it could be pruned out of the rail while its transcript
            # kept growing (A-230).
            chat_client = _web_client(self.headers)
            chat_key = web_resolve_session(chat_client, req.get("session"))
            if web_owned_by_other(chat_key, chat_client):
                self._json({"reply": "that conversation belongs to another browser on "
                                     "this host - you may read it in the shared view, "
                                     "not chat in it"},
                           403)
                return
            kind, payload = _web_command(text, chat_key)
            if kind == "task":
                # The same one-run-per-conversation rule /api/run enforces. This route
                # called AGENT.run directly and registered nothing, so it bypassed the
                # rule entirely: three simultaneous POSTs all ran in one conversation
                # (A-228, measured 2026-10-06). Claim the run atomically - the look and
                # the registration are one step - then drive it through the shared
                # driver so its lines land in the same buffer the page polls.
                web_touch(chat_key)
                run, busy = _web_claim_run(chat_key, chat_client)
                if busy is not None:
                    self._json({"reply": "⚠️ a run is already going in this "
                                         "conversation — wait for it to finish, or "
                                         "stop it", "busy": True, "run_id": busy.id},
                               409)
                    return
                run.add("you", text)
                reporter = RunReporter(WebDestination(run), chat_key)
                failed = False
                try:
                    # AGENT.run, exactly as before: this route has always called the
                    # driver with no confirm door, and the shell tool reads "no
                    # confirm_cb" as DECLINED - a scripted caller must keep getting a
                    # fast decline, not a five-minute wait for a question it cannot
                    # answer. What changed is the run is now REGISTERED (above), so the
                    # one-run rule sees it and the rail can.
                    payload = AGENT.run(chat_key, payload)
                except (KeyboardInterrupt, SystemExit):
                    raise
                except BaseException as e:      # noqa: BLE001 - a lane must not die
                    # BaseException, not Exception: a stop raised from inside the run used
                    # to escape here and the browser got nothing at all.
                    failed = True
                    log.exception("web run failed")
                    payload = f"⚠️ Something broke on my side: {e}"
                finally:
                    # Always: a registered run that is never finished would block the
                    # conversation for ever.
                    _finish_web_run(run, reporter, payload, failed=failed)
            self._json({"reply": payload})

    # Loopback unless the operator says otherwise; the installer asks on a headless
    # box and writes web.host 0.0.0.0, where the token rides in cleartext on a LAN
    # the operator has declared trusted. There is deliberately NO TLS.
    host = str(web.get("host") or "127.0.0.1").strip() or "127.0.0.1"
    port = int(web.get("port", 8790))
    srv = None
    for attempt in range(6):
        try:
            srv = QuietServer((host, port), Handler)
            break
        except OSError as e:
            if getattr(e, "errno", None) in (1, 13):          # EPERM / EACCES
                # A privilege boundary, not a busy port: nothing will change by waiting.
                # (Ports below 1024 need root; a host that asked for 80 gets told why.)
                log.error("web UI disabled: cannot bind %s:%d (%s). Ports below 1024 need "
                          "root - set web.port to a port above 1024 (the default is 8790), "
                          "or run the service elevated.", host, port, e)
                lane_down("web", "cannot bind %s:%d (%s)" % (host, port, e))
                return None
            if attempt == 5:
                # A taken port must never kill the bot (8787 - RStudio Server's
                # default - is why this default moved to 8790; web.port moves it,
                # web_busy_note names the holder).
                log.error("web UI disabled: cannot bind %s:%d (%s). Another "
                          "process holds the port — set web.port or "
                          "web.enabled: false in config.json.", host, port, e)
                lane_down("web", "port %d is held by another process" % port)
                return None
            # after a restart the previous instance may still be releasing the
            # port for a second or two
            log.info("web UI port %d busy — retrying in 1s (attempt %d/6)",
                     port, attempt + 1)
            time.sleep(1)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    # ...and the guard that lets a wedged run go: without it a hang held its conversation
    # for ever (see _web_stall_tick).
    if _web_stall_minutes("warn") or _web_stall_minutes("abandon"):
        threading.Thread(target=_web_stall_loop, daemon=True, name="web-stall").start()
    log.info("web UI listening on http://%s:%d", host, srv.server_address[1])
    # The BOUND port, not the configured one: web.port 0 means "any free port", and the
    # record is what health/doctor read back.
    lane_up("web", "port %d" % srv.server_address[1])
    return srv

def web_port_recorded():
    """The port the running page actually BOUND, or None when this host recorded nothing.

    Only a SUCCESSFUL bind records a port (run_webui's lane_up "port N"): a failure's
    `detail` names the port it TRIED, which is the 0 that got here in the first place.
    The 8790 fallback therefore lives in web_port_effective, NOT here - a reader that
    needs "is a page of mine already up?" must not treat the published default as a
    record, or it would probe an unrelated program on 8790 and conclude it is served.
    """
    record = ((_lane_state_read().get("lanes") or {}).get("web") or {})
    if record.get("ok"):
        m = re.match(r"port\s+(\d+)", str(record.get("detail") or ""))
        if m:
            return int(m.group(1))
    return None


def web_port_effective():
    """The port the page is on, which is what a reader must NAME.

    `web.port: 0` is an instruction - "let the OS pick a free port" - not a missing value.
    Collapsing it to 8790 built links to a port this box is not serving: with 0 the bound
    port is decided by the kernel, and on a box where something else holds 8790 the link
    pointed at the wrong program (the a2a card, the setup summary, doctor, `web`, `token
    set` and the firewall hints all did this, measured 2026-10-06).

    Order:
      1. the configured port when it is a real one (any non-zero int) - the 0 case never
         reaches a reader as a port a browser could open;
      2. else the port the running page actually BOUND (web_port_recorded) - the
         persisted lane record, so a cold process (`tinycmdr web`, a cron doctor) reads
         back what the serving process wrote;
      3. else 8790.

    That last step is a GUESS for a box that has recorded nothing yet, never a silent
    rewrite of a configured 0: the 0 stays on disk as written, and a 0 host whose record
    exists reports the record's port instead.

    Never raises: config.json is hand-editable and `int("nope")` is not this function's
    problem to report (doctor owns that complaint).
    """
    try:
        configured = int((CONFIG.get("web") or {}).get("port"))
    except (TypeError, ValueError):
        configured = 0
    if configured:
        return configured
    recorded = web_port_recorded()
    return recorded if recorded else 8790


def _web_port(web):
    """(port, complaint) for the web port this box serves. Never raises.

    A hand-edited config.json can hold anything here (`int('nope')` was a traceback out
    of two verbs before this), and a verb that reports on a box must name the problem.
    A configured 0 is not a problem to report: `web_port_effective` answers which port
    the page is actually on."""
    raw = (web or {}).get("port")
    try:
        int(raw)
    except (TypeError, ValueError):
        return 8790, ("web.port in config.json is %r, which is not a port: reading 8790"
                      % (raw,))
    return web_port_effective(), None

def _port_holder(port):
    """Who is listening on a TCP port, as a printable line (or None). Read-only."""
    if os.name == "nt":
        rc, out, _err, _ = run_capture(
            ["powershell", "-NoProfile", "-Command",
             "Get-NetTCPConnection -State Listen -LocalPort %d -ErrorAction SilentlyContinue | "
             "ForEach-Object { 'pid ' + $_.OwningProcess + ' on ' + $_.LocalAddress }" % port],
            60)
    else:
        rc, out, _err, _ = run_capture(
            ["sh", "-c", "(ss -ltnp 2>/dev/null || netstat -ltnp 2>/dev/null) "
                         "| grep -E '[:.]%d[[:space:]]' | head -3" % port], 60)
    lines = [ln.strip() for ln in (out or "").splitlines() if ln.strip()]
    return "; ".join(lines[:3]) if lines else None


def web_busy_note(host, port):
    """What to say when the page did not start: which URL, who holds it, what to do.

    `--web` failing used to print one vague line ("the port may be taken"), which on a box
    where the BOT already serves the page (web.enabled true in config.json) reads as a
    mystery rather than as "it is already up". Read-only: it names the holder, it never
    kills anything. `port` may be junk (a hand-edited config), which is not an error here.
    """
    shown = "127.0.0.1" if host in ("0.0.0.0", "::") else host
    url = "http://%s:%s" % (shown, port)
    try:
        holder = _port_holder(int(port))
    except (TypeError, ValueError):
        holder = None
    if holder:
        return ["Could not start the web UI on %s." % url,
                "  %s is listening there - another tinycmdr (this install's bot serving its "
                "own page, or a second web lane) or an unrelated program." % holder,
                "  If a page answers at %s it is already usable: open that instead. Otherwise "
                "set web.port in config.json." % url]
    return ["Could not start the web UI on %s." % url,
            "  No process answered a look-up on that port, which does not mean it is "
            "free: a socket in the kernel's TIME_WAIT window (a restart seconds ago) "
            "or a holder this verb cannot see (another user) both look like this. Wait "
            "a few seconds and retry, or set web.port in config.json."]

def _web_token():
    """The token a server run would require: web.token, else .env's TINYCMDR_WEB_TOKEN."""
    return str((CONFIG.get("web") or {}).get("token")
               or os.environ.get("TINYCMDR_WEB_TOKEN") or "").strip()


WEB_FONTS = {
    # Bundled, never fetched from a CDN: this is a local page on a box that may have no
    # route to the internet, and a webfont that needs one is a font that sometimes is not
    # there. The OFL texts ride along in the same folder (assets/fonts/OFL-*.txt).
    # cinzel-600: the headings' face, referenced by webui.css since the page redesign -
    # and served by neither this map nor the package manifest until 2026-10-04, so
    # /fonts/cinzel-600.woff2 404'd on every install and every heading fell back a weight.
    "cinzel-600.woff2": "cinzel-600.woff2",
    "cinzel-700.woff2": "cinzel-700.woff2",
    "inter.woff2": "inter.woff2",                      # variable: 100-900 in one file
    "jetbrains-mono-400.woff2": "jetbrains-mono-400.woff2",
}


def _web_font_path(name):
    """The file for a font slug, or None - the slug must be one we ship (no traversal)."""
    if name not in WEB_FONTS:
        return None
    path = BASE_DIR / "assets" / "fonts" / WEB_FONTS[name]
    return path if path.exists() else None


def _web_temple_bytes():
    """The stage backdrop photo: the host's own file, else None (the CSS draws nothing).

    Operator, 2026-10-04: `roman-temple-spring.jpg` is "the permanent background
    replacement for the dark pillars background". Read per request, so a host that drops
    a new photo sees it on the next reload; the bytes are static, so the route caches for
    a day like the other art.
    """
    try:
        return (BASE_DIR / "assets" / "roman-temple-spring.jpg").read_bytes()
    except OSError:
        return None


def _web_backdrop_html():
    """The stage's backdrop element, or "" - a host with no photo gets no backdrop.

    The new page design drew a faint colonnade in gold and bronze; the operator replaced it
    the same day with the photo. The file is served at /temple.jpg and drawn by
    .colonnade's own CSS rule (cover, bottom-anchored, dimmed and feathered into the
    stage), so this only decides whether the element exists at all.
    """
    if _web_temple_bytes() is None:
        return ""
    return '<div class="colonnade" aria-hidden="true"></div>'


def _firewall_note(port):
    """How to open `port` to this box's LAN, for the OS we are on - [] when nothing is
    likely to block it or we cannot tell.

    The bind itself never needs root; the firewall HOLE does (checked for real on macOS
    and Linux: a launchd/systemd service cannot answer an interactive prompt, and Windows
    Defender refuses inbound by default). `setup`, `doctor` and the startup announce all
    say the same thing, because switching a running install to the LAN happens long after
    the installer asked.
    """
    # A caller with no port (or a configured 0) means "the port the page is on", not 8790.
    port = int(port) if port else web_port_effective()
    if os.name == "nt":
        return ["to reach it from other machines, Windows Defender Firewall needs an inbound rule",
                "  (once, in an ELEVATED PowerShell):",
                "    New-NetFirewallRule -DisplayName 'tinycmdr page' -Direction Inbound "
                "-Protocol TCP -LocalPort %d -Action Allow" % port,
                "or skip the firewall with a tunnel: ssh -N -L %d:127.0.0.1:%d <user>@<box>"
                % (port, port)]
    if sys.platform == "darwin":
        try:
            rc, out, _err, _to = run_capture(
                ["/usr/libexec/ApplicationFirewall/socketfilterfw", "--getglobalstate"], 10)
        except Exception:                                        # noqa: BLE001
            return []
        if "enabled" not in (out or "").lower():
            return []
        py = str(Path(sys.executable))
        return ["the macOS firewall is ON, and a launchd agent cannot answer its prompt",
                "  (once, with your password):",
                "    sudo /usr/libexec/ApplicationFirewall/socketfilterfw --add " + py,
                "    sudo /usr/libexec/ApplicationFirewall/socketfilterfw --unblockapp " + py,
                "or skip the firewall with a tunnel: ssh -N -L %d:127.0.0.1:%d <user>@<box>"
                % (port, port)]
    def _probe(command):
        """ for a shell command - through run_capture, never shutil, because
        this module keeps its imports local and a probe must be patchable in a test."""
        try:
            rc, out, _err, _to = run_capture(["sh", "-c", command], 10)
        except Exception:                                        # noqa: BLE001
            return False, ""
        return rc == 0, out or ""

    lines = []
    found, _out = _probe("command -v ufw")
    if found:
        _found, status = _probe("ufw status 2>/dev/null")
        if "Status: active" in status:
            lines += ["ufw is active; open the page once (needs root): "
                      "sudo ufw allow %d/tcp" % port]
    found, _out = _probe("command -v firewall-cmd")
    if found:
        _found, status = _probe("firewall-cmd --state 2>/dev/null")
        if "running" in status.lower():
            lines += ["firewalld is running: sudo firewall-cmd --permanent --add-port=%d/tcp "
                      "&& sudo firewall-cmd --reload" % port]
    if lines:
        lines.append("or skip the firewall with a tunnel: ssh -N -L %d:127.0.0.1:%d <user>@<box>"
                     % (port, port))
    return lines


_WEB_CSS_CACHE = {}          # {"stamp": (css stat, theme stat), "text": themed css}


def _web_page_css():
    """The page's stylesheet, themed - or None when the host ships none.

    It is a real asset (assets/webui.css, the operator's design) rather than a string in
    this file: editable, reviewable, and served with the palette substituted from the SAME
    theme.toml the terminal reads.

    The themed result is cached against the (mtime, size) of the two files it reads -
    webui.css and theme.toml - so a browser that fetches the stylesheet on every boot
    does not make this re-read and re-substitute a 42 KB file each time; either file
    changing (or vanishing) invalidates it (A-254, measured 2026-10-06)."""
    path = BASE_DIR / "assets" / "webui.css"
    theme_path = BASE_DIR / "theme.toml"

    def _stamp(p):
        try:
            st = p.stat()
            return (st.st_mtime_ns, st.st_size)
        except OSError:
            return None

    stamp = (_stamp(path), _stamp(theme_path))
    if stamp[0] is not None and _WEB_CSS_CACHE.get("stamp") == stamp:
        return _WEB_CSS_CACHE.get("text")
    try:
        css = path.read_text(encoding="utf-8")
    except OSError:
        return None
    theme = _web_theme_vars()
    out = (css.replace("{{THEME}}", "".join("%s:%s;" % kv for kv in theme.items()))
              .replace("{{VERSION}}", VERSION))
    if stamp[0] is not None:
        _WEB_CSS_CACHE["stamp"], _WEB_CSS_CACHE["text"] = stamp, out
    return out


def _web_token_mint(announce=True):
    """Mint the page's token into .env when a host has none, and say so.

    The token is OURS to generate (unlike a provider's), so an install that was set up
    before the page existed - or that starts it for the first time - never has to invent
    43 characters by hand, and still never gets an open port: "no token, no server" is
    kept by the server minting the token it requires. The value goes to .env (the one
    file the agent cannot read into a prompt) and to this process's environment; it is
    never written to config.json, and only the link built from it is printed.
    """
    import secrets as _secrets
    tok = _secrets.token_urlsafe(32)
    try:
        _env_set("TINYCMDR_WEB_TOKEN", tok)
    except Exception as e:                                            # noqa: BLE001
        print("could not write %s: %s" % (ENV_FILE, e), file=sys.stderr)
        return ""
    os.environ["TINYCMDR_WEB_TOKEN"] = tok
    if announce:
        print("minted TINYCMDR_WEB_TOKEN (the page's access token; it is in %s, never "
              "printed in full here)." % ENV_FILE.name)
        print("  the page is this install's door - the link is printed as the server "
              "starts; `tinycmdr setup` picks LAN vs loopback and the port.")
    log.info("minted TINYCMDR_WEB_TOKEN into .env: the page is enabled and had none")
    return tok


def _web_lan_ip():
    """This box's first non-loopback IPv4, or "" - what a LAN visitor would type."""
    try:
        names = _web_local_hosts() - {"127.0.0.1", "localhost", "::1"}
    except Exception:
        names = set()
    for n in sorted(names):
        if re.fullmatch(r"\d+\.\d+\.\d+\.\d+", n):
            return n
    return ""


def _browser_possible():
    """Is there a GUI this process could open a browser in? Best-effort by design:
    the server does not depend on the answer, only the auto-open does.

    TINYCMDR_NO_BROWSER=1 forbids the auto-open everywhere (main's --no-browser is the
    per-run spelling). It exists for the suites: a staged child that opens the page once
    per test puts real tabs in the operator's browser (measured: ~60 across a day of
    gate runs on a Mac), and a test must not have that side effect.
    """
    if str(os.environ.get("TINYCMDR_NO_BROWSER") or "").strip().lower() in (
            "1", "true", "yes", "on"):
        return False
    if os.name == "nt" or sys.platform == "darwin":
        return True
    return bool(os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"))


def _web_base_urls(port):
    """The addresses to print, most useful first.

    A LAN-bound server's link must be the one the OPERATOR's browser can open: a
    0.0.0.0 bind serves the box's LAN address, so that address leads and loopback
    follows for a browser on the box itself. A loopback bind has one address.
    """
    web = CONFIG.get("web") or {}
    host = str(web.get("host") or "127.0.0.1").strip()
    if host in ("0.0.0.0", "::"):
        out = []
        ip = _web_lan_ip()
        if ip:
            out.append(("http://%s:%d/" % (ip, port), False))
        out.append(("http://127.0.0.1:%d/" % (port), True))
        return out
    return [("http://%s:%d/" % (host or "127.0.0.1", port), True)]


def _web_answers(port, timeout=2.0):
    """Is a tinycmdr page already serving on this port? (/api/health is auth-free
    by design, and its JSON carries `lanes` - specific enough not to confuse it
    with whatever else might answer on the number.)"""
    try:
        import urllib.request
        with urllib.request.urlopen("http://127.0.0.1:%d/api/health" % int(port),
                                    timeout=timeout) as r:
            return r.status == 200 and b"lanes" in r.read(4096)
    except Exception:
        return False


_WEB_OPEN_TTL = 6 * 3600   # one auto-opened tab per token+port per this window


def _browser_open_mark(tok, port):
    """Record that a tab for (token, port) was just opened. Best-effort, never raises."""
    try:
        key = hashlib.sha1(("%s|%d" % (tok, port)).encode("utf-8", "replace")).hexdigest()[:16]
        (BASE_DIR / ".web-open").write_text(
            json.dumps({"key": key, "port": int(port), "at": round(time.time(), 3)}),
            encoding="utf-8")
    except Exception:
        pass


def _browser_open_due(tok, port, ttl=None):
    """True when the auto-open should fire: one tab per token+port per TTL.

    Every start used to open a tab, so a restart ladder, a supervisor loop or a day of
    gate runs stacked dozens in the operator's browser - each carrying the token of the
    process that opened it, which is why a pile of them read "token not accepted" after
    any rotation. The marker records (token digest, port, time): the same pair inside the
    TTL skips the open with a log line (never silent), a rotated token or a different port
    opens at once, and the `web` verb bypasses this entirely because typing it IS the
    asking. Never raises; an unwritable marker never stops the announce.
    """
    ttl = _WEB_OPEN_TTL if ttl is None else ttl
    key = hashlib.sha1(("%s|%d" % (tok, port)).encode("utf-8", "replace")).hexdigest()[:16]
    marker = BASE_DIR / ".web-open"
    now = time.time()
    try:
        if marker.exists():
            prev = json.loads(marker.read_text(encoding="utf-8") or "{}")
            if prev.get("key") == key and now - float(prev.get("at") or 0) < ttl:
                log.info("browser auto-open skipped: this link opened %d min ago",
                         int((now - float(prev.get("at") or 0)) / 60))
                return False
    except Exception:
        pass
    _browser_open_mark(tok, port)
    return True


def _announce_web(port, open_browser=True, force=False):
    """Say where the page is - tokenized link first, then how to reach it.

    The token rides the FRAGMENT: it never reaches the server, so it cannot land
    in its log or a Referer header. The page hands the fragment to /api/login once,
    takes an HttpOnly cookie, and scrubs the address bar; the cookie is what a
    bookmark then rides.
    """
    web = CONFIG.get("web") or {}
    port = int(port)
    urls = _web_base_urls(port)
    tok = _web_token()
    print("")
    for i, (base, _loop) in enumerate(urls):
        label = "tinycmdr page: " if i == 0 else "  also: "
        print("%s%s#token=%s" % (label, base, tok) if tok else "%s%s" % (label, base))
    if str(web.get("host") or "") in ("0.0.0.0", "::"):
        print("  token required; that link works from any machine on your network - "
              "the token travels in cleartext there, so use a network you trust")
        for _line in _firewall_note(port):
            print("  " + _line)
    else:
        print("  from another machine: ssh -N -L %d:127.0.0.1:%d <user>@<box>"
              % (port, port))
    if open_browser and _browser_possible() and (force or _browser_open_due(tok, port)):
        try:
            import webbrowser
            webbrowser.open(base + (("#token=" + tok) if tok else ""))
        except Exception:
            pass
    print("")


def start_web_surface(open_browser=True, force=False):
    """Start the page beside whatever else this process does. Best-effort: a box
    where it cannot start still has its other doors, and the reason is printed."""
    web = CONFIG.get("web") or {}
    if not web.get("enabled", True):
        return None
    if not _web_token() and not _web_token_mint():
        print("web UI off: no token, and one could not be minted (see above). Set "
              "web.enabled: false to stop this line, or write .env by hand.",
              file=sys.stderr)
        return None
    raw_port = web.get("port")
    # 0 is a real value here ("let the OS pick"), not a missing one: `or 8790` turned the
    # suite's port-0 server into a probe of 8790, and on a box whose live install serves
    # the page that read as "already serving here".
    port = int(raw_port) if raw_port is not None else 8790
    # With web.port 0 the live page's port was chosen by the OS at bind time and only the
    # lane record knows it, so probing 0 - which can never answer - made a SECOND process
    # bind another port and announce a second, independent page instance (A-260, measured
    # 2026-10-06: a live page on 50917 went unseen and 50922 was bound instead). A
    # configured 0 asks where THIS install's page already is: only a RECORDED bind counts
    # (web_port_recorded), never the 8790 fallback - probing a guess can hit an unrelated
    # program on 8790 and make a host with no page of its own refuse to start one.
    probe_port = port or web_port_recorded()
    if probe_port and _web_answers(probe_port):
        # The service (or another session) already serves the page: announce it
        # instead of spending six seconds failing to bind the same port.
        print("tinycmdr page: already serving here")
        _announce_web(probe_port, open_browser=open_browser, force=force)
        return None
    srv = run_webui()
    if srv is None:
        # Say what would work: who holds the port, and that a page already answering
        # there is usable as-is (the log gets the same, but a person at the terminal
        # sees this).
        for line in web_busy_note(web.get("host") or "127.0.0.1", web_port_effective()):
            print(line, file=sys.stderr)
        return None
    _announce_web(srv.server_address[1], open_browser=open_browser, force=force)
    return srv


def _verb_web(rest=None):
    """Open the page: print the tokenized link, hand it to the browser when there
    is one. Read-only with respect to the running SERVICE - a second process must
    NOT bind the port to answer this. It is not read-only on disk: a host with no
    token gets one minted into .env (the page is gated, so the verb that opens it
    must be able to create the key), which is the only file it writes."""
    tok = _web_token() or _web_token_mint()
    if not tok:
        print("no token: mint one with `tinycmdr token set TINYCMDR_WEB_TOKEN`.",
              file=sys.stderr)
        return 2
    # A configured 0 means the OS picked the port at bind time; the link must name that
    # port, not 8790, or `tinycmdr web` hands out an address this box is not serving.
    port = web_port_effective()
    urls = _web_base_urls(port)
    full = urls[0][0] + "#token=" + tok
    print("tinycmdr page: %s" % full)
    for base, _loop in urls[1:]:
        print("  also: %s" % base)
    if _browser_possible():
        try:
            import webbrowser
            webbrowser.open(full)
            _browser_open_mark(tok, port)
        except Exception:
            pass
    return 0


class MattermostDestination(Destination):
    """A Mattermost channel: posts, edits and deletes through the dispatcher.

    The message id each call hands back is the ref the reporter redraws. Burst
    merging is ON here because a post notifies a phone - five calls in two
    seconds is five notifications - and that is the only thing this lane does
    differently from a browser or a terminal.
    """

    name = "mattermost"
    has_human = True
    merge_tools = True
    max_lines = 4

    def __init__(self, dispatcher, channel_id, root_id=None):
        self.d = dispatcher
        self.channel_id = channel_id
        self.root_id = root_id
        self._draft = None       # THIS run's streamed draft, waiting for the answer

    @staticmethod
    def _color(kind):
        return {"note": COLOR_NARRATION, "narration": COLOR_NARRATION,
                "tool": COLOR_TOOL, "tool_done": COLOR_TOOL,
                "tool_fail": COLOR_FAIL, "checkin": COLOR_STATUS, "say": COLOR_STATUS,
                "ask": COLOR_STATUS, "status": COLOR_TOOL,
                "error": COLOR_FAIL}.get(kind, COLOR_STATUS)

    def line(self, kind, text, src="main"):
        colour = want_color(self._color(kind))
        draft = None if colour else self._draft
        if draft is not None:
            # The draft is this run's own post: the next colourless line from HERE is
            # the answer that replaces it. It used to sit in a channel-wide slot that
            # the next colourless post from ANYONE took - see `drop`.
            self._draft = None
        return self.d._post(self.channel_id, self.root_id, text, color=colour,
                            draft_id=draft)

    def update(self, ref, kind, text, src="main"):
        self.d._edit(ref, self.channel_id, text,
                     color=want_color(self._color(kind)))
        return ref

    def drop(self, ref):
        """The streamed draft is finished; keep its id for the answer that replaces it.

        Do NOT delete the post: Mattermost delete_post leaves an ugly "(message
        deleted)" tombstone in the channel. The id stays on THIS destination rather
        than in a channel-wide slot, because a channel can hold two runs at once - a
        cron job reporting while a chat run is live - and the old shared slot gave the
        draft to whichever colourless post came first: the other run's answer was
        edited into this run's message and this run's own answer went to a new post
        (measured 2026-10-06 on a colourless terminal: the chat's answer edited
        `post-1`, the cron job's draft, and the cron answer landed in `post-2`). The
        dispatcher's own notices - "⏳ Queued", "✅ Got it", a slash-command reply -
        post without a destination and so can no longer take a draft either.
        """
        self._draft = ref

    def ask(self, question, options=None, wait=300.0, label=None):
        """Post the question and wait for the reply, as the confirm prompt did.

        Returns the operator's own words, or None if nobody answered in time: the
        reporter decides what counts as a yes, so every lane answers to the same
        words instead of each carrying its own list.

        One open question per channel - the rule the Telegram lane learned in A-144
        and `ask_operator` states for a session. The wait state is keyed by CHANNEL,
        so a second question used to overwrite the first: the operator's reply
        released the NEWER waiter and the first sat out its whole window and came
        back None, which the reporter reads as "no answer within Ns - that command
        was skipped" after the answer had already been given (measured 2026-10-06:
        two asks in one channel, one row, first=None, second='yes'). Claiming the
        slot BEFORE the post also closes the gap where a reply that landed in the
        milliseconds between the post and the claim found no row and was taken for a
        new order.
        """
        if not self.channel_id:
            return None
        ev = threading.Event()
        row = {"event": ev, "answer": None}
        held = self.d.pending.setdefault(self.channel_id, row)   # the atomic claim
        if held is not row:
            if not held["event"].is_set():
                self.line("ask", "❓ A question is already open in this channel - "
                                 "answer that one first; this one was not asked.")
                return None
            self.d.pending[self.channel_id] = row  # the old one is answered: take over
        body = question
        if options:
            body += " — reply " + " / ".join(options)
        try:
            self.line("ask", body)
        except Exception:
            if self.d.pending.get(self.channel_id) is row:
                self.d.pending.pop(self.channel_id, None)
            raise
        answered = ev.wait(wait)
        row = self.d.pending.pop(self.channel_id, {"answer": None})
        return row.get("answer") if answered else None

    def attach(self, path, note=""):
        return self.d.send_file(self.channel_id, self.root_id, path, note)


def ProgressReporter(dispatcher, channel_id, root_id, session_key,
                     label="🔧 Working…"):
    """The Mattermost lane's reporter: a RunReporter reporting into a channel.

    Kept as a name because this lane's callers and its suites already use it. It
    is a wiring function now, not a second implementation of the reporting
    vocabulary - there is exactly one of those, and every interface shares it.
    """
    return RunReporter(MattermostDestination(dispatcher, channel_id, root_id),
                       session_key, label=label)
class MattermostDispatcher:
    """Serializes tasks per channel, posts progress + answers in threads."""

    def __init__(self):
        self.queues = {}
        self.workers = set()
        self.workers_lock = threading.Lock()
        self.pending = {}          # channel_id -> confirmation wait state
        self.cancel_events = {}    # channel_id -> set of threading.Event
        self.steering = {}         # channel_id -> [(sender, text)] for the LIVE run
        self.steering_lock = threading.Lock()
        self.paused = None         # None or pause-reason string
        self.seen = deque(maxlen=5000)  # message ids already handled
        self.driver = None
        self.bot_username = None
        # Listener liveness. The vendor's websocket object is rebuilt per connect and its
        # `_last_msg` starts at 0, so the probe needs the bot's own clock as well: when the
        # socket was last seen here, and since when it has been gone.
        self._ws_probe_warned = False
        self._ws_missing_since = None
        self._ws_attach_time = time.time()
        self.dead_roots = {}       # channel_id -> root_id the server rejected
        self.bot_user_id = None
        # channel_id -> unix time of newest handled post. CARRIED across a restart:
        # it is the map the catch-up sweep queries, and a message posted while this
        # process was down arrives with no websocket event at all, so an empty map
        # means an unanswered order (see _restored_last_seen).
        self.last_seen = self._restored_last_seen()
        # The exact boundary, for the same reason: that time is this box's own clock
        # (the live message object carries no create_at), so it can sit BEHIND the
        # post it describes and hand an already-answered message back as new work.
        self.seen.extend(self._restored_seen_ids())
        self.channel_dm = {}       # channel_id -> bool (is a direct message)
        # Stall guard (2026-09-10). One worker thread serves a channel, so a run
        # that blocks for ever is indistinguishable from a dead bot: later
        # messages queue behind it and NOTHING is posted or logged. run_capture()
        # removes the known cause; this is the net that makes any other stall
        # visible and self-healing instead of silent.
        self.worker_gen = {}       # channel_id -> generation of the live worker
        self.active = {}           # channel_id -> run bookkeeping
        self.running = set()       # channel_ids with a message ACTUALLY being handled
        self.queued_notice = {}    # channel_id -> post id of the queued notice
        # channel_id (or session key) -> the ask_user row a run is parked on. It lives
        # here, not in the run, because the ANSWER arrives on the listener thread and
        # has to be readable without touching the run.
        self.pending_asks = {}
        # session key -> channel id. An ask_user answer arrives addressed to the
        # CHANNEL, so the door needs the reverse mapping to find the parked run; a
        # /stop also needs it, because it flags the channel's cancel events.
        self._session_channel = {}

    def _restored_last_seen(self):
        """The channels this box was talking in, with the time of the newest post it
        handled, read back from state.json.

        was killed, and the operator's order was posted inside the downtime. No run
        started, no answer was ever posted, and the log said nothing - because the sweep
        that exists for this case had no channel to ask about. The notice that records
        WHICH channel asked for the restart is therefore also a floor for that channel.
        """
        seen = {}
        try:
            st = _state()
        except Exception as e:                                   # noqa: BLE001
            log.debug("no carried last_seen: %s", e)
            return seen
        raw = st.get("last_seen")
        if isinstance(raw, dict):
            for chan, ts in raw.items():
                try:
                    seen[str(chan)] = float(ts)
                except (TypeError, ValueError):
                    continue
        note = st.get("announce_restart") or {}
        if note.get("channel_id") and note.get("at"):
            try:
                seen.setdefault(str(note["channel_id"]), float(note["at"]))
            except (TypeError, ValueError):
                pass
        return seen

    @staticmethod
    def _restored_seen_ids():
        """The post ids handled just before the restart, oldest first."""
        try:
            ids = _state().get("seen_ids") or []
        except Exception as e:                                   # noqa: BLE001
            log.debug("no carried seen ids: %s", e)
            return []
        return [str(i) for i in ids if i][-50:]

    def _remember_last_seen(self, channel_id, msg_id=None):
        """Persist one channel's high-water mark and the id of the post it came from,
        bounded so the file cannot grow."""
        ts = self.last_seen.get(channel_id)
        if not ts:
            return

        def _mut(st):
            seen = st.setdefault("last_seen", {})
            seen[str(channel_id)] = float(ts)
            if len(seen) > 20:            # a bot talks to a handful of channels
                for old in sorted(seen, key=lambda k: seen[k])[:-20]:
                    seen.pop(old, None)
            if msg_id:
                ids = st.setdefault("seen_ids", [])
                if str(msg_id) not in ids:
                    ids.append(str(msg_id))
                del ids[:-50]
        try:
            _state(_mut)
        except Exception as e:                                   # noqa: BLE001
            log.debug("could not persist last_seen for %s: %s", channel_id, e)

    def _stall_warn_minutes(self):
        return float(CONFIG["agent"].get("stall_warn_minutes", 8) or 0)

    def _stall_abandon_minutes(self):
        return float(CONFIG["agent"].get("stall_abandon_minutes", 20) or 0)

    def _touch(self, channel_id):
        """Mark output in a channel as progress for the stall watchdog."""
        a = self.active.get(channel_id)
        if a:
            a["last"] = now_mono()

    def _ask_label(self, channel_id):
        """How to answer: a DM has no @mention, a channel needs one."""
        if channel_id and (self._is_dm(channel_id) or not self.bot_username):
            return "reply here"
        return ("reply here or @mention me (in a channel Mattermost only hands me "
                "messages addressed to me)")

    def open_question(self, session_key, question, options, timeout):
        """Open a question for this session: register it and post it. NO wait here.

        The wait belongs to ask_operator, which shares this row. The first shape had
        the door waiting as well, so every answer took TWICE the window (measured:
        12.0s for a 6s config) and a timed-out question still reported the right thing
        only by luck.
        """
        row = {"ev": threading.Event(), "answer": None, "question": question,
               "options": list(options or [])}
        ch = self._session_channel.get(session_key)
        self.pending_asks[ch if ch else session_key] = row
        _ASK_PENDING[session_key] = row
        opts = ""
        self._post(ch, None,
                   _ask_format(question, row["options"])
                   + "\n_(" + self._ask_label(ch) + " — or `/tinycmdr stop` to "
                   "cancel this run. Waiting up to "
                   f"{max(1, int((timeout or 300) / 60))} min; if nothing "
                   f"arrives I carry on with my own judgment.)_")
        return row

    def close_question(self, session_key, answered=False):
        """Called by ask_operator when the question is done, however it ended: the
        listener thread must stop treating the next message as an answer."""
        ch = self._session_channel.get(session_key)
        self.pending_asks.pop(ch if ch else session_key, None)
        return True

    def reply_ask(self, session_key, text, sender=""):
        """Hand a message to the run parked on a question, and say so.

        True means it was claimed as the answer (so the caller stops). The row is
        CLEARED here, which is what makes a second message land as ordinary steering
        instead of overwriting the answer the run is already acting on.
        """
        ch = self._session_channel.get(session_key)
        row = self.pending_asks.pop(ch if ch else session_key, None)
        if row is None or row["ev"].is_set():
            return False
        row["answer"] = _ask_record_choice(row, text) or text
        row["ev"].set()
        log.info("ask_user: answer handed to the parked run (%s)", sender or "?")
        said = " ".join(str(row["answer"]).split())
        self._post(ch, None,
                   ("\u2705 Got it: " + said[:160]
                   + ("..." if len(said) > 160 else "") + " \u2014 carrying on."))
        return True

    def _spawn_worker(self, channel_id, q):
        """Start the single worker for a channel. Caller holds workers_lock."""
        gen = self.worker_gen.get(channel_id, 0) + 1
        self.worker_gen[channel_id] = gen
        self.workers.add(channel_id)
        self.active[channel_id] = {"started": now_mono(), "last": now_mono(),
                                   "warned": False, "gen": gen}
        threading.Thread(target=self._worker, args=(channel_id, q, gen),
                         daemon=True).start()
        return gen

    def attach(self, driver, bot_username):
        self.driver = driver
        self._ws_attach_time = time.time()
        self._ws_missing_since = None
        self.bot_username = bot_username
        try:
            me = driver.users.get_user_by_username(bot_username) or {}
            self.bot_user_id = me.get("id")
        except Exception as e:
            log.debug("could not resolve my own user id: %s", e)
        if int(CONFIG["agent"].get("catch_up_seconds") or 0) > 0:
            threading.Thread(target=self._catch_up_loop, daemon=True).start()
        if self._stall_warn_minutes() or self._stall_abandon_minutes():
            threading.Thread(target=self._stall_loop, daemon=True).start()

    # -- posting helpers ----------------------------------------------------
    @staticmethod
    def _is_root_rejection(err):
        """Mattermost answers 400 'Invalid RootId parameter' when the thread
        root no longer exists. Anything else — 429, 5xx, a network blip, a
        timeout after the post actually committed — is TRANSIENT and must not
        be mistaken for a dead root (that would flatten the thread for the rest
        of the channel's life, and re-posting could duplicate the message)."""
        msg = str(err).lower()
        return "rootid" in msg or "root id" in msg or "invalid root" in msg

    def _post(self, channel_id, root_id, text, color=None, touch=True, draft_id=None):
        """Post text (chunked); returns the new post's id, or None.

        `color` (v1.9.30) carries the text inside a colored attachment bar instead of
        the post body. Only the first chunk is barred: one bar marks a message, and a
        long answer split across batches should not sprout one per chunk.

        `touch=False` posts WITHOUT counting as run progress. The stall warning uses it:
        a watchdog observer that reset the clock it watches stretched every abandon by
        the warn interval, and with warn >= abandon it disabled abandonment outright
        .

        Only a genuine root rejection falls back to a top-level post, and only
        that poisons the root for this channel. Transient failures get one
        retry with the identical payload.
        """
        post_id = None
        if touch:
            self._touch(channel_id)   # output here counts as run progress
        if root_id and self.dead_roots.get(channel_id) == root_id:
            root_id = None  # already known bad — go straight to top-level
        if color:
            draft_id = None      # a coloured line is not the answer replacing a draft
        chunks = list(self._chunks(text))
        if draft_id and chunks:
            # Seamlessly transform the streamed draft in place: no tombstone, no dupe
            self._edit(draft_id, channel_id, chunks[0], color=None)
            post_id = draft_id
            chunks = chunks[1:]
        for chunk in chunks:
            post = {"channel_id": channel_id, "message": chunk}
            if color and post_id is None:
                post["message"] = ""
                post["props"] = bar_props(chunk, color)
            if root_id:
                post["root_id"] = root_id
            err = None
            for attempt in (1, 2):
                try:
                    resp = self.driver.posts.create_post(post)
                    post_id = resp.get("id") or post_id
                    err = None
                    break
                except Exception as e:
                    err = e
                    if self._is_root_rejection(e) or attempt == 2:
                        break
                    time.sleep(1.0)   # transient: one retry, same payload
            if err is None:
                continue
            # A chunk that cannot be posted is an answer the channel never got, and
            # from the inside the run still looks delivered. Log the LOST TEXT beside
            # the reason, bounded so a 16,000-character chunk cannot bloat the log:
            # measured 2026-10-06, a rejected post left `failed to post: <err>` and no
            # trace anywhere on the box of what had been lost.
            log.error("failed to post %d chars to %s: %s — lost: %.2000s",
                      len(chunk), channel_id, err, chunk)
            if not post.get("root_id") or not self._is_root_rejection(err):
                continue
            # the thread root itself is gone: re-post this chunk top-level
            self.dead_roots[channel_id] = post.pop("root_id")
            log.warning("thread root rejected — re-posting this chunk top-level")
            try:
                resp = self.driver.posts.create_post(post)
                post_id = resp.get("id") or post_id
                root_id = None  # don't re-use the dead root for later chunks
            except Exception as e:
                log.error("failed to post %d chars to %s after the root died: %s"
                          " — lost: %.2000s", len(chunk), channel_id, e, chunk)
        return post_id

    def _delete(self, post_id, channel_id):
        """Delete a post this bot made.

        Used for a streamed narration draft that turned out to be the final answer,
        which the caller posts properly: without this the channel would show the
        answer twice. Failures are silent - a leftover draft is cosmetic, and raising
        here would kill a run for nothing.
        """
        self._touch(channel_id)
        try:
            self.driver.posts.delete_post(post_id)
        except Exception as e:
            log.debug("failed to delete post %s: %s", post_id, e)

    def _edit(self, post_id, channel_id, text, color=None):
        """Edit an existing post in place. Failures are silent.

        `color` keeps a post's bar when the body is rewritten - without it an edit
        would silently strip the bar off a line that is being updated every couple of
        seconds (the working line, the streamed narration)."""
        self._touch(channel_id)   # a live status edit is progress too
        payload = {"id": post_id, "channel_id": channel_id, "message": text}
        if color:
            payload["message"] = ""
            payload["props"] = bar_props(text, color)
        else:
            payload["props"] = {}
        try:
            self.driver.posts.update_post(post_id, payload)
        except Exception as e:
            log.debug("failed to edit post %s: %s", post_id, e)

    # -- sending a file into the chat ---------------------------------------
    def send_file(self, channel_id, root_id, path, note=""):
        """Upload a local file into a channel and post it. The send_file tool's door.

        Files only travel this way; no line of prose can hand somebody a video.
        Failures come back as text for the model, because a run that claims a
        delivery that did not happen is the failure class this batch is about.
        """
        p = Path(str(path)).expanduser()
        if not p.is_file():
            return f"ERROR: no such file: {p}"
        size = p.stat().st_size
        cap = int(CONFIG["agent"].get("send_file_max_bytes") or SEND_FILE_MAX)
        if size > cap:
            return (f"ERROR: {p.name} is {size:,} bytes, over this box's {cap:,}-byte "
                    f"send limit (agent.send_file_max_bytes). It is at {p}.")
        try:
            ids = self.driver.upload_files([str(p)], channel_id)
        except Exception as e:                                   # noqa: BLE001
            return f"ERROR: upload failed: {e}"
        post = {"channel_id": channel_id,
                "message": " ".join(str(note or "").split())[:MAX_POST_LEN],
                "file_ids": ids}
        if root_id:
            post["root_id"] = root_id
        try:
            resp = self.driver.posts.create_post(post)
        except Exception as e:                                   # noqa: BLE001
            return f"ERROR: the file uploaded but the post failed: {e}"
        self._touch(channel_id)
        log.info("sent %s (%d bytes) into %s", p.name, size, channel_id)
        return f"sent: {p.name} ({size:,} bytes) is now in this chat"

    @staticmethod
    def _chunks(text):
        """Split for the post limit, on a line boundary, never inside a code fence.

        A bare slice cut the answer wherever 16,000 characters happened to fall.
        Measured 2026-10-06 with a long fenced answer: the first post ended
        `value_1010 = 1010` INSIDE an open ``` block, so Mattermost rendered the rest
        of the answer as code and the second post began with orphaned markers - and
        the mid-word cut is what the operator copies out of the channel. So: prefer
        the last line break in the window; close an open fence at the cut and reopen
        it on the next post, which costs 4 characters against a limit of 16,383; and
        never back off past half the window, so one over-long line or block still
        makes progress instead of looping.
        """
        while len(text) > MAX_POST_LEN:
            cut = text.rfind("\n", 0, MAX_POST_LEN)
            if cut < MAX_POST_LEN // 2:
                cut = MAX_POST_LEN            # one long line: cut it anyway
            if text[:cut].count("```") % 2:
                lower = text.rfind("\n", 0, MAX_POST_LEN - 4)
                if lower > MAX_POST_LEN // 2:
                    cut = lower
                yield text[:cut] + "\n```"
                text = "```\n" + text[cut:].lstrip("\n")
                continue
            yield text[:cut]
            text = text[cut:].lstrip("\n")
        if text:
            yield text

    # -- confirmations (optional; only active if confirm_patterns set) ------


    def door_post(self, channel_id, question, options, wait, label=None):
        """Stage two of the ask_user door, and the reason the door spec makes `post`
        mandatory even when an `opener` already posted the question: this is the
        watchdog's view of the question.

        It has to exist. The first shape pointed the door at `self.door_post`, which was
        never defined on this class: the call raised, ask_operator swallowed it at debug
        level, and the run would have parked with no activity recorded for the channel -
        exactly the state the stall watchdog abandons runs for.
        """
        self._touch(channel_id)   # asking IS progress; never let the watchdog eat it
        return True

    def ask_door_factory(self, channel_id, session_key):
        """A door bound to the RUN's session, not the channel.

        Every run has its own session key while the channel is the operator's door, and
        /stop flags the channel's cancel events - so the door records which session this
        channel is running, in order to release the right waiter.
        """
        if session_key:
            self._session_channel[session_key] = channel_id
        return {"label": self._ask_label(channel_id),
                "opener": lambda q, opts, wait, label: self.open_question(
                    session_key, q, opts, wait),
                "post": lambda q, opts, wait, label: self.door_post(
                    channel_id, q, opts, wait, label),
                "post_done": lambda text: self._post(channel_id, None, text),
                "close_question": lambda answered: self.close_question(
                    session_key, answered)}

    # -- attachments ----------------------------------------------------------
    def _process_attachments(self, post):
        notes, images = [], []
        meta = (post.get("metadata") or {}).get("files") or []
        by_id = {f.get("id"): f for f in meta}
        for fid in post.get("file_ids") or []:
            info = by_id.get(fid, {})
            name = info.get("name") or fid
            mime = info.get("mime_type", "")
            try:
                data = self.driver.files.get_file(fid)
                content = data.content if hasattr(data, "content") else data
                if isinstance(content, str):
                    content = content.encode()
            except Exception as e:
                notes.append(f"[failed to download attachment {name}: {e}]")
                continue
            UPLOADS_DIR.mkdir(exist_ok=True)
            dest = UPLOADS_DIR / f"{int(time.time())}_{os.path.basename(name)}"
            dest.write_bytes(content)
            if mime.startswith("image/") and CONFIG["agent"].get("vision"):
                images.append((mime, base64.b64encode(content).decode()))
                notes.append(f"[image attached; also saved to {dest}]")
            else:
                notes.append(f"[attachment saved to {dest} "
                             f"({mime or 'unknown'}, {len(content)} bytes) "
                             f"— use read_file to inspect it]")
        return notes, images

    # -- intake -------------------------------------------------------------
    def enqueue(self, message, text):
        sender = message.sender_name
        channel_id = message.channel_id
        created = float(getattr(message, "create_at", 0) or 0) / 1000.0
        self.last_seen[channel_id] = max(self.last_seen.get(channel_id, 0.0),
                                         created or time.time())
        msg_id = getattr(message, "id", None)
        self._remember_last_seen(channel_id, msg_id)
        if sender == self.bot_username:
            return
        # de-duplicate (a message can match more than one listener)
        if msg_id:
            if msg_id in self.seen:
                return
            self.seen.append(msg_id)
        user_id = getattr(message, "user_id", None)
        if not user_is_allowed(sender, user_id):
            log.warning("ignored message from unauthorized user: %s (%s)",
                        sender, user_id)
            return
        # `/tinycmdr stop` — and a forced restart — must NOT queue behind the run they are meant
        # to kill: one worker serves a channel, so a queued command is only read AFTER
        # that very run. Handle them here, on the listener thread, where they always
        # land. On 2026-09-10 the user's /restart sat in the queue behind a frozen run
        # and was never read at all; on 2026-09-18 `/tinycmdr restart force` was answered with
        # "Queued behind the task already running here" and only took effect when the
        # run reached its next boundary, which took 90s because the run was inside a
        # `sleep 280` tool call.
        low = text.strip().lower()
        # `/tinycmdr stop` has to be understood HERE too: this listener thread is the only
        # reader that works while a run owns the channel, so a prefixed command that
        # fell through to the queue would wait behind the very run it kills.
        _cmdr = cmdr_strip(text)
        if _cmdr != text.strip():
            text, low = _cmdr, _cmdr.lower()
        # A run parked on an ask_user question takes the next message in its channel as
        # the ANSWER, on the listener thread, while that run stays blocked. Ahead of
        # /stop so an answer that reads like a command is still the answer; `/tinycmdr stop`
        # itself cancels instead, so a parked run is never unreleasable.
        if low != "/stop" and not low.startswith("/"):
            for _sk in [s for s, r in list(self.pending_asks.items())
                        if not r["ev"].is_set()]:
                _ch = self._session_channel.get(_sk)
                if (_ch and _ch == channel_id) or (not _ch and _sk == channel_id):
                    if self.reply_ask(_sk, text, sender):
                        return
        if low == "/stop":
            # The listener thread, so a stop is read even while a wedged run owns
            # this channel's worker. See _stop_channel for why this is a helper.
            self._stop_channel(channel_id, None)
            return
        if low in ("/restart", "/restart force"):
            force = low.endswith("force")
            busy = self._channel_busy(channel_id)
            if busy and not force:
                self._post(channel_id, None,
                           "⚠️ A task is still running. `/tinycmdr stop` it first, or use "
                           "`/tinycmdr restart force` to kill it and restart now.")
                return
            if force:
                # "force" has to MEAN force: flag the live run so its in-flight tool
                # calls are killed (run_capture polls this event) instead of letting it
                # finish first. The restart below does not wait for the run to unwind.
                for e in self.cancel_events.get(channel_id, set()):
                    e.set()
            self._post(channel_id, None,
                       "♻️ Restarting — back in a few seconds, and I'll confirm here "
                       "when I'm up. Sessions and scheduled jobs survive; config.json "
                       "and tinycmdr.py changes are picked up.")
            perform_restart(channel_id, None, sender)
            return
        pend = self.pending.get(channel_id)
        if pend and not pend["event"].is_set():
            # the operator's own words, not a pre-chewed boolean: RunReporter
            # decides what counts as a yes, so every lane answers the same way
            pend["answer"] = text.strip()
            pend["event"].set()
            return
        if self.paused is not None and not text.strip().lower().startswith("/pause"):
            self._post(channel_id, None,
                       f"⏸️ Paused ({self.paused}). `/pause off` to resume.")
            return
        thread_root = getattr(message, "root_id", "") or message.id
        is_dm = bool(getattr(message, "is_direct_message", False))
        with self.workers_lock:
            busy = channel_id in self.running   # a run is actually in flight
        if busy and not text.strip().startswith("/"):
            # STEERING, not queueing. A run holds this channel's worker for its whole
            # duration, so anything queued behind it is not read until the run is over: that
            # is why "Leave it alone" arrived only after the mess it was meant to prevent
            # (live 2026-09-11, the run went on to pause 32 curl processes on another host).
            # The run drains this at the top of each turn and again before it answers.
            with self.steering_lock:
                self.steering.setdefault(channel_id, []).append((sender, text))
            log.info("steering from %s handed to the live run in %s", sender, channel_id)
            self._post(channel_id, None,
                       "📨 Passing that into the run now — it picks it up on its next step.")
            return
        q = self.queues.setdefault(channel_id, queue.Queue())
        backlog = q.qsize()
        q.put((sender, text, message.id, thread_root, is_dm))
        with self.workers_lock:
            if channel_id not in self.workers:
                self._spawn_worker(channel_id, q)
        if busy and not backlog:
            # First message of a backlog: say so ONCE, and only when a run really
            # is in flight. Otherwise the user stares at silence for as long as
            # the run ahead of them takes and concludes the bot is dead — which
            # is what kept happening.
            self._post(channel_id, None,
                       "⏳ Queued behind the task already running here — I'll "
                       "take it as soon as that finishes (a run with no "
                       "progress for %d minutes is abandoned automatically)."
                       % int(self._stall_abandon_minutes()))

    def _worker(self, channel_id, q, gen=0):
        try:
            while True:
                if self.worker_gen.get(channel_id) != gen:
                    log.warning("worker for %s is stale (gen %s) — exiting "
                                "without touching the channel", channel_id, gen)
                    return          # a watchdog abandoned this run
                try:
                    sender, text, msg_id, thread_root, is_dm = q.get(timeout=10)
                except queue.Empty:
                    return  # idle channel: thread exits, next message respawns it
                # "running" means a message is being handled RIGHT NOW. Do not
                # use membership in self.workers for that: a worker outlives its
                # run by up to 10s waiting on an empty queue, so a message
                # landing in that window was wrongly told it was queued behind a
                # task that had already finished.
                self.running.add(channel_id)
                try:
                    self._handle(channel_id, sender, text, msg_id, thread_root,
                                 is_dm, gen)
                except Exception:
                    # One bad message (an attachment with a Windows-illegal
                    # name, an API hiccup) must not kill the worker and drop
                    # every message still queued behind it.
                    log.exception("unhandled error handling a message in %s",
                                  channel_id)
                    self._post(channel_id, None,
                               "⚠️ I hit an internal error on that message — "
                               "it's in the log, and I'm still listening.")
                finally:
                    self.running.discard(channel_id)
        finally:
            with self.workers_lock:
                if self.worker_gen.get(channel_id) == gen:
                    self.workers.discard(channel_id)
                    self.active.pop(channel_id, None)
                    # a message may have arrived between timeout and discard
                    if not q.empty():
                        self._spawn_worker(channel_id, q)

    def _stall_loop(self):
        """Watchdog: a run that stops making progress must never be silent.

        One worker serves a channel, so a blocked run queues every later
        message behind it with no error and no reply — the bot looks dead while
        it is alive. Warn visibly, then abandon the run and hand the channel to
        a fresh worker so the backlog behind it gets served.
        """
        warn_m = self._stall_warn_minutes()
        kill_m = self._stall_abandon_minutes()
        while True:
            time.sleep(30)
            try:
                self._stall_tick(warn_m, kill_m)
            except Exception:
                log.exception("stall watchdog tick failed")

    def _stall_tick(self, warn_m=None, kill_m=None, now=None):
        """One watchdog pass (separate from the loop so it can be tested).

        `now` is monotonic seconds: `active[...]["started"/"last"]` are set from
        now_mono(), and injecting a wall clock here would abandon every live run."""
        warn_m = self._stall_warn_minutes() if warn_m is None else warn_m
        kill_m = self._stall_abandon_minutes() if kill_m is None else kill_m
        now = now_mono() if now is None else now
        _mem_probe()        # cheap when the process is small; names the hog when it isn't
        for channel_id, a in list(self.active.items()):
            quiet = now - a["last"]
            if kill_m and quiet > kill_m * 60:
                log.error("stall: abandoning the run in %s after %.0f "
                          "min without progress", channel_id, quiet / 60)
                for e in self.cancel_events.get(channel_id, set()):
                    e.set()
                self._post(channel_id, None,
                           f"⚠️ No output for {int(quiet / 60)} min — "
                           f"that run is wedged, so I'm abandoning it "
                           f"and picking up whatever you queued "
                           f"behind it. (`/tinycmdr status` for state.)")
                with self.workers_lock:
                    self.active.pop(channel_id, None)
                    # The run is written off, so it must stop counting as "busy": while
                    # this stayed set, a later plain message was STEERED into a run that
                    # was never going to read it, and a later /new queued behind a task
                    # the watchdog had already abandoned it.
                    self.running.discard(channel_id)
                    self.workers.discard(channel_id)
                    q = self.queues.get(channel_id)
                    if q is not None and not q.empty():
                        self._spawn_worker(channel_id, q)
                continue
            if warn_m and quiet > warn_m * 60 and not a.get("warned"):
                a["warned"] = True
                log.warning("stall: no output in %s for %.0f min",
                            channel_id, quiet / 60)
                self._post(channel_id, None,
                           f"⏳ Still on it — nothing posted here for "
                           f"{int(quiet / 60)} min (run started "
                           f"{int((now - a['started']) / 60)} min ago). "
                           f"`/tinycmdr stop` cancels it.",
                           touch=False)

    # -- catch-up: reconnect gaps and restarts lose messages ----------------
    def _is_dm(self, channel_id):
        if channel_id not in self.channel_dm:
            dm = False
            try:
                ch = self.driver.channels.get_channel(channel_id) or {}
                dm = (ch.get("type") == "D")
            except Exception as e:
                log.debug("catch-up: channel lookup failed for %s: %s",
                          channel_id, e)
            self.channel_dm[channel_id] = dm
        return self.channel_dm[channel_id]

    def _catch_up_once(self, now=None):
        """One sweep. Returns the number of recovered messages."""
        now = now or time.time()
        window = int(CONFIG["agent"].get("catch_up_max_minutes") or 30) * 60
        total = 0
        for channel_id, since in list(self.last_seen.items()):
            # +1ms: `since` is inclusive, and after a restart the in-memory dedupe set
            # is empty, so asking from the high-water mark itself would hand the LAST
            # message we already handled back to a fresh process as new work.
            try:
                data = self.driver.posts.get_posts_for_channel(
                    channel_id, params={"since": int(since * 1000) + 1,
                                        "per_page": 50}) or {}
            except Exception as e:
                log.debug("catch-up: query for %s failed: %s", channel_id, e)
                continue
            posts = data.get("posts") or {}
            for pid in reversed(data.get("order") or []):
                p = posts.get(pid) or {}
                uid = p.get("user_id")
                if (not p.get("message") or pid in self.seen
                        or (self.bot_user_id and uid == self.bot_user_id)):
                    continue
                if not user_is_allowed("", uid):
                    self.seen.append(pid)   # never reconsider it
                    continue
                ts = int(p.get("create_at") or 0) / 1000.0
                if ts and ts < now - window:
                    continue
                when = (time.strftime("%H:%M:%S", time.localtime(ts))
                        if ts else "unknown time")
                log.warning("catch-up: recovering a message from %s (%s)",
                            when, pid)
                # Evidence, not assumption: a recovery means this lane IS losing
                # posts. While that is fresh the endpoint gate refuses rather than
                # asking (7 recoveries on 2026-09-12, on the box that runs this work).
                note_steering_gap("recovered a message from %s (%s)" % (when, pid))
                self.enqueue(_CatchUpMessage(p, self._is_dm(channel_id)),
                             p["message"])
                total += 1
        if total:
            log.info("catch-up: recovered %d message(s)", total)
        return total

    def _catch_up_loop(self):
        """mmpy_bot reconnects the websocket but never replays what it missed,
        so a message posted during a gap (or while the bot was restarting) is
        silently ignored. Poll channels we've already been active in, and push
        anything unseen through the normal path."""
        every = max(15, int(CONFIG["agent"].get("catch_up_seconds") or 60))
        window = int(CONFIG["agent"].get("catch_up_max_minutes") or 30)
        log.info("catch-up sweep: every %ds, up to %dm back", every, window)
        # ONE sweep before the first sleep. A restart is the case this sweep exists
        # for, and the channels it has to ask about were just restored from
        # state.json: waiting a full interval first leaves the operator's order
        # unanswered for up to a minute longer than it needs to be.
        if self.last_seen:
            try:
                recovered = self._catch_up_once()
                if recovered:
                    log.info("catch-up: recovered %d message(s) at startup "
                             "(posted while this process was down)", recovered)
            except Exception:
                log.exception("startup catch-up sweep failed")
        while True:
            time.sleep(every)
            if self.driver:
                try:
                    self._catch_up_once()
                except Exception:
                    log.exception("catch-up sweep failed")
                # Listener liveness check (item F): a bot that stays silently deaf must
                # restart rather than sit there. The probe reads the VENDOR's object, so it
                # has to know what that object means - and the old `last_msg > 0` test
                # skipped exactly the deafness it exists for: `_last_msg` is 0 on every
                # fresh websocket (the driver builds one per connect) and `ws` is None
                # whenever there is no connection at all, so a reconnect that never
                # completes, an expired token or a server refusing the upgrade all read as
                # "no data yet" for the life of the process (measured 2026-10-07).
                try:
                    ws = getattr(self.driver, "websocket", None)
                    last_msg = getattr(ws, "_last_msg", None) if ws is not None else None
                    deaf = self._listener_deaf(ws, last_msg)
                    if deaf:
                        self._restart_deaf(deaf)
                except Exception:
                    pass

    def _listener_deaf(self, ws, last_msg, now=None):
        """A reason string when the websocket listener is deaf, else "".

        Three states, and the vendor's semantics decide each (all read in
        mattermostautodriver/websocket.py and driver.py, 2026-10-07):

          ws is None       the driver sets this before a connect and rebuilds the object
                           per connect, so it means "not connected" - a dead server, a
                           refused upgrade, or the connection gone. Deaf. The two-minute
                           dwell keeps an ordinary reconnect from looking like one.
          no `_last_msg`   the object is not the class this probe knows (mmpy_bot may wrap
                           it): say so ONCE rather than reading it as healthy for ever.
          `_last_msg` old  the socket received something once and has been quiet since;
                           the rule the watchdog was written for.

        `now` is injectable so the suite can grade three states without sleeping.
        """
        now = time.time() if now is None else now
        if ws is None:
            if self._ws_missing_since is None:
                self._ws_missing_since = now
            elif (now - self._ws_missing_since > 120
                  and now - self._ws_attach_time > 120):
                return ("the websocket object has been gone for %ds"
                        % int(now - self._ws_missing_since))
            return ""
        self._ws_missing_since = None
        if last_msg is None:
            if not self._ws_probe_warned:
                self._ws_probe_warned = True
                log.warning("listener liveness: %s carries no `_last_msg` to read - the "
                            "deaf-listener watchdog is blind on this driver (it still "
                            "restarts when the socket object is gone)", type(ws).__name__)
            return ""
        if last_msg and now - float(last_msg) > 900:
            return "no message for %ds" % int(now - float(last_msg))
        return ""

    def _restart_deaf(self, why):
        """Leave for a deaf listener the way /restart does - through restart_owner().

        This path used to call os._exit(RESTART_EXIT_CODE) and log "restarting" whatever
        the owner was. On a hand-started bot (Terminal, launch-tinycmdr.sh, a logon task
        with no supervisor) that turned a recoverable condition into a DEAD process with no
        relaunch and a log line asserting an outcome nobody had checked - the class
        /restart already paid for once.
        """
        owner = restart_owner()
        log.critical("websocket listener deaf (%s) - restarting (owner: %s)", why, owner)
        if owner == "self":
            try:
                _spawn_replacement()
            except Exception as e:                               # noqa: BLE001
                log.exception("could not start a replacement process: %s", e)
                return
            time.sleep(0.5)
            os._exit(0)
        _release_lock()
        time.sleep(0.5)
        os._exit(RESTART_EXIT_CODE)

    def _drain(self, channel_id):
        q = self.queues.get(channel_id)
        if q:
            try:
                while True:
                    q.get_nowait()
            except queue.Empty:
                pass
        with self.steering_lock:
            self.steering.pop(channel_id, None)

    def _channel_busy(self, channel_id):
        """Is a run still in flight for this channel?

        Deliberately NOT "has an unset cancel event": the stall watchdog (and an
        earlier /stop) SETS those events while the wedged run is still unwinding.
        Reading that as "nothing is running" is what made a /stop answer "Nothing
        is running right now" while the channel was still busy - the
        operator reads that as "my stop was ignored".
        """
        return channel_id in self.running or channel_id in self.active

    def _stop_channel(self, channel_id, post_root):
        """One /stop implementation for both entry points (listener + handler)."""
        events = self.cancel_events.get(channel_id, set())
        live = [e for e in events if not e.is_set()]
        # A run this channel did not spawn - a scheduled job reporting into it, a
        # background task - lives only in the session registry, so /stop has to reach
        # it here too or a wedged cron job answers "nothing is running".
        runs = RUNS.by_channel(channel_id)
        live += [c for c in runs if not c.cancel_event.is_set()]
        busy = self._channel_busy(channel_id) or bool(runs)
        # A run parked on an ask_user question must be RELEASED, not merely flagged: its
        # cancel check runs only once the wait returns, so without this a /stop sat out
        # the whole window - the "my stop was ignored" complaint.
        for _sk in list(self.pending_asks):
            _r = self.pending_asks.get(_sk)
            if _r and not _r["ev"].is_set():
                _r["answer"] = None
                # Flag it as a STOP, not an empty answer: ask_operator reads this and
                # reports "stopped". Without it the run came back as a timeout and the
                # model was told "nobody is at the keyboard, apply your own judgment and
                # carry on" - the opposite of what /stop means.
                _r["stopped"] = True
                _r["ev"].set()
        self._drain(channel_id)
        for e in events:              # idempotent: re-flag anything still set to run
            e.set()
        for c in runs:                # ...and the same for a run this channel did not spawn
            c.cancel_event.set()
        if live:
            note = "🛑 Stopping now — nothing further will be executed."
        elif busy:
            note = ("🛑 That run is already flagged to stop and will execute nothing "
                    "further, but it has not unwound yet (`/tinycmdr status` for state). The "
                    "stall watchdog abandons it if it stays quiet.")
        else:
            note = "Nothing is running right now."
        self._post(channel_id, post_root, note)

    def _take_steering(self, channel_id):
        """Drain the steering messages for a channel. Called from inside the run."""
        with self.steering_lock:
            return self.steering.pop(channel_id, [])

    def _requeue_steering(self, channel_id):
        """Give back any steering the run never read, as ordinary queued messages.

        A correction must never be swallowed by the run it was meant to redirect, and the run can
        end between the drain and the next step (a stop, a loop-stop, an infra failure).
        """
        left = self._take_steering(channel_id)
        if not left:
            return 0
        log.info("requeuing %d unread steering message(s) for %s", len(left), channel_id)
        q = self.queues.setdefault(channel_id, queue.Queue())
        for sender_, txt_ in left:
            q.put((sender_, txt_, None, None, True))
        return len(left)

    def _handle(self, channel_id, sender, text, msg_id, thread_root, is_dm,
                gen=0):
        session_key = f"mm-{channel_id}"
        # DMs are a flat conversation (no subthread per message); in channels,
        # work happens in a thread under the mentioning message.
        post_root = None if is_dm else thread_root
        stripped = text.strip()
        low = stripped.lower()
        retried = False

        # -- slash commands (handled locally, never sent to the model) -------
        # `/tinycmdr <verb>` is the namespaced form of everything below: one registered
        # trigger in the client that carries any command (a bare `help` and `status`
        # are the client's own words and can never reach a bot). The bare verbs stay
        # reachable - the relay posts them that way.
        _cmdr = cmdr_strip(stripped)
        if _cmdr != stripped:
            stripped, low = _cmdr, _cmdr.lower()
        if low in ("/new", "/reset", "!reset", "new session"):
            AGENT.reset(session_key)
            self._post(channel_id, post_root, "🔄 Session cleared. Fresh context.")
            return
        if low == "/stop":
            self._stop_channel(channel_id, post_root)
            return
        if low == "/restart" or low == "/restart force":
            force = low.endswith("force")
            running = (any(not e.is_set()
                           for events in self.cancel_events.values()
                           for e in events)
                       or self._channel_busy(channel_id))
            if running and not force:
                self._post(channel_id, post_root,
                           "⚠️ A task is still running. `/tinycmdr stop` it first, or "
                           "use `/tinycmdr restart force` to kill it and restart now.")
                return
            self._post(channel_id, post_root,
                       "♻️ Restarting — back in a few seconds, and I'll confirm "
                       "here when I'm up. Sessions and scheduled jobs survive; "
                       "config.json and tinycmdr.py changes are picked up.")
            perform_restart(channel_id, post_root, sender)
            return  # unreachable; the process is replaced
        if low == "/model" or low.startswith("/model "):
            parts = stripped.split(maxsplit=1)
            arg = parts[1] if len(parts) > 1 else ""
            self._post(channel_id, post_root, model_command(session_key, arg))
            return
        if low == "/status":
            self._post(channel_id, post_root,
                       status_text(session_key, paused=self.paused))
            return
        if low == "/undo" or low.startswith("/undo "):
            parts = stripped.split()
            try:
                n = int(parts[1]) if len(parts) > 1 else 1
            except ValueError:
                n = 1
            removed = AGENT.undo(session_key, max(1, min(n, 50)))
            if removed:
                self._post(channel_id, post_root,
                           f"↩️ Removed the last {removed} exchange(s) "
                           "from this session.")
            else:
                self._post(channel_id, post_root, "Nothing to undo.")
            return
        # `/tinycmdr <verb>` for the management verbs: one word per thing, every surface.
        # Measured 2026-09-24: this lane dispatched /new /stop /restart /model /status /undo
        # and nothing else, so `/tinycmdr update` - the command the fleet is updated with -
        # fell through to the model as ordinary text.
        _v = low[1:].split()[0] if low.startswith("/") and len(low) > 1 else ""
        if _v in _CHAT_VERB_SET:
            _line = stripped[1:]
            _out = verb_from_chat(_line)
            self._post(channel_id, post_root, _out)
            # `/tinycmdr update` must leave the NEW code running: an update that changed
            # the version and stopped there would be the old bytes serving the channel
            # while the operator believes it is updated. One command, then the host door.
            if (_line.strip().split()[:1] or [""])[0].lower() == "update" \
                    and "VERSION " in str(_out) and "->" in str(_out) \
                    and "already up to date" not in str(_out):
                self._post(channel_id, post_root,
                           "♻️ Restarting onto it now - back in a few seconds.")
                perform_restart(channel_id, post_root, sender)
                return
            return
        if low == "/retry":
            last = AGENT.pop_last_user(session_key)
            if last is None:
                self._post(channel_id, post_root, "Nothing to retry.")
                return
            self._post(channel_id, post_root,
                       "🔁 Retrying your last request...")
            stripped = last if isinstance(last, str) else \
                "\n".join(p.get("text", "") for p in last
                          if isinstance(p, dict))
            low = stripped.lower()
            retried = True
            text = stripped  # task path below builds full_text from `text`
            # fall through to the normal task path below
        elif low == "/bg" or low.startswith("/bg "):
            parts = stripped.split(maxsplit=1)
            if len(parts) < 2 or not parts[1].strip():
                self._post(channel_id, post_root, "Usage: `/bg <task>`")
                return
            bg_text = parts[1].strip()
            bg_key = f"{session_key}-bg-{int(time.time())}"

            def bg_run():
                cancel = threading.Event()
                self.cancel_events.setdefault(channel_id, set()).add(cancel)
                # inherit this conversation's model instead of falling back to
                # the config default (bg sessions are their own session key)
                inherited = AGENT.model_overrides.get(session_key)
                if inherited:
                    AGENT.model_overrides[bg_key] = inherited
                self._post(channel_id, post_root,
                           f"🧵 Background task started: {bg_text[:150]}")
                rep = ProgressReporter(self, channel_id, post_root, bg_key,
                                       label="🧵 Working…")
                try:
                    result = drive_run(bg_key, bg_text, rep,
                                       ask_door=self.ask_door_factory(
                                           channel_id, bg_key),
                                       cancel_event=cancel,
                                       channel_id=channel_id)
                except Exception as e:
                    log.exception("background task failed")
                    result = f"⚠️ Background task broke: {e}"
                    rep.finish(ok=False)
                else:
                    rep.finish(ok=True)
                finally:
                    evs = self.cancel_events.get(channel_id)
                    if evs:
                        evs.discard(cancel)
                    AGENT.model_overrides.pop(bg_key, None)
                self._post(channel_id, post_root,
                           f"🧵 Background task done: {bg_text[:80]}\n\n"
                           f"{result}")
                AGENT.reset(bg_key)  # bg sessions are one-shot

            threading.Thread(target=bg_run, daemon=True).start()
            return
        if low == "/pause" or low.startswith("/pause "):
            parts = stripped.split(maxsplit=1)
            arg = parts[1].strip() if len(parts) > 1 else ""
            if arg.lower() == "off":
                self.paused = None
                self._post(channel_id, post_root, "▶️ Resumed.")
            else:
                self.paused = arg or "no reason given"
                self._post(channel_id, post_root,
                           f"⏸️ Paused ({self.paused}). New tasks will be "
                           "held — `/pause off` to resume.")
            return
        if low == "/reasoning" or low.startswith("/reasoning "):
            arg = stripped.split(maxsplit=1)[1].strip().lower() if " " in stripped else ""
            over = AGENT.reasoning_overrides
            cur = over.get(session_key) or CONFIG["llm"].get("reasoning") or "auto"
            if arg in ("", "?", "status"):
                self._post(channel_id, post_root,
                           "\U0001f9e0 Reasoning effort: **%s** (this conversation; "
                           "config default %s).\nUsage: `/reasoning <auto|off|%s>` - "
                           "`auto` sends no reasoning field at all, `off` disables it "
                           "where the endpoint supports that."
                           % (cur, CONFIG["llm"].get("reasoning") or "auto",
                              "|".join(REASONING_LEVELS)))
            elif arg == "auto":
                over.pop(session_key, None)
                try:
                    over.touched.add(session_key)
                except Exception:
                    pass
                _save_overrides()
                self._post(channel_id, post_root,
                           "\U0001f9e0 Reasoning effort back to auto (no field sent).")
            elif arg in REASONING_LEVELS or arg == "off":
                over[session_key] = arg
                try:
                    over.touched.add(session_key)
                except Exception:
                    pass
                _save_overrides()
                wire = {"effort": "reasoning_effort",
                        "responses": "reasoning.effort",
                        "budget": "thinking.budget_tokens"}[
                            str(CONFIG["llm"].get("reasoning_mode") or "auto")
                            if str(CONFIG["llm"].get("reasoning_mode") or "auto")
                            in ("effort", "responses", "budget")
                            else ("responses" if "/responses" in str(self.llm_url or "")
                                  else "budget" if "anthropic" in str(self.llm_url or "").lower()
                                  else "effort")]
                self._post(channel_id, post_root,
                           "\U0001f9e0 Reasoning effort for this conversation: **%s** "
                           "(sent as `%s`)." % (arg, wire))
            else:
                self._post(channel_id, post_root,
                           "\U0001f9e0 Unknown level %r - use auto, off, or one of: %s."
                           % (arg, ", ".join(REASONING_LEVELS)))
            return
        if low == "/plan" or low.startswith("/plan "):
            arg = stripped.split(maxsplit=1)[1].strip().lower() if " " in stripped else ""
            if arg in ("on", "off"):
                mode = plan_mode_set(session_key, "plan" if arg == "on" else "execute")
                if mode == "plan":
                    self._post(channel_id, post_root,
                               "🧭 Plan mode ON — this machine is read-only: the agent "
                               "investigates and records a plan, and nothing writes or "
                               "runs until `/plan apply`.")
                else:
                    self._post(channel_id, post_root,
                               "🧭 Plan mode OFF — execution resumed.")
            elif arg in ("apply", "approve"):
                plan_mode_set(session_key, "execute")
                body = plan_render(session_key)
                self._post(channel_id, post_root,
                           "✅ Plan approved — execution mode is on."
                           + ("\n\n" + body if body else ""))
            else:
                state = ("plan (read-only)" if plan_mode(session_key) == "plan"
                         else "execute")
                self._post(channel_id, post_root,
                           f"🧭 Mode: {state}. Usage: `/plan on` (look, don't touch), "
                           f"`/plan apply` (approve and execute), `/plan off` "
                           f"(resume execution).")
            return
        if low == "/fork" or low.startswith("/fork "):
            parts = stripped.split(maxsplit=1)
            want = parts[1].strip() if len(parts) > 1 else ""
            made = AGENT.fork(session_key, want or None)
            if not made:
                self._post(channel_id, post_root,
                           "Nothing to fork yet - this session has no saved turns.")
            else:
                self._post(channel_id, post_root,
                           f"🍴 Forked to `{made}` - the original is untouched. "
                           f"`/tinycmdr resume {made}` continues the copy.")
            return
        if low == "/save":
            hist = AGENT._history(session_key)
            if not hist:
                self._post(channel_id, post_root, "This session is empty.")
                return
            lines = [f"# tinycmdr session export — {session_key}",
                     f"_{time.strftime('%Y-%m-%d %H:%M')}_\n"]
            for m in hist:
                role = m.get("role", "?")
                if role == "tool":
                    continue
                content = m.get("content")
                if not isinstance(content, str) or not content.strip():
                    continue
                label = {"user": "**You**", "assistant": "**tinycmdr**",
                         "system": "**system**"}.get(role, f"**{role}**")
                lines.append(f"{label}:\n{content}\n")
            ts = time.strftime("%Y%m%d-%H%M%S")
            _ensure_sessions_dir()
            path = os.path.join(SESSIONS_DIR, f"export-{ts}.md")
            with open(path, "w", encoding="utf-8") as f:
                f.write("\n".join(lines))
            self._post(channel_id, post_root,
                       f"💾 Session exported to `{path}` "
                       f"({len(hist)} messages).")
            return
        if low == "/version":
            self._post(channel_id, post_root, f"tinycmdr v{VERSION}")
            return
        if low == "/help":
            self._post(channel_id, post_root,
                       "**Commands** — type `%s` then one of these "
                       "(`%s help` is this list):\n"
                       "`new` fresh session · `stop` cancel the running "
                       "task · `status` health & context usage\n"
                       "`undo [N]` drop the last N exchanges · `retry` "
                       "re-run your last request · `save` export session\n"
                       "`bg <task>` run in background · `pause [reason|off]` "
                       "hold new tasks\n"
                       "`model [name|list]` show/list/switch model · "
                       "`restart [force]` restart the bot · `version` · `help`\n"
                       "The same word everywhere: `%s status` in a shell or a "
                       "session, `%s status` here.\n"
                       "Everything else is a task — just tell me what you "
                       "need." % (CMDR, CMDR, CMDR, CMDR))
            return
        if cmdr_legacy_prefix(stripped):
            # `/cmdr` existed for one day; a near-miss deserves a pointer, not a shrug.
            self._post(channel_id, post_root, CMDR_MOVED)
            return
        if stripped.startswith("/") and not retried:
            self._post(channel_id, post_root,
                       f"Unknown command `{stripped.split()[0]}` — try {CMDR} help. "
                       "(Slash commands are handled locally; nothing was sent "
                       "to the model.)")
            return

        # One live status line (edited in place) plus periodic check-in posts —
        # the edits alone never reach the operator's phone.
        rep = ProgressReporter(self, channel_id, post_root, session_key)

        # attachments: fetch the full post, save files, build vision content
        try:
            post = self.driver.posts.get_post(msg_id)
        except Exception:
            post = {}
        notes, images = self._process_attachments(post)
        full_text = text + ("\n" + "\n".join(notes) if notes else "")
        rich = None
        if images:
            rich = [{"type": "text", "text": full_text}]
            for mime, b64 in images:
                rich.append({"type": "image_url",
                             "image_url": {"url": f"data:{mime};base64,{b64}"}})

        cancel = threading.Event()
        self.cancel_events.setdefault(channel_id, set()).add(cancel)
        try:
            answer = drive_run(session_key, full_text, rep, rich_content=rich,
                               cancel_event=cancel,
                               steer_cb=lambda: self._take_steering(channel_id),
                               ask_door=self.ask_door_factory(channel_id,
                                                              session_key),
                               channel_id=channel_id,
                               # the channel's own watchdog is stronger here: it also
                               # reclaims the wedged worker, so this run is not watched
                               # twice (the record still exists, for /stop and status).
                               watch=False)
        except Exception as e:
            log.exception("agent run failed")
            answer = f"⚠️ Something broke on my side: {e}"
            rep.finish(ok=False)
        else:
            rep.finish(ok=True)
        finally:
            evs = self.cancel_events.get(channel_id)
            if evs:
                evs.discard(cancel)
            # Anything steered after the run's last drain becomes a normal message, so a
            # correction can never be swallowed by the run it was meant to redirect.
            self._requeue_steering(channel_id)
        if gen and self.worker_gen.get(channel_id) != gen:
            # the watchdog abandoned this run; its worker no longer owns the
            # channel, so a late answer here would interleave with whatever
            # replaced it.
            log.warning("dropping the answer from an abandoned run in %s",
                        channel_id)
            return
        # deliberately unbarred: after a run of colored progress lines, a plain
        # post is the signal that this is the payload and not more working noise
        self._post(channel_id, post_root, answer)


def status_text(key, paused=None):
    """The one /status renderer, used by the Mattermost handler.

    These had drifted into two copies with different fields (one was missing
    sampling and notes, so 'check /status' meant different things depending on
    where you typed it). Plain text on purpose: Mattermost renders markdown and
    plain lines read correctly there too.
    """
    s = AGENT.stats(key)
    uptime = int(time.time() - START_TIME)
    hours, rem = divmod(uptime, 3600)
    mins = rem // 60
    jobs = len(SCHEDULER.jobs) if SCHEDULER else 0
    try:
        notes_kb = NOTES_FILE.stat().st_size / 1024
    except OSError:
        notes_kb = 0
    model = (AGENT.model_overrides.get(key) or CONFIG["llm"]["model"])
    budget = AGENT._context_budget()
    last = fmt_usage(AGENT.last_usage.get(key))
    lines = [f"tinycmdr v{VERSION} on {socket.gethostname()}",
             f"model: {model} → {model_route_for(model)}",
             f"sampling: {sampling_summary()}",
             f"stream:   {llama_extensions_summary()}",
             f"session: {s['exchanges']} exchanges, ~{s['est_tokens']:,} / "
             f"{budget:,} tokens in context "
             f"({100 * s['est_tokens'] // max(1, budget)}%)"]
    if last:
        lines.append(f"last run: {last}")
    lines.append(f"custom tools: {len(REGISTRY.custom)} · "
                 f"skills: {len(skill_index())} · jobs: {jobs}")
    # What this session's requests actually carry. With disclosure on, the visible set is
    # the core list plus whatever this session has already revealed.
    try:
        vis = len(select_tool_schemas(key))
        allt = len(CORE_TOOLS) + len(REGISTRY.custom)
        lines.append(f"tools: {vis} visible of {allt} on this box"
                     + (" (disclosure on: find_tools reveals the rest)"
                        if disclosure_on() else " (disclosure off)"))
    except Exception:
        pass
    # The guardrails, so the operator can see the limits without opening config.
    a = CONFIG["agent"]
    lines.append(
        f"limits: steps {a.get('max_steps')} · run {a.get('max_minutes')}m · "
        f"stall {a.get('stall_warn_minutes')}/{a.get('stall_abandon_minutes')}m "
        f"· dedupe {a.get('loop_dedupe_after')} · loop-stop "
        f"{a.get('loop_stop_repeats')}")
    _ask_lim = (f"on, wait {int(float(a.get('ask_user_wait_seconds') or 120))}s"
                if a.get("ask_user") else "off (agent.ask_user)")
    try:
        _p = CONFIG.get("_dispatcher")
        _pending = _p(_ask_user_pending(key)) if _p else None
    except Exception:
        _pending = None
    lines.append(f"ask_user: {_ask_lim}"
                 + (f" · WAITING on: {_pending['question'][:90]}" if _pending else ""))
    lines.append(f"notes.md: {notes_kb:.1f} KB · uptime: {hours}h {mins}m")
    if paused is not None:
        lines.append(f"paused: {paused or 'no'}")
    return "\n".join(lines)


# --------------------------------------------------------------- lane state
# "Is it up?" had three answers, and all three were true about the wrong question: the
# process was running, an endpoint answered, a token was configured - while the bot could not
# hear anybody. Measured on a live install, 2026-09-28: 510 restarts, a health probe returning
# {"ok": true}, `tinycmdr health` naming mattermost because a token EXISTED, and nothing
# anywhere saying the chat lane was dead.
# Two consequences shape this section:
#   * a dying process cannot count its own restarts, so the failure record is MIRRORED TO
#     DISK (logs/state.json, atomic); the next start reads it back and says "attempt 511";
#   * the log gets one line per STATE CHANGE, not one per attempt. The incident wrote 419 KB
#     of the same CRITICAL every ten seconds, which is noise, not a signal.
def _lane_state_read():
    data = _load_json_state(LANE_STATE_FILE, "the lane failure record")
    return data if isinstance(data, dict) else {}


def _lane_state_write():
    """Best-effort and atomic, and never fatal: a bot must not die because a status file
    could not be written (and a fresh clone has no logs/ until this creates one).

    Merged PER LANE, never replaced wholesale: another process can own a different lane
    (the pair-lane service, a `--once` run, a cron `health`), and writing this process's
    whole view erased the other lane's record - the pair process, or a second writer,
    silently blanked a lane it never touched (A-181). Only the lanes THIS process has
    written are authoritative here; every other lane's on-disk record is carried over."""
    try:
        LANE_STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
        # The whole read-merge-write is under the lock: the pair-lane process has the
        # Mattermost lane and the Telegram lane in two threads, and two same-process
        # writers must not read the same "before" and lose one lane's update.
        with _LANE_LOCK:
            lanes = json.loads(json.dumps(LANE_STATE))
            fails = json.loads(json.dumps(LANE_FAILS))
            touched = set(_LANE_TOUCHED)
            data = _lane_state_read()
            merged_lanes = dict(data.get("lanes") or {})
            merged_fails = dict(data.get("failures") or {})
            for lane in touched:
                if lane in lanes:
                    merged_lanes[lane] = lanes[lane]
                else:
                    merged_lanes.pop(lane, None)
                if lane in fails:
                    merged_fails[lane] = fails[lane]
                else:
                    merged_fails.pop(lane, None)
            data.update({"version": VERSION, "pid": os.getpid(), "updated": time.time(),
                         "lanes": merged_lanes, "failures": merged_fails})
            data.setdefault("started", time.time())
            atomic_write_text(LANE_STATE_FILE,
                              json.dumps(data, indent=2, sort_keys=True) + "\n")
    except Exception as e:                                   # noqa: BLE001
        log.debug("could not write %s: %s", LANE_STATE_FILE, e)


def _lane_fails_load():
    """Bring the persisted failure records in once, so attempt counts survive a restart."""
    global _LANE_FAILS_LOADED
    if not _LANE_FAILS_LOADED:
        _LANE_FAILS_LOADED = True
        stored = _lane_state_read().get("failures") or {}
        if isinstance(stored, dict):
            with _LANE_LOCK:
                LANE_FAILS.update(stored)


def _lane_fails_snapshot():
    _lane_fails_load()
    with _LANE_LOCK:
        return json.loads(json.dumps(LANE_FAILS))


LANE_PERMANENT_BACKOFF = 600      # a credential the service REFUSED is not an outage


def _lane_reason(exc):
    """A reason worth reading, even when the exception carries none.

    mattermostautodriver raises `InvalidOrMissingParameters(message)` where `message` is the
    API's empty `message` field for a bad token: str(exc) is "", so the lane recorded "no
    detail", `doctor` printed that, and the log line was blank. Measured on a Windows install,
    """
    text = str(exc).strip()
    name = type(exc).__name__
    if not text:
        text = repr(exc).strip() or name
        if text in (name + "()", name + "('',)", name + '("",)'):
            text = name           # "InvalidOrMissingParameters()" reads worse than the name
    if name not in text:
        text = "%s: %s" % (name, text)
    return text[:400]


# The failures a HUMAN has to fix. Everything else is retried on the growing backoff.
# The status must arrive in a STATUS SHAPE - "HTTP 401", "status: 403", "401 Unauthorized",
# "error code 400" - and not as a bare number anywhere in the text: `\b40[13]\b` matched a
# port ("connect to host:401"), an id ("update id 401") or a run number, marking a TRANSIENT
# network fault PERMANENT and parking it on the refused-credential retry (A-183). Every true
# refusal the libraries hand us is in that shape ("401 Invalid or expired session"; our own
# probe says "HTTP 400 Bad Request at <url>"), so the shape keeps the true positives.
_LANE_PERMANENT_RE = re.compile(
    r"(?:(?:http|status|error[_ ]?code|response|api|reason)[\s:=\-]*40[013]\b"
    r"|\b40[013]\b[\s:,()\-]*(?:bad request|unauthori[sz]ed|forbidden|invalid|expired|"
    r"refused|denied|missing|unusable|no[t]?\s+authoriz)"
    r"|InvalidOrMissingParameters|NoAccessTokenProvided|NotEnoughPermissions"
    r"|unauthori[sz]ed"
    r"|the token was refused|no Mattermost token|no Telegram token|is unusable)", re.I)


def _lane_error_permanent(exc):
    """True when no amount of waiting will start this lane: the service answered and said no."""
    return bool(_LANE_PERMANENT_RE.search(_lane_reason(exc)))


# The reason CLASSES. The counting in lane_down must not key on the literal text: the
# caller's own message carries a clock, a pid or a count ("poll failing for 5 min: ...")
# and the transport's varies per attempt ("Connection reset by peer" one minute,
# "Temporary failure in name resolution" the next), so a lane that kept failing looked
# like a lane failing DIFFERENTLY every time - the count reset on every attempt and the
# escalation never accumulated (A-179/A-180). A class is what a human would call it.
_LANE_UNREACHABLE_RE = re.compile(
    r"(connection|connect|timed? ?out|timeout|unreachable|reset by peer|broken pipe|"
    r"no route|name resolution|temporary failure|dns|socket|ssl|network|proxy|"
    r"max retries|could not be reached|requests\.)", re.I)
_LANE_CLASS_WS = re.compile(r"\s+")
_LANE_CLASS_NUM = re.compile(r"\d+")


def _lane_reason_class(reason):
    """The class a lane's reason belongs to, for counting repeats: refused, unreachable,
    or the number-stripped shape for anything else (a port, an errno or a count cannot
    split one failure into many)."""
    text = _LANE_CLASS_WS.sub(" ", str(reason or "").strip().lower())
    if _LANE_PERMANENT_RE.search(text):
        return "refused"
    if _LANE_UNREACHABLE_RE.search(text):
        return "unreachable"
    return _LANE_CLASS_NUM.sub("#", text)[:120] or "unknown"


def lane_down(lane, error):
    """Record a lane failing. Returns (count, was_same_error, first_seen) so the caller can
    decide what to SAY: the full story once per state, and nothing while the same error
    repeats on the retry backoff.

    The repeat is keyed on the LANE and the reason's CLASS, not the literal text - see
    _lane_reason_class. A stubborn failure whose message carried a changing clock, count
    or errno used to look like a brand-new failure on every attempt."""
    _lane_fails_load()
    now = time.time()
    reason_class = _lane_reason_class(error)
    with _LANE_LOCK:
        prior = LANE_FAILS.get(lane) or {}
        prior_class = prior.get("reason_class")
        if prior_class is None and prior.get("error"):
            prior_class = _lane_reason_class(prior["error"])   # a record from an older build
        same = bool(prior) and prior_class == reason_class
        first = prior.get("first") if same else now
        count = (prior.get("count") or 0) + 1 if same else 1
        LANE_FAILS[lane] = {"count": count, "error": error,
                            "reason_class": reason_class, "first": first, "last": now}
        LANE_STATE[lane] = {"ok": False, "detail": error, "since": first}
        _LANE_TOUCHED.add(lane)
    _lane_state_write()
    return count, same, first


def lane_up(lane, detail=""):
    """Record a lane connecting. A recovery is news ONCE (the supervisor's own words: a
    silently-recovered bot is indistinguishable from a dead one from the outside)."""
    _lane_fails_load()
    with _LANE_LOCK:
        prior = LANE_FAILS.pop(lane, None)
        LANE_STATE[lane] = {"ok": True, "detail": detail, "since": time.time()}
        _LANE_TOUCHED.add(lane)
    _lane_state_write()
    if prior and prior.get("count"):
        log.warning("%s lane recovered after %d failed start(s), the first at %s",
                    lane, prior["count"],
                    time.strftime("%Y-%m-%d %H:%M", time.localtime(prior.get("first") or 0)))


def lane_poll_failure_due(failing_since, now, grace=300.0):
    """True when a lane whose polls have failed since `failing_since` must be reported down.

    A lane that STARTED and then went deaf never raises, so nothing ever calls
    lane_down: the record keeps saying "up" while the box can hear nothing. The
    Telegram poll loop retries internally for ever; this is the decision that turns
    that silence into a lane record every other reader can see.

    `failing_since` and `now` must come from the SAME clock, and the caller passes a
    MONOTONIC one: a wall clock steps backwards (NTP, a VM resume), `now - failing_since`
    then goes NEGATIVE, and the comparison reads that as "no time has passed" and
    silences the report on a lane that is still deaf (A-182). A caller that does hand a
    backwards pair gets True, not False - a subtraction across a clock step proves
    nothing, and the failure this decision exists to fix is the SILENCE.
    """
    if failing_since is None:
        return False
    elapsed = now - failing_since
    if elapsed < 0:
        return True
    return elapsed >= grace


# ------------------------------------------------- retrying a lane that CANNOT START
# The Windows helper (tinycmdr-supervise.py) relaunches a crashed bot on a GROWING backoff,
# but systemd's RestartSec and launchd's ThrottleInterval are fixed - neither manager can
# grow a delay - so on Linux and macOS a lane that could not start exited every 10s and
# re-imported this 22k-line module with it. Measured 2026-09-30: 1654 startups in the 4h45m
# the network was gone. Retrying HERE gives every host the supervisor's curve from the same
# build, and leaves the manager its fixed delay for what only a manager can do: the CRASH
# backstop, which needs the process to be GONE first.
LANE_BACKOFF_START = 5           # tinycmdr-supervise.py BACKOFF_START - keep in step
LANE_BACKOFF_MAX = 60            # ... BACKOFF_MAX
LANE_RAPID_EXIT_S = 30           # ... RAPID_EXIT_S: a shorter lifetime is a failed start


def lane_backoff(failures):
    """tinycmdr-supervise.py's next_backoff, in-process: 5, 10, 20, 40, 60, 60, ..."""
    return min(LANE_BACKOFF_MAX, LANE_BACKOFF_START * (2 ** max(0, failures - 1)))


def lane_backoff_after(failures, uptime):
    """What one failed lane start means for the next try: (failures, delay).

    The supervisor's reset rule: a lifetime longer than LANE_RAPID_EXIT_S was healthy, so
    the count resets and the next attempt waits the start delay; a shorter one is a failed
    start and grows the backoff. `uptime` is clamped at 0 first: a backwards clock makes
    `now() - t0` negative, and a negative lifetime is a failed start, not a shorter path
    through the curve (A-184). `failures` is clamped too, so a caller cannot hand the
    curve a negative count.
    """
    failures = max(0, failures)
    uptime = max(0.0, uptime)
    if uptime > LANE_RAPID_EXIT_S:
        return 0, LANE_BACKOFF_START
    failures += 1
    return failures, lane_backoff(failures)


def _lane_wait(seconds):
    """The one place the retry sleeps, so a suite can drive the backoff without sleeping
    (the same seam _stall_tick gets from its now=)."""
    time.sleep(seconds)


def lane_with_retry(start, lane, report, sleep=None, now=None):
    """Run a chat lane, retrying one that cannot START, in this process.

    `start` raising SystemExit is NOT caught: a missing token, a broken config and a token
    the API refused all need a human, and the line between "this will fix itself" and "this
    needs a human" is the point of retrying the connectivity-class failures only. `report`
    gets (error, count, same, first_seen, delay) and decides what to SAY: the log stays one
    line per STATE change, never one per attempt. Returns when the lane ends by itself.
    """
    sleep = sleep or _lane_wait
    now = now or time.time
    failures = 0
    while True:
        t0 = now()
        try:
            start()
        except Exception as e:                                # noqa: BLE001 - retried
            permanent = _lane_error_permanent(e)
            if permanent:
                # It will not fix itself, and 5, 10, 20, 60 seconds of retrying said
                # nothing: the operator's log had 723 failed starts and one blank ERROR
                # line each (a Windows install, 2026-10-02). Say it once, then park on a long
                # interval - which also keeps the OTHER lane (a daemon thread here) alive.
                failures, delay = failures + 1, LANE_PERMANENT_BACKOFF
            else:
                failures, delay = lane_backoff_after(failures, now() - t0)
            count, same, first = lane_down(lane, _lane_reason(e))
            report(e, count, same, first, delay, permanent)
            sleep(delay)
            continue
        return


def _lane_report_mattermost(e, count, same, first, delay, permanent=False):
    """One line per STATE, not one per attempt: a repeat of the SAME error is not news (the
    incident wrote 419 KB saying so), and the count and the reason are in LANE_STATE_FILE
    where `tinycmdr health` reads them."""
    if same and count > 1:
        return
    if permanent:
        log.critical("Mattermost REFUSED this bot's credentials: %s. Waiting will not fix "
                     "it — the lane is parked and retried every %ds. Replace the token: "
                     "`tinycmdr token set TINYCMDR_MM_TOKEN`, then `tinycmdr restart` "
                     "(and check mattermost.url in config.json).", _lane_reason(e), delay)
        return
    log.critical("Mattermost connection failed: %s — this bot cannot hear anybody. Check "
                 "mattermost.url/port in config.json, and the bot token in %s as "
                 "TINYCMDR_MM_TOKEN (System Console -> Integrations -> Bot Accounts). "
                 "Retrying in %ds; `tinycmdr health` reports this with exit code 1, and "
                 "the full state is in %s.", _lane_reason(e), ENV_FILE.name, delay,
                 LANE_STATE_FILE)


def _lane_report_telegram(e, count, same, first, delay, permanent=False):
    """The Telegram twin: what reaches here is the network. A token the API REFUSED is a
    permanent failure and exits 2 from the lane itself, before this."""
    if same and count > 1:
        return
    if permanent:
        log.critical("Telegram REFUSED this bot's token: %s. Replace it: `tinycmdr token "
                     "set TINYCMDR_TG_TOKEN`, then `tinycmdr restart`.", _lane_reason(e))
        return
    log.critical("Telegram lane is down: %s — this bot cannot hear anybody. Check this "
                 "host's network and TINYCMDR_TG_TOKEN in %s; retrying in %ds. `tinycmdr "
                 "health` reports this with exit code 1, and the full state is in %s.",
                 _lane_reason(e), ENV_FILE.name, delay, LANE_STATE_FILE)


def _lane_token(lane):
    if lane == "mattermost":
        return _mm_token_configured()
    if lane == "telegram":
        return _tg_token_configured()
    return ""


def _lane_pid_alive(pid):
    """Is the process that WROTE the lane record still running?

    A cold reader (`tinycmdr health` in a cron job, the page) reads the LAST record, and
    nothing said whether its writer was still there: a crashed bot's last "up" was handed
    to the operator as current state (A-186). A pid this process is (or has just written
    with) is alive; anything unopenable is not.
    """
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return False
    if pid <= 0:
        return False
    if pid == os.getpid():
        return True
    if os.name == "nt":
        # os.kill(pid, 0) is not a liveness probe on Windows; OpenProcess is the documented
        # one. PROCESS_QUERY_LIMITED_INFORMATION (0x1000) asks without needing full access.
        try:
            import ctypes
            kern = ctypes.windll.kernel32
            handle = kern.OpenProcess(0x1000, False, pid)
            if not handle:
                return False
            kern.CloseHandle(handle)
            return True
        except Exception:                                    # noqa: BLE001
            return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True          # it exists, it just is not ours to signal
    except OSError:
        return False
    return True


def lanes_snapshot():
    """Every lane this build knows about, with what is actually RECORDED about it.

    A lane with no record is `configured`, not connected - that distinction is the whole
    point: the incident's `health` said "mattermost" because a token existed. A cold process
    (a cron job running `tinycmdr health`) still reports the LAST known state from disk, with
    `as_of` so a reader can see how stale it is.
    """
    _lane_fails_load()
    stored = _lane_state_read()
    with _LANE_LOCK:
        state = json.loads(json.dumps(LANE_STATE)) or (stored.get("lanes") or {})
        fails = json.loads(json.dumps(LANE_FAILS)) or (stored.get("failures") or {})
    out = {}
    for lane in ("mattermost", "telegram", "web"):
        if lane == "web":
            # The page lane carries no chat token, so its evidence is the RECORD
            # run_webui writes: lane_up on bind, lane_down when it cannot start. A cold
            # process on a box that merely has web.enabled (the default) has no news to
            # report, and "configured, never started" would read as a lane on a box that
            # deliberately runs CLI-only (tests/test_lane_choice grades that line). Once a
            # record exists it is kept current and reported like the chat lanes
            # (measured 2026-10-05: logs/state.json held a current `web` record while
            # /api/health, `tinycmdr health` and doctor showed two lanes, so "the page
            # never started" was invisible to the operator's one "is it alive?" command).
            if not (state.get(lane) or fails.get(lane)):
                continue
            if not (CONFIG.get("web") or {}).get("enabled", True):
                continue
        elif not _lane_token(lane):
            continue
        st = state.get(lane) or {}
        fail = fails.get(lane) or {}
        alive = _lane_pid_alive(stored.get("pid"))
        out[lane] = {
            "state": ("up" if st.get("ok") else "failed") if st else "configured",
            "detail": st.get("detail") or fail.get("error") or "",
            "since": st.get("since") or fail.get("first"),
            "failed_starts": fail.get("count") or 0,
            "as_of": stored.get("updated"),
            "from_pid": stored.get("pid"),
            # NOT "current" when the writer is gone: a record whose process has died is
            # the LAST known state, not now (A-186). `stale` is the flag to read.
            "pid_alive": alive,
            "stale": not alive,
        }
    return out


def run_bot():
    global REPORTER
    import asyncio
    import warnings
    # Python 3.12+ no longer creates an implicit event loop, which the
    # (unmaintained) driver mmpy_bot depends on needs. Provide one.
    warnings.filterwarnings("ignore", "There is no current event loop",
                            DeprecationWarning)
    try:
        asyncio.get_event_loop()
    except RuntimeError:
        asyncio.set_event_loop(asyncio.new_event_loop())
    log.info("%s", capability_line("mattermost"))
    try:
        from mmpy_bot import Bot, Plugin, Settings, listen_to
    except ImportError as exc:
        # Without this, a host missing mmpy_bot started, wrote two warnings, then
        # died on a traceback that pythonw discards -- "running but never connects"
        # with nothing in the log (live 2026-09-10 on a fresh install).
        log.critical("the Mattermost layer needs mmpy_bot (%s). Install this "
                     "install's DECLARED dependencies - the file is the authority, "
                     "not a hand-picked module list:\n"
                     "  %s -m pip install -r %s", exc, sys.executable,
                     BASE_DIR / "requirements.txt")
        sys.exit(2)

    dispatcher = MattermostDispatcher()
    mm = CONFIG["mattermost"]
    if not mm.get("token") or mm["token"] == "PASTE_BOT_TOKEN_HERE":
        # .env holds TINYCMDR_MM_TOKEN now; a missing one used to fail silently
        # as "never connects"
        log.critical("no Mattermost token: put TINYCMDR_MM_TOKEN=<bot token> "
                     "in %s (or mattermost.token in config.json) and restart.",
                     BASE_DIR / ".env")
        sys.exit(2)
    # A value that is ALREADY on disk and cannot work is named as such. The tower taught
    # this one: one 0x16 byte in .env made the lane fail 723 times with a blank ERROR line
    # and `doctor` saying "no detail", because nothing looked at the value (2026-10-02).
    try:
        secret_check("TINYCMDR_MM_TOKEN", mm["token"])
    except ValueError as _problem:
        raise RuntimeError("the Mattermost token in %s is unusable: %s - replace it with "
                           "`tinycmdr token set TINYCMDR_MM_TOKEN`, then restart"
                           % (ENV_FILE.name, _problem))

    # mmpy_bot 2.2.x only registers listeners defined as Plugin methods.
    class TinycmdrPlugin(Plugin):
        @listen_to("(.*)", re.DOTALL, direct_only=True)   # DMs: respond to all
        def on_dm(self, message, query):
            dispatcher.enqueue(message, query if query else message.text)

        @listen_to("(.*)", re.DOTALL, needs_mention=True)  # channels: @mentions
        def on_mention(self, message, query):
            if message.is_direct_message:
                return  # DMs are handled by on_dm; avoid double handling
            dispatcher.enqueue(message, query if query else message.text)

    url = mm["url"]
    if "://" not in url:
        url = f"{mm.get('scheme', 'https')}://{url}"
    # Ask the server before the driver does. The driver reports a refused token with an
    # EMPTY message (see _mm_probe), so the lane used to fail with no reason at all; this
    # makes the failure say "HTTP 400 ... /api/v4/users/me", which _lane_error_permanent
    # parks instead of retrying for ever.
    _ok_mm, _why_mm = _mm_probe(_mm_base_url(mm), mm["token"])
    if _ok_mm is False:
        raise RuntimeError("Mattermost refused this bot's token: %s - replace it with "
                           "`tinycmdr token set TINYCMDR_MM_TOKEN`, then restart"
                           % _why_mm)
    bot = Bot(
        settings=Settings(
            MATTERMOST_URL=url,          # 2.2.x: scheme folded into the URL
            MATTERMOST_PORT=mm.get("port", 443),
            BOT_TOKEN=mm["token"],
            SSL_VERIFY=mm.get("ssl_verify", True),
        ),
        plugins=[TinycmdrPlugin()],
    )
    # Every Mattermost call goes through this driver's httpx client, and the
    # driver's default request_timeout is None, which in httpx turns OFF the
    # connect, read and write timeouts. That is an unbounded wait on a remote
    # server, and it is how a channel dies: on 2026-09-11 a POST sat 30+ minutes
    # inside the TLS handshake to a stalled edge, holding the session lock, so
    # the run never continued and /stop could not clear it (the blocked thread
    # never reaches a cancel check — only /restart helps). httpcore hands the
    # connect timeout to start_tls, so this bounds the handshake as well.
    # (mattermostautodriver keeps options on the driver as `.options`, and the
    # client holds the SAME dict, so this reaches the httpx calls.)
    bot.driver.options["request_timeout"] = 60
    # Heartbeat and receive timeout detect dead sockets within 30-60s
    # instead of blocking indefinitely.
    bot.driver.options["websocket_kw_args"] = {"heartbeat": 30.0, "receive_timeout": 60.0}
    dispatcher.attach(bot.driver, bot.driver.users.get_user("me")["username"])
    SCHEDULER.dispatcher = dispatcher    # so long jobs can report progress too
    REPORTER = lambda cid, text: dispatcher._post(cid, None, text)
    log.info("tinycmdr connected to Mattermost as @%s", dispatcher.bot_username)
    lane_up("mattermost", "connected as @%s" % dispatcher.bot_username)
    if CONFIG["agent"].get("announce_restart", True):
        # tell the channel that asked for the restart that we are back
        announce_startup(dispatcher)
    # If this logs 0 listeners, the bot will connect but stay silent.
    log.info("registered %d message listener(s): %s",
             sum(len(v) for v in bot.plugin_manager.message_listeners.values()),
             sorted(p.pattern for p in bot.plugin_manager.message_listeners))
    bot.run()


# CLI mode (test + terminal use, no Mattermost needed)
# ------------------------------------------------------------------ telegram lane

# The second messaging door beside Mattermost: the same agent, the same
# notes/tasks/atlas/skills and the same sessions corpus, reached from a Telegram DM.

# The transport is the Bot API over plain HTTPS long polling, so there is no webhook,

# no certificate, no inbound port and NO new dependency: it uses the requests the bot

# already ships. What it costs instead is presentation. Telegram has posts rather than

# attachments, an edit rate of about one per second per chat, and a hard 4096-character

# ceiling per message, so the lane keeps ONE growing message per run and posts the

# answer on its own.

TG_API = "https://api.telegram.org"

TG_MAX = 4096                 # per message, hard

TG_EDIT_AFTER = 1.0           # the API's own edit rate, per chat

TG_LIVE_LINES = 9             # tool lines kept in the growing message

TG_POLL_TIMEOUT = 50          # getUpdates long poll, seconds

# How long a chat's worker waits with nothing to do before it exits. A worker used to
# block on its queue for ever, so one thread lived per chat this process ever heard
# from; Mattermost's worker gives up after the same kind of idle wait, and the next
# message respawns it.

TG_IDLE_SECONDS = 10.0

TG_UPLOAD_TIMEOUT = 300.0     # a file upload is not a poll: leave room for a slow uplink
TG_HTTP_TIMEOUT = 45          # per Bot API call, overridable by telegram.http_timeout
TG_CAPTION_MAX = 1024         # the Bot API's caption ceiling; a longer note is cut, not refused
TG_PHOTO_SUFFIXES = (".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp")

TG_SEEN_PER_CHAT = 200        # message ids remembered per chat for redelivery dedupe
TG_NOTICE_MAX = 256           # chats remembered for the once-only "no text here" notice
TG_QUEUE_MAX = 5              # DMs allowed to queue behind a live run in one chat

# The verbs this lane answers. Kept in one place so the dedupe can tell an order
# (idempotent, must re-fire when redelivered) from a task (must not) - A-171.
_TG_VERBS = ("/start", "/help", "/stop", "/new", "/usage")

# Of those, ONLY /stop is re-run on a redelivered update: a task must never run twice
# and /help or /usage re-answering is just noise, but a /stop dropped as "already seen"
# leaves a run going while the operator believes it stopped (A-171).
_TG_REDELIVER = ("/stop",)

TG_HELP = ("<b>tinycmdr</b>\n"

           "Send a task in plain words and it runs on this box: shell, files, a URL "

           "you hand it, its notes and its own tools.\n\n"

           "<b>/new</b> start a fresh conversation\n"

           "<b>/usage</b> tokens and time for this chat's last run\n"

           "<b>/stop</b> cancel the run in flight\n"

           "<b>/help</b> this screen (also <b>/start</b>)\n\n"

           "Every verb also works with a <b>/tinycmdr</b> prefix — "

           "<b>/tinycmdr stop</b>, for instance — and a <b>@botname</b> suffix.\n\n"

           "Anything else is a request. While it works, the message above keeps "

           "itself current, and a plain line you type is sent in at the next step.")





def tg_escape(text):

    """HTML parse mode, which is the one that survives a model's own output.



    MarkdownV2 needs eighteen characters escaped and one of them is '-', so a

    sentence about a command line turns into noise. HTML needs three.

    """

    if text is None:
        return ""
    return (str(text).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))





def tg_html(text):
    """Escaped text, with the markdown a model writes rendered in Telegram's HTML.

    Backticks were the only thing this converted, so bold showed its asterisks, links
    were dead text and a table arrived as pipes - while Mattermost rendered the same
    answer (2026-10-04). Telegram's HTML subset has no table element,
    so a pipe table is wrapped in <pre>: columns keep their alignment and nothing is
    dropped. Fenced blocks are lifted out FIRST - before the inline-code rule - and
    their bodies never reach the emphasis, link or autolink rules, so a sample of
    `**bold**` or a URL written inside a fence stays the code it was written as
    (A-2026-10-05-187/190). Code spans and the text are escaped before any tag is
    added.

    Tags emitted: <b> <i> <code> <pre> <a> - nothing else, and no attribute is taken
    from the model's text except the sanitized href.
    """
    text = tg_escape(text).replace("\x00", "").replace("\x01", "")
    # ^ tg_escape(None) is "" (A-192), and a stray NUL/^A in model output (a tool's own
    #   bytes) would collide with the placeholder alphabet below - `\x00<digits>\x00` -
    #   so the restore read an index that was never minted and the answer died with
    #   IndexError (A-193). Telegram's HTML accepts neither byte, so they are dropped
    #   before any placeholder exists.
    code = []                       # inline code spans, restored as <code>
    pre = []                        # fenced blocks, restored as <pre>

    # 1. fenced blocks. ``` and ~~~ both open a block, the same marker closes it, and
    #    an unclosed fence runs to the end (the shape the renderer always had). Each
    #    block becomes one placeholder line, so the table pass below still sees whole
    #    lines. This has to happen BEFORE the inline-code rule: `[^`]+` used to pair
    #    the opening fence's third backtick with the closing fence's first and hand
    #    the whole block back as a broken <code> span.
    lines, kept, i = text.split("\n"), [], 0
    while i < len(lines):
        head = lines[i].lstrip()
        if head.startswith("```") or head.startswith("~~~"):
            marker = head[:3]
            i += 1
            body = []
            while i < len(lines) and not lines[i].lstrip().startswith(marker):
                body.append(lines[i])
                i += 1
            if i < len(lines):
                i += 1                              # consume the closing fence
            pre.append("\n".join(body))
            kept.append("\x01%d\x01" % (len(pre) - 1))
            continue
        kept.append(lines[i])
        i += 1
    text = "\n".join(kept)

    def _keep(m):
        code.append(m.group(1))
        return "\x00%d\x00" % (len(code) - 1)

    # 2. inline code, then the emphasis and link rules; the placeholders above are
    #    opaque to every one of them. A code span does not span a line, so the rule
    #    cannot pair two unrelated backticks across a newline.
    text = re.sub(r"`([^`\n]+)`", _keep, text)
    text = re.sub(r"\*\*([^*\n]+)\*\*", r"<b>\1</b>", text)
    text = re.sub(r"(?<![*\w])\*([^*\n]+)\*(?![*\w])", r"<i>\1</i>", text)
    text = re.sub(r"\[([^\]\n]+)\]\((https?://[^)\s\"<>]+)\)", r'<a href="\2">\1</a>', text)
    text = re.sub(r"(?<![\"'=])(https?://[^\s<>\")]+)",
                  lambda m: '<a href="%s">%s</a>' % (m.group(1), m.group(1)), text)

    # 3. a pipe table -> <pre> (Telegram's HTML has no table element)
    lines, out, i = text.split("\n"), [], 0
    while i < len(lines):
        # A table is a run of lines that start with a pipe. The `---|---` separator row a
        # model usually writes is KEPT in the body when present, but it is no longer the
        # thing that TRIGGERS the branch: a model that writes a header and data rows with
        # no separator line arrived as raw pipes (A-2026-10-05-196). Two adjacent pipe
        # lines are enough.
        if (i + 1 < len(lines) and lines[i].strip().startswith("|")
                and lines[i + 1].strip().startswith("|")):
            body = [lines[i]]
            i += 1
            while i < len(lines) and lines[i].strip().startswith("|"):
                body.append(lines[i])
                i += 1
            out.append("<pre>%s</pre>" % "\n".join(body))
            continue
        out.append(lines[i])
        i += 1
    text = "\n".join(out)

    # 4. put the protected spans back, whole.
    text = re.sub(r"\x00(\d+)\x00",
                  lambda m: "<code>%s</code>" % code[int(m.group(1))], text)
    return re.sub(r"\x01(\d+)\x01",
                  lambda m: "<pre>%s</pre>" % pre[int(m.group(1))], text)





# The tags tg_html itself emits (and only those): a split has to know which ones a
# cut left open so it can close them here and re-open them there.
_TG_TAG_RX = re.compile(r"</?([a-zA-Z][a-zA-Z0-9]*)[^>]*>")

# The markdown spans a raw cut must never divide: an inline code span, a link, a bold
# or italic run, a bare URL. Kept in step with tg_html's own rules, so a construct
# that renders as one tag is also an atom the splitter refuses to break.
_TG_SPAN_RX = re.compile(
    r"`[^`\n]+`"                          # inline code
    r"|\[[^\]\n]+\]\([^)\s\"<>]+\)"           # a markdown link
    r"|\*\*[^*\n]+\*\*"                   # bold
    r"|(?<![*\w])\*[^*\n]+\*(?![*\w])"    # italic
    r"|https?://[^\s<>\")]+")             # a bare URL


def _tg_open_tags(html):
    """The tags `html` leaves open, outermost first."""
    stack = []
    for m in _TG_TAG_RX.finditer(html):
        name = m.group(1).lower()
        if m.group(0).startswith("</"):
            if stack and stack[-1] == name:
                stack.pop()
        elif not m.group(0).endswith("/>"):
            stack.append(name)
    return stack


def _tg_safe_cut(s, limit):
    """The largest index <= limit whose position is outside any tag or entity.

    Index k is safe when `s[:k]` does not end in the middle of a <...> tag or an
    &...; entity: that is the payload Telegram answers with a 400 (A-150)."""
    window = s[:limit]
    safe = []
    i, n = 0, len(window)
    while i < n:
        c = window[i]
        if c == "<":
            j = window.find(">", i)
            if j == -1:
                break                      # an unclosed tag: nothing after it is safe
            i = j + 1
            continue
        if c == "&":
            j = window.find(";", i)
            if j == -1:
                # Rendered text carries no bare '&' (tg_escape makes '&amp;'), so a
                # '&' with entity characters and no ';' before the window ends is a
                # truncated entity: nothing after it is a safe cut.
                if re.match(r"[#0-9a-zA-Z]{0,10}$", window[i + 1:]):
                    break
                safe.append(i)
                i += 1
                continue
            if j - i > 12:                 # not an entity shape: ordinary text
                safe.append(i)
                i += 1
                continue
            i = j + 1
            continue
        safe.append(i)
        i += 1
    if not safe:
        return min(limit, len(s))
    safe_set = set(safe)
    cut = safe[-1] + 1
    for sep_len, sep in ((2, "\n\n"), (1, "\n"), (1, " ")):
        idx = window.rfind(sep)
        if idx < limit // 3:
            break
        end = idx + sep_len
        while end > limit // 3 and end not in safe_set:
            end -= 1
        if end > limit // 3:
            cut = end
            break
    return max(1, min(cut, limit))


def tg_html_split(text, limit=TG_MAX):
    """Split ALREADY-RENDERED HTML without cutting a tag or an entity.

    A cut inside <b> or &amp; is the 400 that loses the rest of the answer
    (A-2026-10-05-150). Every boundary sits outside every tag and entity, and when a
    cut lands between an opening and a closing tag the open tags are closed on this
    message and re-opened on the next, so each message is a balanced document.
    """
    text = str(text)
    if len(text) <= limit:
        return [text]
    out, rest = [], text
    while len(rest) > limit:
        cut = _tg_safe_cut(rest, limit)
        while True:
            chunk = rest[:cut]
            open_tags = _tg_open_tags(chunk)
            closers = "".join("</%s>" % t for t in reversed(open_tags))
            if len(chunk) + len(closers) <= limit or cut <= 1:
                break
            cut = _tg_safe_cut(rest, max(1, limit - len(closers)))
        carry = "".join("<%s>" % t for t in open_tags)
        piece = (chunk + closers).rstrip()
        if piece:                       # an all-whitespace chunk is not a message (A-194)
            out.append(piece)
        rest = (carry + rest[cut:]).lstrip("\n")
    if rest:
        out.append(rest)
    return out


def _tg_fits(text, limit):
    """How many raw chars of `text` render within `limit` rendered chars."""
    lo, hi = 0, len(text)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if len(tg_html(text[:mid])) <= limit:
            lo = mid
        else:
            hi = mid - 1
    return lo


def _tg_raw_cut(text, limit):
    """The raw cut for a rendered limit, on a boundary no construct straddles.

    Fences, code spans and links are atoms: a cut is pulled back to before any one of
    them it would otherwise divide, and a fence still open at the cut is left whole on
    the next message (A-2026-10-05-187/190)."""
    cut = _tg_fits(text, limit)
    if cut <= 0:
        return 1                            # one char already renders over: hard cut

    def _pull_back(c):
        """`c`, pulled to before any span it would divide.

        An atom that STARTS the remaining text cannot be kept whole - it is longer than a
        message on its own (a signed link, a data URI) - so the binary cut stands and the
        atom is hard-cut. Without that guard the pull-back returned 0, `max(1, cut)`
        emitted ONE character, and a long answer's URL came out as an empty message, then
        "h", then a broken "ttps://..." link (A-2026-10-05-194/195)."""
        for m in _TG_SPAN_RX.finditer(text[:c + 1]):
            if m.start() < c < m.end():
                return m.start() if m.start() > 0 else c
        return c

    cut = _pull_back(cut)
    open_at, pos = None, 0
    for line in text[:cut].split("\n"):
        s = line.lstrip()
        if s.startswith("```") or s.startswith("~~~"):
            open_at = None if open_at is not None else pos
        pos += len(line) + 1
    if open_at is not None and open_at > limit // 3:
        cut = open_at                        # do not cut inside a fence body
    for sep in ("\n\n", "\n", " "):
        c = text.rfind(sep, 0, cut)
        if c >= limit // 3 and len(tg_html(text[:c])) <= limit:
            cut = c
            break
    cut = _pull_back(cut)
    while cut > 1 and len(tg_html(text[:cut])) > limit:
        cut -= 1
    return max(1, cut)


def tg_render(text, limit=TG_MAX):
    """Raw markdown -> balanced HTML pieces, each within `limit`.

    Split FIRST, render each piece: the escaping and the tags land per message, so no
    message can carry half a tag (A-2026-10-05-150), and a cut never lands inside a
    fence, a code span or a link, so a construct whole in the answer stays whole in one
    message. This is the order the answer writer uses; text the renderer already
    produced goes through tg_html_split instead.
    """
    text = str(text)
    if not text:
        return [""]
    if len(tg_html(text)) <= limit:
        return [tg_html(text)]
    out, rest = [], text
    while rest:
        cut = _tg_raw_cut(rest, limit)
        piece = tg_html(rest[:cut]).rstrip()
        # A cut can land just after a run of whitespace, leaving a piece that renders as
        # nothing. Posting it meant an "(empty)" message in the chat (A-194); drop it and
        # carry on.
        if piece:
            out.append(piece)
        rest = rest[cut:].lstrip("\n")
    return out or [""]


def _tg_retry_after(data):
    """Seconds a Bot API 429 told us to wait, clamped to telegram.retry_after_max.

    0 means "do not wait": no `parameters.retry_after`, or a cap of 0. The same
    contract as llm.retry_after_max - the endpoint's hint, bounded by config."""
    if not isinstance(data, dict):
        return 0.0
    try:
        secs = float((data.get("parameters") or {}).get("retry_after") or 0)
    except (TypeError, ValueError):
        secs = 0.0
    if secs <= 0:
        return 0.0
    try:
        cap = float(CONFIG["telegram"].get("retry_after_max", 60) or 0)
    except (TypeError, ValueError):
        cap = 60.0
    return max(0.0, min(secs, cap))


class TelegramClient:

    """The Bot API, one method per thing this lane needs and nothing more.



    A token is a credential: it is never logged and never returned to a caller. The

    API wants it in the URL path, so the base URL is built once, here, and kept.

    """



    def __init__(self, token, http_timeout=None):

        self._base = "%s/bot%s/" % (TG_API, token)

        if http_timeout is None:

            # telegram.http_timeout bounds every non-poll call; the long poll has its own
            # (A-158). Read HERE, where the client is built, so the one-argument
            # constructor stays - every caller and every test stub keeps working.

            try:

                http_timeout = float((CONFIG.get("telegram") or {}).get(
                    "http_timeout", TG_HTTP_TIMEOUT) or TG_HTTP_TIMEOUT)

            except (TypeError, ValueError):

                http_timeout = TG_HTTP_TIMEOUT

        self.http_timeout = http_timeout



    def call(self, method, http_timeout=None, **payload):

        """One Bot API call, honouring a 429's own wait.

        Telegram flood control answers ok:false with `parameters.retry_after`;
        raising on the first 429 lost the answer instead of waiting out a rate
        limit that clears by itself (A-2026-10-05-149). ONE retry, bounded by
        telegram.retry_after_max, is the whole fix: a second 429 is the lane's
        to report, not to spin on.
        """

        attempts = 0

        while True:

            r = requests.post(self._base + method, json=payload,

                              timeout=http_timeout or self.http_timeout)

            try:

                data = r.json()

            except Exception:

                raise RuntimeError("%s: HTTP %s and no JSON" % (method, r.status_code))

            if data.get("ok"):

                return data.get("result")

            wait = _tg_retry_after(data)

            if wait and attempts < 1:

                attempts += 1

                log.warning("telegram: %s rate-limited; waiting %ss then retrying once",

                            method, int(wait))

                time.sleep(wait)

                continue

            # The API's own error_code (falling back to the HTTP status) rides in the
            # message: a `{"ok":false,"description":"Unauthorized"}` used to come out as
            # "getUpdates: Unauthorized", which _lane_error_permanent cannot read as a
            # refusal and which the poll loop then retried for ever (A-157/A-176/A-177).
            raise RuntimeError("%s: %s (HTTP %s)" % (method,
                                                     data.get("description") or "no description",
                                                     data.get("error_code") or r.status_code))



    def me(self):

        """getMe as a dict. A 200 with a null result (a misbehaving proxy) is not a
        crash and not a username: {} lets the caller name the lane "@unknown" instead of
        printing "connected as @None" (A-2026-10-05-154)."""

        me = self.call("getMe")

        return me if isinstance(me, dict) else {}



    def send(self, chat_id, text, buttons=None, reply_to=None):

        """Send, splitting a long body without breaking a tag; buttons ride the last piece."""

        pieces = tg_html_split(text)

        sent = []

        for i, piece in enumerate(pieces):

            payload = {"chat_id": chat_id, "text": piece or "(empty)",

                       "parse_mode": "HTML", "disable_web_page_preview": True}

            if i == 0 and reply_to:

                payload["reply_to_message_id"] = reply_to

            if buttons and i == len(pieces) - 1:

                payload["reply_markup"] = {"inline_keyboard": buttons}

            sent.append(self.call("sendMessage", **payload))

        return sent



    def edit(self, chat_id, message_id, text, buttons=None):

        if len(text) > TG_MAX:

            # A raw character cut left a tag open and Telegram 400'd the edit, so the
            # live message froze for the rest of the run (A-2026-10-05-151). Cut
            # outside every tag/entity, close what is still open, then mark it short.
            text = tg_html_split(text, TG_MAX - 3)[0] + "..."

        payload = {"chat_id": chat_id, "message_id": message_id, "text": text,

                   "parse_mode": "HTML", "disable_web_page_preview": True}

        if buttons:

            payload["reply_markup"] = {"inline_keyboard": buttons}

        try:

            return self.call("editMessageText", **payload)

        except RuntimeError as exc:

            if "not modified" in str(exc).lower():

                return None                    # the same text twice is not an error

            raise



    def typing(self, chat_id):

        return self.call("sendChatAction", chat_id=chat_id, action="typing")



    def send_file(self, chat_id, path, note="", reply_to=None):

        """Upload a local file into the chat: ONE multipart POST, like every other call.

        `sendDocument` is the upload this lane needs - it carries any type and keeps the
        file's own name - except for an image, which Telegram renders inline as a photo.
        The file-size cap is the DOOR's (`agent.send_file_max_bytes`, the same shape the
        Mattermost lane uses); this is only the transport, and it refuses a path that is
        not there rather than posting nothing. Raises RuntimeError on the API's refusal,
        which `TelegramDestination.attach` turns into the honest line the model reads.
        """
        import mimetypes
        p = Path(str(path)).expanduser()
        if not p.is_file():
            raise RuntimeError("no such file: %s" % p)
        method, field = ("sendPhoto", "photo") if p.suffix.lower() in TG_PHOTO_SUFFIXES \
            else ("sendDocument", "document")
        data = {"chat_id": chat_id}
        if note:
            data["caption"] = str(note)[:TG_CAPTION_MAX]
        if reply_to:
            data["reply_to_message_id"] = reply_to
        ctype = mimetypes.guess_type(p.name)[0] or "application/octet-stream"
        with p.open("rb") as fh:
            r = requests.post(self._base + method, data=data,
                              files={field: (p.name, fh, ctype)},
                              timeout=TG_UPLOAD_TIMEOUT)
        try:
            body = r.json()
        except Exception:                                        # noqa: BLE001 - reported
            raise RuntimeError("%s: HTTP %s and no JSON" % (method, r.status_code))
        if not body.get("ok"):
            raise RuntimeError("%s: %s" % (method,
                                           body.get("description") or r.status_code))
        return body.get("result")



    def answer_callback(self, callback_id, text=""):

        return self.call("answerCallbackQuery", callback_query_id=callback_id,

                         text=text or None)



    def updates(self, offset):

        return self.call("getUpdates", http_timeout=TG_POLL_TIMEOUT + 20,

                         offset=offset, timeout=TG_POLL_TIMEOUT,

                         allowed_updates=["message", "callback_query"]) or []





class TelegramDestination(Destination):

    """The Telegram lane's reporter: one growing message per run, then the answer.



    An edit is a whole message write and the API allows about one per second per

    chat, so a line per tool call would be both a wall of notifications and a rate

    limit problem. The run's own line and the last few tool lines share a single

    message, and the answer is posted as its own so it can be read without the

    chatter above it.

    """



    merge_tools = True

    shows_calls = True

    # This lane CAN ask: ask() posts the question with one button per option, turns the
    # typing lamp on, and waits. The base's False meant RunReporter.ask returned None
    # before ever reaching it, so a human could never be asked here and every
    # confirm-tier command was declined in silence (A-2026-10-05-139/140).
    has_human = True



    def __init__(self, client, chat_id, session_key="", reply_to=None):

        self.c = client

        self.chat_id = chat_id

        self.session_key = session_key

        self.reply_to = reply_to

        self.live_id = None

        self.lines = []                 # (kind, text) in the growing message

        self.status = ""

        self._edited = 0.0

        self._asking = {}               # question id -> wait state



    # -- the growing message ---------------------------------------------

    def _live_text(self):

        body = [self._mark(kind, text) for kind, text in self.lines[-TG_LIVE_LINES:]]

        if len(self.lines) > TG_LIVE_LINES:

            body.insert(0, "... %d earlier step(s)" % (len(self.lines) - TG_LIVE_LINES))

        if self.status:

            body.append(tg_escape(self.status))

        return "\n".join(body) or tg_escape("working...")



    @staticmethod

    def _mark(kind, text):

        mark = {"tool": "\U0001F527 ", "tool_done": "\u2714 ", "tool_fail": "\u26a0\ufe0f ",

                "ask": "\u2753 ", "checkin": "", "note": "", "narration": "",

                "error": "\u26d4 ", "say": ""}.get(kind, "")

        return mark + tg_html(text)



    def _flush(self, force=False):

        """Write the growing message, at most once a second unless it must land."""

        now = time.time()

        if not force and (now - self._edited) < TG_EDIT_AFTER:

            return

        self._edited = now

        text = self._live_text()

        try:

            if self.live_id is None:

                sent = self.c.send(self.chat_id, text)

                if sent:

                    self.live_id = sent[0].get("message_id")

            else:

                self.c.edit(self.chat_id, self.live_id, text)

        except Exception as exc:            # a failed edit must never kill the run

            # A failed EDIT (the message was deleted, a 400, a flood control) must not
            # leave the run redrawing a dead id for ever: the next flush opens a fresh
            # message instead, so the live view keeps moving (A-2026-10-05-152). Only the
            # edit branch is dropped - "no message yet" is already the send branch's state.
            if self.live_id is not None:
                self.live_id = None
            log.warning("telegram: the live message failed (%s)", exc)



    # -- the Destination contract ----------------------------------------

    def line(self, kind, text, src="main"):

        if kind == "final":

            self.answer(text)

            return ("tg-final", len(self.lines))

        self.lines.append((kind, str(text)))

        self._flush(force=kind in ("ask", "error"))

        return ("tg", len(self.lines) - 1)



    def update(self, ref, kind, text, src="main"):

        if kind == "status":

            self.status = str(text)

            self._flush()

            return ref

        if kind == "narration":

            self.lines.append(("narration", str(text)))

            self._flush()

            return ref

        if kind == "final":

            # The run is over. Clear the pinned status line, or the closing flush would
            # leave the last status dangling under the final steps (A-2026-10-05-198), and
            # FORCE the last live write - the one-edit-a-second throttle would otherwise
            # drop it and the growing message would end on a step that is not the last
            # (A-2026-10-05-153).
            self.status = ""

            self._flush(force=True)

            self.answer(text)

            return ref

        if kind == "error":

            # A failed run closes the same way: no pinned status, a forced last write.
            self.status = ""

            return self.line(kind, text, src)

        return self.line(kind, text, src)



    def drop(self, ref):

        """A draft that turned out to be the answer: drop the line, keep the text."""

        try:

            _, idx = ref

            self.lines.pop(idx)

        except Exception:

            pass



    def answer(self, text):

        """The answer as its own message, so the chatter never buries it.

        Split as RAW markdown, then rendered: the cut never lands inside a fence, a

        code span or a link, and the escaping is applied per message, so no message

        carries a tag the split left open (A-2026-10-05-150)."""

        pieces = tg_render("\u2705 " + str(text))

        try:

            for i, piece in enumerate(pieces):

                self.c.send(self.chat_id, piece,

                            reply_to=self.reply_to if i == 0 else None)

        except Exception as exc:

            log.error("telegram: the answer could not be posted (%s)", exc)



    # -- the file door ---------------------------------------------------
    def attach(self, path, note=""):
        """Put a local file in this chat. The send_file tool's door.

        The base class answered "this lane cannot carry a file", so an order to send
        something here failed while the chat, console and page lanes could all attach
        (A-199). The size cap is the SAME `agent.send_file_max_bytes` the Mattermost lane
        uses, and a send is a send: nothing is written to disk and no backup is taken,
        so the only two answers are "sent" and an honest error naming the file.
        """
        p = Path(str(path)).expanduser()
        if not p.is_file():
            return "ERROR: no such file: %s" % p
        size = p.stat().st_size
        cap = int(CONFIG["agent"].get("send_file_max_bytes") or SEND_FILE_MAX)
        if size > cap:
            return (f"ERROR: {p.name} is {size:,} bytes, over this box's {cap:,}-byte "
                    f"send limit (agent.send_file_max_bytes). It is at {p}.")
        try:
            self.c.send_file(self.chat_id, p, note=note, reply_to=self.reply_to)
        except Exception as e:                                   # noqa: BLE001
            return "ERROR: upload failed: %s" % e
        return f"sent: {p.name} ({size:,} bytes) is now in this chat"

    def _open_question(self, question, options):

        """The row a question parks on. The ask() path and the ask_user door share

        this shape; `ev` is the name ask_operator waits on, so one Event serves both.

        None when a question is already open: a second question used to overwrite the

        first waiter's slot and leave it parked for its whole window (A-144)."""

        if self._asking:

            return None

        ev = threading.Event()

        row = {"ev": ev, "event": ev, "answer": None, "question": question,

               "options": [str(o) for o in (options or [])]}

        self._asking["q"] = row

        return row



    def _post_question(self, question, options, wait, label=None):

        """Post the question with one button per option, and turn the typing lamp on."""

        del wait, label

        body = "\u2753 " + tg_html(question)

        if options:

            body += "\n" + "\n".join(tg_escape("%d) %s" % (i + 1, o))

                                   for i, o in enumerate(options))

        buttons = [[{"text": str(o)[:60], "callback_data": "opt:%d" % (i + 1)}]

                   for i, o in enumerate(options or [])]

        row = self._asking.get("q")

        if row is not None:

            # Appended, not flushed: the question message must be the newest one in the
            # chat, so the live redraw waits for the next flush (or the resolution).
            self.lines.append(("ask", str(question)))

            row["ref"] = ("tg", len(self.lines) - 1)

        self.c.send(self.chat_id, body, buttons=buttons or None,

                    reply_to=self.reply_to)

        self.c.typing(self.chat_id)



    def _resolve_ask(self, row, outcome):

        """Rewrite the question's live line with what happened to it (A-148)."""

        ref = (row or {}).get("ref")

        if not ref:

            return

        try:

            idx = ref[1]

            kind, question = self.lines[idx]

            self.lines[idx] = (kind, "%s — %s" % (question.split(" — ")[0], outcome))

            self._flush(force=True)

        except Exception:                   # a missing line must never break an answer

            pass



    # --- ask_user's door: the lane has a human at the other end ---------------

    # Without these the tool answered "nothing in this run can reach a human" on

    # Telegram while the chat, web and console lanes could all ask (A-141).

    def opener(self, question, options, wait, label=None):

        """The row the run parks on. ask_operator owns the waiting; this lane only

        has to release the event when the operator answers."""

        return self._open_question(question, options)



    def post(self, question, options, wait, label=None):

        """Draw the question; the wait belongs to ask_operator, so a /stop is seen."""

        self._post_question(question, options, wait, label)



    def post_done(self, text):

        """What happened to the question: answered, stopped or timed out."""

        self._resolve_ask(self._asking.get("q"), str(text))

        self.line("checkin", text)



    def close_question(self, answered=False):

        """The question is over: nothing else typed at this chat is its answer."""

        del answered

        self._asking.pop("q", None)



    def ask(self, question, options=None, wait=300.0, label=None):

        """Post the question with the options as buttons, and wait for either a press

        or a typed line. Both land in the same slot: the reporter decides what counts

        as a yes, exactly as it does in every other lane.

        The wait is bounded by _ask_wait_cap() (A-146), a question that never reached

        the screen returns at once instead of burning the window (A-145), and a second

        question while one is open is refused rather than allowed to steal the answer

        (A-144)."""

        row = self._open_question(question, options)

        if row is None:

            return None

        wait = min(float(wait), _ask_wait_cap())

        try:

            self._post_question(question, options, wait, label)

        except Exception as exc:

            log.warning("telegram: the question could not be posted (%s)", exc)

            self._asking.pop("q", None)

            return None

        answered = row["ev"].wait(wait)

        self._resolve_ask(row, row["answer"] if answered else "no answer")

        self._asking.pop("q", None)

        if not answered:

            self.line("checkin", "no answer in %ds, carrying on without one"

                      % int(wait))

            return None

        return row["answer"]



    def reply_ask(self, text):

        """A typed answer to the open question."""

        row = self._asking.get("q")

        if row is None:

            return False

        row["answer"] = text

        row["ev"].set()

        return True



    def button_ask(self, data):

        """A button press: 'opt:<n>'. Answers with the option's own WORDS, the way

        every other lane's ask does; the confirm gate reads words, not a number, and

        an out-of-range press (a stale keyboard) is refused rather than inventing an

        answer (A-142/147)."""

        row = self._asking.get("q")

        if row is None:

            return False

        try:

            idx = int(str(data).split(":", 1)[1])

        except (IndexError, ValueError):

            return False

        opts = row.get("options") or []

        if not 1 <= idx <= len(opts):

            return False

        row["answer"] = opts[idx - 1]

        row["ev"].set()

        return True





class TelegramPoller:

    """Long-poll the Bot API and hand each update to the right chat's worker.



    One worker per chat, like the Mattermost dispatcher: a chat's second request

    queues behind its first, and two chats never wait on each other. The allowed list

    is a gate, not a warning: anyone else is logged and ignored, and group chats are

    ignored by design (DM only, the same discipline as the chat lane).

    """



    def __init__(self, client, allowed):

        self.c = client

        self.allowed = allowed

        self.submit = None              # set by run_telegram

        self.live = {}                  # chat_id -> TelegramDestination

        self.cancel = {}                # chat_id -> the run's cancel event

        # Dedupe is PER CHAT: message ids are per chat, so one shared window let a busy
        # second user evict the first user's history and a redelivery became a second run
        # (A-166). Each chat keeps the last TG_SEEN_PER_CHAT ids it handled.
        self.seen = {}                  # chat_id -> deque of message ids

        # Chats already told "I can only read text here", so a photo album draws ONE
        # notice, not one per photo (A-161). Bounded so it cannot grow for ever.
        self._no_text_told = {}         # chat_id -> True, insertion-ordered (bounded)



    def allowed_user(self, user):

        uid = str((user or {}).get("id") or "")

        return bool(uid) and uid in self.allowed



    def _verb(self, chat_id, text):

        words = text.split()

        if not words:                   # `/stop` on an empty line must not IndexError

            return False                # (A-159: the guard and the split were 20 lines apart)

        # `/help@MyBot` is the form Telegram itself writes into a group and a /cmd link;
        # the lane is DM-only, but a user who types it still wants help, not a task sent
        # to the model (A-160).
        verb = words[0].lower().split("@", 1)[0]

        if verb in ("/start", "/help"):

            self.c.send(chat_id, TG_HELP)

            return True

        if verb == "/stop":

            ev = self.cancel.get(chat_id)

            if ev is not None:

                ev.set()

                self.c.send(chat_id, "\u23f9 stopping - the call in flight is being closed")

            else:

                self.c.send(chat_id, "nothing is running")

            return True

        if verb == "/new":

            AGENT.reset(tg_session_key(chat_id))

            # A FRESH conversation needs a fresh progress message: the live destination
            # kept the old run's steps on screen (A-172).
            live = self.live.get(chat_id)

            if live is not None:

                live.lines = []

                live.status = ""

                live._flush(force=True)

            self.c.send(chat_id, "\U0001F195 fresh conversation")

            return True

        if verb == "/usage":

            u = AGENT.last_usage.get(tg_session_key(chat_id))

            self.c.send(chat_id, tg_escape(fmt_usage(u) if u and u.get("calls")

                                           else "nothing yet in this chat"))

            return True

        return False



    def steer(self, chat_id, text, sender=""):

        """Hand a mid-run message to the live run instead of queueing it behind.

        A chat's worker holds the chat for the whole run, so a message that only
        queued was read AFTER the run it was meant to redirect - the README's
        "a message sent mid-run steers the run instead of queueing behind it" was
        true of Mattermost and the CLI, not here. The run's control (drive_run opens
        it by construction) is what the message goes into.

        """

        ctrl = RUNS.control(tg_session_key(chat_id))

        if ctrl is None:

            return False

        ctrl.steer(sender, text)

        log.info("telegram: steering from %s handed to the live run in %s",

                 sender or "?", chat_id)

        try:

            self.c.send(chat_id, "\U0001f4e8 Passing that into the run now \u2014 it picks "

                                 "it up on its next step.")

        except Exception as exc:            # noqa: BLE001 - the steer already landed

            # The message is already in the run: a failed RECEIPT (a 429 on this one
            # send) must not raise into handle(), where "one update failed" would blame
            # the update that actually worked (A-170).

            log.warning("telegram: the steer receipt could not be sent (%s)", exc)

        return True



    def handle(self, update):

        """One update. True when it was ours to handle."""

        cb = update.get("callback_query")

        if cb:

            user = cb.get("from") or {}

            chat_id = ((cb.get("message") or {}).get("chat") or {}).get("id")

            if not chat_id:

                # A press can lose its message (deleted, or a truncated update). That is
                # not the user being disallowed, and it is not a reason a /stop in the
                # chat should depend on (A-164).

                log.warning("telegram: ignored a button press with no chat (from %s)",

                            user.get("id"))

                return False

            if not self.allowed_user(user):

                log.warning("telegram: ignored a button press from %s", user.get("id"))

                return False

            try:

                self.c.answer_callback(cb.get("id"))

            except Exception:

                pass

            dest = self.live.get(chat_id)

            return bool(dest is not None and dest.button_ask(cb.get("data")))

        msg = update.get("message") or update.get("edited_message")

        if not msg:

            return False

        chat = msg.get("chat") or {}

        chat_id = chat.get("id")

        user = msg.get("from") or {}

        # Telegram always sends a string, but a malformed update with a number used to
        # die in `.strip()` and the sender got nothing at all (A-162).
        raw = msg.get("text")

        if raw is None:

            raw = msg.get("caption")

        text = str(raw).strip() if raw is not None else ""

        if not chat_id:

            return False

        if chat.get("type") != "private":

            log.info("telegram: ignored a message with chat.type=%r (DM only); it needs "

                     "a private chat", chat.get("type"))

            return False

        if not self.allowed_user(user):

            log.warning("telegram: ignored a message from %s (@%s) - not in "

                        "telegram.allowed_users", user.get("id"), user.get("username"))

            return False

        if not text:

            # A photo, voice note or sticker carries no text (a caption does, and is
            # read now); it used to vanish with no reply and no log line, which reads
            # as the bot being broken. Say so ONCE per chat - three photos used to draw
            # three identical replies (A-161).

            log.info("telegram: a message with no text from chat %s", chat_id)

            if chat_id not in self._no_text_told:

                self._no_text_told[chat_id] = True

                while len(self._no_text_told) > TG_NOTICE_MAX:      # bounded

                    self._no_text_told.pop(next(iter(self._no_text_told)), None)

                try:

                    self.c.send(chat_id, "I can only read text here - describe it in words.")

                except Exception:               # noqa: BLE001 - a reply must not kill the lane

                    pass

            return False

        mid = msg.get("message_id")

        # Telegram numbers message ids per chat, so the window is per chat and holds the
        # last TG_SEEN_PER_CHAT ids: one busy user can no longer evict another's history
        # and turn a redelivery into a second run (A-166).
        seen = self.seen.setdefault(chat_id, deque(maxlen=TG_SEEN_PER_CHAT))

        # A verb is an ORDER, not a task, and it is idempotent: a redelivered `/stop`
        # (the offset replays after a restart) must bite again, while a redelivered task
        # must not run twice. The dedupe below therefore lets the verbs through (A-171).

        _cmdr = cmdr_strip(text)

        if _cmdr != text:

            text = _cmdr

        verb = text.split()[0].lower().split("@", 1)[0] if text.split() else ""

        if mid in seen and verb not in _TG_REDELIVER:

            return True

        seen.append(mid)

        # A verb is an order, not an answer. This used to try reply_ask FIRST, so a

        # `/stop` (or `/new`) typed while a question was open was swallowed as the

        # answer, the run kept going, and the operator believed it had stopped

        # (A-2026-10-05-143). Verbs are checked before the open question now; anything

        # that is not a verb still falls through to the question.

        # `/tinycmdr <cmd>` works here too: a Telegram client hands an unknown command
        # over as ordinary text, so the prefix only has to be understood (done above).
        if verb in _TG_VERBS and self._verb(chat_id, text):

            return True

        dest = self.live.get(chat_id)

        if dest is not None and dest.reply_ask(text):

            return True

        # A run is live for this chat: a plain message is a correction to it, not a
        # second task to queue behind it (a command above is still out-of-band).

        if self.steer(chat_id, text, str(user.get("id") or "")):

            return True

        if self.submit is not None:

            self.submit(chat_id, text, mid)

        return True





def tg_session_key(chat_id):

    """One conversation per Telegram chat, named so the corpus stays readable."""

    return "telegram-%s" % chat_id


class TelegramDispatcher:
    """What a SCHEDULED job needs to report into a Telegram chat.

    `run_bot` hands the Scheduler its Mattermost dispatcher and sets `REPORTER`; the
    Telegram lane set neither, so on a Telegram-only box a scheduled job's progress lines
    went to the log, its answer to stdout, and the operator never saw either (A-200).
    `Scheduler._fire` builds `MattermostDestination(self.dispatcher, token, ...)`, which
    speaks `_post`/`_edit`/`_delete`/`send_file`/`pending`; this is exactly that surface
    over a TelegramClient, so ONE job path carries the report in every lane. Text is
    converted with `tg_html` here because the Bot API is called with parse_mode=HTML.
    """

    name = "telegram"

    def __init__(self, client):
        self.c = client
        self.pending = {}          # chat_id -> ask wait state (MattermostDestination.ask)

    def _post(self, channel_id, root_id=None, text="", color=None, touch=True):
        """Post a new message; returns its id (the ref the reporter redraws)."""
        del root_id, color, touch
        try:
            sent = self.c.send(channel_id, tg_html(str(text)))
        except Exception as e:                                   # noqa: BLE001 - reported
            log.error("telegram: a scheduled post failed: %s", e)
            return None
        return (sent[0] or {}).get("message_id") if sent else None

    def _edit(self, post_id, channel_id, text, color=None):
        del color
        try:
            self.c.edit(channel_id, post_id, tg_html(str(text)))
        except Exception as e:                                   # noqa: BLE001
            log.debug("telegram: a scheduled edit failed: %s", e)

    def _delete(self, post_id, channel_id):
        try:
            self.c.call("deleteMessage", chat_id=channel_id, message_id=post_id)
        except Exception as e:                                   # noqa: BLE001
            log.debug("telegram: could not delete message %s: %s", post_id, e)

    def send_file(self, channel_id, root_id, path, note=""):
        return TelegramDestination(self.c, channel_id,
                                   reply_to=root_id).attach(path, note)





def run_telegram():

    """The Telegram lane: long poll, gate on allowed ids, one run per chat.



    The unified backend is the point: same Agent, same notes/tasks/atlas/skills, same

    sessions corpus as the chat lanes, so the fleet keeps one memory whichever
    door is used.

    """

    global REPORTER
    tg = CONFIG.get("telegram") or {}

    def _refuse(reason):
        """Record WHY this lane cannot start, then exit 2.

        A lane that dies must not leave the last record standing: on a two-lane box the
        Mattermost lane keeps the process alive, nothing else rewrites `telegram`, and
        `health` went on reporting the dead lane's last "up" (A-185). The exit IS the
        lane's true state, so it is written before the exit.
        """
        lane_down("telegram", reason)
        sys.exit(2)

    token = (tg.get("token") or "").strip()

    if not token:

        log.critical("no Telegram token: put TINYCMDR_TG_TOKEN=<bot token> in %s "

                     "(or telegram.token in config.json) and restart.", BASE_DIR / ".env")

        _refuse("no Telegram token configured")

    try:

        secret_check("TINYCMDR_TG_TOKEN", token)

    except ValueError as _problem:

        log.critical("the Telegram token in %s is unusable: %s - replace it with "

                     "`tinycmdr token set TINYCMDR_TG_TOKEN`, then restart.",

                     ENV_FILE.name, _problem)

        _refuse("the Telegram token in %s is unusable: %s" % (ENV_FILE.name, _problem))

    allowed = {str(u).strip() for u in (tg.get("allowed_users") or []) if str(u).strip()}

    if not allowed:

        log.critical("telegram.allowed_users is empty, and this bot is deny-by-default: "

                     "it would ignore every DM. Put your numeric Telegram id there.")

        _refuse("telegram.allowed_users is empty (deny-by-default)")

    bad = sorted(a for a in allowed if not re.fullmatch(r"\d+", a))

    if bad:

        # The field takes NUMERIC ids and the check compares them as strings, so a
        # "@david" or a username can never match: the lane starts, looks alive, and
        # silently refuses every DM with only a per-message warning (A-174). A startup
        # error is the honest shape.

        log.critical("telegram.allowed_users has %s - Telegram ids are NUMERIC (message "

                     "@userinfobot for yours), and a username can never match. Fix it and "

                     "restart.", ", ".join(repr(b) for b in bad[:5]))

        _refuse("telegram.allowed_users has non-numeric id(s): %s"

                % ", ".join(repr(b) for b in bad[:5]))

    client = TelegramClient(token)

    try:

        me = client.me()

    except requests.RequestException:

        # The HOST, not the token: api.telegram.org could not be reached at all (no wifi,
        # an ISP outage), which is exactly what main()'s lane retry backs off on. A token
        # the API REFUSED answered, so it is permanent and takes the exit-2 path below.

        raise

    except Exception as exc:

        if not _lane_error_permanent(exc):

            # A transport failure wearing a credential costume: a captive portal's HTML
            # or a 204 with no JSON raises RuntimeError, not RequestException, and it used
            # to be reported as "the token was refused" + exit 2 - so the supervisor
            # restarted the box into the same portal for ever (A-176). Raising hands it to
            # the in-process retry, exactly like the unreachable case above.

            raise

        log.critical("telegram: the token was refused (%s)", exc)

        _refuse("the Telegram token was refused: %s" % exc)

    # The name the lane reports itself under. getMe can answer `result: null` (a proxy
    # between us and the API), which used to read "connected as @None" (A-154).
    who = me.get("username") or "unknown"

    # The Scheduler and the scheduled-report door, exactly as run_bot wires them: on a
    # Telegram-only box a scheduled job's progress went to the log and its answer to
    # stdout, with nobody at the other end (A-200). announce_startup is honoured here
    # too, so a restart asked for from this chat is answered in it (A-201).
    _tg_disp = TelegramDispatcher(client)
    SCHEDULER.dispatcher = _tg_disp
    REPORTER = lambda cid, text: _tg_disp._post(cid, None, text)
    if CONFIG["agent"].get("announce_restart", True):
        announce_startup(_tg_disp)
    log.info("telegram: connected as @%s, %d allowed id(s), DM only",

             who, len(allowed))



    poller = TelegramPoller(client, allowed)

    queues, workers, locks = {}, {}, threading.Lock()



    def worker(chat_id):

        while True:

            try:

                task = queues[chat_id].get(timeout=TG_IDLE_SECONDS)

            except queue.Empty:

                # Nothing to do: this thread has outlived its run. Exit and let the
                # next message spawn a fresh worker - one thread per chat this process
                # ever heard from used to live for ever (Mattermost's worker gives up
                # after the same kind of idle wait).

                with locks:

                    if queues.get(chat_id) is not None and queues[chat_id].empty():

                        queues.pop(chat_id, None)

                        workers.pop(chat_id, None)

                        return

                continue

            if task is None:

                return

            # Adopt the event submit() already registered for this chat: /stop sets

            # that one, so minting a fresh event here silently dropped a stop that

            # landed between the message arriving and this run starting.

            text, msg_id, cancel = task

            key = tg_session_key(chat_id)

            dest = TelegramDestination(client, chat_id, key, reply_to=msg_id)

            with locks:

                poller.live[chat_id] = dest

                poller.cancel[chat_id] = cancel

            reporter = RunReporter(dest, key)

            try:

                client.typing(chat_id)

                answer = drive_run(key, text, reporter, cancel_event=cancel,

                                   # The chat id is this run's channel: it is what a
                                   # `schedule` job made here reports back to, and what
                                   # the watchdog names when it has to speak (A-200).

                                   channel_id=chat_id,

                                   # The lane's own destination is the ask_user door:

                                   # it has opener/post/post_done/close_question, so

                                   # ask_user reaches this chat instead of answering

                                   # "nothing in this run can reach a human" (A-141).

                                   ask_door=dest)

                if answer:

                    dest.answer(answer)

            except OperatorStop as exc:

                dest.line("checkin", "stopped: %s" % exc)

            except Exception as exc:                        # noqa: BLE001 - reported

                log.exception("telegram: the run failed")

                dest.line("error", "run failed: %s: %s" % (type(exc).__name__, exc))

            finally:

                reporter.finish(ok=True)

                with locks:

                    poller.live.pop(chat_id, None)

                    # The mailbox slot belongs to the run that is live. Clearing it
                    # unconditionally wiped the slot for a run still QUEUED behind this
                    # one, so a /stop during that next run found nothing and answered
                    # "nothing is running" while the run kept going (A-167/168). The next
                    # run claims the slot for itself when it starts; only an empty queue
                    # lets it go.

                    if queues.get(chat_id) is None or queues[chat_id].empty():

                        poller.cancel.pop(chat_id, None)



    def submit(chat_id, text, msg_id):

        over = False

        with locks:

            q = queues.get(chat_id)

            if q is not None and q.qsize() >= TG_QUEUE_MAX:

                # Six DMs typed in annoyance used to become six sequential full runs,
                # each with its own growing message (A-169). The cap is per chat; the
                # refusal is said in the chat, not swallowed.
                over = True

            else:

                if q is None:

                    q = queues[chat_id] = queue.Queue()

                    t = threading.Thread(target=worker, args=(chat_id,), daemon=True,

                                         name="tg-%s" % chat_id)

                    workers[chat_id] = t

                    t.start()

                # A FRESH event per message, so a run that queues behind a stopped one
                # does not inherit its stop; but the slot keeps the event of the run that
                # is live (setdefault), so a /stop typed before the first run starts still
                # bites (A-167/168).

                cancel = threading.Event()

                poller.cancel.setdefault(chat_id, cancel)

                q.put((text, msg_id, cancel))

        if over:

            try:

                client.send(chat_id, "I'm already working through %d message(s) here - "

                                     "send this one when they are done." % TG_QUEUE_MAX)

            except Exception as e:                          # noqa: BLE001 - the cap holds

                log.warning("telegram: could not say the queue is full: %s", e)



    poller.submit = submit



    # The offset is the lane's ACK, and it survives a restart (A-165). Telegram keeps
    # unacknowledged updates 24 h, so after a crash or any downtime the whole backlog
    # used to be delivered again and each DM launched a full run - the same order,
    # answered twice or three times. It is read here and written after every batch.
    try:

        offset = int((_state().get("telegram_offset") or 0))

    except (TypeError, ValueError):

        offset = 0

    _persisted_offset = offset

    def _remember_offset(nxt):

        """Record the next update_id to ask for, so a restart does not replay."""

        nonlocal _persisted_offset

        try:

            _state(lambda st: st.__setitem__("telegram_offset", int(nxt)))

            _persisted_offset = int(nxt)

        except Exception as e:                              # noqa: BLE001 - not fatal

            log.debug("telegram: could not persist the update offset: %s", e)

    _failing_since = None
    # The lane is not "up" until the API has ANSWERED a poll: lane_up before the loop
    # reported a lane that died on its first poll as up for the whole grace window
    # (A-178). `_heard` is that first-answer flag; a recovery re-uses the same call.
    _heard = False
    while True:

        try:

            updates = client.updates(offset)

        except Exception as exc:                            # noqa: BLE001 - retried

            if _lane_error_permanent(exc):

                # A token revoked MID-RUN answered and said no; retrying it every 5s
                # just hammers the API twelve times a minute for ever (A-177). Same
                # exit as a refused start: record why, then stop.
                log.critical("telegram: the token was refused mid-run (%s) - stopping "

                             "the lane; replace TINYCMDR_TG_TOKEN and restart", exc)

                _refuse("the Telegram token was refused mid-run: %s" % _lane_reason(exc))

            # MONOTONIC: this window must not be broken by a wall-clock step (NTP, a VM
            # resume) - `now - _failing_since` going negative is read as "no time has
            # passed" and silences the report (A-182).
            now = time.monotonic()

            if _failing_since is None:

                _failing_since = now

            elif lane_poll_failure_due(_failing_since, now):

                # The loop retries for ever in silence: without this, health says the
                # lane is up while it has heard nothing for minutes. Report through the
                # same lane record the other lanes use; the reason CLASS accumulates even
                # though the transport's own message varies per attempt (A-179/A-180).

                lane_down("telegram", "poll failing for %d min: %s"
                          % (int((now - _failing_since) / 60), exc))

                _failing_since = now

            log.warning("telegram: poll failed (%s), retrying in 5s", exc)

            time.sleep(5)

            continue

        if not _heard or _failing_since is not None:

            lane_up("telegram", "connected as @%s" % who)

            _heard = True

            _failing_since = None

        for update in updates:

            offset = max(offset, int(update.get("update_id") or 0) + 1)

            try:

                poller.handle(update)

            except Exception:                               # noqa: BLE001 - per update

                log.exception("telegram: one update failed")

        if offset != _persisted_offset:

            _remember_offset(offset)





# ------------------------------------------------------------------ the console
# This is the console: `tinycmdr` with no verb, or `--cli`. No second build cuts
# it, so every change lands here and nowhere else (2026-09-21).
_CLI = {"colour": False, "stop": None, "inbox": None, "steer": None,
        "leave": False, "stream": "", "streamed": "", "streamed_answer": "",
        # "ask": the question a run is parked on (None when none is open), and
        # "reader": is a reader thread the one owner of stdin (see _cli_reader)?
        # "app": the AppScreen when --app owns the terminal (None otherwise).
        "ask": None, "reader": False, "app": None}


def _console_utf8():
    """Windows consoles are not UTF-8 by default, and the banner is.

    Python's streams are reconfigured AND the console's own output code page is lifted to
    65001, so a child (`chcp`-inheriting PowerShell, a tool writing bytes) lands in the same
    encoding the harness reads.
    """
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")
        except Exception:
            pass
    if os.name == "nt":
        try:
            import ctypes
            ctypes.windll.kernel32.SetConsoleOutputCP(65001)
        except Exception:
            pass


def _ansi_enable():
    if os.name == "nt":
        try:
            import ctypes
            kern = ctypes.windll.kernel32
            # 0x0004 ENABLE_VIRTUAL_TERMINAL_PROCESSING, 0x0002 ENABLE_WRAP_AT_EOL_OUTPUT,
            # 0x0001 ENABLE_PROCESSED_OUTPUT - the same set colorama's
            # just_fix_windows_console() sets, without the dependency.
            kern.SetConsoleMode(kern.GetStdHandle(-11), 0x0001 | 0x0002 | 0x0004)
        except Exception:
            return False
    return bool(getattr(sys.stdout, "isatty", lambda: False)())


def _paint(text, role):
    """Paint a verb's line for a SEMANTIC role (see tui_sgr - the one conversion)."""
    code = tui_sgr(role)
    return "\033[%sm%s\033[0m" % (code, text) if _CLI["colour"] and code != "0" else text


def green(text):
    """The agent talking (narration, answers, confirmations): success reads `mark_success`."""
    return _paint(text, "mark_success")


def amber(text):
    """A tool call: what it is about to do."""
    return _paint(text, "33")


def red(text):
    """A failure, and only a failure: the palette's `error`."""
    return _paint(text, "error")


def dim(text):
    return _paint(text, "2")


def bold(text):
    """The answer: the one bright thing on the screen."""
    return _paint(text, "1;97")


def prompt(text):
    """The operator's own prompt - a colour nothing else on the screen uses."""
    return _paint(text, "1;36")


def answer_block(text):
    """The answer, announced: a dim rule, a blank line, then the bright text.

    A terminal has no bubbles and no cards, so the answer has to be marked. The
    complaint this answers (2026-09-21) was that the tool lines, the model's
    narration and the answer all read as the same white/green soup, so the eye had
    nowhere to land.
    """
    text = str(text)
    if not text.strip():
        return text
    rule = "-" * 62 if tui_ascii_only() else "\u2501" * 62   # heavy, matching the boxes
    return "\n" + _paint("  " + rule, "2") + "\n" + bold(text)


HELP_TEXT = ("\n"
             "  /tinycmdr help            this list\n"
             "  /tinycmdr new             forget the conversation so far and start clean\n"
             "  /tinycmdr model [name|list] show model status, list models, or switch\n"
             "  /tinycmdr setup           guided setup: endpoint, chat gateways, web search\n"
             "  /tinycmdr sessions        the conversations saved in this folder\n"
             "  /tinycmdr resume N        continue one of them in this window\n"
             "  /tinycmdr status          version, endpoint, context use, memory, skills\n"
             "  /tinycmdr memory          the knowledge bundle it keeps about this machine\n"
             "  /tinycmdr skills          the runbooks it can load\n"
             "  /tinycmdr tools           every tool it has right now\n"
             "  /tinycmdr usage           tokens and time for the last run\n"
             "  /tinycmdr stop            cancel the run in flight (Ctrl-C does the same)\n"
             "  /tinycmdr plan on|off|apply  read-only plan mode, and the approval that leaves it\n"
             "  /tinycmdr fork [name]     copy this conversation to try a different approach\n"
             "  /tinycmdr exit            quit (Ctrl-D does the same)\n"
             "\n"
             "  Anything else is a request:  check why the backup job failed\n"
             "  Type at any time, including while it is working: a request is sent in\n"
             "  at the next step, /tinycmdr stop and the read-only verbs act immediately,\n"
             "  and the verbs that change state (/tinycmdr new, /tinycmdr model) run when\n"
             "  the current run ends. One word everywhere: `tinycmdr status` in a shell,\n"
             "  `/tinycmdr status` in a session or in chat.\n"
             "  Ctrl-C stops the run in flight; a second Ctrl-C quits.\n")


def envelope_facts():
    """The one measurement of what a request carries.

    Two facts a skeptical reader checks: the disclosed schema set (what the WIRE
    sends, not what the registry holds - counting every schema read "34 tool
    schemas" on an install whose requests carried 14, which overstates the
    per-request cost by exactly what disclosure hides), and the static/live token
    arithmetic (the same measured static the request path and _compact use, so
    neither surface can drift from what is sent).

    The banner shows ONE merged line of this; /status shows the long form. Both
    read this function, so the short form can never disagree with the long one.
    """
    visible = select_tool_schemas(None)
    hidden = len(REGISTRY.openai_schemas()) - len(visible)
    env = AGENT._envelope()
    static = env["static"]
    live = est_tokens(volatile_context())
    return {
        "env": env, "schemas": len(visible), "hidden": hidden,
        "static": static, "live": live,
        "envelope": envelope_line(env),
        "prompt": ("\u007e%s tokens, cache-stable" % fmt_tokens(static + live)),
        "overhead": ("prompt overhead ~%s tokens (static %s: system prompt + %d tool "
                     "schemas%s, cache-stable; live %s: notes, sent "
                     "trailing)"
                     % (fmt_tokens(static + live), fmt_tokens(static), len(visible),
                        (", +%d hidden, revealed on demand" % hidden) if hidden > 0 else "",
                        fmt_tokens(live))),
    }


def cli_banner():
    name = "tinycmdr %s" % VERSION
    if "BUILD" in globals():          # the console build sets BUILD; the bot does not
        name += " (%s build)" % BUILD
    # The screen is taken FIRST, before anything measures or logs: tui_screen() is
    # what detaches the console log handler, and envelope_facts() logs a line
    # ("context: server reports ...") whose INFO record otherwise lands above the
    # banner as the very first thing a session shows.
    screen = tui_screen()
    f = envelope_facts()
    model = "%s at %s" % (CONFIG["llm"]["model"], CONFIG["llm"]["base_url"])
    context = ("~%s usable per turn \u00b7 prompt %s"
               % (fmt_tokens(f["env"]["budget"]), f["prompt"]))
    if f["env"].get("source") == "assumed":
        # The number below it is a guess with a moving denominator (8000 + static + reply);
        # saying so is the difference between a wrong window and an honest unknown.
        context += (" \u00b7 window ASSUMED - the endpoint did not report one; set "
                    "llm.context_window")
    if screen is not None:
        # Three content rows, not seven: the envelope and the prompt arithmetic
        # live in /status now. The frame carries the one accent.
        screen.banner(name, [
            ("model", model),
            ("folder", str(BASE_DIR)),
            ("context", context),
        ], hint="type /help for the commands, /exit to quit")
        return
    box = _cli_render_box(name, [
        "Model:    %s" % model,
        "Folder:   %s" % BASE_DIR,
        "Context:  %s" % context,
        "---",
        "Type /tinycmdr help for commands, /tinycmdr exit to quit",
    ])
    print(box + "\n")


def _tui_session():
    """The prompt_toolkit session, or None. Built once, and only with a screen.

    History is in memory on purpose: a history FILE would be one more file in a
    folder whose rule is that opening the build creates nothing but the log's first
    line, and up-arrow within the session is the part that matters.
    """
    if "prompt" in _CLI:
        return _CLI["prompt"]
    _CLI["prompt"] = None
    if tui_screen() is not None:
        try:
            from prompt_toolkit import PromptSession
            from prompt_toolkit.history import InMemoryHistory
            from prompt_toolkit.styles import Style
            _CLI["prompt"] = PromptSession(
                history=InMemoryHistory(),
                bottom_toolbar=_tui_toolbar,
                enable_history_search=True,
                style=Style.from_dict({
                    "prompt": "ansicyan bold",
                    "bottom-toolbar": "bg:#1b1f27 #8b939e",
                }))
            _CLI["screen"].on_status = _tui_on_status
        except Exception:
            _CLI["prompt"] = None
    return _CLI["prompt"]


def _tui_toolbar():
    """The line under the input: the run's own line, and the keys that matter."""
    from prompt_toolkit.formatted_text import FormattedText
    status = (_CLI.get("status") or "").strip()
    tail = "/help · /stop cancels a run · Ctrl-C stops one · Ctrl-D quits"
    return FormattedText([("class:bottom-toolbar",
                           " " + (status + "      " if status else "") + tail)])


def _tui_on_status(text):
    """The run reported something: show it under the input, where it cannot be
    mistaken for part of the transcript, and leave it there for the next prompt."""
    _CLI["status"] = str(text)
    sess = _CLI.get("prompt")
    if sess is not None:
        try:
            sess.app.invalidate()
        except Exception:
            pass


def _tui_prompt_text():
    """'you> ' in the session's own style, so it stops looking like agent output."""
    from prompt_toolkit.formatted_text import FormattedText
    return FormattedText([("class:prompt", "you> ")])


def tui_screen():
    """The screen for this console, or None for plain lines. Built once per process:
    the banner, the cards and the done line all come from the same one."""
    if "screen" not in _CLI:
        _CLI["screen"] = TuiScreen() if tui_wanted() else None
        if _CLI["screen"] is not None:
            log_console_off()      # one writer per terminal: see log_console_off()
    return _CLI["screen"]


def _cli_key():
    """Which conversation this console is in. 'cli' until /resume says otherwise.

    Always a STRING: this becomes a filename (sessions/<key>.json). The prompt
    tool's editing surface lives in _CLI["prompt"] and must never land here - it
    did, and sessions stopped saving (a Windows host measured 2026-09-22: "could not
    save session ... got 'PromptSession'", event log unwritten). The isinstance
    belt is the same guard that box shipped.
    """
    key = _CLI.get("session") or "cli"
    return key if isinstance(key, str) else "cli"


def _session_tail_state(hist):
    """'unfinished' when a stored history ended badly, else 'ok'.

    The same read `_prior_run_unfinished` makes from the LIVE history, applied to a file:
    a dangling operator message (killed mid-run) or one of the harness's abnormal end
    markers as the last assistant turn. The session picker then shows which conversations
    ended badly instead of making an operator open each one.
    """
    if not isinstance(hist, list) or not hist:
        return "ok"
    last = ""
    newest = ""
    for msg in reversed(hist):
        if not isinstance(msg, dict):
            continue
        role = msg.get("role")
        if role not in ("user", "assistant"):
            continue
        if not newest:
            newest = role
        if role == "assistant" and (msg.get("content") or "").strip():
            last = str(msg["content"]).strip()
            break
    if newest == "user":
        return "unfinished"
    for marker, _reason in _ABNORMAL_END_MARKERS:
        if last.startswith(marker):
            return "unfinished"
    return "ok"


_CLI_LAUNCH_SEQ = {"n": 0}      # two launches in one process (a test, a wrapper) differ


def _fresh_cli_key():
    """A NEW conversation for a new launch.

    Typing `tinycmdr` means "start" - the operator should not land in yesterday's
    transcript still asking about yesterday's ledger (measured 2026-10-03: a brand-new
    window answered a new question about the previous run's work, and every `--once` run
    on a box shared one `cli` conversation with every other). Older conversations stay on
    disk, are listed by `/tinycmdr sessions`, and are resumed with `--continue` or
    `/tinycmdr resume N`.
    """
    _CLI_LAUNCH_SEQ["n"] += 1
    return "cli-%s-%d-%d" % (time.strftime("%Y%m%d-%H%M%S"), os.getpid(),
                             _CLI_LAUNCH_SEQ["n"])


def _cli_startup_session(argv=()):
    """Which conversation this console opens in: fresh, unless asked to continue.

    `--session NAME` names one exactly; `TINYCMDR_SESSION` does the same from the
    environment (scripts and tests); `--continue` resumes the most recently used
    conversation that is not already a fresh one. The bot lanes never come through here -
    their keys are their channels.
    """
    argv = list(argv or ())
    want = ""
    for i, arg in enumerate(argv):
        if arg == "--session" and i + 1 < len(argv):
            want = argv[i + 1].strip()
        elif arg.startswith("--session="):
            want = arg.split("=", 1)[1].strip()
    if want:
        return want
    env = (os.environ.get("TINYCMDR_SESSION") or "").strip()
    if env:
        return env
    if "--continue" in argv or "--resume" in argv:
        for row in _cli_session_rows():          # newest first
            key = str(row.get("key") or "")
            if key:
                return key
    return _fresh_cli_key()


def _cli_session_rows():
    """Saved conversations, newest first: key, exchanges, when it was last used.

    A session key IS a filename here (the agent writes sessions/<key>.json), so
    this reads what is on disk rather than keeping a second list that could
    disagree with it.
    """
    rows = []
    try:
        files = list(SESSIONS_DIR.glob("*.json"))
    except OSError:
        files = []
    for f in files:
        if f.name.startswith("export-"):
            continue        # /save exports, not conversations
        if not _is_session_file(f):
            # ...and neither are the carry/hints/question sidecars: the hints file IS a
            # JSON list, so the shape check below let it list as a conversation called
            # "x.hints".
            continue
        try:
            hist = json.loads(f.read_text(encoding="utf-8"))
        except Exception:
            continue        # a damaged session is not a reason to fail here
        if not isinstance(hist, list):
            continue
        rows.append({"key": f.stem, "messages": len(hist),
                     "state": _session_tail_state(hist),
                     "exchanges": sum(1 for m in hist if isinstance(m, dict)
                                      and m.get("role") == "user"),
                     "mtime": f.stat().st_mtime})
    rows.sort(key=lambda r: r["mtime"], reverse=True)
    return rows


def _cli_sessions():
    rows = _cli_session_rows()
    if not rows:
        print(dim("  no saved conversations yet"))
        return rows
    cur = _cli_key()
    for i, r in enumerate(rows, 1):
        print("  %s %2d. %-30s %3d exchange(s)  %s%s"
              % ("*" if r["key"] == cur else " ", i, r["key"][:30],
                 r["exchanges"],
                 time.strftime("%Y-%m-%d %H:%M", time.localtime(r["mtime"])),
                 "   [unfinished]" if r.get("state") == "unfinished" else ""))
    print(dim("  /resume N continues one of them here; * is the one in use"))
    return rows


def _cli_resume(rest):
    rows = _cli_session_rows()
    if not rows:
        print(dim("  no saved conversations yet"))
        return
    try:
        n = int((rest or "").split()[0])
    except (IndexError, ValueError):
        n = 0
    if not 1 <= n <= len(rows):
        print(dim("  /tinycmdr resume N - pick N from /tinycmdr sessions"))
        return
    key = rows[n - 1]["key"]
    _CLI["session"] = key
    s = AGENT.stats(key)
    print(green("  now in '%s' - %d exchange(s), %s"
                % (key, s["exchanges"], fmt_tokens(s["est_tokens"]))))
    print(dim("  /tinycmdr new clears it; /tinycmdr sessions lists the others"))


def cli_out(text):
    """One place for a console line, so a screen can be the only writer.

    Anything printed while prompt_toolkit owns the terminal has to go through it;
    everything else in the console (the banner, the command answers) prints before
    or between prompts, where prompt_toolkit handles it.
    """
    screen = tui_screen()
    if screen is not None:
        screen.echo_ansi(str(text))
        return
    print(text)


def _cli_usage_line(force=False):
    """Tokens/time for the last run.

    With a prompt_toolkit toolbar under the input, the status surface is the
    toolbar and the transcript gets nothing: the same numbers in both places read
    as duplication. Without one, or when /usage asks explicitly, the
    line prints."""
    u = AGENT.last_usage.get(_cli_key())
    if not u or not u.get("calls"):
        return
    if not force and (_CLI.get("prompt") is not None or _CLI.get("app") is not None):
        return
    s = AGENT.stats(_cli_key())
    budget = AGENT._context_budget()
    pct = 100 * s["est_tokens"] // max(1, budget)
    cli_out(dim("  %s - %s step(s) in %ss - context ~%s/%s (%d%%)"
                % (fmt_usage(u), u["steps"], int(u["secs"]), fmt_tokens(s["est_tokens"]),
                   fmt_tokens(budget), pct)))


def _cli_memory():
    """The memory bundle as the operator reads it: its index and size."""
    if not MEMORY_INDEX.exists():
        print(dim("  memory/ is empty - nothing written down yet"))
        return
    index = MEMORY_INDEX.read_text(encoding="utf-8", errors="replace").strip()
    count = len(memory_scan())
    print(dim("  %s (%d concept%s, index %d chars)"
              % (MEMORY_INDEX, count, "" if count == 1 else "s", len(index))))
    for line in index.splitlines()[-60:]:
        print("  " + line)


def _cli_render_box(title, lines, width=74):
    if tui_ascii_only():
        tl = tr = bl = br = sep = "+"
        hz, vt = "-", "|"
    else:
        tl, tr, bl, br = "\u250f", "\u2513", "\u2517", "\u251b"   # heavy
        hz, vt, sep = "\u2501", "\u2503", "\u2523"
    top = tl + hz + " %s " % title + hz * max(0, width - len(title) - 5) + tr
    bottom = bl + hz * (width - 2) + br
    rule = sep + hz * (width - 2) + tr if tui_ascii_only() else sep + hz * (width - 2) + "\u252b"
    body = []
    for line in lines:
        if line == "---":
            body.append(rule)
        else:
            padding = max(0, width - 4 - len(line))
            body.append(vt + " %s" % line + " " * padding + " " + vt)
    return "\n".join([top] + body + [bottom])


MODEL_ENDPOINT_DEFAULT = "http://127.0.0.1:8081/v1"


def _ask_endpoint_kind(default_url, prompt="   Is the endpoint local or cloud? [%s]: "):
    """Local or hosted? The first model question, with the current URL as the default.

    The question that was missing: the wizard asked for a URL, probed it WITHOUT the key
    (so a hosted provider's 401 read as "not reachable"), and only then asked for a key -
    after the model list it needed that key to fetch had already failed. Ask this first,
    so a cloud endpoint carries its key into the probe."""
    local_default = "local" if _is_local_url(default_url) else "cloud"
    print(dim("   local: this machine or your LAN (llama.cpp, Ollama, vLLM - no key)"))
    print(dim("   cloud: a hosted OpenAI-compatible provider (answers only with a key)"))
    while True:
        ans = input(prompt % local_default).strip().lower()
        if not ans:
            return local_default
        if ans in ("l", "local", "lan", "1", "on-prem", "on prem", "this machine"):
            return "local"
        if ans in ("c", "cloud", "hosted", "remote", "2", "provider"):
            return "cloud"
        print(red("   answer local or cloud"))


def _choose_one_model(url, ids, default=""):
    """The model an endpoint serves: pick from what it advertised, or type an id.

    A picker when the terminal can host one, a NUMBER-able list otherwise, and the plain
    prompt when the endpoint advertised nothing (offline, or a custom path). The number
    resolution matches the installer's own ask_model_id, so "2" means the same thing in
    every door."""
    if not ids:
        print(dim("   no model list came back, so the model id is whatever you type"))
        ans = input("   Model id [%s]: " % default).strip()
        return ans or default
    if default not in ids:
        default = ids[0]
    if pick_terminal_ready():
        state = ModelPick([(i, "advertised by %s" % url, i == default) for i in ids],
                          current=default, title="Which model? (%d advertised)" % len(ids),
                          scope="ENTER sets the model - ESC keeps %s" % default)
        picked = run_model_pick(state)
        if not picked:
            print(dim("   kept %s" % default))
        return picked or default
    print("   models it advertises:")
    for n, i in enumerate(ids, 1):
        print("     %2d) %s" % (n, i))
    ans = input("   Model id (number or name) [%s]: " % default).strip()
    if not ans:
        return default
    if ans.isdigit() and 1 <= int(ans) <= len(ids):
        return ids[int(ans) - 1]
    return ans


def _ask_model_target(default_url="", default_model="", default_key=""):
    """Ask where a model lives, prove the key, and choose from what the endpoint serves.

    THE one model-adding conversation: `setup` (the primary) and `model add` (an endpoint
    added later) both call it, so both ask the same things in the same order - local or
    cloud, then the endpoint link, then the key that link needs (cloud only), then the
    model list the endpoint actually returns. A cloud answer sends the key as a bearer on
    GET /models before a model is chosen, so a wrong key is named here (HTTP 401) instead
    of surfacing as a failed first message; a local answer sends none.

    Returns {"url", "model", "key"} (key "" for local), or None when there is no endpoint
    to write.
    """
    default_url = str(default_url or MODEL_ENDPOINT_DEFAULT).strip().rstrip("/")
    kind = _ask_endpoint_kind(default_url)
    # The LINK comes before the key: the link says which key belongs to it, and asking
    # for a key before the endpoint it is for reads as a question out of order
    # (2026-10-04). Asked once, after the first URL is accepted; a
    # 401 re-asks it below, where the reason is visible.
    key = ""
    url, ids, url_tries = "", None, 0
    while True:
        label = ("Endpoint (e.g. https://api.provider.com/v1)" if kind == "cloud"
                 else "Endpoint")
        ans = input("   %s [%s]: " % (label, url or default_url)).strip()
        url = (ans or url or default_url)
        if not url.lower().startswith(("http://", "https://")):
            print(red("   URL must start with http:// or https://"))
            if not ans:
                return None
            continue
        if kind == "cloud" and not key:
            if default_key:
                print(dim("   a key is already set for this endpoint (Enter keeps it)"))
            key = input("   API key (leave empty if it needs none): ").strip() or default_key
        # The key changed on a 401 without the URL changing: re-probe the same link
        # rather than making the reader re-type it. Bounded - three refusals means the
        # provider is not going to take it, and the rest of the wizard has work to do.
        key_tries = 0
        while True:
            res = probe_endpoint(url, key, timeout=10)
            if res["status"] in (401, 403) and kind == "cloud":
                key_tries += 1
                if key_tries >= 3:
                    print(dim("   the provider still refuses the key - keeping %s "
                              "unverified" % url))
                    break
                print(red("   \u2717 the provider refused that key (HTTP %d)"
                          % res["status"]))
                key = input("   API key (try again): ").strip() or key
                continue
            break
        if res["ok"]:
            ids = res["ids"]
            print(green("   \u2713 reachable%s"
                        % (" - models: %s" % ", ".join(ids[:8]) if ids
                           else " (no model list advertised)")))
            break
        print(red("   \u2717 %s" % probe_sentence(url, res)))
        if not ans:
            # Enter on the URL that was already there: say what is wrong, name the command
            # that fixes it, and let the rest of the wizard run. The retry loop is for a
            # typo somebody just typed.
            print(dim("   keeping it: fix it later with `tinycmdr model endpoint <url>`"))
            break
        url_tries += 1
        if url_tries >= 3:
            print(dim("   keeping it anyway: fix it later with "
                      "`tinycmdr model endpoint <url>`"))
            break
        print(dim("   check the host and port (the server may not be running yet)."))
    model = _choose_one_model(url, ids or [], default_model)
    return {"url": url, "model": model, "key": key}


def run_setup(rest=None):
    """Guided interactive setup wizard: model endpoint, chat gateways, the page, web search."""
    if _CLI.get("app") is not None:
        # The app owns stdin as well as the screen, and a raw input() competes with its
        # input box for the same bytes - the prompts and the app's frame scribble over each
        # other. Say so, and point at the door that works.
        print(red("  setup needs the terminal to itself: run `tinycmdr setup` in a shell, "
                  "not from inside --app."), file=sys.stderr)
        return 1
    if not sys.stdin.isatty():
        print("tinycmdr setup requires an interactive terminal.\n"
              "For non-interactive: tinycmdr config set <key> <val> and tinycmdr token set <NAME>",
              file=sys.stderr)
        return 1

    print(_cli_render_box("tinycmdr Setup Wizard", [
        "Configure model endpoints, Mattermost, Telegram, the page, and web-search consent.",
        "Press Enter to keep current values shown in [brackets].",
    ]))
    print()

    try:
        raw = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    except Exception as e:
        print(red("could not read config.json: %s" % e), file=sys.stderr)
        return 1

    llm = raw.setdefault("llm", {})
    mm = raw.setdefault("mattermost", {})
    tg = raw.setdefault("telegram", {})

    cur_url = llm.get("base_url") or "http://127.0.0.1:8081/v1"
    cur_model = llm.get("model") or "main"

    print(bold("1. LLM Endpoint & Model"))
    cur_key = _primary_api_key()
    target = _ask_model_target(cur_url, cur_model, cur_key)
    if target is None:
        print(red("   no endpoint written"), file=sys.stderr)
        return 1
    llm["base_url"], llm["model"] = target["url"], target["model"]
    if target["key"]:
        if target["key"] != cur_key:
            if _env_set_safe("TINYCMDR_LLM_API_KEY", target["key"]):
                print(dim("   API key saved to .env as TINYCMDR_LLM_API_KEY"))
        # The running process must see it NOW, not after a restart: model_catalog and every
        # later probe read _primary_api_key(), which prefers config.json and falls back to
        # this variable. (The wizard used to save the key and then drop it from the live
        # CONFIG when it wrote the file back.)
        os.environ["TINYCMDR_LLM_API_KEY"] = target["key"]
    # A hosted endpoint says nothing about its window (/v1/models carries no max_model_len
    # and there is no /props to ask), so the harness would run it on an assumed 8000 and clip
    # replies at 2048. Setup is where the endpoint is being named, so it is where the one key
    # that fixes it belongs. The probe is read-only, the same one the envelope runs;
    # an on-LAN box is skipped - its lever is its own context slot, not a config key.
    if not _is_local_url(llm["base_url"]) and not _detect_window(llm["base_url"], None):
        # The window is ASKED here, at the moment the endpoint is being named, rather
        # than left as a note and homework: the operator is already configuring this
        # endpoint ("it should have asked at that time";
        # 2026-10-04). Only a hosted endpoint gets asked - an on-LAN box has its own
        # context slot, and the probe reads no window from /v1/models.
        cur_win = int(llm.get("max_context_tokens") or 8000)
        print(dim("   The endpoint reported no context window; the harness assumes %d and"
                  % cur_win))
        print(dim("   clips replies at 2048. Hosted models usually document 32k-128k+."))
        ans_win = input("   Context window in tokens [%s]: " % cur_win).strip()
        if ans_win:
            try:
                win = int(ans_win.replace(",", "").lower().replace("k", "000").strip())
            except ValueError:
                print(red("   '%s' is not a number; keeping %d" % (ans_win, cur_win)))
            else:
                if win >= 2048:
                    llm["max_context_tokens"] = win
                else:
                    print(red("   %d is below the 2048 reply floor; keeping %d"
                              % (win, cur_win)))
    # A cloud fallback is only reached automatically when the operator says so, and
    # the flag shipped with no door (config.json only). Ask, but only when such an
    # endpoint is actually configured - an install with no off-LAN endpoint has
    # nothing to decide.
    _cloud_fbs = [str(f.get("base_url")) for f in (llm.get("fallbacks") or [])
                  if isinstance(f, dict) and f.get("base_url")
                  and not _is_local_url(str(f["base_url"]))]
    if _cloud_fbs:
        _cur_cf = bool(llm.get("allow_cloud_fallback", False))
        print(dim("   Off-LAN endpoint(s) configured: %s" % ", ".join(_cloud_fbs)))
        ans_cf = input("   Allow automatic failover to them when the local one "
                       "fails? [%s]: " % ("y" if _cur_cf else "n")).strip().lower()
        llm["allow_cloud_fallback"] = (_cur_cf if not ans_cf
                                       else ans_cf in ("y", "yes", "true", "1"))
    print()

    print(bold("2. Mattermost Gateway (Chat)"))
    cur_mm_url = mm.get("url") or ""
    want_mm = input("   Configure Mattermost gateway? [%s]: " % ("y" if cur_mm_url else "n")).strip().lower()
    if want_mm in ("y", "yes"):
        mm_url = input("   Mattermost server URL (e.g. https://chat.example.com) [%s]: " % cur_mm_url).strip()
        if mm_url:
            mm["url"] = mm_url
        mm_token = input("   Mattermost bot token (leave empty to keep current): ").strip()
        if mm_token:
            if _env_set_safe("TINYCMDR_MM_TOKEN", mm_token):
                print(dim("   Mattermost token saved to .env"))
        cur_users = ",".join(mm.get("allowed_users") or [])
        mm_users = input("   Allowed User ID(s) (comma-separated) [%s]: " % cur_users).strip()
        if mm_users:
            mm["allowed_users"] = [u.strip() for u in mm_users.split(",") if u.strip()]
    print()

    print(bold("3. Telegram Gateway (Chat)"))
    cur_tg_users = ",".join(str(u) for u in (tg.get("allowed_users") or []))
    want_tg = input("   Configure Telegram gateway? [%s]: " % ("y" if cur_tg_users else "n")).strip().lower()
    if want_tg in ("y", "yes"):
        tg_token = input("   Telegram bot token (leave empty to keep current): ").strip()
        if tg_token:
            if _env_set_safe("TINYCMDR_TG_TOKEN", tg_token):
                print(dim("   Telegram token saved to .env"))
        tg_users = input("   Allowed numeric User ID(s) (comma-separated) [%s]: " % cur_tg_users).strip()
        if tg_users:
            try:
                tg["allowed_users"] = [int(u.strip()) for u in tg_users.split(",") if u.strip()]
            except ValueError:
                tg["allowed_users"] = [u.strip() for u in tg_users.split(",") if u.strip()]
    print()

    print(bold("4. The page (browser)"))
    # The page is the default door; its token is the one secret this project will MINT
    # for you - and since 2026-10-04 the wizard also lets the operator SET it. A token
    # chosen elsewhere (a password manager, a fleet convention) used to force a hand-edit
    # of .env after setup; that was reported. Enter keeps the host's own
    # token or mints one, either way the answer is a working link, not homework.
    web = raw.setdefault("web", {})
    cur_on = bool(web.get("enabled", True))
    ans_on = input("   Serve the page? [%s]: " % ("y" if cur_on else "n")).strip().lower()
    web["enabled"] = cur_on if not ans_on else ans_on in ("y", "yes", "true", "1")
    if web["enabled"]:
        cur_host = str(web.get("host") or "127.0.0.1")
        print(dim("   127.0.0.1 keeps it on this machine; 0.0.0.0 lets any machine on "
                  "your network open it, where the token travels in cleartext."))
        ans_lan = input("   Reachable from other machines on your network? [%s]: "
                        % ("y" if cur_host in ("0.0.0.0", "::") else "n")).strip().lower()
        if ans_lan:
            web["host"] = "0.0.0.0" if ans_lan in ("y", "yes", "true", "1") else "127.0.0.1"
        else:
            web["host"] = cur_host
        # A configured 0 is "the OS picks a free port", so the default this prompt shows
        # is the port the box is actually on, not 8790 - and Enter keeps the 0 on disk.
        cur_port = web.get("port") or web_port_effective()
        ans_port = input("   Port [%s]: " % cur_port).strip()
        if ans_port:
            try:
                web["port"] = int(ans_port)
            except ValueError:
                print(dim("   '%s' is not a port; keeping %s" % (ans_port, cur_port)))
        web.setdefault("port", 8790)
        # `web` above is the dict being written; the helper reads the LIVE config, which
        # does not carry a port typed in this wizard run yet. So the typed value wins,
        # and anything falsy (0, absent) means "ask the helper".
        page_port = int(web.get("port") or web_port_effective())
        cur_tok = _web_token()
        # The write path enforces the shape (`token set`'s rule: 20+ of letters, digits,
        # _ or -), and a refused value must come back as a question, not as a link that
        # quietly still carries the old token.
        for _try in range(3):
            ans_tok = input("   Access token (Enter to %s): "
                            % ("keep the current one" if cur_tok else "mint one")).strip()
            if not ans_tok:
                break
            if _env_set_safe("TINYCMDR_WEB_TOKEN", ans_tok):
                os.environ["TINYCMDR_WEB_TOKEN"] = ans_tok
                print(dim("   token saved to .env as TINYCMDR_WEB_TOKEN"))
                if web.get("token"):
                    # config.json is readable into a prompt, so the token lives in .env
                    # only; a stale value here would silently outrank the one just set.
                    # The LIVE CONFIG too: the link printed below reads it first.
                    web.pop("token", None)
                    CONFIG.setdefault("web", {}).pop("token", None)
                    print(dim("   removed the older web.token from config.json - the "
                              "token belongs in .env, which the agent never reads"))
                break
            if _try < 2:
                print(dim("   try again, or press Enter to %s"
                          % ("keep the current one" if cur_tok else "mint one")))
        if not _web_token():
            _web_token_mint(announce=True)
        tok = _web_token()
        if tok:
            urls = _web_base_urls(page_port)
            print(dim("   page link : %s#token=%s" % (urls[0][0], tok)))
            if web.get("host") in ("0.0.0.0", "::"):
                print(dim("   that link works from your network; the token rides in "
                          "cleartext there, so use a network you trust"))
                for _line in _firewall_note(page_port):
                    print(dim("   " + _line))
    else:
        print(dim("   the page will not start; `tinycmdr --web` can still serve it for "
                  "one run."))
    print()

    print(bold("5. Web search (optional)"))
    search = raw.setdefault("search", {})
    cur_egress = bool(search.get("allow_cloud_egress"))
    print(dim("   A provider off this LAN sees the words of the model's query. A provider"))
    print(dim("   on this LAN (searxng) never leaves the wire and needs no consent."))
    ans_eg = input("   Allow search providers off this LAN (anysearch/tavily)? [%s]: "
                   % ("y" if cur_egress else "n")).strip().lower()
    if ans_eg:
        search["allow_cloud_egress"] = ans_eg in ("y", "yes", "true", "1")
    else:
        search["allow_cloud_egress"] = cur_egress
    print()

    try:
        _write_config(raw)
        CONFIG.update(raw)
        _MODEL_CACHE["at"] = 0.0
    except Exception as e:
        print(red("could not write config.json: %s" % e), file=sys.stderr)
        return 1
    # Setup can add a key this process did not have at import; re-derive the sweep so
    # the keys it just wrote are masked like the rest (2026-09-29).
    global _SECRETS
    _SECRETS = _secret_values()

    summary = [
        "LLM Endpoint : %s" % llm.get("base_url"),
        "LLM Model    : %s" % llm.get("model"),
        "---",
        "Mattermost   : %s" % (mm.get("url") or "(disabled)"),
        "MM Users     : %s" % (", ".join(mm.get("allowed_users") or []) or "(none)"),
        "---",
        "Telegram     : %s" % ("configured" if tg.get("allowed_users") else "(disabled)"),
        "TG Users     : %s" % (", ".join(str(x) for x in (tg.get("allowed_users") or [])) or "(none)"),
        "---",
        "Page         : %s" % ("http://%s:%s (token in .env)"
                               % (web.get("host") or "127.0.0.1", web_port_effective())
                               if web.get("enabled", True) else "(disabled)"),
        "Web search   : %s" % ("off-LAN providers allowed"
                               if search.get("allow_cloud_egress")
                               else "this LAN only (searxng never needs consent)"),
        "---",
        "✓ Saved to config.json & .env",
        "Run `tinycmdr restart` to apply to background service.",
    ]
    print(_cli_render_box("Setup Complete", summary))
    return 0





MODEL_PICK_VIEW = 12      # rows on screen at once; the list scrolls under the cursor

# The picker's first row: the way to ADD or CHANGE an endpoint without typing a command.
# It is a row NAME the shell verb intercepts (never a real model id), so it goes through
# the same ↑↓/filter/ENTER machinery as everything else.
MODEL_PICK_ADD = "\u2795 add or change the endpoint\u2026"



def model_pick_rows(entries, current):
    """[(name, detail, is_current)] for the picker, from model_catalog()'s entries.

    The detail is what tells two rows with the same name apart: the endpoint behind it, and
    the id it actually sends when the name is an alias.
    """
    rows = []
    for e in entries:
        name = str(e.get("name") or "").strip()
        if not name:
            continue
        bits = []
        if e.get("send_as") and str(e["send_as"]) != name:
            bits.append("sends as %s" % e["send_as"])
        if e.get("url"):
            bits.append("%s%s" % ("local " if e.get("local") else "", e["url"]))
        rows.append((name, " · ".join(bits), name.lower() == str(current or "").lower()))
    return rows


# A `bg:` slot takes a COLOUR. The palette's `16` and `none` rows put the style
# ATTRIBUTE `reverse` in `selection_bg` (the Basic-ANSI set has no dark red to select
# with), and a theme.toml written in human words can land there the same way after
# `_ANSI_WORDS`. prompt_toolkit parses the whole table up front and one bad slot raises
# ValueError("Wrong color format 'reverse'") out of `Style.from_dict`, which killed
# `--app` at startup on every plain conhost / `TERM=xterm` session (tier `16` is
# `tui_colour_tier()`'s fallback) and the shell's model picker on a NO_COLOR terminal -
# measured on a real pty 2026-10-06. A value that is not a colour rides as attributes.
_PICK_COLOUR = re.compile(
    r"^(#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})|ansi(bright)?"
    r"(black|red|green|yellow|blue|magenta|cyan|white)"
    r"|(black|red|green|yellow|blue|magenta|cyan|white|default))$")


def pick_sel_style(palette):
    """The selected row's style: `bg:<colour>` when the palette names a COLOUR, the
    palette's own words when it names an attribute (`reverse` on the 16-colour tier)."""
    sel = str(palette.get("selection_bg") or "").strip()
    fg = str(palette.get("selection_fg") or "").strip()
    if not sel:
        return "reverse"
    body = ("bg:" + sel) if _PICK_COLOUR.match(sel.lower()) else sel
    return ("%s %s" % (body, fg)).strip()


def model_pick_styles(palette):
    """The picker's style classes, from the same palette the cards read."""
    return {
        "pick.title": palette.get("gold", ""),
        "pick.hint": palette.get("muted", ""),
        "pick.row": palette.get("text", ""),
        "pick.sel": pick_sel_style(palette),
        "pick.cur": palette.get("gold", ""),
        "pick.filter": palette.get("ember", ""),
    }


class ModelPick:
    """The model list as something you MOVE through - the predecessor harness's picker
    on this install's data.

    One state machine and one renderer, two hosts: `--app` draws it inside its own
    Application (a second prompt_toolkit Application cannot own the terminal the first one
    holds), and the shell verb runs it as a small Application of its own. Every key means
    the same thing in both, because the meaning lives here.

    It replaces what bare `model` used to be: a Commands box telling the reader to retype
    the whole command with an exact name they had to already know.
    """

    def __init__(self, rows, current="", title="Select model", scope=""):
        self.rows = list(rows)
        self.current = current
        self.title = title
        self.scope = scope                       # what ENTER does here, said out loud
        self.filter = ""
        self.cursor = next((i for i, r in enumerate(self.rows) if r[2]), 0)
        self.top = 0
        self._clamp()

    def visible(self):
        q = self.filter.lower()
        if not q:
            return list(range(len(self.rows)))
        return [i for i, r in enumerate(self.rows)
                if q in r[0].lower() or q in r[1].lower()]

    def _clamp(self):
        shown = self.visible()
        if not shown:
            self.cursor = self.top = 0
            return
        self.cursor = max(0, min(self.cursor, len(shown) - 1))
        self.top = min(self.top, self.cursor)
        if self.cursor >= self.top + MODEL_PICK_VIEW:
            self.top = self.cursor - MODEL_PICK_VIEW + 1

    def move(self, delta):
        shown = self.visible()
        if shown:
            self.cursor = max(0, min(self.cursor + delta, len(shown) - 1))
        self._clamp()
        return self

    def typed(self, text):
        self.filter += str(text)
        self.cursor = 0
        self._clamp()
        return self

    def backspace(self):
        self.filter = self.filter[:-1]
        self._clamp()
        return self

    def picked(self):
        shown = self.visible()
        return self.rows[shown[self.cursor]][0] if shown else None

    def footer(self):
        """What ENTER will do, and where the cursor is - the line both hosts show."""
        return self.scope

    def render(self, width=80):
        """The predecessor harness's shape: a title, the key hint, the list with ONE
        cursor row, the filter.

        Returns [(style, text)] with a newline between rows: a FormattedTextControl splits
        lines on "\\n" INSIDE a piece, so rows handed over as separate pieces and no newline
        render as one long line.
        """
        out = [("class:pick.title", " " + self.title)]
        out.append(("class:pick.hint",
                    " \u2191\u2193 navigate  ENTER select  ESC cancel  \u00b7 type to filter"))
        shown = self.visible()
        limit = max(8, int(width) - 2)
        if self.top:
            out.append(("class:pick.hint", " \u2191 %d more" % self.top))
        for pos in range(self.top, min(self.top + MODEL_PICK_VIEW, len(shown))):
            name, detail, is_current = self.rows[shown[pos]]
            here = pos == self.cursor
            line = "%s (%s) %s" % ("\u2192" if here else " ",
                                   "\u25cf" if (here or is_current) else "\u25cb", name)
            if detail:
                line += "  " + detail
            if is_current:
                line += "  \u2190 current"
            out.append(("class:pick.sel" if here else "class:pick.row", " " + line[:limit]))
        below = len(shown) - (self.top + MODEL_PICK_VIEW)
        if below > 0:
            out.append(("class:pick.hint", " \u2193 %d more" % below))
        if not shown:
            out.append(("class:pick.hint",
                        " nothing matches %r - Backspace to widen" % self.filter))
        if self.filter:
            out.append(("class:pick.filter",
                        " Filter: %s\u258f  (%d/%d match - type to narrow, Backspace to clear)"
                        % (self.filter, len(shown), len(self.rows))))
        if self.scope:
            out.append(("class:pick.hint", " " + self.scope))
        last = len(out) - 1
        return [(style, text + ("\n" if i < last else ""))
                for i, (style, text) in enumerate(out)]


def run_model_pick(state, input=None, output=None):
    """The shell door's host: the picker as its own Application over an OWNED terminal.

    Only a lane that owns the terminal may call this. `--app` must not - its Application is
    already on that terminal, so it draws the picker inside itself
    (AppScreen.open_model_pick) - and neither may the inline console, whose reader holds
    stdin in a prompt. Returns the chosen name, or None when it was cancelled.
    """
    from prompt_toolkit.application import Application
    from prompt_toolkit.key_binding import KeyBindings
    from prompt_toolkit.keys import Keys
    from prompt_toolkit.layout import Layout, Window
    from prompt_toolkit.layout.controls import FormattedTextControl
    from prompt_toolkit.styles import Style

    kb = KeyBindings()
    app = None
    done = {}

    def finish(value):
        done["value"] = value
        if app is not None and app.is_running:
            app.exit()

    @kb.add("up")
    def _(event):
        state.move(-1)

    @kb.add("down")
    def _(event):
        state.move(1)

    @kb.add("pageup")
    def _(event):
        state.move(-MODEL_PICK_VIEW)

    @kb.add("pagedown")
    def _(event):
        state.move(MODEL_PICK_VIEW)

    @kb.add("enter")
    def _(event):
        # Nothing under the cursor (an empty filter): ENTER stays put, ESC is the way out.
        name = state.picked()
        if name:
            finish(name)

    @kb.add("escape")
    def _(event):
        finish(None)

    @kb.add("c-c")
    def _(event):
        finish(None)

    @kb.add("backspace")
    def _(event):
        state.backspace()

    @kb.add(Keys.Any)
    def _(event):
        if event.data and event.data.isprintable() and event.data != "\t":
            state.typed(event.data)

    def _width():
        try:
            return app.output.get_size().columns
        except Exception:                                        # noqa: BLE001
            return 80

    app = Application(
        layout=Layout(Window(FormattedTextControl(lambda: state.render(_width())),
                             wrap_lines=False)),
        key_bindings=kb, full_screen=False, erase_when_done=True, mouse_support=False,
        style=Style.from_dict(model_pick_styles(TUI_PALETTE[tui_colour_tier()])))
    if input is not None:
        app.input = input
    if output is not None:
        app.output = output
    app.run()
    return done.get("value")


def pick_terminal_ready():
    """Can a shell verb open the picker? A terminal, and not the plain-lines lane."""
    if os.environ.get("TINYCMDR_PLAIN"):
        return False
    try:
        return bool(sys.stdin.isatty() and sys.stdout.isatty())
    except Exception:                                            # noqa: BLE001
        return False


def _cli_pick_available():
    """Can THIS door show the picker? Only `--app`: it owns the terminal, so the picker is
    drawn inside its own Application. The inline console's reader holds stdin in a prompt
    and chat has no arrow keys at all, so both keep the printed list."""
    return _CLI.get("app") is not None


def _cli_model_pick(is_global):
    """Bare `/model` on a door that can host the picker: choose a model, then switch.

    The catalog is fetched HERE, off the app's main thread, so ENTER costs nothing more
    than the switch itself. Returns True when the picker took the command over.
    """
    try:
        entries = model_catalog(force=True)
    except Exception as e:                                       # noqa: BLE001
        print(red("  could not ask the endpoints for their model list: %s" % e))
        print(dim("  fix a wrong or dead endpoint with: /tinycmdr model endpoint <url>"))
        return False
    if not entries:
        print(dim("  no models advertised by any endpoint."))
        print(dim("  check it with `/tinycmdr model endpoint`, or set one with "
                  "`/tinycmdr model endpoint <url>`"))
        return False
    current = AGENT.model_overrides.get(_cli_key()) or CONFIG["llm"]["model"]
    state = ModelPick(
        model_pick_rows(entries, current), current=current, title="Select model",
        scope=("ENTER sets the default in config.json" if is_global
               else "ENTER switches this session (%s to persist)" % "/tinycmdr model --global"))
    screen = _CLI.get("app")
    screen.open_model_pick(state, lambda name: _cli_model_apply(name, is_global))
    return True


def _cli_model_apply(name, is_global):
    """What the picker's ENTER does: exactly what a typed name does, same lines and all."""
    if not name:
        print(dim("  model unchanged"))
        return
    _cli_model(("%s --global" % name) if is_global else name)


def _switch_global_model(name):
    """Set the default model and say so the same way `model use` does (one path, two doors)."""
    prev, err = set_global_model(str(name))
    if err:
        print("could not write config.json: %s" % err, file=sys.stderr)
        return 1
    print("default model: %s -> %s" % (prev, name))
    if _verb_running() is True:
        print("a running bot reads config.json at start: use /model in chat, "
              "or run `tinycmdr restart`.")
    return 0


def _cli_model(rest, pick=False):
    tokens = (rest or "").strip().split()
    sub = tokens[0].lower() if tokens else ""
    is_global = any(t.lstrip("-").lower() in ("global", "g", "all")
                    for t in tokens if t.startswith("-"))
    force = any(t.lstrip("-").lower() in ("force", "f")
                for t in tokens if t.startswith("-"))
    clean_tokens = [t for t in tokens if not t.startswith("-")]

    current = AGENT.model_overrides.get(_cli_key()) or CONFIG["llm"]["model"]
    base_url = CONFIG["llm"]["base_url"]
    budget = AGENT._context_budget()

    # 1. Bare /model: the picker where the door can host one, else the status box
    if not tokens or (is_global and not clean_tokens):
        if pick and _cli_pick_available() and _cli_model_pick(is_global):
            return
        scope = ("session override" if _cli_key() in AGENT.model_overrides
                 else "config default")
        box = _cli_render_box("Model Status", [
            "Active:   %s (%s)" % (current, scope),
            "Endpoint: %s" % base_url,
            "Context:  ~%s tokens" % fmt_tokens(budget),
            "---",
            "Commands:",
            "  /tinycmdr model list             list available models & endpoints",
            "  /tinycmdr model <name>           switch model for this session",
            "  /tinycmdr model <name> --global  set default model in config.json",
            "  /tinycmdr model default          revert to config default",
            "  /tinycmdr model add <url>        add fallback endpoint",
            "  /tinycmdr model remove <name>    remove fallback endpoint",
        ])
        print(box)
        return

    # 2. List models
    if sub in ("list", "ls", "models"):
        try:
            entries = model_catalog(force=True)
        except Exception as e:
            print(red("  could not query endpoints: %s" % e))
            return
        if not entries:
            print(dim("  no models advertised by endpoint(s)"))
            return
        lines = []
        width = 74
        for e in entries:
            name = e.get("name") or "?"
            is_active = (name.lower() == current.lower())
            star = "* " if is_active else "  "
            tag = " (active)" if is_active else ""
            left = "%s%s%s" % (star, name, tag)
            if e.get("alias") and e.get("alias") is not True:
                right = "[alias: %s] -> %s" % (e["alias"], e.get("send_as", ""))
            elif e.get("alias") is True and e.get("send_as"):
                right = "-> %s" % e["send_as"]
            else:
                loc = " (local)" if e.get("local") else " (fallback)"
                right = "%s%s" % (e.get("url", ""), loc)
            spacing = max(2, width - 4 - len(left) - len(right))
            lines.append("%s%s%s" % (left, " " * spacing, right))
        box = _cli_render_box("Available Models (%d)" % len(entries), lines, width=width)
        print(box)
        print(dim("  Switch: /tinycmdr model <name>  (add --global to persist)"))
        return

    # 3. Default / Reset
    if sub in ("default", "reset", "off"):
        if is_global:
            prev, err = restore_global_model()
            if err:
                print(red("  could not revert globally: %s" % err))
                return
            AGENT.model_overrides.clear()
            _save_overrides()
            print(green("  reverted global model to %s (config.json)" % prev))
            return
        AGENT.model_overrides.pop(_cli_key(), None)
        _save_overrides()
        print(green("  reverted to default model: %s" % CONFIG["llm"]["model"]))
        return

    # 4. Add endpoint
    if sub in ("setup", "wizard", "new", "change"):
        # The wizard asks for an API key with the echo off, which only a shell can do.
        print(dim("  the model wizard asks for a key, so run it in a shell: "
                  "tinycmdr model setup"))
        return
    if sub == "add":
        args = tokens[1:]
        if not args:
            print(dim("  usage: /tinycmdr model add <url> [--model NAME] [--alias ALIAS] "
                      "[--key-env VAR] [--primary] [--force]"))
            print(dim("  (or run `tinycmdr model setup` in a shell to be asked)"))
            return
        opts, pos, idx = {}, [], 0
        while idx < len(args):
            a = args[idx]
            if a in ("--model", "--alias", "--key-env"):
                if idx + 1 >= len(args):
                    print(red("  %s needs a value" % a))
                    return
                opts[a[2:]] = args[idx + 1]
                idx += 2
                continue
            if a in ("--primary", "--force"):
                opts[a[2:]] = True
                idx += 1
                continue
            pos.append(a)
            idx += 1
        if not pos:
            print(red("  model add requires an endpoint url (e.g. http://<host>:8081/v1)"))
            return
        url = pos[0].strip().rstrip("/")
        if not url.lower().startswith(("http://", "https://")):
            print(red("  endpoint url must start with http:// or https://"))
            return
        try:
            raw = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
        except Exception as e:
            print(red("  could not read config.json: %s" % e))
            return
        llm = raw.setdefault("llm", {})
        fbs = llm.setdefault("fallbacks", [])
        if not isinstance(fbs, list):
            fbs = llm["fallbacks"] = []
        want_model = opts.get("model", "")
        alias = opts.get("alias", "")
        key_env = opts.get("key-env", "")
        if opts.get("primary"):
            llm["base_url"] = url
            if want_model:
                llm["model"] = want_model
            CONFIG["llm"]["base_url"] = url
            if want_model:
                CONFIG["llm"]["model"] = want_model
            line = "primary endpoint set to %s" % url
        else:
            entry = {"base_url": url, "model": want_model or "main"}
            if alias:
                entry["alias"] = alias
            if key_env:
                entry["api_key_env"] = key_env
            fbs.append(entry)
            CONFIG["llm"]["fallbacks"] = fbs
            line = "added fallback endpoint %s -> %s" % (url, want_model or "(default)")
        try:
            _write_config(raw)
        except Exception as e:
            print(red("  could not write config.json: %s" % e))
            return
        _MODEL_CACHE["at"] = 0.0
        print(green("  ✓ %s" % line))
        return

    # 4b. The endpoint itself: read it, or correct a typo in it, then pick from what it
    # advertises. This is where a wrong URL from install time gets fixed.
    if sub in ("endpoint", "url", "host"):
        urls = [t for t in clean_tokens[1:] if t]
        if not urls:
            for line in endpoint_report():
                print("  " + line)
            return
        rc, ids, lines = set_primary_endpoint(urls[0], force)
        for line in lines:
            print(red("  " + line) if rc else "  " + line)
        if rc == 0 and ids and _cli_pick_available():
            state = ModelPick(
                [(i, "advertised by %s" % urls[0], False) for i in ids],
                title="Which model does %s serve? (%d advertised)" % (urls[0], len(ids)),
                scope="ENTER saves it to config.json")
            _CLI["app"].open_model_pick(state, lambda name: _cli_model_apply(name, True))
        elif rc == 0 and ids:
            print(dim("  choose one with `/tinycmdr model <name> --global`"))
        return

    # 5. Remove endpoint
    if sub in ("remove", "rm"):
        args = clean_tokens[1:]
        if not args:
            print(dim("  usage: /tinycmdr model remove <name|alias|url>"))
            return
        target = args[0].strip().lower()
        try:
            raw = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
        except Exception as e:
            print(red("  could not read config.json: %s" % e))
            return
        llm = raw.setdefault("llm", {})
        fbs = llm.get("fallbacks") or []
        keep, removed = [], None
        for fb in fbs:
            if not isinstance(fb, dict):
                keep.append(fb)
                continue
            matches = [str(fb.get(k) or "").strip().rstrip("/").lower()
                       for k in ("base_url", "model", "alias")]
            if removed is None and target in matches:
                removed = fb
                continue
            keep.append(fb)
        if removed is None:
            print(red("  no fallback endpoint matches %r" % target))
            return
        llm["fallbacks"] = keep
        CONFIG["llm"]["fallbacks"] = keep
        try:
            _write_config(raw)
        except Exception as e:
            print(red("  could not read config.json: %s" % e))
            return
        _MODEL_CACHE["at"] = 0.0
        print(green("  ✓ removed fallback %s -> %s" % (removed.get("base_url"), removed.get("model"))))
        return

    # 6. Switch model: /model <name>
    name = " ".join(clean_tokens).strip()
    e = model_entry(name)
    if not e:
        if force:
            target = name
            CONFIG["llm"]["model"] = target
            AGENT.model_overrides[_cli_key()] = target
            print(amber("  ⚠ forced model to %s (unverified)" % target))
            return
        cat = model_catalog()
        if not _MODEL_CACHE.get("live"):
            # Test or offline mock: allow switch
            CONFIG["llm"]["model"] = name
            AGENT.model_overrides[_cli_key()] = name
            print(dim("  endpoint did not advertise models; model set to %s (unverified)" % name))
            return
        print(red("  unknown model: %r" % name))
        known = [x.get("name") for x in cat if x.get("name")]
        if known:
            print("  available models: %s" % ", ".join(known[:12]))
            print(dim("  run `/tinycmdr model list` to view all endpoints, or append --force"))
        return

    target = e["name"]
    if is_global:
        prev, err = set_global_model(target)
        if err:
            print(red("  could not switch globally: %s" % err))
            return
        AGENT.model_overrides.clear()
        _save_overrides()
        print(green("  ✓ global model switched to %s (was %s) -> saved to config.json" % (target, prev)))
        return

    AGENT.model_overrides[_cli_key()] = target
    CONFIG["llm"]["model"] = target
    _save_overrides()
    where = (" at %s" % e["url"]) if e.get("url") else ""
    print(green("  ✓ model is now %s%s (this session)" % (target, where)))


def _cli_command(text):
    """Handle one /verb. True = keep the loop, False = quit."""
    text = cmdr_strip(text)          # `/tinycmdr model` is `/model`, handled below
    verb, _, rest = text.partition(" ")
    verb = verb.lower()
    rest = rest.strip()
    if verb == "/stop":
        print(dim("  nothing is running"))
        return True
    if verb in ("/exit", "/quit", "/bye"):
        return False
    if verb in ("/help", "/?"):
        print(HELP_TEXT)
        return True
    if verb in ("/new", "/reset"):
        AGENT.reset(_cli_key())
        print(green("  (context cleared, this machine's notes stay)"))
        return True
    if verb == "/setup":
        run_setup()
        return True
    if verb == "/model":
        _cli_model(rest, pick=True)
        return True
    if verb in ("/sessions", "/conversations"):
        _cli_sessions()
        return True
    if verb == "/resume":
        _cli_resume(rest)
        return True
    if verb == "/status":
        u = AGENT.last_usage.get(_cli_key()) or {}
        s = AGENT.stats(_cli_key())
        budget = AGENT._context_budget()
        notes = 0
        if NOTES_FILE.exists():
            # stat(), not read_text(): this line reports a SIZE, and the read path is the
            # one the prompt builder insists must stay a read (the whole file was pulled
            # into memory to print a number another site already gets from st_size).
            notes = NOTES_FILE.stat().st_size
        concepts = len(memory_scan())
        index_chars = (len(MEMORY_INDEX.read_text(encoding="utf-8", errors="replace"))
                       if MEMORY_INDEX.exists() else 0)
        print("  version    %s" % VERSION)
        print("  model      %s" % CONFIG["llm"]["model"])
        print("  endpoint   %s" % CONFIG["llm"]["base_url"])
        print("  python     %s" % platform.python_version())
        print("  folder     %s" % BASE_DIR)
        print("  context    ~%s of %s (%d%%), %d exchange(s) this session"
              % (fmt_tokens(s["est_tokens"]), fmt_tokens(budget),
                 100 * s["est_tokens"] // max(1, budget), s["exchanges"]))
        print("  last run   %s" % (fmt_usage(u) if u.get("calls") else "nothing yet"))
        print("  session    %s (%d exchange(s))" % (_cli_key(), s["exchanges"]))
        print("  notes      %d bytes in notes.md (legacy)" % notes)
        print("  memory     %d concept%s, index %d chars"
              % (concepts, "" if concepts == 1 else "s", index_chars))
        print("  skills     %d runbooks" % len(skill_index()))
        print("  tools      %d" % len(REGISTRY.openai_schemas()))
        # The banner keeps three rows; this is where its folded arithmetic lives
        # envelope_facts() is the same source, so the short and the
        # long form cannot disagree.
        f = envelope_facts()
        print("  envelope   %s" % f["envelope"])
        print("  prompt     %s" % f["overhead"])
        strays = strays_in_config()
        if strays:
            print("  ignored    %s (in config.json, never sent)" % ", ".join(strays))
        return True
    if verb == "/memory":
        _cli_memory()
        return True
    if verb in ("/skills", "/skill"):
        sk = skill_index()
        if not sk:
            print(dim("  no runbooks in ./skills"))
        for s in sk:
            print("  %-34s %s%s" % (s.get("name", "?"), (s.get("desc") or "")[:90],
                                    "  [operator-only]"
                                    if s.get("hide") else ""))
        return True
    if verb == "/tools":
        for sch in REGISTRY.openai_schemas():
            fn = sch.get("function") or {}
            print("  %-18s %s" % (fn.get("name", "?"), (fn.get("description") or "")[:88]))
        return True
    if verb == "/usage":
        _cli_usage_line(force=True)
        return True
    # A MANAGEMENT verb the session cannot run still has an answer: say which door has it.
    # Measured 2026-09-30: /update typed in a session got "not a command - /tinycmdr help lists them", where the list has no
    # update verb in it. `update` is the one that arrives as "how do I update?", so it names
    # both steps.
    bare = verb.lstrip("/")
    if bare == "update":
        # The rule: `/update` works here, from any version. It runs the same verb the shell
        # does - fetch the published release, verify it, apply it, leave host-owned files
        # alone - and says how this session gets the new bytes (a terminal session is
        # relaunched; the service is restarted with `tinycmdr restart`).
        print(dim("  updating from the published release..."))
        try:
            run_verb(["update"])
        except SystemExit as e:
            return bool(e.code)
        print(dim("  this session still runs the OLD bytes: relaunch it, or "
                  "`tinycmdr restart` for the service"))
        return True
    if bare == "restart":
        print(dim("  `restart` runs in a shell on the host: `tinycmdr restart`"))
        return True
    if bare in VERBS:
        print(dim("  `%s` is a shell verb on this host: run `tinycmdr %s` there, "
                  "or `%s%s` from chat." % (bare, bare, CMDR, bare)))
        return True
    print(dim("  %s is not a command - %s help lists them" % (verb, CMDR)))
    return True


FAST_VERBS = ("/stop", "/help", "/?", "/usage", "/exit", "/quit", "/bye",
              "/sessions", "/conversations")


def _cli_while_running(line):
    """Handle one line that arrived WHILE the agent is mid-turn.

    True means it was dealt with here: /stop and the read-only verbs. False means
    it has to wait for the main loop, because a run reads the session history and
    the model id at its start, not during it, so /new and /model cannot mean
    anything until the run that is in flight has finished.

    This runs on the reader thread, so it only prints, sets the stop event, or
    reads state. The run owns the history, the log and the tools.
    """
    line = cmdr_strip(line)          # `/tinycmdr stop` has to work mid-run too
    verb = line.split()[0].lower()
    if verb == "/stop":
        ev = _CLI.get("stop")
        if ev is not None:
            ev.set()
            print(red("\n  (stopping - the call in flight is being closed)"))
        else:
            print(dim("\n  (nothing is running)"))
        return True
    if verb in ("/exit", "/quit", "/bye"):
        ev = _CLI.get("stop")
        if ev is not None:
            ev.set()
        _CLI["leave"] = True
        print(red("\n  (stopping this run, then quitting)"))
        return True
    if verb in ("/help", "/?"):
        print(HELP_TEXT)
        return True
    if verb == "/usage":
        _cli_usage_line(force=True)
        return True
    if verb in ("/sessions", "/conversations"):
        _cli_sessions()
        return True
    return False


# ------------------------------------------------------- questions at a prompt
# One owner of stdin, for questions too (operator, 2026-09-22: "the cli version ...
# asks the user for an answer ask_user and the cmd window freezes and doesnt accept
# any input at all"). `_cli_reader` owns the terminal for the whole interactive
# session, so a question must NOT read it: the reader was already blocked in
# readline(), took the typed line, filed it as steering, and the run waited for an
# answer that had already been swallowed. The line comes back through `_CLI["ask"]`.

CLI_ASK_WAIT = 120.0        # a terminal question nobody answers gives up here


def cli_question_open(row=None):
    """Publish an open question: the reader's next plain line is the ANSWER.

    `row` is ask_user's row (the parked run waits on its event); a yes/no at the
    prompt has none and is collected from the box's own queue.
    """
    box = {"q": queue.Queue(), "row": row}
    _CLI["ask"] = box
    return box


def cli_question_answer(line):
    """Hand a typed line to whoever is waiting on the open question. True = taken."""
    box = _CLI.get("ask")
    if not box:
        return False
    row = box.get("row")
    if row is not None:
        # The row releases the parked run; the queue is filled too, so one wait
        # shape serves both a question with a row and a bare yes/no.
        row["answer"] = line
        row["ev"].set()
    box["q"].put(line)
    return True


def cli_question_wait(box, wait=None):
    """Block for the answer the reader will hand over. None = nobody answered."""
    try:
        return box["q"].get(timeout=float(wait)) if wait else box["q"].get()
    except queue.Empty:
        return None
    finally:
        if _CLI.get("ask") is box:
            _CLI["ask"] = None


def cli_ask_print(question, options=None, out=None, colour=True):
    """The question and its prompt, printed. Drawing only: who WAITS for the line
    depends on the shape - cli_ask_line for a yes/no at the prompt, ask_user's row
    for a question whose answer releases a parked run."""
    out = out or sys.stdout
    text = " ".join(str(question or "").split())
    say = (lambda s: print(amber(s), file=out)) if colour else (lambda s: print(s, file=out))
    say("  " + text)
    if options:
        say("  reply " + " / ".join(str(o) for o in options))
    print(green("  > ") if colour else "  > ", end="", flush=True)


def cli_ask_line(question, options=None, wait=None, out=None, colour=True):
    """Ask at the prompt and return the line the operator typed.

    With a reader thread running (the interactive console) the answer comes back
    through it, never from a second read of the terminal. With no reader thread (a
    one-shot `--once`, a closed pipe) this thread is the only reader, so it reads the
    line itself - and an unanswerable question returns None instead of hanging.
    """
    cli_ask_print(question, options, out=out, colour=colour)
    if not _CLI.get("reader"):
        try:
            raw = sys.stdin.readline()
        except (EOFError, KeyboardInterrupt):
            print(file=(out or sys.stdout))
            return None
        return None if raw == "" else raw.rstrip("\r\n")
    try:
        return cli_question_wait(cli_question_open(), wait if wait else CLI_ASK_WAIT)
    except (EOFError, KeyboardInterrupt):
        print(file=(out or sys.stdout))
        return None


def _cli_handle_line(line):
    """One line of operator input, routed: an answer if a question is open, a steer
    or a verb if a run is in flight, an inbox turn otherwise.

    The ONE router. `_cli_reader` calls it with each line read from stdin, and the
    `--app` input box calls it with each submitted line, so the two doors cannot
    disagree about where a typed line goes.
    """
    if _CLI.get("stop") is not None:
        if _CLI.get("ask") is not None:
            # A question is open: the next plain line is the ANSWER. A command
            # still acts (/stop, /exit, /help), and /stop releases the wait with
            # nothing, which every door reads as "declined, do not guess".
            if line.startswith("/"):
                if _cli_while_running(line):
                    # The command was answered, not the question. A yes/no at
                    # the prompt has no run to cancel, so release it (nothing
                    # reads as "declined"); a question with a row is released
                    # by ask_operator's own /stop check.
                    if (_CLI.get("ask") or {}).get("row") is None:
                        cli_question_answer(None)
                else:
                    _CLI["inbox"].put(line)
                return
            cli_question_answer(line)
            return
        if _cli_while_running(line):
            return
        if line.startswith("/"):
            _CLI["inbox"].put(line)         # a state-changing verb waits its turn
            print(dim("\n  (that verb runs when this turn ends)"))
            return
        _CLI["steer"].put(line)             # a request, handed in at the boundary
        print(dim("\n  (sending that in when this turn ends - %s stop cancels "
                   "the run)" % CMDR))
        return
    _CLI["inbox"].put(line)


def _cli_reader():
    """The one reader for stdin. Every line lands in the inbox.

    One reader, not two: a prompt reading stdin itself while a run is in flight
    would lose whatever was typed at the wrong moment, which is the bug this
    exists to fix. A run in flight is _CLI["stop"] being set.
    """
    session = _tui_session()
    while True:
        line = None
        if session is not None and _CLI.get("stop") is None:
            # Idle: prompt_toolkit reads the line (editing, history, the status line
            # under it). Mid-run the reads stay plain on purpose - the run's own
            # questions answer through stdin too, and two owners of a terminal in raw
            # mode is how a typed answer lands in the wrong place.
            try:
                line = session.prompt(_tui_prompt_text()).strip()
            except KeyboardInterrupt:        # Ctrl-C at the prompt: what SIGINT does
                _cli_sigint(None, None)
                continue
            except EOFError:                 # Ctrl-D
                _CLI["inbox"].put(None)
                return
            except Exception:
                session = None               # prompt_toolkit gave up: plain lines
        if line is None:
            raw = sys.stdin.readline()
            if raw == "":                    # EOF: Ctrl-D, /exit, or a closed pipe
                _CLI["inbox"].put(None)
                return
            line = raw.rstrip("\r\n").strip()
        if not line:
            continue
        _cli_handle_line(line)


def _cli_startup(app_mode, once=False):
    """What a console says before its first request.

    The app's chrome already carries the meta - the rail has the session, the model
    and the context gauge, the status bar has the idle hint - so the transcript is
    left EMPTY and opens on the first exchange. Inline (and the plain path) keep the
    banner, the note and the capability line, because there is no chrome to hold them
    """
    if app_mode and not once:
        screen = tui_screen()
        if screen is not None:
            screen.status = "ready \u00b7 type a request \u00b7 /help lists the commands"
        return
    if not once:
        cli_banner()
        print(dim("  type at any time: a line is sent in at the next step, "
                  "%s stop cancels the run,\n  Ctrl-C does the same. Nothing you "
                  "type is lost while it works.\n" % CMDR))
    print(dim(capability_line("cli")))


def _resolve_colour():
    """Always, never or auto - from `--color`, then TINYCMDR_COLOR, then NO_COLOR, then the
    `color_coded` switch and a tty check (the designer's resolution order, 2026-10-03).

    TINYCMDR_COLOR carries two jobs: `always`/`never`/`auto` say whether to paint at all,
    and a tier name (`truecolor`, `256`, `16`, `none`) still forces which palette tier to
    use - the tests and screenshots depend on that, and `never` outranks it.
    """
    def flag():
        argv = sys.argv[1:]
        for i, arg in enumerate(argv):
            if arg == "--color" and i + 1 < len(argv):
                return argv[i + 1].strip().lower()
            if arg.startswith("--color="):
                return arg.split("=", 1)[1].strip().lower()
        return ""
    want = flag() or (os.environ.get("TINYCMDR_COLOR") or "").strip().lower()
    if want == "always":
        return True
    if want == "never":
        return False
    if os.environ.get("NO_COLOR") is not None:
        return False
    if not bool(CONFIG["agent"].get("color_coded", True)):
        return False
    return bool(_ansi_enable())


def run_cli(once=None, app=False):
    global CONFIG
    _console_utf8()
    # The conversation this launch opens in: a fresh one, unless --continue/--session (or
    # TINYCMDR_SESSION) says otherwise. Set BEFORE anything reads _cli_key() - the banner,
    # the rail and the reporter all name the session.
    _CLI["session"] = _cli_startup_session(sys.argv[1:])
    _CLI["colour"] = _resolve_colour()
    # `--app` takes the terminal over: it draws its own banner in its own pane, so
    # dispatch before anything prints. A terminal that cannot host it falls back to
    # the inline cards with one dim note, never an error (drawn below, in order).
    if app and not once:
        if app_wanted():
            return _run_cli_app()
        print(dim("  --app needs a real terminal with prompt_toolkit; "
                  "drawing inline cards instead"))

    def narration(txt):
        """interim_cb: the prose that arrived WITH tool calls, nothing streamed."""
        line = " ".join(str(txt).split())
        if line:
            print(green("  %s" % line[:400]))

    def narration_stream(txt, final=False, first=False):
        """narration_cb: what the model is saying, as it says it.

        The callback hands over everything written so far, not the delta, up to
        twice a second, so only the new tail is printed. What it prints may turn
        out to be the final answer: narration_drop() then remembers the text and
        the answer is not printed a second time when the run returns.
        """
        text = str(txt or "")
        if first:
            _CLI["stream"] = ""
        shown = _CLI.get("stream") or ""
        if not text.startswith(shown):
            shown = ""                  # the model rewrote its line: start again
        fresh = text[len(shown):]
        if fresh:
            print(green("  " + fresh) if not shown else green(fresh),
                  end="", flush=True)
            _CLI["stream"] = text
        if final:
            print()
            _CLI["streamed"] = text

    def narration_drop():
        """That streamed text WAS the answer, which is printed once, below."""
        _CLI["streamed_answer"] = _CLI.get("streamed") or ""

    def progress(name, args):
        if name == "generating":
            return                      # the stream's own status, not a tool call
        short = args if isinstance(args, str) else json.dumps(args)
        print(amber("  -> %s %s" % (name, short.replace(chr(10), " ")[:160])))

    def progress_done(name, args, output, elapsed):
        if not output:
            return
        first = " ".join(str(output).split())[:120]
        print(dim("     %s in %.1fs: %s" % (name, elapsed or 0.0, first)))

    def say(text):
        """A line from the harness itself (not the model): a run that continued past its
        budget, for instance. The console has no chat to post into, so it prints -
        through the screen when there is one, or the line lands on top of the
        toolbar."""
        try:
            cli_out(amber("  %s" % text))
        except Exception:
            pass

    _CLI["inbox"] = queue.Queue()
    _CLI["steer"] = queue.Queue()
    _CLI["leave"] = False
    # `--once` starts no reader: there is nobody to steer, and a question then reads
    # stdin itself, which is the only safe shape while the run IS the reader.
    # `--app` starts none either: its input box is the reader (AppScreen._submit).
    _CLI["reader"] = not once
    if not once and _CLI.get("app") is None:
        threading.Thread(target=_cli_reader, daemon=True).start()

    _cli_startup(_CLI.get("app") is not None, once=bool(once))
    # reported for BOTH entry points. It used to live in cli_banner(), which a
    # one-shot run never reaches, so `--once` - the CLI's most common entry -
    # said nothing about what it could enforce.
    if once:
        try:
            _tty = bool(sys.stdin.isatty())
        except Exception:                                        # noqa: BLE001
            _tty = False
        reporter = _cli_new_reporter(has_human=_tty)
        # A piped stdin has nobody who can type an answer: mounting the console door
        # parked a question the full 120s wait and then stopped the run (a Windows install,
        # 2026-10-03, driven over ssh with the script piped in). No door = ask_user
        # refuses at once and states the assumption, per the documented rule.
        answer = drive_run(_cli_key(), once, reporter,
                           ask_door=(reporter.dest if _tty else None))
        screen = tui_screen()
        if screen is not None:
            # The same answer card the interactive lane draws. `--once` used to print
            # the raw markdown under a dim rule, so a one-shot run showed the answer's
            # pipes and headings where the session showed a rendered card (measured on
            # a pty, 2026-09-30). The plain path is unchanged: no screen, no card.
            _draw_answer(screen, once, answer)
        else:
            print(answer_block(answer))
        _cli_usage_line()
        return
    return _cli_console_loop()


REPLY_REF_CHARS = 100


def _reply_ref(text, ellipsis="..."):
    """The question, as the one dim line an answer card is a reply to.

    In `--app` (and `--once`) the request is NOT in the transcript: the composer clears
    when it sends, and a one-shot prompt never was on screen - so the one thing a reader
    needs in order to read the answer as an answer ("what did I ask?") was the one thing
    missing, while every chat client quotes the message it replies to. Flattened to one
    line and capped, because a pasted page of a question must not push the answer off the
    pane: an app pane does not wrap it, it would simply be cut mid-word with no marker.
    """
    flat = re.sub(r"\s+", " ", str(text or "")).strip()
    if not flat:
        return ""
    if len(flat) > REPLY_REF_CHARS:
        flat = flat[:REPLY_REF_CHARS].rstrip() + ellipsis
    return "re: " + flat


def _draw_answer(screen, question, answer):
    """The answer card, preceded by the question it answers (see _reply_ref).

    The console lanes are the only place this is needed: in chat the question is the
    message the post replies to, and at the inline `you>` prompt it is still on screen
    above the card. Both call sites below are console lanes.
    """
    screen.answer_card(_reply_ref(question, screen.ellipsis), answer)


def _cli_new_reporter(has_human=True):
    """One per run: the check-in cadence and the done line are per run.

    Its destination is also the run's ask door, so a question reaches the terminal
    the way a chat question reaches its channel. The confirm prompt used to be a
    second implementation here that read stdin directly and was never called
    (`confirm_cb` is `reporter.confirm`, which goes through dest.ask) - one door,
    one reader.

    `has_human=False` (a `--once` run with a piped stdin: cron, `ssh host --once`)
    means nobody can type an answer, so the caller mounts no ask door and a
    confirm-pattern command takes the doorless default instead of waiting on a
    stdin that is a script.
    """
    return RunReporter(
        CliDestination(colour=bool(_CLI["colour"]), out=sys.stdout,
                       screen=tui_screen(), has_human=has_human,
                       on_drop=lambda t: _CLI.__setitem__("streamed_answer", t)),
        _cli_key())


def _cli_steer_queue():
    """Requests typed while the agent is working, handed in at the boundary.

    The same contract as a mid-run correction from chat: it arrives with the next
    turn, and the agent is told it overrides what it was doing.
    """
    out = []
    while True:
        try:
            out.append(("you", _CLI["steer"].get_nowait()))
        except queue.Empty:
            return out


def _cli_console_loop():
    """The console's one loop: read a line, run it, draw the answer.

    Shared by the inline console and `--app` (which runs it in a worker thread
    because prompt_toolkit must own the main thread's terminal).
    """
    while True:
        if _CLI["leave"]:
            return
        if _CLI.get("app") is None and _tui_session() is None:
            # with a session prompt_toolkit draws the prompt; with the app its input
            # box is the prompt. Neither wants one printed into the transcript.
            print(prompt("you> "), end="", flush=True)
        try:
            text = _CLI["inbox"].get()
        except KeyboardInterrupt:
            print()
            return
        if text is None:                    # stdin closed: Ctrl-D
            print()
            return
        text = text.strip()
        if not text:
            continue
        if text.startswith("/"):
            if not _cli_command(text):
                return
            continue
        if text.lower() in ("reset", "exit", "quit"):
            if text.lower() == "reset":
                AGENT.reset(_cli_key())
                print(green("  (context cleared)"))
                continue
            return
        cancel = threading.Event()
        _CLI["stop"] = cancel
        _CLI["streamed_answer"] = ""     # set by the destination when a draft goes
        answer = ""
        failed = False
        reporter = _cli_new_reporter()
        try:
            try:
                answer = drive_run(_cli_key(), text, reporter, cancel_event=cancel,
                                   steer_cb=_cli_steer_queue, ask_door=reporter.dest)
            except KeyboardInterrupt:
                cancel.set()
                cli_out(red("\n  (stopped)"))
            except OperatorStop as e:
                failed = True
                cli_out(red("\n  (stopped: %s)" % e))
            except Exception as e:
                failed = True
                cli_out(red("\n  run failed: %s: %s" % (type(e).__name__, e)))
            reporter.finish(ok=not failed)
            while not _CLI["steer"].empty():    # typed too late for that run
                _CLI["inbox"].put(_CLI["steer"].get())
            if _CLI["leave"]:
                return
            if answer:
                screen = tui_screen()
                if screen is not None:
                    # The WHOLE answer, once, as the one bright card - always. The dim
                    # draft above it is narration a screen cannot take back, and
                    # prefix-matching that whitespace-collapsed, 400-char-capped draft
                    # is what rendered the answer three times. The
                    # streamed_answer note is the plain path's business only.
                    _draw_answer(screen, text, answer)
                else:
                    shown = (_CLI.pop("streamed_answer", "") or "").strip()
                    body = answer
                    if shown and answer.startswith(shown):
                        body = answer[len(shown):]  # only after the streamed text
                    elif shown and shown.startswith(answer.strip()):
                        body = ""                   # already on screen in full
                    if body.strip():
                        print(answer_block(body))
            _cli_usage_line()
            print()
        finally:
            # The run is over only once its card is on screen. This flag is what the
            # reader thread gates `session.prompt()` on, so clearing it earlier let the
            # prompt paint `you> ` BETWEEN the draft pulse and the answer card.
            # Reproduced in both turns.
            _CLI["stop"] = None


def _cli_app_worker():
    """The console loop for `--app`, off the main thread.

    The app owns the terminal and the event loop; this thread owns the runs. When
    the loop returns (a /exit, a closed input) the app is told to leave.
    """
    try:
        run_cli()
    except Exception:
        log.exception("app console loop failed")
    finally:
        screen = _CLI.get("app")
        if screen is not None:
            screen.request_exit()


def _run_cli_app():
    """`--app`: the same console in an alternate-screen app.

    THIS function opens nothing: prompt_toolkit owns the terminal. The page lane,
    when enabled, is started by main() before the session begins, and the app never
    binds it. stdout is swapped for the duration so every plain print the
    console makes (the banner, /help, /status) becomes a transcript line instead of
    painting over the alternate screen.
    """
    screen = AppScreen(colour=bool(_CLI["colour"]))
    _CLI["app"] = screen
    _CLI["screen"] = screen
    # One writer per terminal. Installing the screen HERE (rather than letting
    # tui_screen() build it) skipped the detach tui_screen() does, so every INFO
    # record kept going to the console and painted over the alternate screen - seen
    # in a live screenshot of `--app` on 2026-09-30, where the log lines landed in
    # the middle of the frame.
    log_console_off()
    _CLI["inbox"] = queue.Queue()
    _CLI["steer"] = queue.Queue()
    _CLI["leave"] = False
    _CLI["reader"] = False
    _CLI["stop"] = None
    real_stdout = sys.stdout
    sys.stdout = _AppStdout(screen, real_stdout)
    worker = threading.Thread(target=_cli_app_worker, daemon=True,
                              name="tinycmdr-app-console")

    def _terminated(signum, frame):
        """SIGTERM/SIGHUP: leave the app the way Ctrl-Q does.

        A kill mid-event-loop used to end the process with the alternate screen still
        active, so the terminal was left inside the app's frame with no way back.
        request_exit() is the same one ask every other exit uses, so prompt_toolkit
        runs its own teardown (smcup/rmcup) and the last answer is still reprinted.
        """
        log.warning("app: signal %s - leaving", signum)
        screen.request_exit()

    saved_signals = {}
    for _name in ("SIGTERM", "SIGHUP"):
        _sig = getattr(signal, _name, None)
        if _sig is None:                      # Windows has neither
            continue
        try:
            saved_signals[_sig] = signal.signal(_sig, _terminated)
        except (ValueError, OSError, RuntimeError):
            pass                              # not the main thread, or refused

    try:
        worker.start()
        try:
            screen.run()                # returns on /exit, ESC, Ctrl-Q or Ctrl-D
        except Exception:
            # A failure that came out of Application.run() itself: prompt_toolkit's
            # inner finally has already restored the alternate screen (its teardown
            # is in a finally and is not skippable), so this reports on the real
            # stream below, with the last answer.
            log.exception("app screen failed")
            screen.note_crash("".join(traceback.format_exception(*sys.exc_info())))
    finally:
        sys.stdout = real_stdout
        _CLI["leave"] = True
        try:
            _CLI["inbox"].put(None)
        except Exception:
            pass
        worker.join(timeout=5)
        _CLI["app"] = None
        _CLI["screen"] = None
        for _sig, _prev in saved_signals.items():
            try:
                signal.signal(_sig, _prev)
            except (ValueError, OSError, RuntimeError):
                pass
        # The alternate screen is gone (smcup/rmcup restored the terminal): put the
        # session's last answer back in the scrollback so nothing is lost on exit.
        # In the finally, so the crash paths get the reprint too - after the block, a
        # failure past screen.run() lost the answer.
        screen.print_final_inline()
    crash = screen.take_crash()
    if crash:
        # On the REAL stream: while the app is up, stdout is _AppStdout, so a report
        # printed then landed in the pane - invisible, and the reason a crash used to
        # leave the terminal sitting in the app's frame.
        print(crash, file=sys.stderr, flush=True)
        raise SystemExit(1)


def _cli_sigint(signum, frame):
    """First Ctrl-C asks the run to stop; a second one gets out of the way."""
    ev = _CLI.get("stop")
    if ev is not None and not ev.is_set():
        ev.set()
        print(red("\n  (stopping - the call in flight is being closed)"))
        return
    raise KeyboardInterrupt
















def _note_restart(channel_id, root_id, by):
    """Record that a restart was asked for, so the NEW process can say it is
    back in the channel that asked.

    A channel-less restart (CLI) must NOT stomp a notice already
    queued for a real channel — otherwise the chat only ever hears
    'restarting…'.
    """
    def mut(st):
        prev = st.get("announce_restart") or {}
        if channel_id:
            chan, root = channel_id, (root_id or "")
        else:
            chan, root = prev.get("channel_id"), prev.get("root_id", "")
        st["announce_restart"] = {"channel_id": chan, "root_id": root,
                                  "by": by or "operator", "at": time.time()}
    try:
        _state(mut)
    except Exception as e:
        log.warning("could not record the restart notice: %s", e)


def announce_startup(dispatcher):
    """Say 'back up' after a restart. Without this the only thing a channel ever
    hears is 'restarting…' — it never learns the bot returned."""
    try:
        st = _state()
    except Exception as e:
        log.warning("startup announce: unreadable state: %s", e)
        return
    note = st.get("announce_restart") or {}
    if not note:
        return
    try:
        _state(lambda s: s.pop("announce_restart", None))   # one-shot
    except Exception:
        pass
    cid = note.get("channel_id")
    if not cid:
        log.info("restart notice had no channel (web/CLI restart) — nothing to "
                 "post")
        return
    downtime = int(time.time() - float(note.get("at") or time.time()))
    text = (f"✅ **Back up** — tinycmdr v{VERSION}, listening again "
            f"({downtime}s after {note.get('by', 'operator')} asked).")
    for attempt in (1, 2, 3):
        if dispatcher._post(cid, note.get("root_id") or None, text):
            log.info("posted startup notice to %s (downtime %ds)", cid, downtime)
            return
        log.warning("startup notice attempt %d failed", attempt)
        time.sleep(2)
    log.error("could not post the startup notice to %s", cid)


def restart_owner():
    """Who is going to start this process again?

    /restart used to ALWAYS spawn a detached copy of itself. That is only correct
    when nothing else would start the bot: it puts a second process on disk while
    the first is still alive, and the instance lock decides which one survives.
    On a supervised host that race cost real time (the supervisor's child lost
    the lock, logged "bot exited 3 (lock held elsewhere)" and backed off 300 s);
    under systemd it produced two instances fighting over the web port. So ask
    who the owner is instead:

      systemd     INVOCATION_ID is set by systemd on every unit start, and the
                  unit ships with Restart=always, so exiting is enough
      supervisor  the Windows keep-alive sets TINYCMDR_SUPERVISED=1 in the
                  child's environment and relaunches on RESTART_EXIT_CODE
      launchd     macOS launchd sets XPC_SERVICE_NAME (com.tinycmdr.agent), and
                  its KeepAlive.SuccessfulExit=false relaunches on exit 75
      self        started by hand, or by a logon task with no supervisor:
                  nothing would start it again, so spawn a detached replacement
    """
    if os.environ.get("INVOCATION_ID"):
        return "systemd"
    if os.environ.get("TINYCMDR_SUPERVISED") == "1":
        return "supervisor"
    # Measured 2026-09-26 on macOS 27/arm64 with throwaway launchd labels: a process that
    # IS the job's process (ProgramArguments = [python, tinycmdr.py], exactly the installer's
    # plist) sees XPC_SERVICE_NAME=<label>, while a hand-run python sees "0". So the label
    # test IS the launchd test, and the old `or sys.platform == "darwin"` catch-all
    # misclassified every hand-started mac bot (Terminal, launch-tight... launch-tinycmdr.sh):
    # /restart then released the lock and exited 75, launchd was never there to relaunch it,
    # and the bot stayed DEAD (a suite). Linux/Windows keep the spawn path.
    if "com.tinycmdr" in os.environ.get("XPC_SERVICE_NAME", ""):
        return "launchd"
    return "self"


def _env_file_keys():
    """Names defined in .env, so a child can be made to re-read the file."""
    keys = set()
    try:
        for line in ENV_FILE.read_text(encoding="utf-8-sig").splitlines():
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                keys.add(line.split("=", 1)[0].strip())
    except OSError:
        pass
    return keys


def _env_file_value(name):
    """The value of NAME in .env, or "" - how a verb sees a key `token set` wrote but
    this process never inherited (a fresh CLI is not the service's environment)."""
    try:
        for line in ENV_FILE.read_text(encoding="utf-8-sig").splitlines():
            line = line.strip()
            if line.startswith(name + "="):
                return line.split("=", 1)[1].strip()
    except OSError:
        pass
    return ""


def _endpoint_key(name):
    """A key from the environment or from .env, whichever has it. Never printed."""
    name = str(name or "").strip()
    if not name:
        return None
    return os.environ.get(name) or _env_file_value(name) or None


def _spawn_replacement():
    """Start a fresh instance, detached, then the caller exits.

    os.execv (the previous approach) is fatal under the console-free pythonw
    launch: the replacement dies before it can even open the log, so a /restart
    left the bot dead. Spawning a detached process is deterministic.

    The child inherits this environment, and _load_env_file never overwrites an
    inherited value ("real env wins"), so a token the operator just changed in
    .env would be masked by our stale copy: /restart would look like it ignored
    the edit. Strip the keys .env owns and let the child read the file itself.
    """
    args = [sys.executable, str(BASE_DIR / "tinycmdr.py")]
    env = dict(os.environ)
    for k in _env_file_keys():
        env.pop(k, None)
    flags = 0
    if os.name == "nt":
        flags = (getattr(subprocess, "DETACHED_PROCESS", 0x00000008)
                 | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0x00000200))
    subprocess.Popen(args, cwd=str(BASE_DIR), close_fds=True, env=env,
                     creationflags=flags, stdin=subprocess.DEVNULL,
                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    log.info("replacement process started: %s", " ".join(args))


RESTART_MARKER_FILE = BASE_DIR / "logs" / "restart-requested.json"


def _write_restart_marker(by):
    """`logs/restart-requested.json`: this exit 75 was ASKED FOR.

    A handover (/restart) and a restart the bot decided on itself both leave as
    RESTART_EXIT_CODE, and the supervisor cannot tell them apart - so its
    stop-the-loop ladder cannot see a restart loop the bot began on its own
    (measured 2026-10-07). This file is the difference: written only on a
    handover, read and consumed once by the supervisor, and never written by the
    watchdog paths.
    """
    try:
        RESTART_MARKER_FILE.parent.mkdir(exist_ok=True)
        atomic_write_text(RESTART_MARKER_FILE,
                          json.dumps({"at": int(time.time()), "by": str(by or "operator")}))
    except Exception as e:                                   # noqa: BLE001
        log.debug("restart marker not written: %s", e)


def perform_restart(channel_id=None, root_id=None, by="operator"):
    """Restart the bot, whoever owns its lifecycle. Does not return."""
    owner = restart_owner()
    _note_restart(channel_id, root_id, by)
    log.info("restarting (requested by %s; %s starts it again)", by, owner)
    time.sleep(1.0)          # let the reply post / the HTTP response flush
    time.sleep(0.5)          # let the log queue drain
    _release_lock()
    if owner == "self":
        try:
            _spawn_replacement()
        except Exception as e:
            log.exception("could not start the replacement process: %s", e)
            raise
        time.sleep(0.5)      # let that last log line reach the file
        os._exit(0)
    # Someone else owns the lifecycle, so hand over by exiting. Spawning here is
    # exactly what made two bots exist at once.
    if owner == "supervisor":
        # Only the supervisor reads this, and it is what keeps a human's /restart out of
        # the failed-start count.
        _write_restart_marker(by)
    log.info("exiting %d — %s will start me again", RESTART_EXIT_CODE, owner)
    time.sleep(0.5)          # let that last log line reach the file
    os._exit(RESTART_EXIT_CODE)


def user_is_allowed(sender, user_id):
    """Deny-by-default allowlist.

    Tolerates a null or a bare string, because a crash or a substring match here
    is a security bug rather than a style problem: `uid not in None` raises, and
    `"abc" in "abcdef"` is True -- a single-user string would otherwise let any
    name that contains it through.
    """
    allowed = CONFIG["mattermost"].get("allowed_users") or []
    if isinstance(allowed, str):
        allowed = [allowed]
    if not isinstance(allowed, (list, tuple)):
        return False
    return sender in allowed or (user_id is not None and str(user_id) in
                                 [str(a) for a in allowed])


# Management verbs — `tinycmdr <verb>` (2026-09-22)
# The installers left no command behind, so day-two work meant hand-editing
# config.json and .env, and finding the right restart helper per OS. These are the
# things an operator actually does between installs. Rules this block holds to:
#   * A verb NEVER runs the agent loop. `status` and `doctor` ask the endpoint for
#     METADATA (/v1/models, /props) and nothing else; no verb spends tokens.
#   * A verb that touches config writes through atomic_write_text - the same writer
#     the agent uses - so a failed write cannot truncate the file the bot reads at
#     start.
#   * No verb prints a secret VALUE. `token` reports whether one is set, never what
#     it is.
#   * Nothing here is a second implementation: the model catalog, the config
#     writer, the log file and the shipped restart helpers are the ones the running
#     bot already uses. `restart` calls this host's own helper rather than
#     re-implementing the kill/launch dance, because that dance is where two bots
#     on one token came from.

VERBS = ("status", "doctor", "health", "model", "reasoning", "config", "setup", "logs", "proc",
         "restart", "update", "clean", "token", "version", "run", "help", "failures",
         "approvals", "web")

def ensure_launcher_executable():
    """Give the folder's launcher its execute bit back after a pull or an adoption.

    ".../tinycmdr: Permission denied" - and the same under sudo, because execve wants at
    least one execute bit set for EVERY user, root included. The two-line shim in
    /usr/local/bin was correct; the file it execs was mode 0644. The tree tracks
    `tinycmdr` as 100644 (a Windows checkout cannot record the bit, and fileMode ignores
    it there), the macOS installer lands it with `cp -f` and never chmods it, so EVERY
    git-based update wrote a door nobody could open on every Unix host. A door that
    cannot be executed is the first thing a reader meets, so the update path re-asserts
    the bit instead of trusting the checkout.
    """
    if os.name != "posix":
        return
    try:
        p = BASE_DIR / "tinycmdr"
        if p.exists() and not os.access(p, os.X_OK):
            os.chmod(p, os.stat(p).st_mode | 0o111)
    except OSError:
        log.debug("could not restore the launcher's execute bit", exc_info=True)


_LOCK_FH = None


def _lock_target(for_probe=False):
    """(kind, handle) for this folder's single-instance lock.

    POSIX locks the INSTALL FOLDER itself, not a file beside it. flock lives on the
    inode, so a lock FILE is defeated by `rm`: measured, a second instance was refused,
    the file was deleted, and the very next instance acquired a fresh lock and ran
    against the same bot token. A directory cannot be unlinked while it has
    contents, so that foot-gun is gone - and so is the abort message that used to tell
    the operator to delete the file. Windows has no directory handle msvcrt can lock, so
    it keeps the file.

    `for_probe` opens that file for reading and NEVER creates it: a read-only probe
    (status, doctor) used to write tinycmdr.lock into the install folder
    . A missing file comes back as OSError, which the caller turns into
    "unknown" - safe, because a missing file means nothing holds the lock.
    """
    if os.name == "nt":
        return "file", open(BASE_DIR / "tinycmdr.lock",
                            "r+b" if for_probe else "a+b")
    try:
        return "dir", os.open(str(BASE_DIR), os.O_RDONLY)
    except OSError:
        # No handle on the folder (exotic filesystem, odd permissions): the file is the
        # old fallback. Weaker, but a lock that refuses to start is worse.
        return "file", open(BASE_DIR / "tinycmdr.lock", "a")

def _lock_release_fd(fh):
    if isinstance(fh, int):
        try:
            import fcntl
            fcntl.flock(fh, fcntl.LOCK_UN)
        except OSError:
            pass
        try:
            os.close(fh)
        except OSError:
            pass
        return
    if os.name == "nt":
        try:
            import msvcrt
            try:
                fh.seek(0)
                msvcrt.locking(fh.fileno(), msvcrt.LK_UNLCK, 1)
            except Exception:                                    # noqa: BLE001
                pass
        except Exception:                                        # noqa: BLE001
            pass
    try:
        fh.close()
    except Exception:                                            # noqa: BLE001
        pass

def acquire_single_instance_lock():
    """Bot mode only: refuse a second tinycmdr from the same folder.
    (Logon shortcut + manual double-click = two bots on one Mattermost
    token = duplicate replies.) Lock is released on process exit, and on
    os.execv (/restart) thanks to PEP 446 non-inheritable fds."""
    global _LOCK_FH, _LOCK_HELD
    fh = None
    try:
        _kind, fh = _lock_target()
        if os.name == "nt":
            import msvcrt
            fh.seek(0)
            msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(fh, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        if fh is not None:
            _lock_release_fd(fh)     # close what we opened before refusing
        return False
    except Exception:
        if fh is not None:
            _lock_release_fd(fh)
        _LOCK_HELD = True   # lock mechanics failed - never block startup on that
        return True
    _LOCK_FH = fh
    _LOCK_HELD = True
    return True


def _release_lock():
    """Drop the single-instance lock so a replacement process can take it."""
    global _LOCK_FH, _LOCK_HELD
    try:
        if _LOCK_FH:
            _lock_release_fd(_LOCK_FH)
    except Exception:                                            # noqa: BLE001
        pass
    _LOCK_FH = None
    _LOCK_HELD = False     # released: this process is no longer the bot

def _instance_lock_free():
    """True when no process holds this folder's instance lock.

    One probe, one target, so the bot and `tinycmdr status` can never disagree about
    which inode is the instance lock (the probe used to look for a FILE while
    the fix now locks the FOLDER on POSIX). Raises OSError when the target cannot be
    opened; callers turn that into "unknown".
    """
    _kind, fh = _lock_target(for_probe=True)
    try:
        if os.name == "nt":
            import msvcrt
            fh.seek(0)
            try:
                msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
            except OSError:
                return False
            msvcrt.locking(fh.fileno(), msvcrt.LK_UNLCK, 1)
            return True
        import fcntl
        try:
            fcntl.flock(fh, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            return False
        fcntl.flock(fh, fcntl.LOCK_UN)
        return True
    finally:
        _lock_release_fd(fh)

def instance_busy_note():
    """What the operator is told when a second bot is refused.

    Names the door to LOOK through, and never tells anyone to delete the lock file: the
    old wording did, and on POSIX flock lives on the inode, so deleting it handed the
    next instance a fresh lock and a second bot on the same token.
    """
    return ("One bot per folder - a second instance double-answers every message.\n"
            "See what is running with `tinycmdr status`, then stop it the way this\n"
            "install starts it (launchd, systemd, or the Windows Startup shortcut).")

def _verb_running():
    """True / False / None: does another live process hold this folder's lock?

    A probe, not a claim: it takes the same lock and gives it straight back, so a
    lock file left behind by a crash reads as NOT running.
    """
    try:
        return not _instance_lock_free()
    except Exception:                                            # noqa: BLE001
        return None

VERB_HELP = """tinycmdr <verb> — management, never a model call

  (nothing)          a session in this folder: what the `tinycmdr` shim does when you
                     type it with no verb, and the same as --cli below
  status             version, folder, model, endpoint, context, log, instance
  doctor             check this install and name what is wrong (exit 1 when it is)
  model              pick the model this install uses; when the endpoint is dead or wrong
                     it offers the setup wizard instead of a dead end
  model setup        the model wizard: local or cloud, the key, the link, the bearer
                     check, then the models the endpoint serves to choose from
  model use <name>   set the default model in config.json, catalog-checked
  model add [<url>]  add an endpoint this install can route to (no <url> asks; a fallback
                     entry unless --primary makes it the one that answers; --model NAME,
                     --alias A, --key-env VAR, --force to add it unverified)
  model endpoint [<url>]
                     read the primary endpoint, or fix it - a 401 asks for the key
  model failover [on|off]
                     may automatic failover send to an off-LAN endpoint? (off by
                     default: off-LAN endpoints are reached only when you switch)
  model remove <x>   drop a fallback entry (by model name, alias or url)
  setup              interactive wizard: model, Mattermost, Telegram, the page, web search
  config get|set|unset <dotted.key> [value]
                     read or edit config.json (a read-back is printed; secrets refused)
  health             one line + exit code: up, lane, model (no network, for scripts)
  failures           the known-failure library: which entries have EVER fired on this
                     box, and which failures keep arriving with no entry (-c, --json)
  approvals [clear]  what the confirm gate has been told to stop asking about
                     (the session and permanent answers); `clear` asks again
  version            the version alone
  web                open the page: prints the tokenized link, opens a browser
  proc               the processes running from THIS folder
  update [--full]    fetch the published build (verified download; nothing to do with git)
  update <src>       put a newer build in place (file, zip or folder); no .bak copy
  clean [--yes]      list the junk in this folder; --yes removes it (state is kept)
  logs [n]           the last n lines of tinycmdr.log (default 40)
  restart            restart through this host's own door (task, systemd, launchd)
  token              where the secrets live and which are set (never their values)
  token set <NAME>   read one value from stdin and write it to .env (mode 600)
  run                start the agent in this window, exactly as the file does
  help               this text


In a chat window the same names are slash commands, and `/tinycmdr` is the prefix that
always gets through: `/tinycmdr model` lists them, `/tinycmdr status` is this host,
`/tinycmdr help` lists every command.

A bare `tinycmdr` from a shell opens the app in this folder (the same as --app); the
inline lane is `--cli`, and a terminal that cannot host the app falls back to it.
`tinycmdr --app` opens the same session as a full-screen terminal app (alternate
screen, live status bar, in-pane scrolling); it falls back to inline cards when the
terminal cannot host it. A bare `tinycmdr` also starts the page and opens a browser
when the machine has one; `--no-web` turns the page off for that run. The terminal
flags themselves need no port, server or browser.

A chat lane is chosen by the token that is set; when BOTH a Mattermost and a
Telegram token are configured, one process serves BOTH lanes. --telegram and
--mattermost force a single lane when you want only one.

With no verb this file is the agent itself, exactly as it has always been.
"""




def _verb_log_lines(count):
    text = ""
    try:
        with (BASE_DIR / "tinycmdr.log").open("r", encoding="utf-8",
                                             errors="replace") as f:
            text = f.read()
    except OSError:
        return [], 0
    lines = text.splitlines()
    return lines[-count:], len(lines)


def _verb_status():
    print("tinycmdr %s — %s" % (VERSION, BASE_DIR))
    print("  python    : %s" % sys.version.split()[0])
    print("  model     : %s" % CONFIG["llm"]["model"])
    env = AGENT._envelope()
    url = CONFIG["llm"]["base_url"]
    if env["source"] == "server":
        print("  endpoint  : %s — %s per request" % (url, fmt_tokens(int(env["window"]))))
        print("  envelope  : %s" % envelope_line(env))
        if env.get("refused"):
            print("  envelope  : REFUSED — below the %s minimum this build needs"
                  % fmt_tokens(ENVELOPE_MIN_WINDOW), file=sys.stderr)
    else:
        print("  endpoint  : %s — no answer (metadata probe only)"
              % url, file=sys.stderr)
    running = _verb_running()
    print("  instance  : %s" % {True: "running (the lock is held)",
                                False: "not running (the lock is free)",
                                None: "unknown"}[running])
    _lanes = lanes_snapshot()
    if _lanes:
        print("  lanes     : %s" % ", ".join("%s=%s" % (n, i["state"])
                                             for n, i in _lanes.items()))
    lines, total = _verb_log_lines(1)
    if total:
        print("  log       : %s — %d lines" % (BASE_DIR / "tinycmdr.log", total))
    else:
        print("  log       : none yet")
    try:
        concepts = memory_scan()
        index_bytes = MEMORY_INDEX.stat().st_size if MEMORY_INDEX.exists() else 0
        notes = (BASE_DIR / "notes.md").stat().st_size
        print("  memory    : %d concept%s, %d chars index; notes.md %d bytes (legacy)"
              % (len(concepts), "" if len(concepts) == 1 else "s", index_bytes, notes))
    except OSError:
        pass
    print("  config    : %s" % (CONFIG_PATH if CONFIG_PATH.exists() else
                                "MISSING (copy config.example.json)"))
    if env["source"] != "server":
        print("status: the endpoint did not answer its metadata probe"
              + lan_permission_hint(CONFIG["llm"].get("base_url")), file=sys.stderr)
        return 1
    return 0


def leak_gate_armed():
    """("yes"|"no"|"n/a", hook path) - will a push from THIS clone be scanned?

    The leak gate is only as good as its arming: the hook is not tracked by git, so a
    hand-typed install is the step that gets skipped. A package install is not a clone and
    carries no installer, so it answers n/a rather than naming a script it does not have -
    the state is reported, never left to memory.
    """
    script = BASE_DIR / "maintenance" / "install-hooks.sh"
    if not script.is_file() or not (BASE_DIR / ".git").is_dir():
        return "n/a", str(script)
    hook = BASE_DIR / ".git" / "hooks" / "pre-push"
    try:
        if hook.is_file() and os.access(str(hook), os.X_OK):
            return "yes", str(hook)
    except OSError:
        pass
    return "no", str(hook)


def guard_tier_lines():
    """One line per guard tier: (name, state, the config key that changes it).

    Six mechanisms carry this harness's refusals and each has its own key and its own
    off-switch, and doctor reported none of them - so "why did the harness refuse that?"
    was answered by reading a 38k-line file (measured 2026-10-07). Every key named here is
    the one the reader actually reads, so `tinycmdr config set <key> <value>` is the
    answer the line hands over.
    """
    ag = CONFIG.get("agent") or {}
    llm = CONFIG.get("llm") or {}
    return [
        ("absolute", "on, %d pattern(s)" % len(_patterns("blocked_patterns")),
         "agent.blocked_patterns - cannot be approved in-band"),
        ("confirm", "on, %d command + %d content pattern(s)"
         % (len(_patterns("confirm_patterns")),
            len(ag.get("confirm_content_patterns") or ())),
         "asked through the lane's confirm door"),
        ("cost", "%s, search_timeout %ss"
         % ("on" if ag.get("command_cost_guard", True) else "OFF",
            int(ag.get("search_timeout") or 0)),
         "agent.command_cost_guard, agent.search_timeout"),
        ("segments", "%s, +%s segment(s) of %s steps / %s min"
         % ("on" if ag.get("auto_continue", True) else "OFF",
            ag.get("auto_continue_max"), ag.get("max_steps"), ag.get("max_minutes")),
         "agent.auto_continue, agent.auto_continue_max"),
        ("turns", "%s turn(s) for the whole run" % llm.get("max_turns"),
         "llm.max_turns - shared by every segment"),
        ("stall", "warn %s min, abandon %s min"
         % (ag.get("stall_warn_minutes"), ag.get("stall_abandon_minutes")),
         "agent.stall_warn_minutes, agent.stall_abandon_minutes (0 = off)"),
        ("web stall", "warn %s min, abandon %s min"
         % (ag.get("stall_warn_minutes", 8), ag.get("stall_abandon_minutes", 20)),
         "the same two keys, for the page's runs (WEB_RUNS)"),
    ]


def _verb_doctor():
    problems, notes = [], []
    print("tinycmdr %s doctor — %s" % (VERSION, BASE_DIR))

    err = validate_startup_config()
    if not _chat_lane_configured():
        notes.append("no chat lane configured - CLI-only install (--cli / --once)")
    print("  config    : %s" % (err.splitlines()[0] if err else "ok"))
    if err:
        problems.append(err)

    print("  python    : %s" % sys.version.split()[0])
    if sys.version_info < (3, 10):
        problems.append("python %s is older than this build supports"
                        % sys.version.split()[0])

    # The image switch: nothing else in doctor says whether a screenshot-returning
    # tool's pictures can reach the model at all, and the enable path is otherwise
    # buried in config.json. When it is on, the endpoint gets the last word (only a
    # positive modalities.vision=false vetoes; an endpoint that says nothing does not).
    _vision = bool(CONFIG["agent"].get("vision"))
    if _vision:
        _vok, _vwhy = _endpoint_vision()
        if _vok:
            print("  vision    : on - tool images (computer_use screenshots) ride one "
                  "request")
        else:
            problems.append("agent.vision is on but %s; a screenshot would be sent to "
                            "an endpoint that cannot see it" % _vwhy)
    else:
        print("  vision    : off - tool screenshots are NOT sent; set agent.vision true "
              "(`tinycmdr config set agent.vision true` + restart) if the endpoint "
              "accepts images")

    # The persona is invisible state: nothing else in this output says whether the agent is
    # running the shipped identity or one somebody edited here. (`update` copies an edited
    # file aside before pulling; see preserve_edited_soul.)
    try:
        _soul_edited = (SOUL_FILE.read_text(encoding="utf-8").strip()
                        != DEFAULT_SOUL.strip()) if SOUL_FILE.exists() else None
    except OSError:
        _soul_edited = None
    if _soul_edited is None:
        print("  persona   : the built-in default (no soul.md on this host)")
    else:
        print("  persona   : soul.md (%s)"
              % ("edited on this host" if _soul_edited else "the shipped seed"))
        if _soul_edited:
            notes.append("soul.md is an uncommitted edit to a tracked file: `update` "
                         "copies it aside before pulling, but anything that discards "
                         "local changes (git reset --hard) would take it. The persona is "
                         "read once per process, so restart after editing it")

    drift = guard_list_drift()
    if drift:
        missing = sum(len(m) for _k, m, _e in drift)
        print("  guards    : %d shipped pattern(s) missing from config.json's lists"
              % missing)
        problems.append(guard_drift_note(drift))
    else:
        print("  guards    : shipped lists intact (v%d)" % GUARD_LIST_VERSION)

    # ...and the tiers those lists arm, each with the key that moves it: a refusal with no
    # visible switch reads as a bug in the harness rather than as a guard doing its job.
    for _name, _state, _key in guard_tier_lines():
        print("  guard %-9s: %s  [%s]" % (_name, _state, _key))

    _armed, _hook = leak_gate_armed()
    if _armed == "yes":
        print("  leak gate : armed - the pre-push hook will scan a push from this clone")
    elif _armed == "n/a":
        print("  leak gate : n/a - not a development clone (nothing is pushed from this folder)")
    else:
        print("  leak gate : NOT ARMED - run `bash maintenance/install-hooks.sh`")
        notes.append("this clone's push is NOT scanned for private strings: "
                     "maintenance/install-hooks.sh installs the pre-push hook the leak gate "
                     "runs from (it is what would have refused the token that reached the "
                     "public repo in a commit message)")

    _gaps = dropin_gaps()
    if _gaps:
        print("  drop-ins  : %s"
              % "; ".join("tools/%s.py is an older copy (missing %s)"
                          % (n, ", ".join(m)) for n, m in _gaps))
        notes.append("a host-owned drop-in is older than this build, so the features that "
                     "call into it are OFF (auto-background and cross-restart exit codes "
                     "need the shipped tools/process.py); refresh it from the release or "
                     "delete it to inherit the packaged seed")
    else:
        print("  drop-ins  : ok")

    _hfgaps = host_file_gaps()
    if _hfgaps:
        print("  host files: %s"
              % "; ".join("%s differs from this release's %s" % (n, d) for n, d in _hfgaps))
        notes.append("a host-owned file differs from the default this release ships "
                     "(update never overwrites those on purpose): if you never edited it, "
                     "delete it to inherit the new default, or diff the two to see what "
                     "changed")
    else:
        print("  host files: ok")

    _cands = field_note_candidates(limit=3)
    if _cands:
        print("  fieldnotes: %d recurring failure signature(s) have no note entry; the "
              "top 3:" % len(field_note_candidates(limit=100)))
        for _line in _cands:
            print("      " + _line)
        notes.append("field-notes.md has no entry for recurring failure signatures this "
                     "box keeps hitting; add a `match:` + `note:` (+ optional "
                     "`repeat: once|gap:N`) for the ones you recognize")

    # What web search would actually DO, so a BLOCKED line in a run has somewhere to be
    # read from: the chain, and whether off-LAN providers are allowed on this host.
    usable, withheld, s_problems = _search_chain_in_use()
    if withheld:
        print("  search    : off-LAN providers REFUSED (%s); on this LAN: %s"
              % (", ".join(e["label"] for e in withheld),
                 ", ".join(e["label"] for e in usable) or "none configured"))
    else:
        print("  search    : %s" % (", ".join(e["label"] for e in usable)
                                    or "no provider configured"))
    if s_problems:
        notes.append("search.providers: " + "; ".join(s_problems))

    try:
        probe = BASE_DIR / ".tinycmdr-write-probe"
        probe.write_text("x", encoding="utf-8")
        probe.unlink()
        print("  folder    : writable")
    except OSError as e:
        print("  folder    : NOT writable (%s)" % e)
        problems.append("the install folder is not writable, so state cannot be saved")

    env = _env_file_keys()
    have_env = ENV_FILE.exists()
    print("  .env      : %s (%d key%s)" % ("present" if have_env else "missing",
                                           len(env), "" if len(env) == 1 else "s"))
    # names only, never values
    wanted = ("TINYCMDR_MM_TOKEN", "TINYCMDR_TG_TOKEN", "TINYCMDR_WEB_TOKEN",
              "DEEPSEEK_API_KEY", "ANYSEARCH_API_KEY", "TAVILY_API_KEY")
    for name in wanted:
        where = []
        if os.environ.get(name):
            where.append(".env" if name in env else "environment")
        print("    %-20s %s" % (name, ", ".join(where) if where else "not set"))
    # "none" is the shipped PLACEHOLDER, not a key: warning about it made every fresh
    # install report a secret where there was none.
    _llm_key = str(CONFIG["llm"].get("api_key") or "").strip()
    if _llm_key and _llm_key.lower() != "none":
        notes.append("llm.api_key is set in config.json — .env is the safer home")

    # The page is the door a bare start opens, and "no token" is a supported state (the
    # next start mints one) - but it is worth NAMING, because an install that predates the
    # page has exactly that and nothing else in this output would say the page exists.
    web = CONFIG.get("web") or {}
    port, port_note = _web_port(web)
    if not web.get("enabled", True):
        print("  page      : off (web.enabled false; `tinycmdr setup` turns it on)")
    elif _web_token():
        print("  page      : on, port %d, token set (`tinycmdr web` prints the link)" % port)
        if str(web.get("host") or "").strip() in ("0.0.0.0", "::"):
            for _line in _firewall_note(port):
                notes.append(_line)
    else:
        print("  page      : on, port %d, no token yet - the next start mints one" % port)
        notes.append("no page token yet: the next start mints one into .env, or choose "
                     "your own with `tinycmdr token set TINYCMDR_WEB_TOKEN`")
    if port_note:
        notes.append(port_note)

    for mod, why in (("requests", "the HTTP layer"), ("croniter", "scheduling"),
                     ("mmpy_bot", "the Mattermost layer")):
        try:
            __import__(mod)
        except ImportError:
            if mod == "requests" or CONFIG["mattermost"].get("token"):
                problems.append("%s is not installed (%s)" % (mod, why))
            print("  dep %-6s: MISSING (%s)" % (mod, why))
        else:
            print("  dep %-6s: ok" % mod)

    env = AGENT._envelope()
    url = CONFIG["llm"]["base_url"]
    if env["source"] == "server":
        print("  endpoint  : %s — %s per request" % (url, fmt_tokens(int(env["window"]))))
        print("  envelope  : %s" % envelope_line(env))
        if env.get("refused"):
            problems.append(env["refusal"])
    elif env["source"] == "assumed" and not _is_local_url(url):
        # A hosted endpoint answers /v1/models but carries no max_model_len there and serves
        # no /props, /api/ps or /get_server_info - nothing tells the harness its window, so
        # the envelope falls back to an assumed 8000 tokens and clips replies at 2048 (a 128k
        # cloud model driven at 8k). The old line called this "did not answer", which sends
        # the operator to the endpoint when the lever is one config key. Silent on an on-LAN
        # box: its window comes from its own context slot, which a restart changes.
        print("  endpoint  : %s — no window known; assuming %s"
              % (url, fmt_tokens(int(env["window"]))))
        problems.append(
            "no context length was available from %s, so the harness assumes a %s "
            "window and clips replies at %s tokens. Set llm.max_context_tokens in "
            "config.json to the window your provider documents (hosted models are usually "
            "32k-128k+)."
            % (url, fmt_tokens(int(env["window"])), fmt_tokens(int(env["reply"]))))
    else:
        print("  endpoint  : %s — NO ANSWER" % url)
        problems.append(("the model endpoint at %s did not answer" % url)
                        + lan_permission_hint(url))

    running = _verb_running()
    print("  instance  : %s" % {True: "running (the lock is held)",
                                False: "not running (the lock is free)",
                                None: "unknown"}[running])

    _lanes = lanes_snapshot()
    if _lanes:
        print("  lanes     : %s" % ", ".join("%s=%s" % (n, i["state"])
                                             for n, i in _lanes.items()))
        for _n, _i in _lanes.items():
            if _i["state"] == "failed":
                problems.append("%s lane is DOWN (%d failed start(s)): %s"
                                % (_n, _i["failed_starts"], _i["detail"] or "no detail"))
    else:
        print("  lanes     : none configured")

    _drift = config_drift()
    if _drift:
        print("  config    : %s" % _drift)
        notes.append(_drift)

    # A run parked on a legitimate question must not be abandoned as a stall first:
    # _ask_wait_cap() reaches 900 s, so an abandon window under that cancels the
    # question and the operator gets "stopped" instead of an answer. Only meaningful
    # while the watchdog is on - 0 (or less) disables it, and there is nothing to
    # compare against.
    try:
        _abandon_m = float(CONFIG["agent"].get("stall_abandon_minutes", 20) or 0)
    except (TypeError, ValueError):
        _abandon_m = 0.0
    _ask_cap = _ask_wait_cap()
    if _abandon_m > 0 and _ask_cap > _abandon_m * 60:
        problems.append(
            "agent.stall_abandon_minutes (%gm) is shorter than the ask cap (%gs): a run "
            "parked on a question would be abandoned as a stall; raise the abandon window "
            "above %g minutes or lower agent.ask_user_wait_seconds"
            % (_abandon_m, _ask_cap, _ask_cap / 60))

    # The same coherence, for the watchdog's OTHER inputs:
    # the warning must land before the abandon, and a single request
    # budget longer than the abandon window means a slow-but-healthy request - or a
    # retry ladder with nothing to post - can be declared a stall.
    try:
        _warn_m = float(CONFIG["agent"].get("stall_warn_minutes", 8) or 0)
    except (TypeError, ValueError):
        _warn_m = 0.0
    if _abandon_m > 0 and _warn_m >= _abandon_m:
        problems.append(
            "agent.stall_warn_minutes (%gm) is not below agent.stall_abandon_minutes "
            "(%gm): the warning would never precede the abandon" % (_warn_m, _abandon_m))
    try:
        _req_s = (float(CONFIG["llm"].get("request_timeout") or 0)
                  + float(CONFIG["llm"].get("request_grace") or 0))
    except (TypeError, ValueError):
        _req_s = 0.0
    if _abandon_m > 0 and _req_s > _abandon_m * 60:
        notes.append(
            "a single request budget (llm.request_timeout + request_grace = %gs) is "
            "longer than agent.stall_abandon_minutes (%gm): a slow, silent request or "
            "retry ladder can be abandoned as a stall" % (_req_s, _abandon_m))

    for n in notes:
        print("  note      : %s" % n)
    if problems:
        print("\ndoctor: %d problem(s)" % len(problems), file=sys.stderr)
        for p in problems:
            print("  - %s" % p.replace("\n", " "), file=sys.stderr)
        return 1
    print("\ndoctor: no problems found")
    return 0


# ------------------------------------------------------------- the endpoints
# `model add` / `model remove` exist because an endpoint had no route of its own:
# `model use` can only pick among the endpoints already written, so the only ways
# in were hand-editing config.json or re-running the installer - and an installer
# is a fresh-install path, not an endpoint manager (operator, 2026-09-22: "your
# solution to wire in another endpoint is to rerun the installer? Are you fucking
# serious?"). Nothing here runs the agent or spends a token: the one request is a
# /v1/models GET, for the id check.

MODEL_ADD_HELP = """tinycmdr model add [<url>] [--model NAME] [--alias A] [--key-env VAR]
                   [--primary] [--force]

  With no <url> it asks: local or cloud, then the API key (cloud) and the endpoint
  link, proves the key with a bearer GET /v1/models, and offers the models that come
  back to choose from.

  With a <url> it takes the endpoint from the command line and checks the model id
  against what the endpoint advertises (one /v1/models GET, metadata only). --force
  writes it when the endpoint is not reachable yet.

  A cloud endpoint added here goes into llm.fallbacks and its key into .env under a
  generated TINYCMDR_ENDPOINT<n>_API_KEY the entry points at with api_key_env; a
  cloud PRIMARY keeps its key in .env as TINYCMDR_LLM_API_KEY. Never config.json -
  that is a file the agent reads into a prompt.

  The KEY is never a command-line value: --key-env names the .env variable, and
  `tinycmdr token set <NAME>` reads the value from stdin.

  A running bot reads config.json at start, so `tinycmdr restart` afterwards.

tinycmdr model remove <name|alias|url>    drop a fallback entry
"""


def probe_endpoint(url, key=None, timeout=20):
    """Ask an OpenAI-compatible endpoint which models it serves.

    One GET /models, metadata only - never a completion, so no verb that calls this can
    spend a token. The bearer key is sent when there is one: a hosted provider answers
    /v1/models with 401 unless it is authenticated, and the old probe sent no
    Authorization header at all, so every cloud endpoint read as "down" and its model
    list never came back. That is the bug this shape exists to end.

    Returns {"ok": bool, "ids": [...], "status": int|None, "error": str}. `ok` is True
    only for a 2xx answer - an endpoint that answers with no list is still reachable.
    `status` is the HTTP code when a response came back, so a caller can tell 401 (the
    key) from a dead host; `error` is a short reason when something went wrong.
    """
    headers = {"Accept": "application/json", "User-Agent": "tinycmdr"}
    if key:
        headers["Authorization"] = "Bearer " + str(key)
    try:
        r = requests.get(str(url).rstrip("/") + "/models", headers=headers,
                         timeout=timeout)
    except Exception as e:
        log.debug("probe: /models on %s failed: %s", url, e)
        return {"ok": False, "ids": [], "status": None,
                "error": " ".join(str(e).split())[:160]}
    if r.status_code >= 400:
        log.debug("probe: /models on %s answered %s", url, r.status_code)
        return {"ok": False, "ids": [], "status": r.status_code,
                "error": "HTTP %d" % r.status_code}
    try:
        data = r.json()
    except Exception as e:
        log.debug("probe: /models on %s was not JSON: %s", url, e)
        return {"ok": False, "ids": [], "status": r.status_code,
                "error": "not JSON: %s" % " ".join(str(e).split())[:80]}
    out = []
    for item in (data.get("data") or data.get("models") or []):
        if isinstance(item, str):
            out.append(item)
        elif isinstance(item, dict):
            mid = item.get("id") or item.get("name") or item.get("model")
            if mid:
                out.append(str(mid))
    return {"ok": True, "ids": out, "status": r.status_code, "error": ""}


def _probe_model_ids(url, key=None):
    """The model ids one endpoint advertises, or None when it did not answer.

    The thin compatibility wrapper around probe_endpoint(): callers that only need the
    list keep their None-means-no-answer contract; a caller that must tell 401 from a
    dead host (the setup wizard, `model add`) reads probe_endpoint() directly."""
    res = probe_endpoint(url, key)
    return list(res["ids"]) if res["ok"] else None


def _primary_api_key():
    """The key the PRIMARY endpoint authenticates with, from wherever it lives.

    `llm.api_key` in config.json (the old home), or TINYCMDR_LLM_API_KEY in .env/the
    environment, which is the home the wizard now writes. The shipped `"api_key": "none"`
    sentinel means "no key" and comes back empty, so a local box is not mistaken for a
    keyed one."""
    val = (str(CONFIG["llm"].get("api_key") or "").strip()
           or os.environ.get("TINYCMDR_LLM_API_KEY", "").strip())
    return "" if val.lower() == "none" else val


def probe_sentence(url, res):
    """One line saying what a probe found, written for the two ways it goes wrong: a
    key the provider refuses, and a host that is not answering."""
    if res["ok"]:
        return ("it answers, and advertises: %s" % ", ".join(res["ids"][:12]) if res["ids"]
                else "it answers, but advertises no model list")
    if res["status"] in (401, 403):
        return "the provider refused that key (HTTP %d)" % res["status"]
    return "no answer from %s (%s)" % (url, res["error"])


def _config_raw():
    """config.json exactly as it is on disk: (raw, error)."""
    try:
        return json.loads(CONFIG_PATH.read_text(encoding="utf-8")), None
    except Exception as e:
        return None, "could not read config.json: %s" % e


def _config_write_raw(raw):
    """Write through the agent's own atomic writer. Error string, or None."""
    try:
        _write_config(raw)
    except Exception as e:
        return "could not write config.json: %s" % e
    return None


def _config_take_effect():
    """Re-read config.json and make the change live. The read-back is the proof."""
    back, err = _config_raw()
    if err:
        return err
    CONFIG["llm"] = back.get("llm") or CONFIG["llm"]
    # Resolve each fallback's api_key_env against the environment AND .env, exactly as
    # load_config does at import: a key `model add` just wrote to .env has to reach
    # model_catalog in THIS process, or the new endpoint cannot answer until a restart.
    for _fb in CONFIG["llm"].get("fallbacks", []):
        if isinstance(_fb, dict) and _fb.get("api_key_env"):
            _val = _endpoint_key(_fb["api_key_env"])
            if _val:
                _fb["api_key"] = _val
    _MODEL_CACHE["at"] = 0.0
    # A key added after import was not in the sweep, so it reached the transcript, the
    # log and the chat unmasked. Re-derive it with the config (2026-09-29).
    global _SECRETS
    _SECRETS = _secret_values()
    return None


# --- the verbs that wrap a host command --------------------------------------
# Each of these replaces something that was typed by hand on cmd, PowerShell or bash, and
# got typed wrong at least once: the process query filtered by the install folder, the
# instance-lock check, a dotted-key edit of config.json, swapping in a newer build,
# and tidying the folder.
# Nothing here runs the agent or spends a token, and no verb prints a secret value.


def _verb_version():
    print("tinycmdr %s" % VERSION)
    print("  folder : %s" % BASE_DIR)
    print("  python : %s" % sys.version.split()[0])
    return 0


def _verb_health():
    """One line a script can read, with an exit code that means something.

    `status` is for a human (it asks the endpoint for its window and prints a page of
    facts); this answers "is it up, on which lane, on which model" without touching the
    network, so a supervisor or a cron job can call it every minute."""
    running = _verb_running()
    # STATES, not names: a configured lane is not a connected lane, and that distinction is
    # what let 510 failed starts look like a healthy bot (a live install, 2026-09-28).
    lanes_state = lanes_snapshot()
    # Built as a list on purpose: a conditional expression as a genexp element swallows the
    # `for` clause, so `",".join(A if c else B for ...)` joined the STRING's characters -
    # the health line printed `lane m,a,t,t,e,r,m,o,s,t,...` (caught by the suite, 2026-09-28).
    _parts = ["%s=%s" % (_name, _info["state"])
              for _name, _info in lanes_state.items()]
    lanes = ",".join(_parts)
    state = {True: "up", False: "not running", None: "unknown"}[running]
    # The envelope rides this line only when it was already computed: `health` keeps
    # its no-network contract (a script calls it every minute), so a cold process
    # prints no numbers rather than paying a metadata probe for them.
    env = AGENT.cached_envelope()
    tail = (" · " + envelope_line(env, raw=True)) if env else ""
    print("%s v%s %s · lane %s · model %s at %s%s"
          % (os.path.basename(sys.argv[0] or "tinycmdr"), VERSION, state,
             lanes or "none", CONFIG["llm"].get("model"),
             CONFIG["llm"].get("base_url"), tail))
    if running is not True:
        print("the single-instance lock is not held: nothing is listening for messages",
              file=sys.stderr)
        return 1
    _drift = config_drift()
    if _drift:
        # On stderr with the lane lines, so the one readable stdout line keeps its shape.
        # This is the surface that SURVIVED the web UI's removal, which is why it is here:
        # the trap (an edit that has not applied) is what an operator hits after asking
        # the agent in chat.
        print(_drift, file=sys.stderr)
    for _name, _info in lanes_state.items():
        if _info["state"] == "failed":
            print("%s lane is DOWN%s: %s"
                  % (_name,
                     (" (%d failed start%s)" % (_info["failed_starts"],
                                                "" if _info["failed_starts"] == 1 else "s"))
                     if _info["failed_starts"] else "",
                     _info["detail"] or "no detail"), file=sys.stderr)
    return 1 if any(i["state"] == "failed" for i in lanes_state.values()) else 0


def _install_processes():
    """Lines of (pid, started, command) for processes running from THIS folder.

    The query everyone types by hand: `Get-CimInstance Win32_Process | Where-Object
    CommandLine -like '*tinycmdr*'` on Windows, `ps -eo pid,lstart,args | grep` elsewhere.
    Matching on the install dir rather than the word keeps a second install out of it."""
    here = str(BASE_DIR).lower()
    if os.name == "nt":
        rc, out, err, _ = run_capture(
            ["powershell", "-NoProfile", "-Command",
             "Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -and "
             "($_.CommandLine.ToLower().Contains('" + here.replace("'", "''") + "')) } | "
             "ForEach-Object { '{0} {1} {2}' -f $_.ProcessId, $_.CreationDate, $_.CommandLine }"],
            60)
    else:
        rc, out, err, _ = run_capture(
            ["sh", "-c", "ps -eo pid,lstart,args | grep -i -- '%s' | grep -v grep" % BASE_DIR],
            60)
    if rc != 0 and not out.strip():
        return [], (err or "").strip()
    rows = [ln.strip() for ln in out.splitlines() if ln.strip()]
    rows = [r for r in rows if "powershell" not in r.lower()]
    return rows, None


def _verb_proc():
    """This install's own processes, and who holds the lock. Read-only."""
    rows, err = _install_processes()
    print("install : %s   instance: %s"
          % (BASE_DIR, {True: "running (the lock is held)",
                        False: "not running (the lock is free)",
                        None: "unknown"}[_verb_running()]))
    if err:
        print("  the process query failed: %s" % err, file=sys.stderr)
    if not rows:
        print("  no process running from this folder")
    for r in rows[:12]:
        print("  %s" % r[:160])
    if len(rows) > 12:
        print("  ... %d more" % (len(rows) - 12))
    return 0


def _verb_reasoning(rest):
    """`reasoning [auto|off|minimal|low|medium|high|xhigh|max]` - what the box asks for.

    The operator's door to llm.reasoning. With no argument it prints the level in force and
    the shape the endpoint will receive it in (apply_reasoning decides that from the URL or
    llm.reasoning_mode); with one it writes config.json through the same path `config set`
    uses, so the read-back and the file format are the ones already graded.
    """
    want = (rest[0].strip().lower() if rest else "")
    if not want:
        level = str(CONFIG["llm"].get("reasoning") or "auto")
        mode = str(CONFIG["llm"].get("reasoning_mode") or "auto").lower()
        if mode not in ("effort", "responses", "budget"):
            url = str(CONFIG["llm"].get("base_url") or "").lower()
            mode = ("responses" if "/responses" in url
                    else "budget" if "anthropic" in url else "effort")
        wire = {"effort": "reasoning_effort", "responses": "reasoning.effort",
                "budget": "thinking.budget_tokens"}[mode]
        print("reasoning: %s (sent as `%s`)%s"
              % (level, wire, "" if level != "auto" else " - no field is sent at all"))
        print("levels: auto, off, %s" % ", ".join(REASONING_LEVELS))
        return 0
    if want not in REASONING_LEVELS + ("auto", "off"):
        print("unknown level %r - use auto, off, or one of: %s"
              % (want, ", ".join(REASONING_LEVELS)), file=sys.stderr)
        return 2
    return _verb_config(["set", "llm.reasoning", want])


def _secret_config_path(path):
    """True when a config.json path names a secret (whose one home is .env).

    One rule for two callers: the config verb's write refusal and the verb log's scrub
    (A-2026-10-05-69: the refusal message was written but the argv line, logged BEFORE
    dispatch, carried the value to tinycmdr.log anyway). llm.* is exempt - a local
    endpoint's key lives in config.json - and the *_api_key arm is for a provider key
    written by hand (`search.anysearch_api_key`), which the old two-name test accepted.
    The vocabulary is _SECRET_NAME_RX, the SAME rule the environment sweep uses, so the
    config side no longer misses `password|passwd|credential`
    (`config set db.password X` was not treated as a secret).
    """
    _section, _, key = path.rpartition(".")
    if _section.startswith("llm"):
        return False
    return (_SECRET_NAME_RX.search(key) is not None
            or key in ("token", "api_key") or key.endswith("_api_key"))


def _verb_log_args(verb, rest):
    """The argv the verb log records - a secret VALUE replaced, never written."""
    if verb == "config" and len(rest) >= 2 and rest[0] in ("set", "unset") \
            and _secret_config_path(rest[1]):
        return " ".join([rest[0], rest[1]] + ["<redacted>"] * (len(rest) - 2))
    return " ".join(rest)


def _case_twin_note(node, name, walked, tail=()):
    """` - did you mean a.max_steps?` - the case near-miss hint (A-2026-10-05-72).

    Verbs are case-insensitive (`STATUS` runs), keys are case-sensitive, and a flipped
    key answered `(not set)` rc=0 - indistinguishable from "no such setting". One
    unambiguous case-insensitive match is named; two candidates stay silent, because
    "did you mean" with two answers is not a hint. `tail` is the rest of the path as the
    caller typed it, so the suggestion is the whole corrected path, not one segment.
    """
    low = name.lower()
    hits = [k for k in node if isinstance(k, str) and k.lower() == low]
    if len(hits) != 1:
        return ""
    return " - did you mean %s?" % ".".join(list(walked) + [hits[0]] + list(tail))


def _verb_config(rest):
    """`config get|set|unset <dotted.key> [value]` — a config.json edit with a read-back.

    Hand-editing is how config.json gets a trailing comma, a number that is a string, or a
    token in a file the agent can read. Values are parsed as JSON when they can be (so
    `true`, `250`, `["a"]` land typed), as a string otherwise; --str forces a string."""
    if not rest or rest[0] not in ("get", "set", "unset"):
        print("config get <dotted.key> | set <dotted.key> <value> [--str] | unset <dotted.key>",
              file=sys.stderr)
        return 2
    what = rest[0]
    args = list(rest[1:])
    as_str = "--str" in args
    args = [a for a in args if a != "--str"]
    if not args:
        print("config %s needs a dotted key, e.g. agent.max_steps" % what, file=sys.stderr)
        return 2
    path = args[0].strip()
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*([.][A-Za-z_][A-Za-z0-9_]*)*", path):
        print("%r is not a dotted key path (llm.base_url, agent.max_steps)" % path,
              file=sys.stderr)
        return 2
    parts = path.split(".")
    section, key = ".".join(parts[:-1]), parts[-1]
    if _secret_config_path(path):
        # Secrets have exactly one home (.env), and config.json is a file the agent reads
        # into a prompt and can quote into chat.
        print("%s is a secret: put it in %s instead (tinycmdr token set <NAME>)"
              % (path, ENV_FILE.name), file=sys.stderr)
        return 2
    raw, err = _config_raw()
    if err:
        print(err, file=sys.stderr)
        return 1
    node = raw
    for i, part in enumerate(parts[:-1]):
        cur = node.get(part)
        if not isinstance(cur, dict):
            walked = ".".join(parts[:i + 1])
            if what == "get":
                if part in node:
                    print("(%s is not a section)" % walked)
                else:
                    print("(not set)" + _case_twin_note(node, part, parts[:i], parts[i + 1:]))
                return 0
            if part not in node:
                node[part] = {}
            else:
                print("%s is not a section in config.json (it holds %s), so %s cannot be "
                      "set" % (walked, json.dumps(cur), path), file=sys.stderr)
                return 1
        node = node[part]
    if what == "get":
        if key not in node:
            print("(not set)" + _case_twin_note(node, key, parts[:-1]))
            return 0
        print(json.dumps(node[key]) if not isinstance(node[key], str) else node[key])
        return 0
    if what == "unset":
        if key not in node:
            print("%s is not set" % path, file=sys.stderr)
            return 2
        del node[key]
    else:
        if len(args) < 2:
            print("config set %s needs a value" % path, file=sys.stderr)
            return 2
        value = " ".join(args[1:])
        if not as_str:
            try:
                value = json.loads(value)
            except Exception:
                pass                      # a bare word is a string, and that is fine
        # A key whose SHIPPED value is a boolean takes a boolean and nothing else. The
        # fallback above keeps any bare word as a string, and every non-empty string is
        # truthy - so a typo (`agent.vision treu`) or a `--str false` turned the flag ON
        # while the operator read one as a mistake and the other as "off". The shipped
        # config is the schema here, so this catches the whole class (32 keys today),
        # not that one key.
        schema = DEFAULT_CONFIG.get(section)
        if isinstance(schema, dict) and isinstance(schema.get(key), bool) \
                and not isinstance(value, bool):
            print("%s is a boolean in the shipped config, so it takes true or false: %s "
                  "would be stored as a string, and every non-empty string reads as true"
                  % (path, json.dumps(value)), file=sys.stderr)
            return 2
        node[key] = value
    err = _config_write_raw(raw)
    if err:
        print(err, file=sys.stderr)
        return 1
    back, err = _config_raw()
    if err:
        print(err, file=sys.stderr)
        return 1
    node = back
    for part in ([section] if section else []):
        node = (node.get(part) or {})
    print("config %s: %s = %s" % (path, "unset" if what == "unset" else "set",
                                  json.dumps(node.get(key)) if key in node else "(gone)"))
    if key in ("base_url", "model", "fallbacks", "token") and section == "llm":
        _MODEL_CACHE["at"] = 0.0
    CONFIG.update(back)
    # The secret guard above skips the llm section, so `config set llm.api_key` lands
    # here and takes effect; the import-time sweep does not hold it, and an unscrubbed
    # new key reaches the transcript, the log and the chat (2026-09-29).
    global _SECRETS
    _SECRETS = _secret_values()
    if _verb_running() is True:
        print("a running bot reads config.json at start: `tinycmdr restart`.")
    return 0


# ---- one artifact: update consumes the RELEASE the installer does ----------------------
# `update` used to be `git pull` of the development repository, which meant a user could
# receive unreleased commits, accumulated the project's own kit (test suites, CI workflow,
# docs, changelog, ledger, maintenance scripts), and depended on git being installed. Two
# delivery channels - releases for installs, git for updates - then drifted apart: the
# Unix installer verified its download and the Windows one did not, and "shipping a
# behaviour" quietly meant "a commit landed". It now downloads the SAME verified package
# the one-line installer downloads, checks it against SHA256SUMS, applies it and prunes
# the kit. It never reads main.
DEFAULT_UPDATE_URL = "https://github.com/trappsquid/tinycmdr/releases/latest/download"

# What a package does NOT carry, and therefore what an updated install drops. Still an
# exclusion list, for the same reason as before: a path this forgets stays (harmless),
# while an allowlist that forgot one would DELETE something the harness needs.
_DEV_ONLY_PATHS = ("/tests/", "/.github/", "/docs/", "/STATUS.json", "/CHANGELOG.md")
# maintenance/ ships only its restart helpers; these names are the maintenance kit. Deleted
# BY NAME and never by "anything not shipped" - that folder also holds a host's own files
# (private_rules.py, where-roles.json) which must never be touched. The list drifted once
# (2026-10-07: 10 of the 29 scripts were in no list at all, so an updated checkout-install
# kept them and still looked like a dev tree); tests/test_maintenance_kit.py now fails when
# a file in the folder is classified nowhere, so the name list cannot fall behind again.
_DEV_MAINTENANCE_DROP = ("atlas-merge.py", "build-package.py", "check-hygiene.py",
                         "check-package-assets.py", "check-package-modes.py",
                         "check-package-page.py", "check-readme-assets.py",
                         "check-tree-clean.py", "drive-web-cases.py", "install-hooks.sh",
                         "leak-gate.py",
                         "ledger-tag.py", "make-brand-art.py", "measure-prompt.py",
                         "measured-block.py", "package_assets.py", "pre-push.sh", "product-manifest.json",
                         "publish-product.py",
                         "private_rules.example.py", "probe-web-sessions.py",
                         "probe-web-surface.py", "release.sh", "smoke-install.py",
                         "smoke-install.sh", "stub-openai-endpoint.py",
                         "wait-for-endpoint.py", "where.py")
_NARROW_NOTE = ("  dropped the project's own kit (tests/, .github/, docs/, changelog, "
                "maintenance scripts): a package does not carry them. `tinycmdr update "
                "--full` keeps everything instead.")

# Paths the HOST owns: a package may SEED them, but an update must never write over an
# existing one. 1.0.49 protected only soul.md, so a host's edited tools/patch.py,
# tools/process.py, toolsmith.py, tools/README.md or skills/README.md was silently
# replaced (with a .bak beside it, but replaced) - and tools/ is exactly where the agent
# is told to write its own tools. Mirrors the per-host table in docs/development.md §4.
_HOST_OWNED_EXACT = frozenset((
    # The operator's theme: seeded from the shipped default, then theirs to edit - an
    # update must never take a palette away (the designer's table ships as its default).
    "theme.toml",
    ".env", "config.json", "soul.md", "notes.md", "field-notes.md", "atlas.md",
    "experiments.jsonl", "web-sessions.json", "state.json", "jobs.json", "tasks.json",
    "tasks.journal.jsonl", "tasks.md", "confirm-allow.json", "notes-authored.json",
    "tools-provenance.json", "tinycmdr.log", "tinycmdr.lock",
))
# SIX copies of ONE rule live in this tree: this set, the three installers'
# HOST_DIRS/hostDirs lists (install-tinycmdr.sh:1159, install-tinycmdr-macos.sh:1014,
# install-tinycmdr.ps1:1237) and the two standalone updaters the launcher falls back to
# for an old or broken install (update.sh, update.ps1). The comment said "four" and
# tests/test_verbs.py parsed three, which is how the two updaters stayed in their
# pre-fix state - still missing snapshots/ and tmp/ - while a commit claimed every copy
# had been updated (measured 2026-10-07 A-2026-10-07-05). They
# disagreed once before that too: snapshots/ and tmp/ were the installers' and not the
# updater's, so a re-install left state an update would Overwrite. tests/test_verbs.py
# now parses all six and fails when they are not the same rule.
_HOST_OWNED_PREFIXES = ("tools/", "skills/", "sessions/", "snapshots/", "logs/",
                        "spill/", "venv/", "dist/", "tmp/",
                        "maintenance/private_rules.py",
                        "maintenance/where-roles.json")


def _host_owned(rel):
    """True when a package file's destination belongs to the host, not to the package."""
    r = rel.as_posix()
    return r in _HOST_OWNED_EXACT or any(r == p or r.startswith(p)
                                         for p in _HOST_OWNED_PREFIXES)


def _disk_version():
    """VERSION as the file on disk NOW says it.

    The running process's VERSION was read at startup, so the OLD build printed its own
    number in the update summary - the operator saw "VERSION 1.0.45" immediately after
    pulling 1.0.46. Report what the tree holds, not what this
    process remembers.
    """
    try:
        text = (BASE_DIR / "tinycmdr.py").read_text(encoding="utf-8", errors="replace")
    except OSError:
        return VERSION
    m = re.search(r'^VERSION\s*=\s*"([^"]+)"', text, re.M)
    return m.group(1) if m else VERSION


def _dev_tree_reason():
    """Return "declared", "checkout" or None - why THIS folder must keep its dev kit.

    The existence of a declaration file is not the question: a two-tree box has one in the
    LIVE tree too, and that tree is exactly the one that wants pruning (measured
    "one tree" so nothing ever got cleaned). The question is whether a `dev` role points at
    this folder, or a bare `dev` entry (no path, or a `same_as` alias) describes the tree it
    sits in. Fail SAFE: an unreadable or odd declaration counts as dev, because pruning a
    real dev tree deletes the tests out from under whoever edits them.
    """
    f = BASE_DIR / "maintenance" / "where-roles.json"
    if not f.exists():
        # No declaration: does this LOOK like a checkout? Evidence the prune itself would
        # destroy - .git/, tests/run_all.py, requirements-test.txt. Without this, a
        # contributor who cloned and never ran where.py lost tests/, docs/ AND where.py -
        # the only tool that could have declared the tree - in one update. Fails safe in
        # the same direction as a corrupt declaration.
        if ((BASE_DIR / ".git").exists()
                or (BASE_DIR / "tests" / "run_all.py").exists()
                or (BASE_DIR / "requirements-test.txt").exists()):
            return "checkout"
        return None
    try:
        data = json.loads(f.read_text(encoding="utf-8"))
    except Exception:                                    # noqa: BLE001
        return "declared"
    if not isinstance(data, list):
        return "declared"
    for ent in data:
        if not isinstance(ent, dict) or str(ent.get("role") or "").lower() != "dev":
            continue
        target = str(ent.get("path") or ent.get("dir") or "").strip()
        if not target:
            return "declared"                            # a bare dev entry: this tree
        try:
            if Path(target).expanduser().resolve() == BASE_DIR.resolve():
                return "declared"
        except OSError:
            return "declared"
    return None


def _prune_dev_kit(keep_dev=False):
    """Delete the project's own kit from this install, and say what went.

    Returns a one-line report, or "" when nothing was removed. Never prunes the
    development tree - whether maintenance/where-roles.json declares it or the folder
    simply looks like a checkout (.git/, tests/run_all.py) - because deleting the tests out
    from under the person editing them is not an update, it is sabotage. Keeps quiet about
    it: the keep is the normal, correct outcome, not news. Deletes BY NAME - never
    "anything the package lacks" - because those folders also hold a host's own files
    (private_rules.py, where-roles.json, sessions/, notes) that must survive an update.
    """
    import shutil
    if keep_dev or os.environ.get("TINYCMDR_UPDATE_KEEP_DEV"):
        return ""
    if _dev_tree_reason() is not None:
        return ""
    gone = []
    for rel in _DEV_ONLY_PATHS:
        p = BASE_DIR / rel.strip("/")
        if p.is_dir():
            shutil.rmtree(p, ignore_errors=True)
            gone.append(rel.strip("/") + "/")
        elif p.is_file():
            try:
                p.unlink()
                gone.append(rel.strip("/"))
            except OSError:
                pass
    md = BASE_DIR / "maintenance"
    if md.is_dir():
        for name in _DEV_MAINTENANCE_DROP:
            f = md / name
            if f.is_file():
                try:
                    f.unlink()
                    gone.append("maintenance/" + name)
                except OSError:
                    pass
    if not gone:
        return ""
    return _NARROW_NOTE + " (" + ", ".join(gone[:6]) + ("..." if len(gone) > 6 else "") + ")"


# ---- the release artifact, fetched and checked the way the installer checks it ---------
def _update_base():
    return str(CONFIG["agent"].get("update_url")
               or os.environ.get("TINYCMDR_UPDATE_URL")
               or DEFAULT_UPDATE_URL).rstrip("/")


def _update_asset():
    if IS_WINDOWS:
        return "tinycmdr-win.zip"
    if sys.platform == "darwin":
        return "tinycmdr-macos.zip"
    return "tinycmdr-linux.tar.gz"


def _download(url, dest):
    """(ok, why). requests when it is there, urllib otherwise - both already present."""
    try:
        import requests
        with requests.get(url, timeout=60, stream=True) as r:
            if r.status_code != 200:
                return False, "HTTP %d" % r.status_code
            with open(dest, "wb") as fh:
                for chunk in r.iter_content(65536):
                    fh.write(chunk)
        return True, ""
    except Exception:                                    # noqa: BLE001 - urllib is the retry
        try:
            import urllib.request
            with urllib.request.urlopen(url, timeout=60) as resp, open(dest, "wb") as fh:
                shutil.copyfileobj(resp, fh)
            return True, ""
        except Exception as e2:                          # noqa: BLE001
            return False, "%s: %s" % (type(e2).__name__, e2)


def _sha256(path):
    import hashlib
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for block in iter(lambda: fh.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def _verify_asset(asset_path, sums_path, asset_name):
    """(ok, why): the ONE file this run fetched, against its own SHA256SUMS line.

    The same contract install.sh uses. A mismatch means a corrupted or truncated transfer
    and nothing is unpacked. Releases are unsigned, so this checks the bytes arrived whole -
    it does not prove who made them.
    """
    try:
        lines = Path(sums_path).read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError as e:
        return False, "could not read SHA256SUMS: %s" % e
    want = ""
    for ln in lines:
        parts = ln.split()
        if len(parts) >= 2 and parts[-1].lstrip("*") == asset_name:
            want = parts[0].strip().lower()
            break
    if not want:
        return False, "SHA256SUMS does not cover %s - the release is broken" % asset_name
    got = _sha256(asset_path)
    if got != want:
        return False, ("the download does not match SHA256SUMS (got %s..., expected %s...) - "
                       "a corrupted or truncated transfer; nothing was unpacked"
                       % (got[:12], want[:12]))
    return True, ""


def _extract_release(archive, dest):
    """Unpack an archive into `dest`; return the folder holding tinycmdr.py, or None."""
    import tarfile
    import zipfile
    dest.mkdir(parents=True, exist_ok=True)
    if str(archive).lower().endswith(".zip"):
        with zipfile.ZipFile(archive) as z:
            z.extractall(dest)
    else:
        with tarfile.open(archive) as t:
            try:
                t.extractall(dest, filter="data")        # 3.12+: refuse odd members
            except TypeError:                            # older pythons have no filter
                t.extractall(dest)
    for cand in sorted(dest.rglob("tinycmdr.py")):
        return cand.parent
    return None


def _apply_package(root):
    """Write the package's files over this install. Returns (written, skipped).

    Never overwrites an operator's edited soul.md (see preserve_edited_soul) and never
    copies a replaced file aside: a stamped .bak per file per update is how an install
    grows by gigabytes for no reason, and the release it came from stays downloadable.
    Host state (config.json, .env, sessions/, notes, tools/, skills/) is simply not in
    the package, so it cannot be touched by construction.
    """
    written, skipped = [], []
    for src in sorted(root.rglob("*")):
        if not src.is_file():
            continue
        rel = src.relative_to(root)
        if rel.parts and rel.parts[0] in ("dist", ".git"):
            continue
        dest = BASE_DIR / rel
        try:
            new = src.read_bytes()
        except OSError:
            continue
        # A host-owned path is only ever SEEDED: an existing one is the operator's (or the
        # agent's own tool) and is left exactly as it is. This is the whole per-host set,
        # not just soul.md.
        if _host_owned(rel) and dest.exists():
            skipped.append(rel.as_posix())
            continue
        old = dest.read_bytes() if dest.exists() else None
        if old == new:
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        atomic_write_bytes(dest, new)
        written.append(rel.as_posix())
    return written, skipped


def _package_differs(root):
    """True when applying this package would write anything - content, not the label.

    `update` used to trust the VERSION string alone, so a half-applied release (a write
    loop killed by disk-full, an indexer holding a file open) was told "already up to
    date" for ever, and the one command that repairs it refused to run.
    Same skip rules as _apply_package: an existing host-owned destination is the
    operator's own file and never counts as a difference.
    """
    for src in sorted(root.rglob("*")):
        if not src.is_file():
            continue
        rel = src.relative_to(root)
        if rel.parts and rel.parts[0] in ("dist", ".git"):
            continue
        dest = BASE_DIR / rel
        try:
            new = src.read_bytes()
        except OSError:
            continue
        if _host_owned(rel) and dest.exists():
            continue
        old = dest.read_bytes() if dest.exists() else None
        if old != new:
            return True
    return False


def _verb_update(rest):
    """`update [--full]` or `update <file.py|zip|folder>` — put a newer build in place.

    With no argument it downloads the RELEASE package for this host, checks it against the
    release's SHA256SUMS, applies it and drops the project's own kit. It never reads main
    and never needs git: the artifact is the same one the one-line installer installs, so
    "a behaviour was shipped" and "a user receives it" are the same act, and a user can
    never receive unreleased code.

    With a path, the pushed-by-hand dance: check the source really is a build (a VERSION
    line, and `--version` runs), back the current files up beside themselves, write the new
    bytes, and say what changed.

    `--full` keeps the project's own kit (tests/, docs/, the maintenance scripts) on this
    host instead of pruning it. Nothing here ever restarts anything: the operator decides
    when a running bot is replaced."""
    import shutil
    import tempfile
    import zipfile
    keep_dev = "--full" in rest
    rest = [a for a in rest if a != "--full"]
    if not rest:
        asset = _update_asset()
        base = _update_base()
        # No git, ever: the update is a verified file copy, so a dirty, pruned or gitless
        # checkout cannot block it (installers 1.0.46-1.0.48 used `git pull --ff-only`).
        print("updating from %s/%s" % (base, asset))
        work = Path(tempfile.mkdtemp(prefix="tinycmdr-update-"))
        try:
            archive = work / asset
            ok, why = _download(base + "/" + asset, archive)
            if not ok:
                print("could not download %s: %s" % (asset, why), file=sys.stderr)
                return 1
            sums = work / "SHA256SUMS"
            ok_sum, why_sum = _download(base + "/SHA256SUMS", sums)
            if not ok_sum:
                if os.environ.get("TINYCMDR_NO_SUMS") == "1":
                    print("    (SHA256SUMS could not be fetched (%s) and TINYCMDR_NO_SUMS=1 "
                          "says carry on - this download is UNCHECKED)" % why_sum)
                else:
                    print("could not fetch SHA256SUMS (%s), so this download cannot be "
                          "checked. Re-run it, or set TINYCMDR_NO_SUMS=1 to skip the check "
                          "deliberately." % why_sum, file=sys.stderr)
                    return 1
            else:
                ok, why = _verify_asset(archive, sums, asset)
                if not ok:
                    print(why, file=sys.stderr)
                    return 1
                print("    the download matches SHA256SUMS. Releases are unsigned, so this "
                      "catches a corrupted or truncated transfer, not a replaced release.")
            root = _extract_release(archive, work / "pkg")
            if root is None:
                print("the archive did not contain a tinycmdr-* folder", file=sys.stderr)
                return 1
            new_app = root / "tinycmdr.py"
            text = new_app.read_text(encoding="utf-8", errors="replace")
            m = re.search(r'^VERSION\s*=\s*"([^"]+)"', text, re.M)
            if not m:
                print("%s has no VERSION line - refusing to install it" % new_app,
                      file=sys.stderr)
                return 1
            new_version = m.group(1)
            this_version = _disk_version()
            if new_version == this_version and not _package_differs(root):
                # A TRUE no-op: change NOTHING. This branch used to prune the dev kit,
                # so "already up to date" deleted tests/docs while refusing the repair
                # A half-applied update needed.
                print("already up to date: VERSION %s" % this_version)
                return 0
            if new_version == this_version:
                print("VERSION %s is already here, but this package's files differ - "
                      "applying it to repair the install" % this_version)
            stamp = time.strftime("%Y%m%d-%H%M%S")
            _kept = preserve_edited_soul(stamp)
            if _kept:
                print("your persona is an edit to a shipped file - copied to %s first"
                      % Path(_kept).name)
            written, skipped = _apply_package(root)
            # Host-owned file whose shipped default this package MOVED: the one gap worth
            # a line, because the operator is missing a change right now.
            for _line in _host_gap_notes(written):
                print("    " + _line)
            ensure_launcher_executable()
            if skipped:
                print("    kept your versions of: %s" % ", ".join(skipped[:3]))
            print("wrote %d file(s)%s"
                  % (len(written),
                     (": " + ", ".join(written[:5]) + ("..." if len(written) > 5 else ""))
                     if written else ""))
            if "requirements.txt" in written:
                # The bounds in that file are load-bearing and nothing installs from
                # it here, so the operator gets the exact command instead of a new
                # Build meeting an old venv. Deliberately NOT
                # automatic: an update should not reach the network beyond the
                # release package itself.
                _venv_py = BASE_DIR / "venv" / ("Scripts/python.exe" if IS_WINDOWS
                                                else "bin/python")
                print("dependencies changed in this release - reconcile the venv:")
                print("    %s -m pip install -r %s"
                      % (_venv_py, BASE_DIR / "requirements.txt"))
            note = _prune_dev_kit(keep_dev)
            if note:
                print(note)
            if new_version != this_version:
                print("VERSION %s -> %s" % (this_version, new_version))
            else:
                print("repaired: %d file(s) restored from the %s package"
                      % (len(written), new_version))
            print("Restart tinycmdr to run new build: `tinycmdr restart`")
            return 0
        finally:
            shutil.rmtree(work, ignore_errors=True)
    src = Path(rest[0]).expanduser()
    if not src.exists():
        print("no such file or folder: %s" % src, file=sys.stderr)
        return 2
    work = None
    try:
        if src.is_dir():
            root = src
        elif src.suffix.lower() == ".zip":
            work = Path(tempfile.mkdtemp(prefix="tinycmdr-update-"))
            with zipfile.ZipFile(src) as z:
                z.extractall(work)
            root = work
        else:
            root = src.parent
        # A named .py IS the candidate (the folder is only searched for a zip or a folder):
        # "update ./somewhere/tinycmdr.py" must not silently pick up a neighbour instead.
        named = src if src.is_file() and src.suffix.lower() == ".py" else None

        def find(name):
            # A named file means exactly that file: falling back to its folder is how
            # `update bad.py` quietly installed the build sitting next to it.
            if named is not None:
                return named if named.name == name else None
            direct = (root / name) if root.is_dir() else None
            if direct and direct.is_file():
                return direct
            for hit in sorted(root.rglob(name)):
                if hit.is_file():
                    return hit
            return None
        new_app = find("tinycmdr.py")
        if new_app is None:
            if named is not None:
                # The rule, said out loud. Measured 2026-10-03: `update C:\...\tinycmdr-cand.py`
                # answered "is that a build?" about a perfectly good build, and cost a deploy
                # cycle working out that the NAME was the problem.
                print("the candidate must be named tinycmdr.py (this one is %s) - rename it, "
                      "or point `update` at its folder or a zip" % named.name, file=sys.stderr)
            else:
                print("no tinycmdr.py in %s — is that a build?" % src, file=sys.stderr)
            return 1
        text = new_app.read_text(encoding="utf-8", errors="replace")
        m = re.search(r'^VERSION\s*=\s*"([^"]+)"', text, re.M)
        if not m:
            print("%s has no VERSION line - refusing to install it over this one" % new_app,
                  file=sys.stderr)
            return 1
        new_version = m.group(1)
        rc, out, err, _ = run_capture([sys.executable, str(new_app), "--version"], 120)
        if rc != 0 or "tinycmdr" not in (out or ""):
            print("the candidate does not run: %s %s" % (rc, (err or out or "").strip()[:200]),
                  file=sys.stderr)
            return 1
        print("candidate: %s (VERSION %s, runs ok)" % (new_app, new_version))
        print("this one : %s (VERSION %s)" % (CONFIG_PATH.parent, VERSION))
        changed = []
        for name in ("tinycmdr.py",):
            candidate = find(name)
            if candidate is None:
                continue
            target = BASE_DIR / name
            old = target.read_bytes() if target.exists() else b""
            new = candidate.read_bytes()
            if old == new:
                continue
            # The live build is replaced through the atomic writer for the same reason
            # a state file is: a torn write here bricks the install. The candidate was
            # already read and run as text, so decoding it is safe.
            atomic_write_text(target, new.decode("utf-8"))
            changed.append("%s (%d -> %d bytes)" % (name, len(old), len(new)))
        if not changed:
            print("already the same bytes: nothing to do")
            return 0
        for c in changed:
            print("  updated %s" % c)
        print("no copy of the old build was kept: `update` the release you came from to roll back")
        if _verb_running() is True:
            print("a running bot still runs the OLD bytes: `tinycmdr restart` to switch.")
        return 0
    finally:
        if work is not None:
            shutil.rmtree(work, ignore_errors=True)


CLEAN_JUNK = ("*.bak", "*.bak-*", "*.pre-*", "*.orig", "*.rej", "*~", "*.py.new",
              "*.arm-tmp", "*.corrupt-*", "*.tmp-*")
CLEAN_DIRS = ("__pycache__", "snapshots", "tests", "docs", "inbox")
CLEAN_KEEP = ("sessions", "skills", "tools", "uploads", "spill", "logs", "venv", "dist",
              "assets", "maintenance", "tmp")


def _verb_clean(rest):
    """`clean [--yes]` — say what is junk in this folder, then remove it on request.

    An install folder is runtime, not an archive: backed-up copies and staging files pile up
    (an install updated for a year carries a stamped copy of every build it ever ran, and
    pushes leave .bak files behind), and `tests/`, `docs/`, `snapshots/` and `inbox/` are
    build-time things a reader's folder does not need. DRY RUN unless --yes: this deletes
    files, and a wrong glob here is somebody's session history."""
    apply = "--yes" in rest or "--force" in rest
    junk, dirs = [], []
    for pattern in CLEAN_JUNK:
        for hit in sorted(BASE_DIR.glob(pattern)):
            if hit.is_file():
                junk.append(hit)
    seen = set()
    for name in CLEAN_DIRS:
        d = BASE_DIR / name
        if d.is_dir() and name not in CLEAN_KEEP and str(d) not in seen:
            seen.add(str(d))
            dirs.append(d)
    print("install: %s" % BASE_DIR)
    print("%s: %d file(s), %d folder(s)" % ("removing" if apply else "would remove",
                                            len(junk), len(dirs)))
    for f in junk[:40]:
        print("  %-52s %8d bytes" % (f.name, f.stat().st_size))
    if len(junk) > 40:
        print("  ... %d more" % (len(junk) - 40))
    for d in dirs:
        n = sum(1 for _ in d.rglob("*") if _.is_file())
        print("  %-52s %8d file(s)" % (d.name + "/", n))
    kept = [n for n in CLEAN_KEEP if (BASE_DIR / n).exists()]
    print("kept   : %s" % ", ".join(kept))
    if not apply:
        print("\nnothing was deleted. Run it again with --yes to remove the list above.")
        return 0
    for f in junk:
        try:
            f.unlink()
        except OSError as e:
            print("  could not remove %s: %s" % (f.name, e), file=sys.stderr)
    import shutil
    for d in dirs:
        try:
            shutil.rmtree(d)
        except OSError as e:
            print("  could not remove %s/: %s" % (d.name, e), file=sys.stderr)
    print("\nremoved %d file(s) and %d folder(s)." % (len(junk), len(dirs)))
    return 0


def _verb_model_endpoints(rest):
    """`model add` / `model remove`: the endpoints this install can route to."""
    what, args = rest[0], list(rest[1:])
    opts, positional, i = {}, [], 0
    while i < len(args):
        a = args[i]
        if a in ("--model", "--alias", "--key-env"):
            if i + 1 >= len(args):
                print("%s needs a value" % a, file=sys.stderr)
                return 2
            opts[a[2:]] = args[i + 1]
            i += 2
            continue
        if a in ("--primary", "--force"):
            opts[a[2:]] = True
            i += 1
            continue
        positional.append(a)
        i += 1
    if what in ("remove", "rm"):
        return _verb_model_remove(positional)
    return _verb_model_add(opts, positional)


def endpoint_report():
    """The primary endpoint, and whether it answers - the sentence a reader needs.

    Written for the two ways this goes wrong: a typo at install time (invisible until the
    first call fails) and a box that is simply not up yet. Both end at the same command.
    """
    cur = str(CONFIG["llm"].get("base_url") or "")
    lines = ["primary endpoint: %s" % (cur or "(none set)")]
    if not cur:
        lines.append("set it with: tinycmdr model endpoint <url>")
        return lines
    res = probe_endpoint(cur, _primary_api_key())
    if not res["ok"]:
        if res["status"] in (401, 403):
            lines.append("it did NOT answer: the provider refused that key (HTTP %d)"
                         % res["status"])
            lines.append("fix the link or the key with: tinycmdr model endpoint <url>")
        else:
            lines.append("it did NOT answer: %s" % res["error"])
            lines.append("fix a typo with: tinycmdr model endpoint <url>")
    elif res["ids"]:
        lines.append("it answers, and advertises: %s" % ", ".join(res["ids"][:12]))
    else:
        lines.append("it answers, but advertises no model list")
    return lines


def set_primary_endpoint(url, force=False, key=None, clear_api_key=False):
    """Point llm.base_url at `url`, after asking it for its model list.

    Returns (rc, ids, lines): the caller prints the lines, and a door that can host the
    picker offers the ids as a choice. A URL that does not answer is REFUSED unless --force
    - a wrong endpoint writes no error until the first request, which is exactly why this
    command exists and why the setup wizard probes before it moves on. The probe carries
    the primary key (TINYCMDR_LLM_API_KEY / llm.api_key), so a hosted endpoint is checked
    authenticated rather than reported down.
    """
    url = str(url or "").strip().rstrip("/")
    if not url.lower().startswith(("http://", "https://")):
        return 2, [], ["a base_url starts with http:// or https:// "
                       "(e.g. http://<lan-box>:8081/v1)"]
    res = probe_endpoint(url, _primary_api_key() if key is None else key)
    ids = list(res["ids"]) if res["ok"] else None
    if ids is None and not force:
        return 1, [], ["%s did not answer its model list (%s)." % (url, res["error"]),
                       "Check the host and port (the server may not be running yet), or write "
                       "it anyway with --force."]
    raw, err = _config_raw()
    if err:
        return 1, [], [err]
    prev = str((raw.get("llm") or {}).get("base_url") or "")
    raw.setdefault("llm", {})["base_url"] = url
    if clear_api_key:
        # The key this run just put in .env must not ALSO sit in config.json - that copy is
        # the one the agent can read into a prompt, and it would shadow nothing (env wins)
        # while still being quotable.
        raw.setdefault("llm", {}).pop("api_key", None)
    err = _config_write_raw(raw)
    if err:
        return 1, [], [err]
    err = _config_take_effect()
    if err:
        return 1, [], [err]
    lines = ["primary endpoint: %s -> %s" % (prev or "(none)", url)]
    if ids is None:
        lines.append("note: %s did not answer - it is in config.json unverified" % url)
    elif ids:
        lines.append("it advertises: %s" % ", ".join(ids[:12]))
    else:
        lines.append("it answered, but advertises no model list")
    return 0, list(ids or []), lines


def _ask_secret(prompt):
    """Read a secret at the terminal without echoing it; a plain line on a pipe.

    Kept in one place so the fix doors share it and a test can replace the ASKING
    without replacing the flow."""
    import getpass
    try:
        if sys.stdin.isatty():
            return getpass.getpass(prompt).strip()
    except Exception:                                            # noqa: BLE001
        pass
    return (sys.stdin.readline() or "").strip()


def _verb_model_endpoint(args):
    """`model endpoint [<url>]`: read the endpoint, or correct it - KEY included.

    A cloud primary has TWO things that can be wrong and look like one: the link and the
    key. A refusal (HTTP 401/403) asks for the key HERE, writes it to .env and re-probes,
    so a mistyped link or a stale key is repaired from this door instead of by hand-editing
    config.json - and the report above names the same command, so the way out is always
    reachable."""
    force = any(a.lstrip("-").lower() in ("force", "f") for a in args)
    urls = [a for a in args if not a.startswith("-")]
    if not urls:
        lines = endpoint_report()
        print("\n".join(lines))
        ok = "it answers" in lines[1]
        if not ok and pick_terminal_ready():
            ans = input("  Set it up now? [Y/n]: ").strip().lower()
            if ans in ("", "y", "yes"):
                return _model_setup_wizard()
        return 0 if ok else 1
    url = urls[0].strip().rstrip("/")
    if not url.lower().startswith(("http://", "https://")):
        print("a base_url starts with http:// or https:// "
              "(e.g. http://<lan-box>:8081/v1)", file=sys.stderr)
        return 2
    key = _primary_api_key()
    typed_key = False
    key_tries = 0
    interactive = sys.stdin.isatty() and _CLI.get("app") is None
    while True:
        res = probe_endpoint(url, key)
        if res["ok"] or res["status"] not in (401, 403) or not interactive:
            break
        key_tries += 1
        if key_tries >= 3:
            print("the provider still refuses the key - nothing was written",
                  file=sys.stderr)
            return 1
        print(red("  the provider refused that key (HTTP %d)" % res["status"]))
        ans = _ask_secret("  API key (input hidden, try again): ")
        if not ans:
            print("nothing written - the key was empty", file=sys.stderr)
            return 1
        key, typed_key = ans, True
    rc, ids, lines = set_primary_endpoint(url, force, key=key, clear_api_key=typed_key)
    for line in lines:
        print(line, file=sys.stderr if rc else sys.stdout)
    if rc:
        return rc
    if typed_key:
        if _env_set_safe("TINYCMDR_LLM_API_KEY", key):
            os.environ["TINYCMDR_LLM_API_KEY"] = key
            CONFIG["llm"]["api_key"] = key
            print("key saved to %s as TINYCMDR_LLM_API_KEY" % ENV_FILE.name)
    if not ids:
        print("choose one with: tinycmdr model use <name>")
        return 0
    if pick_terminal_ready():
        state = ModelPick([(i, "advertised by %s" % url, False) for i in ids],
                          title="Which model does %s serve? (%d advertised)"
                                % (url, len(ids)),
                          scope="ENTER sets llm.model")
        picked = run_model_pick(state)
        if picked:
            print()
            return _switch_global_model(picked)
        print("model unchanged - choose one later with: tinycmdr model use <name>")
    else:
        print("choose one with: tinycmdr model use <name>")
    return 0


def _pick_advertised_model(url, ids):
    """A new endpoint advertising several ids: move through them, or "" to let the caller
    explain. Typing an id you just saw printed is the step the predecessor harness's
    picker exists to remove."""
    if not pick_terminal_ready():
        return ""
    state = ModelPick([(i, "advertised by %s" % url, False) for i in ids],
                      title="Which model does %s serve? (%d advertised)" % (url, len(ids)),
                      scope="ENTER writes it into config.json - ESC cancels")
    return run_model_pick(state) or ""


def _next_endpoint_env(fbs):
    """The first free TINYCMDR_ENDPOINT<n>_API_KEY, so a new key never lands on an
    existing entry's variable."""
    used = {str(fb.get("api_key_env") or "") for fb in fbs if isinstance(fb, dict)}
    n = 1
    while ("TINYCMDR_ENDPOINT%d_API_KEY" % n) in used:
        n += 1
    return "TINYCMDR_ENDPOINT%d_API_KEY" % n


def _verb_model_add_interactive(opts):
    """`model add` with no URL: the same cloud-or-local conversation `setup` runs.

    Adds a FALLBACK by default (the endpoint the bot already uses keeps answering), or
    becomes the primary with --primary. The key is asked here, proved against the
    provider with a bearer GET /models, and written to .env - never to config.json."""
    print(bold("Add a model endpoint"))
    raw, err = _config_raw()
    if err:
        print(err, file=sys.stderr)
        return 1
    llm = raw.setdefault("llm", {})
    fbs = llm.setdefault("fallbacks", [])
    if not isinstance(fbs, list):
        print("llm.fallbacks in config.json is not a list - fix that first",
              file=sys.stderr)
        return 1
    primary = bool(opts.get("primary"))
    target = _ask_model_target(default_url=str(llm.get("base_url") or "") if primary else "",
                               default_model=str(llm.get("model") or "") if primary else "",
                               default_key=_primary_api_key() if primary else "")
    if target is None:
        print("nothing added", file=sys.stderr)
        return 1
    url, want, key = target["url"], target["model"], target["key"]
    if not primary and url.lower() == str(llm.get("base_url") or "").rstrip("/").lower():
        print("%s IS the primary already - pass --primary to change the primary's URL "
              "or model" % url, file=sys.stderr)
        return 2
    route = want
    if primary:
        if not _is_local_url(url) and not key:
            # The probe above already proved /models answers; a missing key is worth SAYING,
            # not refusing over (a provider can serve /models anonymously while chat needs
            # the key, and the reader can add it later). The scripted door, which never
            # probed, still refuses.
            print(dim("   note: no key given for %s - if chat needs one, put it in %s as\n"
                      "   TINYCMDR_LLM_API_KEY with `tinycmdr token set TINYCMDR_LLM_API_KEY`."
                      % (url, ENV_FILE.name)))
        llm["base_url"], llm["model"] = url, want
        _key_saved = bool(key) and _env_set_safe("TINYCMDR_LLM_API_KEY", key)
        if _key_saved:
            os.environ["TINYCMDR_LLM_API_KEY"] = key
        line = "primary: %s -> %s%s" % (url, want,
                                        " (key in .env as TINYCMDR_LLM_API_KEY)"
                                        if _key_saved else "")
    else:
        for fb in fbs:
            if (isinstance(fb, dict)
                    and str(fb.get("base_url") or "").rstrip("/").lower() == url.lower()):
                print("%s is already there (alias %r)" % (url, fb.get("alias") or ""),
                      file=sys.stderr)
                return 2
        alias = input("   Alias, so `/model <alias>` switches to it (blank = none): ").strip()
        if alias and any(str(fb.get("alias") or "").lower() == alias.lower()
                         for fb in fbs if isinstance(fb, dict)):
            print("alias %r is already taken" % alias, file=sys.stderr)
            return 2
        entry = {"base_url": url, "model": want}
        if alias:
            entry["alias"] = alias
            route = alias
        if key:
            key_env = _next_endpoint_env(fbs)
            entry["api_key_env"] = key_env
            if _env_set_safe(key_env, key):
                os.environ[key_env] = key
        fbs.append(entry)
        line = "fallback: %s -> %s%s%s" % (
            url, want, " (alias %s)" % alias if alias else "",
            " (key in .env as %s)" % entry.get("api_key_env") if key else "")
        # A cloud endpoint just joined the chain. Whether automatic failover may use
        # it is the operator's call, and this is the moment they are thinking about
        # it - asking here is the door that keeps them out of config.json.
        if not _is_local_url(url) and not llm.get("allow_cloud_fallback", False):
            ans = input("   Allow automatic failover to this off-LAN endpoint when "
                        "the local one fails? [y/N]: ").strip().lower()
            if ans in ("y", "yes"):
                llm["allow_cloud_fallback"] = True
                print(dim("   cloud failover: on (change it later with "
                         "`tinycmdr model failover off`)"))
            else:
                print(dim("   cloud failover: off - reach it on purpose with "
                         "`/model %s` or `tinycmdr model failover on`" % (alias or want)))
    err = _config_write_raw(raw)
    if err:
        print(err, file=sys.stderr)
        return 1
    err = _config_take_effect()
    if err:
        print(err, file=sys.stderr)
        return 1
    print(line)
    if not primary and not _is_local_url(url):
        print("note: %s is off-LAN, so automatic failover only reaches it while "
              "llm.allow_cloud_fallback is true; `/model %s` routes there explicitly."
              % (url, route))
    if _verb_running() is True:
        print("a running bot reads config.json at start: `tinycmdr restart`.")
    return 0


def _verb_model_add(opts, positional):
    if not positional:
        # No URL: ask, the same way `setup` does. A pipe or a script still gets the usage
        # text, because a prompt there would read EOF and look like a hang.
        if sys.stdin.isatty() and _CLI.get("app") is None:
            return _verb_model_add_interactive(opts)
        print(MODEL_ADD_HELP, file=sys.stderr)
        return 2
    url = positional[0].strip().rstrip("/")
    if not url.lower().startswith(("http://", "https://")):
        print("a base_url starts with http:// or https:// "
              "(e.g. http://<lan-box>:8081/v1)", file=sys.stderr)
        return 2
    key_env = str(opts.get("key-env") or "").strip()
    if key_env and not re.fullmatch(r"[A-Z][A-Z0-9_]*", key_env):
        print("--key-env takes a .env KEY NAME: capitals, digits, underscore",
              file=sys.stderr)
        return 2
    alias = str(opts.get("alias") or "").strip()
    raw, err = _config_raw()
    if err:
        print(err, file=sys.stderr)
        return 1
    llm = raw.setdefault("llm", {})
    fbs = llm.setdefault("fallbacks", [])
    if not isinstance(fbs, list):
        print("llm.fallbacks in config.json is not a list - fix that first",
              file=sys.stderr)
        return 1
    if url.lower() == str(llm.get("base_url") or "").rstrip("/").lower() \
            and not opts.get("primary"):
        print("%s IS the primary already" % url, file=sys.stderr)
        return 2
    for fb in fbs:
        if not isinstance(fb, dict):
            continue
        if str(fb.get("base_url") or "").rstrip("/").lower() == url.lower():
            print("%s is already there (alias %r) - `tinycmdr model` lists them"
                  % (url, fb.get("alias") or ""), file=sys.stderr)
            return 2
        if alias and str(fb.get("alias") or "").lower() == alias.lower():
            print("alias %r is taken by %s" % (alias, fb.get("base_url")),
                  file=sys.stderr)
            return 2
    want = str(opts.get("model") or "").strip()
    ids = _probe_model_ids(url, _endpoint_key(key_env))
    if ids is None:
        if not opts.get("force"):
            print("the endpoint at %s did not answer its model list, so the model id "
                  "cannot be checked.\nFix the url, or add it unverified: --force"
                  % url, file=sys.stderr)
            return 1
        print("note: %s did not answer - writing it unverified" % url)
    else:
        if want and want.lower() not in [x.lower() for x in ids]:
            print("%s advertises %s - not %r"
                  % (url, ", ".join(ids[:12]) or "nothing", want), file=sys.stderr)
            return 2
        if not want:
            if len(ids) == 1:
                want = ids[0]
            else:
                want = _pick_advertised_model(url, ids)
            if not want:
                print("which model? %s advertises:\n  %s\npass --model <name>"
                      % (url, "\n  ".join(ids[:12])), file=sys.stderr)
                return 2
    if not want:
        print("a fallback entry needs a model id: pass --model <name>", file=sys.stderr)
        return 2
    if opts.get("primary"):
        if not _is_local_url(url) and not _primary_api_key() and not opts.get("force"):
            print("a hosted endpoint as the PRIMARY needs its API key, and the primary's\n"
                  "key lives in %s as TINYCMDR_LLM_API_KEY (the one file the agent\n"
                  "cannot read into a prompt). Put it there with:\n"
                  "  tinycmdr token set TINYCMDR_LLM_API_KEY\n"
                  "or write the endpoint unverified with --force."
                  % ENV_FILE.name, file=sys.stderr)
            return 1
        llm["base_url"], llm["model"] = url, want
        line = "primary: %s -> %s" % (url, want)
    else:
        entry = {"base_url": url, "model": want}
        if alias:
            entry["alias"] = alias
        if key_env:
            entry["api_key_env"] = key_env
        fbs.append(entry)
        line = "fallback: %s -> %s%s%s" % (
            url, want, " (alias %s)" % alias if alias else "",
            " (key from %s)" % key_env if key_env else "")
    err = _config_write_raw(raw)
    if err:
        print(err, file=sys.stderr)
        return 1
    err = _config_take_effect()
    if err:
        print(err, file=sys.stderr)
        return 1
    print(line)
    if key_env and key_env not in _env_file_keys():
        print("note: %s is not in %s yet. Put the value there with:\n"
              "  tinycmdr token set %s      (reads it from stdin, never from a "
              "command line)" % (key_env, ENV_FILE.name, key_env))
    if not _is_local_url(url):
        print("note: %s is off-LAN, so automatic failover only reaches it while "
              "llm.allow_cloud_fallback is true; `/model %s` routes there explicitly."
              % (url, alias or want))
    if _verb_running() is True:
        print("a running bot reads config.json at start: `tinycmdr restart`.")
    return 0


def _verb_model_remove(positional):
    if not positional:
        print("model remove <name|alias|url> - which entry?", file=sys.stderr)
        return 2
    want = positional[0].strip().rstrip("/").lower()
    raw, err = _config_raw()
    if err:
        print(err, file=sys.stderr)
        return 1
    llm = raw.setdefault("llm", {})
    fbs = llm.get("fallbacks") or []
    if not isinstance(fbs, list):
        print("llm.fallbacks in config.json is not a list - fix that first",
              file=sys.stderr)
        return 1
    keep, gone = [], None
    for fb in fbs:
        if not isinstance(fb, dict):
            keep.append(fb)
            continue
        keys = [str(fb.get(k) or "").rstrip("/").lower()
                for k in ("base_url", "model", "alias")]
        if gone is None and want in keys:
            gone = fb
            continue
        keep.append(fb)
    if gone is None:
        print("no fallback entry matches %r (`tinycmdr model` lists them)" % want,
              file=sys.stderr)
        return 2
    llm["fallbacks"] = keep
    err = _config_write_raw(raw)
    if err:
        print(err, file=sys.stderr)
        return 1
    err = _config_take_effect()
    if err:
        print(err, file=sys.stderr)
        return 1
    print("removed: %s -> %s" % (gone.get("base_url"), gone.get("model")))
    if _verb_running() is True:
        print("a running bot reads config.json at start: `tinycmdr restart`.")
    return 0


def _verb_model_failover(rest):
    """`model failover [on|off]`: may a local failure re-send the conversation to an
    off-LAN endpoint?

    The flag shipped `false` with no interactive door - the only way to change it was
    hand-editing config.json, which an operator should never have to do. OFF means an
    off-LAN endpoint is reached only when you switch to it on purpose (`model use`,
    `/model <alias>`); ON lets automatic failover use it when the local box fails.
    """
    want = (rest[0].strip().lower() if rest else "")
    raw, err = _config_raw()
    if err:
        print(err, file=sys.stderr)
        return 1
    llm = raw.setdefault("llm", {})
    cur = bool(llm.get("allow_cloud_fallback", False))
    if not want:
        print("cloud failover: %s" % ("on" if cur else "off"))
        cloud = [str(f.get("base_url")) for f in (llm.get("fallbacks") or [])
                 if isinstance(f, dict) and f.get("base_url")
                 and not _is_local_url(str(f["base_url"]))]
        if cloud:
            print("  off-LAN endpoint(s): %s" % ", ".join(cloud))
            if not cur:
                print("  off = they are only reached when you pick them on purpose "
                      "(`model use <alias>`, `/model <alias>`).")
        else:
            print("  no off-LAN endpoint is configured, so this changes nothing yet.")
        print("  set it with: tinycmdr model failover on|off")
        return 0
    if want not in ("on", "off", "true", "false", "yes", "no", "1", "0"):
        print("model failover on|off", file=sys.stderr)
        return 2
    val = want in ("on", "true", "yes", "1")
    llm["allow_cloud_fallback"] = val
    err = _config_write_raw(raw)
    if err:
        print(err, file=sys.stderr)
        return 1
    err = _config_take_effect()
    if err:
        print(err, file=sys.stderr)
        return 1
    print("cloud failover: %s" % ("on" if val else "off"))
    if _verb_running() is True:
        print("a running bot reads config.json at start: `/model` uses the new value from "
              "the next run; `tinycmdr restart` for the whole service.")
    return 0


def _model_setup_wizard():
    """The model-change wizard, in one call: local/cloud, key, link, probe, model list.

    It targets the PRIMARY - "change my model" is the one the bot answers with - and is
    reachable three ways, so nobody has to remember a command: `model setup`, the first row
    of the picker, and `model` itself when the endpoint is not usable. A door that cannot
    host the prompts (a pipe, --app, chat) gets the usage text instead of a hang."""
    if not (sys.stdin.isatty() and _CLI.get("app") is None):
        print("model setup needs a terminal to ask on: run `tinycmdr model setup` in a "
              "shell.", file=sys.stderr)
        print(MODEL_ADD_HELP, file=sys.stderr)
        return 2
    return _verb_model_add_interactive({"primary": True})


def _verb_model(rest):
    if rest and rest[0] in ("add", "remove", "rm"):
        return _verb_model_endpoints(rest)
    if rest and rest[0] in ("setup", "wizard", "new", "change"):
        return _model_setup_wizard()
    if rest and rest[0] in ("endpoint", "url", "host"):
        return _verb_model_endpoint(rest[1:])
    if rest and rest[0] in ("failover", "cloud-failover"):
        return _verb_model_failover(rest[1:])
    if rest and rest[0] in ("use", "set"):
        if len(rest) < 2:
            print("model use <name> — which model? (tinycmdr model lists them)",
                  file=sys.stderr)
            return 2
        want = " ".join(rest[1:]).strip()
        try:
            entries = model_catalog(force=True)
        except Exception as e:
            print("could not ask the endpoints for their model list: %s" % e,
                  file=sys.stderr)
            return 1
        names = [str(e.get("name")) for e in entries]
        match = next((e for e in entries
                      if str(e.get("name")).lower() == want.lower()
                      or str(e.get("send_as", "")).lower() == want.lower()), None)
        if match is None:
            print("no model named %r here. This install can route to: %s"
                  % (want, ", ".join(names)), file=sys.stderr)
            return 2
        prev, err = set_global_model(str(match.get("name")))
        if err:
            print("could not write config.json: %s" % err, file=sys.stderr)
            return 1
        print("default model: %s -> %s" % (prev, match.get("name")))
        if _verb_running() is True:
            print("a running bot reads config.json at start: use /model in chat, "
                  "or run `tinycmdr restart`.")
        return 0
    try:
        entries = model_catalog(force=True)
    except Exception as e:                                       # noqa: BLE001
        print("could not ask the endpoints for their model list: %s" % e,
              file=sys.stderr)
        return 1
    current = CONFIG["llm"]["model"]
    # Bare `model` does BOTH jobs now: pick among what answers, or get the wizard. When the
    # endpoint that must answer does not, a one-row list is useless - say what is wrong and
    # offer the wizard, so a wrong or dead endpoint is never a dead end. (tty only; a pipe
    # still gets the plain list it greps.)
    primary_url = CONFIG["llm"]["base_url"].rstrip("/")
    primary = probe_endpoint(primary_url, _primary_api_key(), timeout=10)
    if not primary["ok"] and pick_terminal_ready():
        print(red("  the model endpoint is not usable: %s"
                  % probe_sentence(primary_url, primary)))
        ans = input("  Set up a local or cloud model now? [Y/n]: ").strip().lower()
        if ans in ("", "y", "yes"):
            return _model_setup_wizard()
    # The picker, exactly as the predecessor harness opens one - ↑↓ to move, type to
    # filter, ENTER to switch, ESC to leave. Its first row is the way to ADD or CHANGE
    # an endpoint, so the wizard is one ENTER away instead of a command to remember.
    if entries and pick_terminal_ready():
        rows = model_pick_rows(entries, current)
        rows.insert(0, (MODEL_PICK_ADD,
                        "local or cloud, the key, then the models it serves", False))
        state = ModelPick(rows, current=current,
                          title="Select model (%d available)" % len(entries),
                          scope="ENTER sets the default in config.json - ESC leaves it alone")
        picked = run_model_pick(state)
        if picked == MODEL_PICK_ADD:
            return _model_setup_wizard()
        if picked:
            print()
            return _switch_global_model(picked)
        print("cancelled - nothing changed")
        return 0
    return _print_model_catalog(entries)


def endpoint_advertises():
    """[(url, ok, ids)] for the primary and every fallback: what each endpoint SAYS it
    serves. The picker can only offer what these return, so "why does it show N" is
    answerable without guessing which link the bot actually called."""
    out = []
    prim = str(CONFIG["llm"].get("base_url") or "").rstrip("/")
    if prim:
        res = probe_endpoint(prim, _primary_api_key())
        out.append((prim, res["ok"], res["ids"]))
    for fb in CONFIG["llm"].get("fallbacks") or []:
        if not isinstance(fb, dict):
            continue
        url = str(fb.get("base_url") or "").rstrip("/")
        if not url:
            continue
        res = probe_endpoint(url, fb.get("api_key") or _endpoint_key(fb.get("api_key_env")))
        out.append((url, res["ok"], res["ids"]))
    return out


def _print_model_catalog(entries):
    print("models this install can route to (%d):" % len(entries))
    for e in entries:
        bits = [str(e.get("name"))]
        if e.get("send_as") and e.get("send_as") != e.get("name"):
            bits.append("sends as %s" % e["send_as"])
        if e.get("where"):
            bits.append("at %s" % e["where"])
        # `alias` on a catalog entry is a BOOLEAN ("this name is an alias"), not the
        # name - printing it read as "localtest ... alias True". The entry's own name
        # IS the alias, and "sends as" above already gives the route.
        print("  %s" % "  ".join(bits))
    # What each endpoint advertised, so a short list is explainable: the picker only
    # offers what GET /models returned for the link and key this install holds. A name
    # that is configured but NOT in any advertised list is called out - that is the
    # usual reason a list looks short (or wrong), and it is a config problem, not a cap.
    eps = endpoint_advertises()
    advertised = set()
    for url, ok, ids in eps:
        if not ok:
            print("  endpoint %s did NOT answer GET /models - its models cannot appear"
                  % url)
        else:
            print("  endpoint %s advertises %d: %s"
                  % (url, len(ids), ", ".join(ids) or "(none)"))
            advertised.update(str(i).lower() for i in ids)
    if advertised:
        phantom = sorted({str(e.get("send_as") or e.get("name"))
                          for e in entries
                          if not e.get("alias")
                          and str(e.get("send_as") or e.get("name")).lower()
                          not in advertised})
        if phantom:
            print("  configured but NOT advertised by any endpoint (a chat call to one "
                  "may 404): %s" % ", ".join(phantom))
    return 0


def _verb_logs(rest):
    count = 40
    if rest:
        try:
            count = max(1, min(int(rest[0]), 5000))
        except ValueError:
            print("logs [n] — n is a line count", file=sys.stderr)
            return 2
    lines, total = _verb_log_lines(count)
    if not total:
        print("no %s yet — nothing has been logged" % (BASE_DIR / "tinycmdr.log"),
              file=sys.stderr)
        return 1
    print("%s (last %d of %d lines)" % (BASE_DIR / "tinycmdr.log", len(lines), total))
    for line in lines:
        print(scrub(line))
    return 0


def _is_elevated():
    """True when this process can restart a task-account service on Windows.

    A function, not an inline ctypes call, so the suite can grade the argv the restart
    verb builds without restarting anything (2026-09-22).
    """
    try:
        import ctypes
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return False


def _scheduled_task_owned():
    """True when a Windows scheduled task supervises THIS install.

    Elevation is only needed for the S4U lane, where the bot runs as a task account and
    a normal shell gets Access denied. The installer also offers a Startup-shortcut
    lane, and there the restart helper is an ordinary start: demanding an elevated
    shell for it is a dead end the operator can never satisfy. The
    probe is `schtasks` (present on every supported Windows, no PowerShell module
    needed), with a fallback that looks for this folder in the full task list for a
    task registered under another name.
    """
    name = str(CONFIG["agent"].get("windows_task_name") or "Tinycmdr")
    try:
        rc, out, _err, _ = run_capture(
            ["schtasks", "/Query", "/TN", name, "/FO", "LIST"], 30)
        if rc == 0:
            return True
        rc, out, _err, _ = run_capture(["schtasks", "/Query", "/FO", "LIST", "/V"], 60)
        return rc == 0 and str(BASE_DIR).lower() in (out or "").lower()
    except Exception:
        return False


# The helper returns as soon as it has SPARKED the replacement, and the replacement only
# takes the lock once it is up - ~60s later on the Windows task lane (measured twice,
# 2026-10-03, on a live install). One look right here turned that in-flight handover into
# "nothing holds the lock yet - check logs", which reads as a failed restart.
_RESTART_LOCK_POLL = 2.0   # seconds between looks while the handover is in flight
_RESTART_LOCK_WAIT = 90.0  # long enough for the measured handover, short enough to be an answer


def _verb_restart():
    """Restart through this host's own door, by calling the SHIPPED helper.

    Not a re-implementation: the helpers know this host's supervisor (S4U task,
    systemd unit, launchd agent) and getting that dance wrong is how two bots end
    up on one token. They also log what they did.
    """
    if os.name == "nt":
        helper = BASE_DIR / "maintenance" / "restart-tinycmdr.ps1"
        argv = ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass",
                "-File", str(helper)]
    elif sys.platform == "darwin":
        helper = BASE_DIR / "maintenance" / "restart-tinycmdr-macos.sh"
        argv = ["bash", str(helper)]
    else:
        helper = BASE_DIR / "maintenance" / "restart-tinycmdr.sh"
        argv = ["bash", str(helper)]
    # "there is no helper here" is a more useful sentence than "get an elevated shell",
    # so it comes first (the packaged installs always have it; a hand-built folder may not).
    if not helper.exists():
        print("no restart helper for this host at %s\n"
              "this install was not built by the installer, so restart it the way you "
              "started it" % helper, file=sys.stderr)
        return 1
    # Elevation is a TASK-lane requirement, not a Windows one: on the Startup-shortcut
    # lane there is no task to fight and the helper runs as this user.
    if os.name == "nt" and _scheduled_task_owned() and not _is_elevated():
        print("restart needs an elevated shell (the bot runs as a task account):\n"
              "  Start-Process powershell -Verb RunAs -ArgumentList "
              "'-File \"%s\"'" % helper, file=sys.stderr)
        return 1
    if os.name != "nt" and sys.platform != "darwin" and os.geteuid() != 0:
        print("restart needs root:\n  sudo bash %s" % helper, file=sys.stderr)
        return 1
    rc, out, err, timed_out = run_capture(argv, timeout=180)
    if timed_out:
        print("the restart helper did not finish in 180s - check the box",
              file=sys.stderr)
        return 1
    for line in (out or "").splitlines():
        print(scrub(line))
    if rc != 0:
        print("restart helper exited %s%s" % (rc, (": " + (err or "").strip()[-300:])
                                              if err else ""), file=sys.stderr)
        return 1
    # Look until the outcome is known, bounded: the lock appears when the replacement is
    # actually up, and the helper's own success says only that it was launched.
    _t0 = time.time()
    running = _verb_running()
    while running is not True and time.time() - _t0 < _RESTART_LOCK_WAIT:
        time.sleep(_RESTART_LOCK_POLL)
        running = _verb_running()
    _waited = int(time.time() - _t0)
    if running is True:
        print("restart: back up%s (the lock is held again)"
              % (" after %ds" % _waited if _waited >= 2 else ""))
        return 0
    if running is False:
        print("restart: the helper ran, but nothing holds the lock %ds later — "
              "check `tinycmdr logs 20`" % _waited, file=sys.stderr)
        return 1
    print("restart: helper ran; instance state unknown (the lock could not be read)",
          file=sys.stderr)
    return 1


_SECRET_SHAPES = {
    # name -> (regex, what it must look like). A Mattermost bot token is 26 lowercase
    # alphanumerics; a Telegram bot token is "<digits>:<35 chars>". Both are fixed by the
    # services, and a value that misses the shape can NEVER authenticate - which is the
    # whole point of checking here rather than after 723 failed lane starts.
    "TINYCMDR_MM_TOKEN": (re.compile(r"^[A-Za-z0-9]{26}$"),
                          "26 letters/digits, from System Console -> Integrations -> "
                          "Bot Accounts"),
    "TINYCMDR_TG_TOKEN": (re.compile(r"^\d{5,12}:[A-Za-z0-9_-]{30,}$"),
                          "<digits>:<35 characters>, from @BotFather"),
    "TINYCMDR_WEB_TOKEN": (re.compile(r"^[A-Za-z0-9_-]{20,}$"),
                           "20+ letters/digits/underscore/hyphen (an empty value at "
                           "`token set` mints one)"),
}


def secret_check(name, value):
    """The value to write, or ValueError saying why it cannot be a working secret.

    `tinycmdr token` called it "set (.env)" while the lane failed 723 times - nothing had
    looked at the value. The BOM case is not hypothetical either: PowerShell 5.1 prepends
    a UTF-8 BOM to anything piped into a native command, so `"$tok" | tinycmdr token set
    ...` writes seven bytes nobody can see.
    """
    text = str(value or "")
    note = ""
    if text.startswith("\ufeff"):
        text = text[1:]
        note = ("removed a leading UTF-8 BOM (PowerShell 5.1 adds one when it pipes a "
                "value into a command)")
    bad = sorted({ch for ch in text if ch in "\r\n\t" or unicodedata.category(ch)[0] == "C"})
    if bad:
        raise ValueError("the value holds control characters (%s) - paste the token at "
                         "the prompt, do not pipe it through a shell"
                         % " ".join("U+%04X" % ord(c) for c in bad))
    if not text.strip():
        raise ValueError("the value is empty")
    if text != text.strip():
        raise ValueError("the value has leading or trailing whitespace")
    shape = _SECRET_SHAPES.get(name)
    if shape and not shape[0].match(text):
        raise ValueError("a %s does not look like one: %d character(s), expected %s"
                         % (name, len(text), shape[1]))
    return text, note


def _env_set(name, value):
    """Write NAME=value into .env atomically, mode 600, keeping every other line."""
    value, _note = secret_check(name, value)
    lines = []
    if ENV_FILE.exists():
        lines = ENV_FILE.read_text(encoding="utf-8", errors="replace").splitlines()
    out, done = [], False
    for line in lines:
        if line.strip().startswith(name + "="):
            out.append("%s=%s" % (name, value))
            done = True
        else:
            out.append(line)
    if not done:
        out.append("%s=%s" % (name, value))
    atomic_write_text(ENV_FILE, "\n".join(out) + "\n")
    try:
        os.chmod(ENV_FILE, 0o600)
    except OSError:
        pass


def _mm_base_url(mm):
    """The Mattermost server as ONE url (the driver is given url and port separately)."""
    url = str((mm or {}).get("url") or "").strip()
    if url and "://" not in url:
        url = "%s://%s" % ((mm or {}).get("scheme", "https"), url)
    url = url.rstrip("/")
    port = (mm or {}).get("port") or (443 if url.startswith("https") else 80)
    if url and not re.search(r":\d+$", url) and str(port) not in ("443", "80"):
        url = "%s:%s" % (url, port)
    return url


def _mm_probe(url, token, timeout=15):
    """(ok, detail) for a Mattermost bot token against its server.

    The driver this lane runs on answers a refused token with an EMPTY message
    (mattermostautodriver/client.py does `log.error(message)` on the API's `message` field,
    which is empty for a bad token) - so the lane's own failure carried no reason, `doctor`
    said "no detail", and the log got a blank ERROR line per retry. One GET /users/me names
    the status, the URL and the bot, and is the same call the lane needs to make anyway.
    """
    url = str(url or "").strip()
    if not url:
        return None, "no mattermost.url in config.json"
    if "://" not in url:
        url = "https://" + url
    url = url.rstrip("/")
    try:
        r = requests.get(url + "/api/v4/users/me",
                         headers={"Authorization": "Bearer " + str(token)},
                         timeout=timeout)
    except Exception as e:                                    # noqa: BLE001 - reported
        return None, "could not reach %s: %s" % (url, e)
    if r.status_code == 200:
        try:
            who = r.json().get("username") or r.json().get("id") or "?"
        except Exception:                                     # noqa: BLE001
            who = "?"
        return True, "accepted as @%s" % who
    return False, "HTTP %d %s at %s/api/v4/users/me" % (
        r.status_code, (r.reason or "").strip(), url)


def _token_probe(name, value):
    """(ok|None, detail) for a secret we can ask the service about, else (None, "")."""
    if name == "TINYCMDR_MM_TOKEN":
        return _mm_probe((CONFIG.get("mattermost") or {}).get("url"), value)
    if name == "TINYCMDR_TG_TOKEN":
        try:
            r = requests.get("https://api.telegram.org/bot%s/getMe" % value, timeout=15)
            body = r.json()
        except Exception as e:                                # noqa: BLE001 - reported
            return None, "could not reach api.telegram.org: %s" % e
        if body.get("ok"):
            return True, "accepted as @%s" % (body.get("result") or {}).get("username")
        return False, "refused: %s" % (body.get("description") or "the API said no")
    return None, ""


def _env_set_safe(name, value):
    """_env_set, but a refused value is REPORTED instead of raising at a prompt."""
    try:
        _env_set(name, value)
        return True
    except ValueError as problem:
        print("   not saved: %s" % problem, file=sys.stderr)
        return False


def _verb_token(rest):
    if rest and rest[0] == "set":
        if len(rest) < 2:
            print("token set <NAME> — which key? e.g. TINYCMDR_MM_TOKEN",
                  file=sys.stderr)
            return 2
        name = rest[1].strip()
        if not re.fullmatch(r"[A-Z][A-Z0-9_]*", name):
            print("a .env key name, please: capitals, digits, underscore",
                  file=sys.stderr)
            return 2
        import getpass
        try:
            if sys.stdin.isatty():
                value = getpass.getpass("value for %s (not echoed): " % name)
            else:
                value = (sys.stdin.readline() or "").strip()
        except Exception as e:
            print("could not read the value: %s" % e, file=sys.stderr)
            return 1
        if name == "TINYCMDR_WEB_TOKEN" and not value.strip():
            # An empty value MINTS one: the token is ours to generate (unlike a
            # provider's), and a worldwide user should never have to invent 43
            # characters of entropy by hand.
            import secrets as _secrets
            value = _secrets.token_urlsafe(32)
            print("minted a fresh token for the page (%d characters)" % len(value))
        try:
            clean, note = secret_check(name, value)
        except ValueError as problem:
            print("nothing written: %s" % problem, file=sys.stderr)
            return 1
        if note:
            print("note: %s" % note)
        try:
            _env_set(name, clean)
        except Exception as e:
            print("could not write %s: %s" % (ENV_FILE, e), file=sys.stderr)
            return 1
        print("%s written to %s (mode 600 where the OS honours it)" % (name, ENV_FILE))
        if name == "TINYCMDR_WEB_TOKEN":
            urls = _web_base_urls(web_port_effective())
            print("page link : %s#token=%s" % (urls[0][0], clean))
            for base, _loop in urls[1:]:
                print("            also: %s" % base)
            print("            `tinycmdr restart` puts it in service; `tinycmdr web` "
                  "opens it.")
        # Ask the provider NOW. A token that the service refuses is a fact the operator can
        # have at the prompt, instead of a lane that fails every 20s behind them.
        good, detail = _token_probe(name, clean)
        if good is True:
            print("checked   : the provider %s — the lane works once it restarts." % detail)
        elif good is False:
            print("REFUSED   : %s" % detail, file=sys.stderr)
            print("the value is in .env, but that token does not authenticate: get a fresh "
                  "one and run this again.", file=sys.stderr)
            return 1
        elif detail:
            print("unchecked : %s" % detail)
        if _verb_running() is True:
            print("the running bot read .env at start: `tinycmdr restart` to pick it up.")
        return 0

    print("secrets live in %s (the one file the agent cannot read into a prompt)"
          % ENV_FILE)
    env = _env_file_keys()
    print("  .env.example lists every key; set one with: tinycmdr token set NAME")
    print("  %-22s %s" % ("key", "state"))
    for name in ("TINYCMDR_MM_TOKEN", "TINYCMDR_TG_TOKEN", "TINYCMDR_WEB_TOKEN",
                 "DEEPSEEK_API_KEY", "ANYSEARCH_API_KEY", "TAVILY_API_KEY"):
        state = "set (%s)" % (".env" if name in env else "environment") \
            if os.environ.get(name) else "not set"
        print("  %-22s %s" % (name, state))
    if (CONFIG["llm"].get("api_key") or "").strip():
        print("  llm.api_key            set in config.json — move it to .env when you "
              "can: config.json is a file the agent can read")
    print("  values are never printed by this command.")
    return 0


def _verb_run(rest):
    """Start the agent in this window: exactly what running the file does."""
    argv = [sys.executable, str(BASE_DIR / "tinycmdr.py")] + list(rest)
    try:
        if os.name == "nt":
            return subprocess.call(argv, cwd=str(BASE_DIR))
        os.execv(sys.executable, argv)
    except Exception as e:
        print("could not start the agent: %s" % e, file=sys.stderr)
        return 1
    return 0


# The verbs that make sense from a chat message. The rest need a terminal: `run` opens a
# session, `setup` and `token set` prompt, `restart` has its own fast path that must work
# while a run owns the channel. `help` is NOT here on purpose: the chat lane answers
# `/tinycmdr help` with its own list of commands (the "**Commands**" block), which names the
# chat verbs a host-side help page cannot, and a suite pins it.
_CHAT_VERB_SET = frozenset(("status", "doctor", "health", "version", "proc",
                            "config", "model", "logs", "clean", "update"))


def verb_from_chat(argv_line):
    """Run one management verb for a chat request and return what it printed.

    `tinycmdr update` in a shell and `/tinycmdr update` in a chat are the same command, so the
    output goes back to the channel rather than to a console nobody is looking at. Verbs that
    need a terminal are refused by name instead of half-run.
    """
    import contextlib
    import io
    argv = [a for a in str(argv_line or "").split() if a]
    if not argv:
        return VERB_HELP
    verb = argv[0].lower()
    if verb == "help":
        return VERB_HELP          # the lane's own /help block answers this in chat
    if verb not in _CHAT_VERB_SET:
        if verb in VERBS:
            return ("`%s` needs a terminal on the host (it prompts, opens a session, or has "
                    "its own fast path), so it is not a chat verb. From chat: %s."
                    % (verb, ", ".join(sorted(_CHAT_VERB_SET))))
        return ("unknown verb %r. From chat: %s."
                % (verb, ", ".join(sorted(_CHAT_VERB_SET))))
    buf = io.StringIO()
    code = 0
    try:
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            code = run_verb(argv)
    except SystemExit as e:
        code = e.code if isinstance(e.code, int) else 0
    except Exception as e:                                       # noqa: BLE001
        return "`%s` failed: %s" % (verb, e)
    out = buf.getvalue().strip() or "(no output)"
    if len(out) > 3500:
        out = out[:3500] + "\n... (truncated)"
    return "```\n%s\n```\n(exit %s)" % (out, code)


def _verb_approvals(rest):
    """`approvals [clear]`: what the confirm gate has been told to stop asking about.

    The operator's "session" and "always" answers live here, so the state they set is
    visible and reversible without editing a file."""
    if rest and rest[0] in ("clear", "reset", "off"):
        confirm_allow("clear")
        print("cleared: the confirm gate asks again for every command.")
        return 0
    st = confirm_allow_state()
    print("confirm gate allowlist: %s" % CONFIRM_ALLOW_FILE)
    print("  every command, for ever : %s" % ("yes" if st["all"] else "no"))
    print("  this session            : %s" % (", ".join(st["sessions"]) or "none"))
    print("  clear with: tinycmdr approvals clear")
    return 0


def _verb_failures(rest):
    """What this box has already failed at, and what the library knows about it.

    Read-only, and the answer to two questions the library could not answer about itself:
    which entries have EVER fired here (so the header's "delete an entry that does not help"
    can be acted on), and which failures keep arriving with no entry at all - the candidates
    a new entry is written from. `--json` prints the counters; `--candidates` only the
    second list.
    """
    stats = field_notes_stats()
    if "--json" in rest:
        print(json.dumps(stats, indent=2, ensure_ascii=False))
        return 0
    path = _field_notes_path()
    entries = field_notes()
    hits = stats.get("entries") or {}
    unmatched = stats.get("unmatched") or {}
    only_candidates = any(a in ("--candidates", "-c") for a in rest)
    if not path.exists():
        print("no known-failure library at %s" % path)
        return 1
    if not only_candidates:
        fired_rows = sorted(entries,
                            key=lambda e: -(int((hits.get(e["title"]) or {}).get("fired") or 0)))
        since = stats.get("since") or "never counted"
        print("known-failure library: %s (%d entries, counting since %s)"
              % (path, len(entries), since))
        for e in fired_rows:
            slot = hits.get(e["title"]) or {}
            n = int(slot.get("fired") or 0)
            print("  %-56s %s" % (e["title"][:56],
                                  ("fired %d, last %s" % (n, slot.get("last")))
                                  if n else "never fired since counting began"))
        never = [e["title"] for e in entries if not (hits.get(e["title"]) or {}).get("fired")]
        if never:
            print("\n  %d of %d have not fired since %s. The header's rule: an entry that"
                  % (len(never), len(entries), since))
            print("  fires and does not help gets deleted - so these are the first to review,"
                  " not the first to trust.")
    if unmatched:
        print("\n  failures with NO entry (%d signature(s)) - newest first, top 10:"
              % len(unmatched))
        for sig, slot in sorted(unmatched.items(),
                                key=lambda kv: -(int(kv[1].get("fails") or 0)))[:10]:
            print("    %3dx  %s" % (int(slot.get("fails") or 0), sig[:92]))
        print("  Add an entry only when one of these repeats AND its signature always means"
              " one cause:")
        print("  an ambiguous note costs more than no note (4x steps, 3.6x tokens, measured).")
    elif not only_candidates:
        print("\n  no unmatched failures recorded yet.")
    return 0


def run_verb(argv):
    """Dispatch one management verb. Returns the process exit code."""
    verb = (argv[0] or "").strip().lower()
    rest = list(argv[1:])
    if verb in ("help", "-h", "--help"):
        print(VERB_HELP)
        return 0
    if verb not in VERBS:
        print("unknown verb %r\n" % verb, file=sys.stderr)
        print(VERB_HELP)
        return 2
    log.info("verb: %s %s", verb, _verb_log_args(verb, rest))
    if verb == "status":
        return _verb_status()
    if verb == "doctor":
        return _verb_doctor()
    if verb == "health":
        return _verb_health()
    if verb == "failures":
        return _verb_failures(rest)
    if verb == "approvals":
        return _verb_approvals(rest)
    if verb == "version":
        return _verb_version()
    if verb == "proc":
        return _verb_proc()
    if verb == "setup":
        return run_setup(rest)
    if verb == "config":
        return _verb_config(rest)
    if verb == "update":
        return _verb_update(rest)
    if verb == "clean":
        return _verb_clean(rest)
    if verb == "model":
        return _verb_model(rest)
    if verb == "reasoning":
        return _verb_reasoning(rest)
    if verb == "logs":
        return _verb_logs(rest)
    if verb == "restart":
        return _verb_restart()
    if verb == "token":
        return _verb_token(rest)
    if verb == "web":
        return _verb_web(rest)
    if verb == "run":
        return _verb_run(rest)
    return 2


# The values config.example.json ships so a reader sees the shape. They are NOT a lane:
# counting them made every fresh, token-less install look like a Mattermost host with a
# broken URL - and that is exactly the install that is meant to be a supported CLI-only
# one.
MM_TOKEN_PLACEHOLDER = "PASTE_BOT_TOKEN_HERE"
MM_USER_PLACEHOLDER = "your-mattermost-user-id"


def _mm_token_configured():
    """The Mattermost token a lane could run with, or "" - the placeholder excluded."""
    tok = str(CONFIG["mattermost"].get("token")
              or os.environ.get("TINYCMDR_MM_TOKEN") or "").strip()
    return "" if tok == MM_TOKEN_PLACEHOLDER else tok


def _tg_token_configured():
    """The Telegram token a lane could run with, or ""."""
    return str((CONFIG.get("telegram") or {}).get("token")
               or os.environ.get("TINYCMDR_TG_TOKEN") or "").strip()


def _chat_lane_configured():
    """Is any chat lane configured at all (the shipped placeholders do not count)?

    Every requirement in validate_startup_config below is a CHAT-LANE requirement, so a
    host with no chat lane is asked none of them: it can still run `--cli` and `--once`,
    and there is nothing remote to serve.
    """
    return bool(_mm_token_configured() or _tg_token_configured())


def validate_startup_config():
    """Catch the classic first-run mistakes before they die as an unreadable
    traceback inside the Mattermost driver. Returns an error string, or None."""
    if not CONFIG_PATH.exists():
        return (f"config.json not found in {BASE_DIR}\n"
                "Copy config.example.json to config.json and fill in your "
                "Mattermost bot token, LLM endpoint, and allowed_users.")
    if CONFIG_ERROR:
        return CONFIG_ERROR
    # A config.json that REPLACED a shipped guard list is not fatal - it is the operator's
    # file - but it must not be silent. `doctor` turns this into a
    # non-zero exit; the log names every pattern the box is not enforcing.
    _drift = guard_list_drift()
    if _drift:
        log.warning("%s", guard_drift_note(_drift))
    # Everything below exists because a CHAT driver would misbehave, so with no chat token
    # it is simply not asked - and a box that is only a Telegram bot is not asked about
    # Mattermost either (its own lane's requirements are gated the same way).
    _mm_token = _mm_token_configured()
    _tg_token = _tg_token_configured()
    # "Intends to run Mattermost" = a real host or a non-empty allowlist. The example
    # file's placeholders do not count, or a session-only install would be told
    # to fill in a lane it never wanted.
    _mm_url = str(CONFIG["mattermost"].get("url") or "").strip().lower()
    _mm_users = [u for u in (CONFIG["mattermost"].get("allowed_users") or [])
                 if str(u).strip() and str(u).strip() != MM_USER_PLACEHOLDER]
    _mm_intent = bool(_mm_users or (_mm_url and not _mm_placeholder_unset(_mm_url)
                                    and not _mm_documented_placeholder(_mm_url)))
    if not _chat_lane_configured() and not _mm_intent:
        # A CLI-only install is a supported end state: the installers register no
        # service for it, there is no chat driver to validate, and nothing remote
        # to serve. `--cli` and `--once` are its doors.
        log.info("no chat lane configured: CLI-only install (--cli / --once)")
        return None
    tg_users = [u for u in ((CONFIG.get("telegram") or {}).get("allowed_users") or [])
                if str(u).strip()]
    tg_token = str((CONFIG.get("telegram") or {}).get("token") or "").strip()
    if tg_token and not tg_users:
        return ("telegram.token is set but telegram.allowed_users is empty, and "
                "this bot is deny-by-default - it would ignore every DM.\n"
                "Put your numeric Telegram id there (or TELEGRAM_ALLOWED_USERS "
                "in .env).")
    _tg_bad = sorted(str(u).strip() for u in tg_users
                     if not re.fullmatch(r"\d+", str(u).strip()))
    if tg_token and _tg_bad:
        # An "@david" or a username can NEVER match the numeric id the gate compares
        # against: the lane starts, looks alive, and silently refuses every DM (A-174).
        return ("telegram.allowed_users has %s - Telegram ids are NUMERIC (message "
                "@userinfobot for yours), and a username can never match, so this lane "
                "would refuse every DM.\nFix allowed_users (or TELEGRAM_ALLOWED_USERS "
                "in .env)." % ", ".join(repr(b) for b in _tg_bad[:5]))
    users = CONFIG["mattermost"].get("allowed_users")
    if (_mm_token and (users is None
                          or (isinstance(users, (list, tuple)) and not users)
                          or users == "")):
        return ("mattermost.allowed_users is empty, and this bot is "
                "deny-by-default - so it would ignore everybody.\n"
                'Add your Mattermost user id, e.g. "allowed_users": ["abc123"], '
                "or ship it in install/fleet-defaults.json so installs fill it in.")
    url = str(CONFIG["mattermost"].get("url", "") or "").strip()
    if _mm_token and (not url or _mm_placeholder_unset(url)):
        return ("mattermost.url in config.json is empty/placeholder.\n"
                "Set it to your Mattermost host, e.g. chat.example.com "
                "(scheme and port are separate keys).")
    if _mm_documented_placeholder(url):
        # warn, don't abort: example.com is the documented placeholder, but a
        # host could legitimately use it, and a wrong URL fails loudly anyway
        log.warning("mattermost.url still reads %r — that is the placeholder "
                    "from config.example.json; set your real host", url)
    wanted = [("requests", "the HTTP layer")]
    if _mm_token:
        wanted.append(("mmpy_bot", "the Mattermost layer"))
    for mod, why in tuple(wanted):
        try:
            __import__(mod)
        except ImportError:
            return (f"{mod} is not installed for {sys.executable}, and it is "
                    f"needed for {why}.\n"
                    "Install the DECLARED dependencies (the file is the authority):"
                    "  "
                    f"{sys.executable} -m pip install -r "
                    f"{BASE_DIR / 'requirements.txt'}")
    try:
        __import__("croniter")
    except ImportError:
        log.warning("croniter is not installed: the schedule tool will be "
                    "disabled (pip install -r requirements.txt)")
    # A missing Mattermost token is a MISTAKE only when this box intends to run that
    # lane; "no chat token at all" already returned above.
    if not _mm_token:
        if _tg_token or not _mm_intent:
            return None
        _head = "no Mattermost bot token.\n"
        if str(CONFIG["mattermost"].get("token") or "").strip() == MM_TOKEN_PLACEHOLDER:
            _head = ("mattermost.token still has the placeholder from "
                     "config.example.json.\n")
        return (_head +
                "Put it in .env as TINYCMDR_MM_TOKEN=... (preferred, keeps it "
                "out of config.json), or paste it into mattermost.token. "
                "Get it from System Console -> Integrations -> Bot Accounts.")
    if CONFIG["mattermost"].get("allowed_users") == ["your-mattermost-user-id"]:
        return ("mattermost.allowed_users still has the placeholder.\n"
                "Set it to YOUR Mattermost USER ID (System Console -> Users -> "
                "the id column) - not your username: it is compared against the "
                "id on every post, and the bot is deny-by-default, so a "
                "username here means nobody can use it.")
    return None


def tg_token_only():
    """True when Telegram is the configured lane and Mattermost is not."""
    return bool(_tg_token_configured()) and not _mm_token_configured()


def lanes_to_serve(argv=None):
    """Which chat lanes THIS run serves: [] (CLI-only), one, or BOTH.

    A flag forces one lane; otherwise every configured token gets its lane. Two tokens
    used to be a refusal ("neither lane is primary"), and the service runs no flag - so a
    box that added a Telegram token to a working Mattermost install served NOTHING, and
    the lane that "does not work" had simply never been started. One process can poll
    both, so it does; `--telegram` / `--mattermost` still force a single lane.
    """
    args = list(sys.argv if argv is None else argv)
    if "--telegram" in args:
        return ["telegram"]
    if "--mattermost" in args:
        return ["mattermost"]
    lanes = []
    if _mm_token_configured():
        lanes.append("mattermost")
    if _tg_token_configured():
        lanes.append("telegram")
    return lanes


def _root_warning():
    """One line when something runs as root over an install that belongs to another user.

    Every file this process CREATES then belongs to root, and the agent - which runs as the
    install's own user - can no longer read them. Measured three times in one evening on the
    Mac (2026-09-27): `sudo tinycmdr config set ...` left config.json root:staff 0600 and the
    launchd agent exited 1 on every respawn; the same run left sessions/cli.json root-owned,
    so the CLI lane could not load its session; and a bare `sudo tinycmdr` - which opens a
    CLI session - re-created the session files as root. Nothing here REFUSES root: a
    system-wide install legitimately belongs to root. It only says what will happen.
    """
    if os.name == "nt" or not hasattr(os, "geteuid") or os.geteuid() != 0:
        return ""
    try:
        owner = BASE_DIR.stat().st_uid
    except OSError:
        return ""
    if owner == 0:
        return ""
    return ("running as root, but %s belongs to uid %d: every file this process writes "
            "(config.json, session files) will be created root-owned, and the "
            "agent - which runs as uid %d - then cannot read them. Run it as that user, "
            "without sudo." % (BASE_DIR, owner, owner))


def main():
    _rw = _root_warning()
    if _rw:
        log.warning("%s", _rw)
        print("WARNING: " + _rw, file=sys.stderr)
    # `tinycmdr cli` - the console alone, the deliberate opposite of the bare default.
    # Normalised to `--cli` here (one spelling downstream) and handled before the verb
    # dispatch, which would otherwise read the word as a typo.
    if len(sys.argv) > 1 and sys.argv[1].lower() == "cli":
        sys.argv.pop(1)
        sys.argv.append("--cli")
    # Management verbs, and the two inert flags. Nothing here starts the agent loop:
    # `tinycmdr status` asks the endpoint for metadata and answers a question.
    if len(sys.argv) > 1 and sys.argv[1].lower() in VERBS:
        sys.exit(run_verb(sys.argv[1:]))
    # A first argument that is not a flag and not a verb is a verb the operator MEANT
    # (a typo, or a name from an older README): it used to fall through to the start
    # of the bot, which then sat there answering nobody while the terminal looked
    # fine. It goes to the same dispatcher, which names it and prints the list.
    if (len(sys.argv) > 1 and sys.argv[1] and not sys.argv[1].startswith("-")
            and sys.argv[1].lower() not in VERBS):
        sys.exit(run_verb([sys.argv[1]]))
    if "--version" in sys.argv:
        print("tinycmdr %s" % VERSION)
        sys.exit(0)
    if "--help" in sys.argv or "-h" in sys.argv:
        print(VERB_HELP)
        sys.exit(0)
    # The page is the default door, so these adjust it for THIS process:
    # --web forces it on, --no-web off, --web-host/--web-port override the bind,
    # --no-browser only stops the auto-open. Typing --web IS the asking.
    _web_no_browser = ("--no-browser" in sys.argv
                       or os.environ.get("TINYCMDR_NO_BROWSER") == "1")
    _web = CONFIG.setdefault("web", {})
    if "--web" in sys.argv:
        _web["enabled"] = True
    if "--no-web" in sys.argv:
        _web["enabled"] = False
    for _flag, _key in (("--web-port", "port"), ("--web-host", "host")):
        if _flag in sys.argv:
            try:
                _val = sys.argv[sys.argv.index(_flag) + 1]
                _web[_key] = int(_val) if _key == "port" else _val
            except (IndexError, ValueError):
                print("%s needs a value" % _flag, file=sys.stderr)
                sys.exit(2)
    if "--once" in sys.argv:
        idx = sys.argv.index("--once")
        run_cli(once=" ".join(sys.argv[idx + 1:]))
        return
    # The page starts beside the LONG-LIVED SERVICE modes (bare, the lanes) - the default
    # door whichever one this is. It does NOT start beside a terminal session: `--cli`
    # and `--app` used to raise the browser and the console at once (2026-10-04:
    # "typing tinycmdr opens the webui and the TUI/CLI at once"). `--web`
    # still overrides, because typing it IS the asking; `--once` returns before this.
    _terminal_mode = ("--cli" in sys.argv or "--app" in sys.argv)
    if _terminal_mode and "--web" not in sys.argv:
        _srv = None
    else:
        _srv = start_web_surface(open_browser=not _web_no_browser,
                                 force=("--web" in sys.argv))
    def _service_preflight():
        """Validation + the single-instance lock, for a SERVICE lane. Exits on refusal.

        Every service door (bare, --mattermost, --telegram) must take both, or a second
        process on the same token silently double-answers every DM: --telegram used to
        walk straight into its lane without either.
        """
        err = validate_startup_config()
        if err:
            log.critical("STARTUP ABORTED: %s", err.replace("\n", " "))
            print(f"\n*** tinycmdr cannot start ***\n{err}\n"
                  f"(also written to {BASE_DIR / 'tinycmdr.log'})\n",
                  file=sys.stderr)
            try:
                input("Press Enter to close...")  # keep console readable
            except (EOFError, OSError):
                time.sleep(30)  # pythonw: no console; log has the details
            sys.exit(2)
        if not acquire_single_instance_lock():
            log.critical("STARTUP ABORTED: another tinycmdr is already "
                         "running from %s (tinycmdr.lock is held). Two "
                         "instances on one bot token double-answer every "
                         "DM — kill the other one instead.", BASE_DIR)
            print(f"\n*** tinycmdr is already running from this folder ***\n"
                  f"Kill the other instance (or delete tinycmdr.lock if "
                  f"you're sure nothing is running).\n", file=sys.stderr)
            try:
                _log_listener.stop()  # drain queued log records before exit
            except Exception:
                pass
            sys.exit(3)

    if "--app" in sys.argv:
        run_cli(app=True)
    elif "--cli" in sys.argv:
        # TINYCMDR_APP=1 prefers the full-screen app for the human door; `--cli` still
        # spells the inline lane out by hand, and `--app` overrides either way. The app
        # falls back to the inline cards on a terminal that cannot host it.
        run_cli(app=os.environ.get("TINYCMDR_APP") == "1")
    elif "--telegram" in sys.argv:
        _service_preflight()
        lane_with_retry(run_telegram, "telegram", _lane_report_telegram)
    else:
        _service_preflight()
        lanes = lanes_to_serve()
        if "--mattermost" in sys.argv and not _mm_token_configured():
            print("--mattermost was given, but no Mattermost token is configured.",
                  file=sys.stderr)
            sys.exit(2)
        if not lanes:
            # No chat lane to serve. The PAGE is the door now, so when it started
            # this process holds it open; otherwise the folder is still ready for a
            # session or a one-shot.
            log.info("no chat lane configured: serving the page (if enabled)")
            print("no chat lane is configured (no Mattermost and no Telegram token).")
            if _srv is not None:
                print("Serving the page above; Ctrl-C stops it. "
                      "`tinycmdr --once \"<task>\"` runs one task and exits.")
                try:
                    while True:
                        time.sleep(3600)
                except KeyboardInterrupt:
                    print("stopping.")
            else:
                print("A session needs no service, and this folder is ready for one:\n"
                      "  tinycmdr --cli            an interactive session\n"
                      "  tinycmdr --once \"<task>\"  (one task, then exit)\n"
                      "A token turns the page on: `tinycmdr token set "
                      "TINYCMDR_WEB_TOKEN`.")
        elif lanes == ["telegram"]:
            # Telegram-only: this process IS the Telegram lane.
            lane_with_retry(run_telegram, "telegram", _lane_report_telegram)
        elif lanes == ["mattermost"]:
            lane_with_retry(run_bot, "mattermost", _lane_report_mattermost)
        else:
            # BOTH doors: serve them in ONE process (Mattermost on this thread, Telegram
            # on a daemon one), so adding a Telegram token to a working Mattermost install
            # does not leave the new lane dark.
            log.info("both doors configured: serving Mattermost and Telegram")
            print("serving Mattermost and Telegram in this one process.")
            _tg_thread = threading.Thread(
                target=lane_with_retry,
                args=(run_telegram, "telegram", _lane_report_telegram),
                daemon=True, name="telegram-lane")
            _tg_thread.start()
            try:
                lane_with_retry(run_bot, "mattermost", _lane_report_mattermost)
            except SystemExit as exc:
                # A lane that cannot start must not take the other one with it. Telegram
                # rides a DAEMON thread here, so returning from main() kills it - the shape
                # where a missing Mattermost token silences a working Telegram lane. While
                # the other lane is alive, keep serving it; if it is gone too, exit as
                # before and let the supervisor restart the pair.
                if not _tg_thread.is_alive():
                    raise
                log.critical("Mattermost lane stopped (exit %s) - Telegram keeps serving; "
                             "fix Mattermost, then `tinycmdr restart`.",
                             getattr(exc, "code", "?"))
                while _tg_thread.is_alive():
                    time.sleep(1)


if __name__ == "__main__":
    main()
